INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('apko-melange-tutorial', 'apko + melange: Distroless OCI Images Your Scanner Can Actually Read', NULL, 'A working tutorial for apko and melange. Package a binary with melange, assemble it into a signed distroless image with apko, and ship it with an SBOM Trivy can actually parse.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Your container scanner is lying to you."}]},{"type":"paragraph","content":[{"type":"text","text":"The scanner isn''t at fault. Trivy, Grype, Snyk, every CVE feed on Earth, they all identify software the same way: they read a package manager''s database. "},{"type":"text","marks":[{"type":"code"}],"text":"apt"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"apk"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"dpkg"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"rpm"},{"type":"text","text":", the language-level lockfiles. If your image is built with a "},{"type":"text","marks":[{"type":"code"}],"text":"Dockerfile"},{"type":"text","text":" that does "},{"type":"text","marks":[{"type":"code"}],"text":"COPY ./my-binary /usr/local/bin/"},{"type":"text","text":" and then "},{"type":"text","marks":[{"type":"code"}],"text":"RUN curl | sh"},{"type":"text","text":" for the SDK, the scanner sees an Alpine base layer it can read, and then a pile of files it can''t attribute to anything. The CVE report comes back clean. Nothing is clean. The scanner just doesn''t have a name for what''s in the image."}]},{"type":"paragraph","content":[{"type":"text","text":"This is the problem "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/technology/apko","target":null,"rel":null,"class":null,"title":null}}],"text":"apko"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/technology/melange","target":null,"rel":null,"class":null,"title":null}}],"text":"melange"},{"type":"text","text":" were built to fix. Every byte in the final image arrives through a package manager, with a name, a version, a checksum, and a CVE feed entry. Distroless by construction. Reproducible by design. Signed by default. The whole pipeline is two YAML files and two CLI invocations, and you can run it on your laptop right now."}]},{"type":"heading","attrs":{"level":2,"id":"see-it-for-yourself"},"content":[{"type":"text","text":"See It For Yourself"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"# install melange and apko (macOS shown; Linux ships in most package managers)\nbrew install melange apko\n\n# generate the apk-signing keypair\nmelange keygen\n\n# build a Wolfi-based \"hello, world\" apk and a 2 MB OCI image\nmelange build melange.yaml --arch amd64 --signing-key melange.rsa --runner docker\napko build apko.yaml hello:latest hello.tar --keyring-append ./melange.rsa.pub --arch amd64\ndocker load < hello.tar\ndocker run --rm hello:latest\n# > Hello, world!"}]},{"type":"paragraph","content":[{"type":"text","text":"We''ll build the two YAML files below. There are only forty lines between you and a signed, distroless, scanner-visible image."}]},{"type":"heading","attrs":{"level":2,"id":"why-dockerfiles-lie-to-your-scanner"},"content":[{"type":"text","text":"Why Dockerfiles Lie to Your Scanner"}]},{"type":"paragraph","content":[{"type":"text","text":"A scanner finding zero CVEs in a "},{"type":"text","marks":[{"type":"code"}],"text":"Dockerfile"},{"type":"text","text":"-built image is, statistically, more alarming than finding fifty. Fifty means the scanner can read what''s in there. Zero means it can''t."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"Dockerfile"},{"type":"text","text":" lets you do anything, which is the problem. A "},{"type":"text","marks":[{"type":"code"}],"text":"RUN curl https://example.com/install.sh | sh"},{"type":"text","text":" step pulls a binary that the package manager database doesn''t know about. The scanner sees the layer hash, opens it, finds a file, has no idea what it is. It can''t tell you the file is a vulnerable "},{"type":"text","marks":[{"type":"code"}],"text":"libcurl"},{"type":"text","text":", or a sketchy "},{"type":"text","marks":[{"type":"code"}],"text":"kubectl"},{"type":"text","text":" plugin, or a backdoored Helm chart. It moves on."}]},{"type":"paragraph","content":[{"type":"text","text":"The fix is to build images where every file came through a package manager that records what it installed and where. That means no "},{"type":"text","marks":[{"type":"code"}],"text":"RUN curl | sh"},{"type":"text","text":". No "},{"type":"text","marks":[{"type":"code"}],"text":"COPY"},{"type":"text","text":" from anywhere except controlled sources. No "},{"type":"text","marks":[{"type":"code"}],"text":"apt-get install"},{"type":"text","text":" running against a moving target. The image format has to enforce these constraints, not the build script."}]},{"type":"paragraph","content":[{"type":"text","text":"That''s what apko does. There is no "},{"type":"text","marks":[{"type":"code"}],"text":"RUN"},{"type":"text","text":" step in apko. No "},{"type":"text","marks":[{"type":"code"}],"text":"COPY"},{"type":"text","text":" from the host. No shell available during the build. apko takes a YAML config that lists "},{"type":"text","marks":[{"type":"code"}],"text":"apk"},{"type":"text","text":" packages and produces an OCI tarball. The set of installable packages is the set of packages in your declared repositories. The scanner sees the apk database in the final image and gets a 100% match against every byte."}]},{"type":"paragraph","content":[{"type":"text","text":"When you need software that isn''t packaged yet, that''s melange''s job."}]},{"type":"heading","attrs":{"level":2,"id":"two-tools-one-job"},"content":[{"type":"text","text":"Two Tools, One Job"}]},{"type":"paragraph","content":[{"type":"text","text":"apko is the assembler. melange is the package builder. They split the work the way "},{"type":"text","marks":[{"type":"code"}],"text":"apt"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"dpkg-buildpackage"},{"type":"text","text":" split the Debian world, and for the same reasons."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"/technology/apko","target":null,"rel":null,"class":null,"title":null}}],"text":"apko"},{"type":"text","text":" takes a list of "},{"type":"text","marks":[{"type":"code"}],"text":"apk"},{"type":"text","text":" packages and produces a multi-arch OCI image with no shell, no package manager in the final layer, and a deterministic content hash. The whole tool is a thin shell over the "},{"type":"text","marks":[{"type":"code"}],"text":"apk"},{"type":"text","text":" resolver plus a tarball builder. It can''t run arbitrary commands during the build because it never invokes a shell. It just resolves the dependency graph, fetches the packages, and writes the layers."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"/technology/melange","target":null,"rel":null,"class":null,"title":null}}],"text":"melange"},{"type":"text","text":" builds those "},{"type":"text","marks":[{"type":"code"}],"text":"apk"},{"type":"text","text":" packages from source. You give it a YAML that describes the source URL, the build steps, and the test command. melange runs those steps inside a clean sandbox (Docker, bubblewrap, QEMU, or Lima are all supported), produces a signed "},{"type":"text","marks":[{"type":"code"}],"text":".apk"},{"type":"text","text":", and puts it in "},{"type":"text","marks":[{"type":"code"}],"text":"./packages/<arch>/"},{"type":"text","text":". You then point apko at that local repository and apko treats your package the same as anything from Wolfi."}]},{"type":"paragraph","content":[{"type":"text","text":"The reason these are two binaries instead of one: every melange-built package is just an "},{"type":"text","marks":[{"type":"code"}],"text":"apk"},{"type":"text","text":", indistinguishable from the thousands of packages in the "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/wolfi-dev/os","target":null,"rel":null,"class":null,"title":null}}],"text":"Wolfi"},{"type":"text","text":" base distribution. You can publish your apks to a private apk repository, share them across projects, and forget which build system produced them. apko consumes apks. It doesn''t care whose pipeline made them."}]},{"type":"heading","attrs":{"level":2,"id":"setting-up-wolfi-keys-runners"},"content":[{"type":"text","text":"Setting Up: Wolfi, Keys, Runners"}]},{"type":"paragraph","content":[{"type":"text","text":"Install both tools:"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"# macOS\nbrew install melange apko\n\n# Linux with Go installed\ngo install chainguard.dev/melange@latest\ngo install chainguard.dev/apko@latest\n\n# Or pull pre-built containers\ndocker run --rm cgr.dev/chainguard/melange version\ndocker run --rm cgr.dev/chainguard/apko version"}]},{"type":"paragraph","content":[{"type":"text","text":"melange signs every "},{"type":"text","marks":[{"type":"code"}],"text":".apk"},{"type":"text","text":" it builds. Generate a keypair once, store the private key somewhere safe (a CI secret manager for production, your dotfiles for laptop work):"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"melange keygen\n# > generating keypair with a 4096 bit prime, please wait...\n# > wrote private key to melange.rsa\n# > wrote public key to melange.rsa.pub"}]},{"type":"paragraph","content":[{"type":"text","text":"melange runs the build steps inside a sandbox. Pick a runner based on what''s available:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"--runner docker"},{"type":"text","text":" is the easiest path on macOS and most laptops."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"--runner bubblewrap"},{"type":"text","text":" is the lightest option on Linux CI. No daemon, no privileged container."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"--runner qemu"},{"type":"text","text":" uses QEMU user-mode emulation to build arm64 packages natively on an amd64 host, without a cross-compiler."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"--runner lima"},{"type":"text","text":" is the macOS-native Linux VM option if you don''t want Docker Desktop."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"If you''re not sure, start with "},{"type":"text","marks":[{"type":"code"}],"text":"docker"},{"type":"text","text":". The build is hermetic regardless of the runner."}]},{"type":"heading","attrs":{"level":2,"id":"building-a-package-with-melange"},"content":[{"type":"text","text":"Building a Package with melange"}]},{"type":"paragraph","content":[{"type":"text","text":"Let''s package GNU "},{"type":"text","marks":[{"type":"code"}],"text":"hello"},{"type":"text","text":". It''s small, it builds with autotools, and there''s no point packaging anything you already use until you''ve seen the shape of a working config."}]},{"type":"paragraph","content":[{"type":"text","text":"Save this as "},{"type":"text","marks":[{"type":"code"}],"text":"melange.yaml"},{"type":"text","text":":"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"package:\n  name: hello\n  version: 2.12.3\n  epoch: 0\n  description: \"the GNU hello world program\"\n  copyright:\n    - license: GPL-3.0-or-later\n\nenvironment:\n  contents:\n    repositories:\n      - https://packages.wolfi.dev/os\n    keyring:\n      - https://packages.wolfi.dev/os/wolfi-signing.rsa.pub\n    packages:\n      - build-base\n      - busybox\n      - ca-certificates-bundle\n\npipeline:\n  - uses: fetch\n    with:\n      uri: https://ftp.gnu.org/gnu/hello/hello-${{package.version}}.tar.gz\n      expected-sha256: 0d5f60154382fee10b114a1c34e785d8b1f492073ae2d3a6f7b147687b366aa0\n  - uses: autoconf/configure\n  - uses: autoconf/make\n  - uses: autoconf/make-install\n  - uses: strip\n\ntest:\n  pipeline:\n    - runs: hello --version"}]},{"type":"paragraph","content":[{"type":"text","text":"Three blocks worth understanding:"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"},{"type":"code"}],"text":"package"},{"type":"text","text":" is the metadata that ends up in the apk database. "},{"type":"text","marks":[{"type":"code"}],"text":"name"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"version"},{"type":"text","text":" are the identity. "},{"type":"text","marks":[{"type":"code"}],"text":"epoch"},{"type":"text","text":" is the build-of-build number, you bump it when the source is unchanged but the recipe changed. "},{"type":"text","marks":[{"type":"code"}],"text":"copyright.license"},{"type":"text","text":" is read by SBOM generators."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"},{"type":"code"}],"text":"environment"},{"type":"text","text":" is the build sandbox. apk packages, repositories, and keys go here. "},{"type":"text","marks":[{"type":"code"}],"text":"build-base"},{"type":"text","text":" is Wolfi''s equivalent of Debian''s "},{"type":"text","marks":[{"type":"code"}],"text":"build-essential"},{"type":"text","text":". "},{"type":"text","marks":[{"type":"code"}],"text":"busybox"},{"type":"text","text":" gives us a usable shell inside the sandbox. "},{"type":"text","marks":[{"type":"code"}],"text":"ca-certificates-bundle"},{"type":"text","text":" lets the fetch step talk to HTTPS."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"},{"type":"code"}],"text":"pipeline"},{"type":"text","text":" is the sequence of build steps. Each step is a named \"use\" of a melange built-in pipeline plus its arguments. "},{"type":"text","marks":[{"type":"code"}],"text":"fetch"},{"type":"text","text":" downloads the tarball and checks the sha256. "},{"type":"text","marks":[{"type":"code"}],"text":"autoconf/configure"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"autoconf/make"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"autoconf/make-install"},{"type":"text","text":" run the conventional autotools chain. "},{"type":"text","marks":[{"type":"code"}],"text":"strip"},{"type":"text","text":" removes debug symbols from the output binaries."}]},{"type":"paragraph","content":[{"type":"text","text":"Build it:"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"melange build melange.yaml \\\n  --arch amd64,arm64 \\\n  --signing-key melange.rsa \\\n  --runner docker"}]},{"type":"paragraph","content":[{"type":"text","text":"If everything worked, you''ll have "},{"type":"text","marks":[{"type":"code"}],"text":"./packages/amd64/hello-2.12.1-r0.apk"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"./packages/arm64/hello-2.12.1-r0.apk"},{"type":"text","text":". melange also wrote an "},{"type":"text","marks":[{"type":"code"}],"text":"APKINDEX.tar.gz"},{"type":"text","text":" next to them, which is the metadata file apko''s apk resolver needs to find your package."}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","marks":[{"type":"code"}],"text":"test:"},{"type":"text","text":" block at the bottom is melange''s smoke test. After the package is built, melange installs it into a fresh sandbox and runs your test pipeline. "},{"type":"text","marks":[{"type":"code"}],"text":"hello --version"},{"type":"text","text":" exits zero, the build is considered successful. If the binary is broken, the build fails before the apk is published."}]},{"type":"heading","attrs":{"level":2,"id":"assembling-an-image-with-apko"},"content":[{"type":"text","text":"Assembling an Image with apko"}]},{"type":"paragraph","content":[{"type":"text","text":"Now build the image. Save this as "},{"type":"text","marks":[{"type":"code"}],"text":"apko.yaml"},{"type":"text","text":":"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"contents:\n  keyring:\n    - https://packages.wolfi.dev/os/wolfi-signing.rsa.pub\n    - ./melange.rsa.pub\n  repositories:\n    - https://packages.wolfi.dev/os\n    - \"@local ./packages\"\n  packages:\n    - wolfi-baselayout\n    - hello@local\n\nentrypoint:\n  command: /usr/bin/hello\n\narchs:\n  - amd64\n  - arm64\n\nannotations:\n  org.opencontainers.image.source: https://github.com/your-org/hello-distroless"}]},{"type":"paragraph","content":[{"type":"text","text":"The interesting line is "},{"type":"text","marks":[{"type":"code"}],"text":"hello@local"},{"type":"text","text":". apko''s apk resolver supports tagged repositories: "},{"type":"text","marks":[{"type":"code"}],"text":"@local ./packages"},{"type":"text","text":" declares a local repository tagged "},{"type":"text","marks":[{"type":"code"}],"text":"local"},{"type":"text","text":", and "},{"type":"text","marks":[{"type":"code"}],"text":"hello@local"},{"type":"text","text":" tells the solver to pull "},{"type":"text","marks":[{"type":"code"}],"text":"hello"},{"type":"text","text":" specifically from that repo. Without the tag, the solver would try to find "},{"type":"text","marks":[{"type":"code"}],"text":"hello"},{"type":"text","text":" in "},{"type":"text","marks":[{"type":"code"}],"text":"packages.wolfi.dev/os"},{"type":"text","text":" and fail."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"wolfi-baselayout"},{"type":"text","text":" is the absolute minimum filesystem skeleton: "},{"type":"text","marks":[{"type":"code"}],"text":"/etc"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"/usr"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"/var"},{"type":"text","text":", the standard directories, plus "},{"type":"text","marks":[{"type":"code"}],"text":"/etc/passwd"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"/etc/group"},{"type":"text","text":" so the container has a "},{"type":"text","marks":[{"type":"code"}],"text":"nobody"},{"type":"text","text":" user. It''s about 100 KB. Everything else in the image is "},{"type":"text","marks":[{"type":"code"}],"text":"hello"},{"type":"text","text":" and its runtime dependencies."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"entrypoint.command"},{"type":"text","text":" is what runs when the container starts. There is no shell to wrap it. The container is "},{"type":"text","marks":[{"type":"code"}],"text":"hello"},{"type":"text","text":" and nothing else."}]},{"type":"paragraph","content":[{"type":"text","text":"Build:"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"apko build apko.yaml \\\n  hello:latest hello.tar \\\n  --keyring-append ./melange.rsa.pub \\\n  --arch amd64,arm64 \\\n  --sbom-path ./sboms"}]},{"type":"paragraph","content":[{"type":"text","text":"apko emits per-architecture OCI tarballs plus an OCI image index, all reproducible. Run the same command on a different machine with the same inputs and the layer digests match exactly. apko zeroes file timestamps and source-of-build metadata by default precisely to make this work."}]},{"type":"heading","attrs":{"level":2,"id":"loading-inspecting-verifying"},"content":[{"type":"text","text":"Loading, Inspecting, Verifying"}]},{"type":"paragraph","content":[{"type":"text","text":"Load and run:"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"docker load < hello.tar\ndocker run --rm hello:latest-amd64\n# > Hello, world!\n\n# Note: the multi-arch tarball loads `hello:latest-amd64` and\n# `hello:latest-arm64` as separate Docker tags (one per arch). If\n# you ran the single-arch quick-start instead, the tag is just\n# `hello:latest` (no suffix).\n\n# Image size: somewhere between 1 and 2 MB.\ndocker image ls hello\n# > REPOSITORY   TAG            SIZE\n# > hello        latest-amd64   1.43MB"}]},{"type":"paragraph","content":[{"type":"text","text":"Try to get a shell. You can''t:"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"docker run --rm --entrypoint /bin/sh hello:latest-amd64\n# > docker: Error response from daemon: failed to create task: ... no such file or directory"}]},{"type":"paragraph","content":[{"type":"text","text":"There is no "},{"type":"text","marks":[{"type":"code"}],"text":"/bin/sh"},{"type":"text","text":", no "},{"type":"text","marks":[{"type":"code"}],"text":"/bin/bash"},{"type":"text","text":", no "},{"type":"text","marks":[{"type":"code"}],"text":"busybox"},{"type":"text","text":", no nothing. An in-application RCE inside "},{"type":"text","marks":[{"type":"code"}],"text":"hello"},{"type":"text","text":" has nowhere to go. The classic post-exploitation playbook of \"drop a webshell, spawn "},{"type":"text","marks":[{"type":"code"}],"text":"bash"},{"type":"text","text":", pivot\" relies on a shell existing in the container. apko removes that primitive."}]},{"type":"paragraph","content":[{"type":"text","text":"Inspect the SBOM:"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"ls ./sboms/\n# > sbom-amd64.spdx.json   sbom-arm64.spdx.json\n\njq ''.packages[].name'' ./sboms/sbom-amd64.spdx.json | sort -u\n# > \"ca-certificates-bundle\"\n# > \"hello\"\n# > \"wolfi-baselayout\""}]},{"type":"paragraph","content":[{"type":"text","text":"That''s the whole image, attributed. Trivy can read this. Grype can read this. Every byte in the layer has a name and a version. If "},{"type":"text","marks":[{"type":"code"}],"text":"wolfi-baselayout"},{"type":"text","text":" gets a CVE next week, your scanner will tell you before you push."}]},{"type":"heading","attrs":{"level":2,"id":"shipping-it-multi-arch-registry-publish-github-actions"},"content":[{"type":"text","text":"Shipping It: Multi-Arch, Registry Publish, GitHub Actions"}]},{"type":"paragraph","content":[{"type":"text","text":"For CI, switch from "},{"type":"text","marks":[{"type":"code"}],"text":"apko build"},{"type":"text","text":" (which writes a tarball) to "},{"type":"text","marks":[{"type":"code"}],"text":"apko publish"},{"type":"text","text":" (which pushes straight to a registry without a Docker daemon):"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"apko publish apko.yaml ghcr.io/your-org/hello:latest \\\n  --keyring-append ./melange.rsa.pub \\\n  --arch amd64,arm64 \\\n  --sbom-path ./sboms"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"apko publish"},{"type":"text","text":" writes both the per-arch images and an OCI index pointing at them, in one call. There''s no "},{"type":"text","marks":[{"type":"code"}],"text":"manifest create"},{"type":"text","text":" dance. "},{"type":"text","marks":[{"type":"code"}],"text":"--sbom-path"},{"type":"text","text":" works the same way it does in "},{"type":"text","marks":[{"type":"code"}],"text":"apko build"},{"type":"text","text":", so the SPDX SBOMs travel with the image whether you push locally or from CI."}]},{"type":"paragraph","content":[{"type":"text","text":"In GitHub Actions, "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/chainguard-dev/actions","target":null,"rel":null,"class":null,"title":null}}],"text":"Chainguard publishes reusable workflows"},{"type":"text","text":" that wire melange and apko together with "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/technology/sigstore","target":null,"rel":null,"class":null,"title":null}}],"text":"Sigstore"},{"type":"text","text":" keyless OIDC signing:"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"jobs:\n  build:\n    runs-on: ubuntu-latest\n    permissions:\n      id-token: write  # for cosign keyless\n      packages: write  # for ghcr.io\n    steps:\n      - uses: actions/checkout@v4\n      - uses: chainguard-dev/actions/melange-build@main\n        with:\n          config: melange.yaml\n          archs: amd64,arm64\n          sign-with-temporary-key: true\n      - uses: chainguard-images/actions/apko-publish@main\n        with:\n          config: apko.yaml\n          tag: ghcr.io/${{ github.repository }}:${{ github.sha }}\n          archs: amd64,arm64\n          keyring-append: melange.rsa.pub\n          sbom-path: ./sboms\n      - uses: sigstore/cosign-installer@v3\n      - run: cosign sign --yes ghcr.io/${{ github.repository }}:${{ github.sha }}"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"sign-with-temporary-key: true"},{"type":"text","text":" is the keyless equivalent for melange: it mints an ephemeral signing key per CI run, signs the apks with it, and discards the private key. The public key travels with the SBOM. "},{"type":"text","marks":[{"type":"code"}],"text":"cosign sign --yes"},{"type":"text","text":" over the resulting image gets a Fulcio-issued certificate tied to the workflow''s OIDC identity. No long-lived key sits in a GitHub secret."}]},{"type":"paragraph","content":[{"type":"text","text":"You can verify the signature anywhere "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/sigstore/cosign","target":null,"rel":null,"class":null,"title":null}}],"text":"cosign"},{"type":"text","text":" runs:"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"cosign verify ghcr.io/your-org/hello:latest \\\n  --certificate-identity-regexp ''https://github.com/your-org/.*'' \\\n  --certificate-oidc-issuer https://token.actions.githubusercontent.com"}]},{"type":"paragraph","content":[{"type":"text","text":"If the binary on the registry was built by a workflow in your org, you get a green check. If anyone replaces it, the signature breaks."}]},{"type":"heading","attrs":{"level":2,"id":"where-this-fits-in-2026"},"content":[{"type":"text","text":"Where This Fits in 2026"}]},{"type":"paragraph","content":[{"type":"text","text":"This stack is the spiritual successor to Google''s "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/GoogleContainerTools/distroless","target":null,"rel":null,"class":null,"title":null}}],"text":"Distroless"},{"type":"text","text":" project. Distroless v1 required ~300 lines of Bazel per image, with every package, version, and dependency pinned by hand. apko delegates that work to the "},{"type":"text","marks":[{"type":"code"}],"text":"apk"},{"type":"text","text":" solver, so you write a dozen lines of YAML instead. The resulting image is smaller (Distroless "},{"type":"text","marks":[{"type":"code"}],"text":"static"},{"type":"text","text":" is ~2 MB; an apko "},{"type":"text","marks":[{"type":"code"}],"text":"wolfi-baselayout"},{"type":"text","text":" image with a small binary is ~1.5 MB), reproducible by default, and built with the same toolchain Chainguard uses to ship its own commercial image catalog."}]},{"type":"paragraph","content":[{"type":"text","text":"Reach for apko when:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You ship Go, Rust, or C++ binaries that are already statically linked or have a small set of runtime dependencies."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You have a security or compliance team that wants SBOMs and signed images, and you don''t want to bolt those on after the fact."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your scanner reports are currently full of \"unknown\" rows and you''d like that to stop."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Don''t reach for apko when:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your build genuinely needs "},{"type":"text","marks":[{"type":"code"}],"text":"RUN"},{"type":"text","text":" steps (compile-time secrets, pre-baked database state, anything that won''t fit a melange pipeline). Build a melange package instead and feed it to apko."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You ship Go-only services and don''t need image-level package management. "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/technology/ko","target":null,"rel":null,"class":null,"title":null}}],"text":"ko"},{"type":"text","text":" is the lighter tool for that case: it skips the apk layer entirely and just packs a Go binary."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You''re committed to a base image from a vendor who doesn''t ship Wolfi packages and you can''t move off it."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"frequently-asked-questions"},"content":[{"type":"text","text":"Frequently asked questions"}]},{"type":"heading","attrs":{"level":3,"id":"do-i-need-to-use-wolfi-or-can-i-build-apko-images-on-alpine"},"content":[{"type":"text","text":"Do I need to use Wolfi, or can I build apko images on Alpine?"}]},{"type":"paragraph","content":[{"type":"text","text":"You can point apko at any apk repository, so plain Alpine still works for legacy or compatibility reasons. Chainguard moved its own images to Wolfi because Wolfi is glibc-based, ships only modern package versions, and is curated specifically for container use. For new projects in 2026, prefer Wolfi unless you have a hard musl or Alpine-tooling dependency."}]},{"type":"heading","attrs":{"level":3,"id":"how-is-this-different-from-a-multi-stage-dockerfile-with-a-scratch-final-image"},"content":[{"type":"text","text":"How is this different from a multi-stage Dockerfile with a scratch final image?"}]},{"type":"paragraph","content":[{"type":"text","text":"A scratch image hides everything from your scanner. Trivy, Grype, and Snyk identify software by reading package manager databases, and a scratch image has none. apko produces an image whose entire contents come from apk packages, so every byte has a name, a version, and a CVE feed entry. You also get a signed SPDX SBOM at build time rather than reconstructing one after the fact."}]},{"type":"heading","attrs":{"level":3,"id":"can-apko-replace-my-dockerfile-entirely"},"content":[{"type":"text","text":"Can apko replace my Dockerfile entirely?"}]},{"type":"paragraph","content":[{"type":"text","text":"Only if everything you need exists as an apk package. apko has no "},{"type":"text","marks":[{"type":"code"}],"text":"RUN"},{"type":"text","text":", no "},{"type":"text","marks":[{"type":"code"}],"text":"COPY"},{"type":"text","text":" from host, no arbitrary shell. That''s the point: it guarantees reproducibility and scanner visibility by refusing to do those things. If you need "},{"type":"text","marks":[{"type":"code"}],"text":"RUN"},{"type":"text","text":" steps, that''s melange''s job: melange builds the apk, apko composes the image, and the two halves cover what a Dockerfile used to do."}]},{"type":"heading","attrs":{"level":3,"id":"how-do-i-sign-the-final-oci-image"},"content":[{"type":"text","text":"How do I sign the final OCI image?"}]},{"type":"paragraph","content":[{"type":"text","text":"melange signs the apk packages with an RSA keypair. To sign the resulting OCI image, use cosign, ideally with keyless OIDC signing in CI so no long-lived key sits in a GitHub secret. The "},{"type":"text","marks":[{"type":"code"}],"text":"chainguard-dev"},{"type":"text","text":" GitHub Actions wire this together: "},{"type":"text","marks":[{"type":"code"}],"text":"melange-build"},{"type":"text","text":" produces signed apks, "},{"type":"text","marks":[{"type":"code"}],"text":"apko-publish"},{"type":"text","text":" builds and pushes the image, and "},{"type":"text","marks":[{"type":"code"}],"text":"cosign sign"},{"type":"text","text":" attests it to the Sigstore Rekor transparency log."}]},{"type":"heading","attrs":{"level":2,"id":"what-to-do-now"},"content":[{"type":"text","text":"What to do now"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Run the "},{"type":"text","marks":[{"type":"code"}],"text":"hello"},{"type":"text","text":" example end-to-end on your laptop. It takes ten minutes and the muscle memory matters."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pick one service you ship today. Look at its current Dockerfile. Count the "},{"type":"text","marks":[{"type":"code"}],"text":"RUN"},{"type":"text","text":" lines. Each one is a place your scanner is currently guessing."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Try replacing it with an apko config. If you need a "},{"type":"text","marks":[{"type":"code"}],"text":"RUN"},{"type":"text","text":" step, that''s a melange package. Build it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Wire up cosign keyless signing in CI. The biggest security win isn''t the distroless image, it''s having a verifiable chain of custody from source commit to running container."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The whole pipeline is two YAML files, four CLI commands, and a couple of hours of work to convert your first service. The payoff is an image that your scanner can actually read, end to end, every release."}]}]}', 'tutorial', 0, 0, NULL, '[]', '[]', NULL, NULL, NULL, NULL, 'apko + melange: Distroless OCI Images Your Scanner Can Actually Read', 'Package, assemble, sign. No Dockerfile, no shell, no surprises.', '[]', '[]', 1779148800000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('apko-melange-tutorial', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('apko-melange-tutorial', 'apko', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('apko-melange-tutorial', 'melange', 1);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('apko-melange-tutorial', 'sigstore', 2);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('our-architecture', 'The Rawkode Academy Architecture', NULL, 'A high-level overview of the Rawkode Academy platform architecture, exploring the innovative patterns and techniques that power our cloud-native platform.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Welcome to the Rawkode Academy! We''re thrilled to start talking about our new platform, designed to provide developers with an immersive and engaging learning experience."}]},{"type":"paragraph","content":[{"type":"text","text":"In this article, we''ll take you behind the scenes, exploring the innovative patterns and techniques we''ve employed to build a robust, scalable, and cloud-native platform. From CQRS and GraphQL Federation to Restate and our unique approach to service-oriented architecture, we''ll delve into the key components that power our platform."}]},{"type":"paragraph","content":[{"type":"text","text":"It''s my job to make content that helps developers learn stuff. That stuff has varied over the last ten years and I assume that will continue to be the case. Which appeals a lot for me, because I like shiny things."}]},{"type":"paragraph","content":[{"type":"text","text":"So when I decided to remove my dependency on YouTube and build my own platform, I decided to have some fun."}]},{"type":"paragraph","content":[{"type":"text","text":"Let me introduce you to the different patterns and techniques we''ve been using to build out the platform."}]},{"type":"paragraph","content":[{"type":"text","text":"This article will be a little high level, but stay tuned! Over the next few weeks we''ll be going deeper into each pattern and technique, with code samples."}]},{"type":"paragraph","content":[{"type":"text","text":"Too impatient? Check out the "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/RawkodeAcademy/RawkodeAcademy","target":null,"rel":null,"class":null,"title":null}}],"text":"repository"},{"type":"text","text":" today."}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2,"id":"cloud-native"},"content":[{"type":"text","text":"Cloud Native"}]},{"type":"paragraph","content":[{"type":"text","text":"Given that I founded the Rawkode Academy to help make Cloud Native, a vast and ever changing landscape, easier for developers; it''s only fitting that whatever I build for the Rawkode Academy is built as Cloud Native as it can be."}]},{"type":"paragraph","content":[{"type":"text","text":"As such, the Rawkode Academy platform is built as a set of micro-services. Some are less micro and some are nano, so let''s just settle on that this is a service-oriented architecture with it sometimes taking some liberties and sometimes going to extremes."}]},{"type":"paragraph","content":[{"type":"text","text":"We also adopted a hybrid-cloud approach, leveraging bare metal, managed Kubernetes, and serverless."}]},{"type":"paragraph","content":[{"type":"text","text":"Depending on what part of the platform you interact with; you''ll be hitting either:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Website:"},{"type":"text","text":" Cloudflare Pages + Workers"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"GraphQL API:"},{"type":"text","text":" Cloud Run"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Video Encoding:"},{"type":"text","text":" Bare Metal on Equinix Metal"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Auth:"},{"type":"text","text":" GKE AutoPilot"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"We use GKE AutoPilot (with Spot) for consistently running services, such as "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://zitadel.com","target":null,"rel":null,"class":null,"title":null}}],"text":"Zitadel"},{"type":"text","text":"."}]}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"I''ve taken a few liberties with the arrows on the diagram below (on the write path) in-order to have the diagram be more readable."}]},{"type":"paragraph","content":[{"type":"text","text":"All write requests, and some read (such as people) go through Zitadel for AuthN."}]},{"type":"diagram","attrs":{"id":"academy-architecture","title":"Academy read and write services","description":"The website queries the Cosmo GraphQL gateway, which routes to five read services and their databases. Each database also connects to a corresponding write service behind the Restate RPC gateway.","language":"d2","source":"# System architecture in D2\nWebsite: Website\n\nCosmo: Cosmo GraphQL Gateway\n\nWebsite -> Cosmo\n\n# GraphQL Read Services\nPeopleGraphQL: People Read\nShowsGraphQL: Shows Read\nShowHostsGraphQL: Show Hosts Read\nVideosGraphQL: Video Read\nTechnologiesGraphQL: Technologies Read\n\nCosmo -> PeopleGraphQL\nCosmo -> ShowsGraphQL\nCosmo -> ShowHostsGraphQL\nCosmo -> VideosGraphQL\nCosmo -> TechnologiesGraphQL\n\n# Databases\nPeopleDB: People Database\nShowsDB: Shows Database\nShowHostsDB: ShowHosts Database\nVideosDB: Videos Database\nTechnologiesDB: Technologies Database\n\nPeopleGraphQL -> PeopleDB\nShowsGraphQL -> ShowsDB\nShowHostsGraphQL -> ShowHostsDB\nVideosGraphQL -> VideosDB\nTechnologiesGraphQL -> TechnologiesDB\n\n# Restate RPC Gateway\nRestate: Restate RPC Gateway\n\n# Restate Write Services\nPeopleRestate: People Write\nShowsRestate: Shows Write\nShowHostsRestate: Show Hosts Write\nVideosRestate: Video Write\nTechnologiesRestate: Technologies Write\n\nPeopleRestate <-> Restate\nShowsRestate <-> Restate\nShowHostsRestate <-> Restate\nVideosRestate <-> Restate\nTechnologiesRestate <-> Restate\n\nPeopleDB <-> PeopleRestate\nShowsDB <-> ShowsRestate\nShowHostsDB <-> ShowHostsRestate\nVideosDB <-> VideosRestate\nTechnologiesDB <-> TechnologiesRestate\n\n# Optional styling (uncomment and modify as needed)\n# direction: right\n# Website.style.fill: lightblue\n# Cosmo.style.fill: lightgreen\n# Restate.style.fill: lightyellow","meta":"sketch","src":"https://content.rawkode.academy/articles/our-architecture/diagrams/4c1747ebe1c00e58.svg"}},{"type":"heading","attrs":{"level":2,"id":"command-query-responsibility-segregation-cqrs"},"content":[{"type":"text","text":"Command Query Responsibility Segregation (CQRS)"}]},{"type":"paragraph","content":[{"type":"text","text":"I''ve been a huge fan of the work of "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://udidahan.com/","target":null,"rel":null,"class":null,"title":null}}],"text":"Udi Dahan"},{"type":"text","text":" and Greg Young for over ten years, even implementing my own CQRS & Event Sourcing libraries in a variety of languages (I actually used this as my project to learn new languages)."}]},{"type":"paragraph","content":[{"type":"text","text":"Event Sourcing wasn''t required for the platform, but CQRS is a fantastic pattern to implement in almost any project. It allows you to separate the read and write models for your application."}]},{"type":"paragraph","content":[{"type":"text","text":"In a strict CQRS fashion, these would likely actually have different views / data stores / projections; but we don''t need to adopt this quite yet."}]},{"type":"paragraph","content":[{"type":"text","text":"Our read API is powered by GraphQL, with federation, and our write API is powered by "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://restate.dev","target":null,"rel":null,"class":null,"title":null}}],"text":"Restate"},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2,"id":"graphql-federation"},"content":[{"type":"text","text":"GraphQL Federation"}]},{"type":"paragraph","content":[{"type":"text","text":"We use a single GraphQL Gateway, powered by "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://cosmo.wundergraph.com","target":null,"rel":null,"class":null,"title":null}}],"text":"WunderGraph Cosmo"},{"type":"text","text":", which can build a query plan for your GraphQL query. This query plan is realised by individual GraphQL APIs, to the object or field level, provided by each service."}]},{"type":"paragraph","content":[{"type":"text","text":"This allows us to have a single endpoint for all our read operations, while still allowing each service to own its data and schema. This is a fantastic pattern for a service-oriented architecture. The icing on the cake for us with this pattern is that with GraphQL Federation we can actually extend the read model and its schemata with new fields, joins, and pretty much anything we need; all without dealing with database migrations."}]},{"type":"paragraph","content":[{"type":"text","text":"We''ll be diving into this in great detail on our next article."}]},{"type":"heading","attrs":{"level":2,"id":"restate"},"content":[{"type":"text","text":"Restate"}]},{"type":"paragraph","content":[{"type":"text","text":"We use Restate as a HTTP RPC layer with built-in queues and durable execution which provides commands to write data to our, currently, shared data stores."}]},{"type":"paragraph","content":[{"type":"text","text":"Currently, each service shares a data store for both reads and writes. We prioritize write optimization through our RPC commands, as read optimization is not yet a concern."}]},{"type":"paragraph","content":[{"type":"text","text":"We''ll dive into our RPC and Restate in a future article, but here''s a quick example of how we use it."}]},{"type":"paragraph","content":[{"type":"text","text":"We used Restate, with its durable execution, as writing to our platform is a complex task."}]},{"type":"paragraph","content":[{"type":"text","text":"Due to the service-oriented architecture, scheduling a new live stream is a multi-part process; but we want a simple command to do so."}]},{"type":"paragraph","content":[{"type":"text","text":"Imagine the following write:"}]},{"type":"codeBlock","attrs":{"language":"shell","title":null,"meta":null},"content":[{"type":"text","text":"curl -XPOST https://rpc.rawkode.academy/live-stream/new -d ''{\n  \"title\": \"Overview of the Rawkode Academy Architecture\",\n  \"hosts\": [ \"rawkode\" ],\n  \"guests\": [ \"icepuma\" ],\n  \"when\": \"2024-12-23Z10:00:00:Z\",\n  \"description\": \"BLAH\",\n  \"technologies\": [\"Restate\", \"Rust\", \"TypeScript\", \"GraphQL\", \"CQRS\"]\n}''"}]},{"type":"paragraph","content":[{"type":"text","text":"This is not a complete example, but to understand the complexity we need to understand this such a request is a "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://microservices.io/patterns/data/saga.html","target":null,"rel":null,"class":null,"title":null}}],"text":"SAGA"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"We need to write multiple entities to multiple services while also ensuring referential integrity across these boundaries."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Can we schedule a live stream for a date in the past? "},{"type":"text","marks":[{"type":"bold"}],"text":"No"},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Can we schedule an episode with host "},{"type":"text","marks":[{"type":"code"}],"text":"rawkode"},{"type":"text","text":" if that identifier doesn''t exist in the "},{"type":"text","marks":[{"type":"code"}],"text":"people"},{"type":"text","text":" service: "},{"type":"text","marks":[{"type":"bold"}],"text":"No"},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Can we schedule an episode with guest "},{"type":"text","marks":[{"type":"code"}],"text":"icepuma"},{"type":"text","text":" if that identifier doesn''t exist in the "},{"type":"text","marks":[{"type":"code"}],"text":"people"},{"type":"text","text":" service: "},{"type":"text","marks":[{"type":"bold"}],"text":"No"},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Same for technologies"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"and so forth"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"We aim to prevent write failures by implementing checks and balances. While eventual consistency is expected in a distributed system, these measures protect the integrity of the read model."}]},{"type":"paragraph","content":[{"type":"text","text":"Again, stay tuned; there''s lots of examples and code we can share to dive into this deeper."}]},{"type":"horizontalRule"},{"type":"paragraph","content":[{"type":"text","text":"In this article, we''ve explored the architecture and design choices behind the Rawkode Academy''s new platform. We highlighted our commitment to a cloud-native, service-oriented approach, leveraging technologies like Cloudflare Pages, Cloud Run, Equinix Metal, and GKE AutoPilot. We also shallow dived into our implementation of CQRS, GraphQL Federation, and Restate, explaining how these patterns contribute to a robust and scalable platform."}]},{"type":"paragraph","content":[{"type":"text","text":"Our use of Restate for durable execution and handling complex write operations, particularly in the context of SAGAs, ensures data integrity and consistency across our distributed services. We''ve also touched on the importance of eventual consistency in such an environment."}]},{"type":"paragraph","content":[{"type":"text","text":"This high-level overview provides a glimpse into the underlying technologies and principles driving the Rawkode Academy platform."}]},{"type":"paragraph","content":[{"type":"text","text":"Stay tuned for upcoming articles where we''ll deep dive into each component with detailed explanations and code samples."}]},{"type":"paragraph","content":[{"type":"text","text":"Don''t want to miss the new articles?"}]},{"type":"paragraph","content":[{"type":"text","text":"Follow our "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://bsky.app/profile/rawkode.academy","target":null,"rel":null,"class":null,"title":null}}],"text":"BlueSky"},{"type":"text","text":" account to keep up to date with the platform build out and our new articles."}]},{"type":"paragraph","content":[{"type":"text","text":"Until next time!"}]}]}', 'article', 0, 0, NULL, '[]', '[]', 'https://content.rawkode.academy/articles/our-architecture/cover.jpg', 'A homemade steampunk Stargate', 2048, 2048, 'Extreme Cloud Native', 'Over-Engineering for Fun & Profit', '[]', '[]', 1734048000000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('our-architecture', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('our-architecture', 'restate', 0);
