INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('automate-google-calendar-invitations-with-slack-and-pipedream', 'Automate Google Calendar Invitations with Slack and Pipedream', NULL, 'When I was working at InfluxData, I put together a programme that aimed to solve a common business ch...', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When I was working at InfluxData, I put together a programme that aimed to solve a common business challenge."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"How do we encourage and enable cross-functional collaboration within a fast moving organisation?"}]},{"type":"paragraph","content":[{"type":"text","text":"Having spent many years working and contributing to open source communities, I''ve seen many governance and collaboration models used across various successful open source projects; but the one that continues to impress me to this day is the Special Interest Groups (SIGs) model used by Kubernetes."}]},{"type":"paragraph","content":[{"type":"text","text":"I was curious what would happen if we adopted SIGs internally to provide guidance around our organisations involvement, support, and enable of our technology within external communities. That is to say that InfluxData had people across multiple disciplines that wished to collaborate on the use of our product within OpenTracing, Kubernetes, Machine Learning, and many other communities and ecosystems; but until then had no structured way to drive that collaboration forward."}]},{"type":"paragraph","content":[{"type":"text","text":"I''m not writing this article to talk about the progress of that programme, perhaps I''ll do that later. What I wanted to write about was one of the challenges we had and how we solved it with a fantastic piece of open source software: "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://www.pipedream.com","target":null,"rel":null,"class":null,"title":null}}],"text":"Pipedream"},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2,"id":"the-problem"},"content":[{"type":"text","text":"The Problem"}]},{"type":"paragraph","content":[{"type":"text","text":"When I put this programme together, one of my goals was for each SIG to be inclusive. This meant that I was keen to avoid any one person controlling the calendar invitations, deciding whom they seen fit to join each SIG. Instead, I wanted each SIG to have a doors open policy that invited anyone and everyone to join their initiatives."}]},{"type":"paragraph","content":[{"type":"text","text":"Google Calendar provides \"Team Calendars\" to help achieve this. The concept is simple, but sadly the implementation is painful. While I was able to successfully create the shared calendar and pass around a link, the link didn''t seem to work for everyone and was cumbersome, at best, to consume."}]},{"type":"paragraph","content":[{"type":"text","text":"More importantly, "},{"type":"text","marks":[{"type":"bold"}],"text":"there''s no discovery of these events, you need to be told to look for them"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"This led to the first few meetings having next to no participation, other than the core people that expressed an interest in the groups upfront."}]},{"type":"heading","attrs":{"level":2,"id":"the-solution"},"content":[{"type":"text","text":"The Solution"}]},{"type":"paragraph","content":[{"type":"text","text":"So I got my thinking hat on. One of the mandates of the SIG programme was that every SIG "},{"type":"text","marks":[{"type":"bold"}],"text":"MUST"},{"type":"text","text":" have a Slack channel, where the chair will share updates after each meeting."}]},{"type":"paragraph","content":[{"type":"text","text":"What if we could consider \"membership\" of the Slack channel as an indicator that they probably want to be aware of the events; hell, even auto-invite them? I kept my thinking hat on 🎩"}]},{"type":"paragraph","content":[{"type":"text","text":"The goal is now this:"}]},{"type":"paragraph","content":[{"type":"text","text":"Whenever anyone joins one of our "},{"type":"text","marks":[{"type":"code"}],"text":"#sig-channels"},{"type":"text","text":" on Slack, we automatically update the Google Calendar event (which still lives in the team calendar) with their email address."}]},{"type":"paragraph","content":[{"type":"text","text":"Lets do this!"}]},{"type":"heading","attrs":{"level":2,"id":"the-implementation"},"content":[{"type":"text","text":"The Implementation"}]},{"type":"paragraph","content":[{"type":"text","text":"I like to avoid writing code or deploying anything as much as possible. NoCode and LowCode solutions are very exciting to me; because they''re enablers for everyone, no matter what your constraints are. My biggest constraint is time, not technical knowledge; but NoCode and LowCode are great enablers, or gateways, for non-technical folk. I love these solutions."}]},{"type":"paragraph","content":[{"type":"text","text":"So I decided to utilise one of these solutions to provide the \"plumbing\" of this auto-inviter, hopefully allowing me to deliver a solution to my problem without writing or deploying any code or containers."}]},{"type":"heading","attrs":{"level":3,"id":"pipedream"},"content":[{"type":"text","text":"Pipedream"}]},{"type":"paragraph","content":[{"type":"text","text":"You can read more about Pipedream at their "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://www.pipedream.com","target":null,"rel":null,"class":null,"title":null}}],"text":"website"},{"type":"text","text":", but I''ll share the first paragraph from their docs:"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Pipedream is an integration platform for developers to build and run workflows that integrate apps, data, and APIs — no servers or infrastructure to manage!"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Develop any workflow, based on any trigger."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Workflows are code, which you can run for free."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No server or cloud resources to manage."}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"It ticked all the boxes I had:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Support Slack and Google Calendar as sources / sinks"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"OpenSource"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"NoCode / LowCode"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SaaS (I didn''t want to deploy anything)"}]}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"It took me 30 minutes to implement this, let me show you how."}]},{"type":"heading","attrs":{"level":3,"id":"step-1-connect-your-accounts"},"content":[{"type":"text","text":"Step 1. Connect Your Accounts"}]},{"type":"paragraph","content":[{"type":"text","text":"I''m not going to cover this really, but Pipedream makes it very easy to connect your Pipedream account with your other services."}]},{"type":"paragraph","content":[{"type":"text","text":"For this tutorial, you need to connect Twitter and Slack using the built-in OAuth prompts."}]},{"type":"heading","attrs":{"level":3,"id":"step-2-prepare-the-webhook"},"content":[{"type":"text","text":"Step 2. Prepare the Webhook"}]},{"type":"paragraph","content":[{"type":"text","text":"I decided that I wanted to use Slack''s webhooks / events API to consume events from Slack. It''s the easiest way to get started and it works really well in a consume and emit / event driven workflow."}]},{"type":"paragraph","content":[{"type":"text","text":"Pipedream provides HTTP endpoints that can receive arbitrary payloads and you can build your workflow around these with ease."}]},{"type":"paragraph","content":[{"type":"text","text":"So I created a webhook using the Pipedream UI and I got a URL like "},{"type":"text","marks":[{"type":"code"}],"text":"https://randomID.m.pipedream.net"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"You can "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://docs.pipedream.com/workflows/steps/triggers/#webhook","target":null,"rel":null,"class":null,"title":null}}],"text":"see how to do this yourself, on their docs"},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":4,"id":"pro-tip"},"content":[{"type":"text","text":"Pro Tip"}]},{"type":"paragraph","content":[{"type":"text","text":"Pipedream allows you to see the payloads that have hit your endpoint. I suggest hooking up your source ASAP and building up a history of payloads to see what you need to handle."}]},{"type":"paragraph","content":[{"type":"text","text":"Pipedream also provides autocomplete based on previous payloads when working with future steps in the workflow."}]},{"type":"paragraph","content":[{"type":"text","text":"Ridiculous, right?"}]},{"type":"paragraph","content":[{"type":"text","text":"🥰🥰🥰"}]},{"type":"heading","attrs":{"level":3,"id":"step-3-slack-challenge"},"content":[{"type":"text","text":"Step 3. Slack Challenge"}]},{"type":"paragraph","content":[{"type":"text","text":"When you add a new receiver for Slack events, it first sends a challenge. You need to be able to respond to this correctly with their challenge string."}]},{"type":"paragraph","content":[{"type":"text","text":"Pipedream allows us to add arbitrary JavaScript to handle payloads through a \"NodeJS Step\". The code I used was really simple."}]},{"type":"codeBlock","attrs":{"language":"javascript","title":null,"meta":null},"content":[{"type":"text","text":"if (event.body && event.body.challenge) {\n  $respond({\n    status: 200,\n    body: event.body.challenge,\n  });\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"We check if the payload contains a "},{"type":"text","marks":[{"type":"code"}],"text":"challenge"},{"type":"text","text":" parameter and we respond with it."}]},{"type":"paragraph","content":[{"type":"text","text":"Next!"}]},{"type":"heading","attrs":{"level":3,"id":"step-4-slack-channel-lookup"},"content":[{"type":"text","text":"Step 4. Slack Channel Lookup"}]},{"type":"paragraph","content":[{"type":"text","text":"I configured the Slack events integration to only send the join channel events. Part of this payload is a channel identifier, but not the channel name. So we need to query the Slack API to get the actual name of the channel."}]},{"type":"paragraph","content":[{"type":"text","text":"We use the NodeJS Step again to build up a config object to send to Slack with "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/axios/axios","target":null,"rel":null,"class":null,"title":null}}],"text":"axios"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Pipedream provides the authentication we need through the "},{"type":"text","marks":[{"type":"code"}],"text":"auths"},{"type":"text","text":" object that is available after we complete the OAuth connection from Step 1."}]},{"type":"paragraph","content":[{"type":"text","text":"We need to configure a "},{"type":"text","marks":[{"type":"code"}],"text":"param"},{"type":"text","text":" for this step, which we can do through the GUI. You add a param called "},{"type":"text","marks":[{"type":"code"}],"text":"channel"},{"type":"text","text":" which using the shiny autocomplete dropdown we can set to "},{"type":"text","marks":[{"type":"code"}],"text":"event.body.event.channel"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"event.body"},{"type":"text","text":" is the payload we receive from Slack, which contains "},{"type":"text","marks":[{"type":"code"}],"text":"event.channel"},{"type":"text","text":"."}]},{"type":"codeBlock","attrs":{"language":"javascript","title":null,"meta":null},"content":[{"type":"text","text":"// See the API docs here: https://api.slack.com/methods/channels.info\nvar include_locale = params.include_locale || false;\nconst config = {\n  url: `https://slack.com/api/conversations.info?channel=${params.channel}&include_locale=${include_locale}`,\n  headers: {\n    Authorization: `Bearer ${auths.slack.oauth_access_token}`,\n    \"Content-Type\": \"application/x-www-form-urlencoded\",\n  },\n};\nconst channel = await require(\"@pipedreamhq/platform\").axios(this, config);\n\nif (channel.ok != true) {\n  $end(\"Couldn''t fetch Channel information\");\n}\n\nthis.channelName = channel.channel.name;\n\nreturn;"}]},{"type":"heading","attrs":{"level":3,"id":"step-4-user-lookup"},"content":[{"type":"text","text":"Step 4. User Lookup"}]},{"type":"paragraph","content":[{"type":"text","text":"Much like the channel lookup, we also need to lookup the user information. We can''t add the Slack ID to a Google Calendar invite, we need their email address."}]},{"type":"paragraph","content":[{"type":"text","text":"This time we configure a param called "},{"type":"text","marks":[{"type":"code"}],"text":"user"},{"type":"text","text":", which comes from "},{"type":"text","marks":[{"type":"code"}],"text":"event.body.event.user"},{"type":"text","text":"."}]},{"type":"codeBlock","attrs":{"language":"javascript","title":null,"meta":null},"content":[{"type":"text","text":"//See the API docs here: https://api.slack.com/methods/users.info\nconst data = {\n  user: params.user,\n  include_locale: params.include_locale || false,\n};\nconst config = {\n  url: `https://slack.com/api/users.info`,\n  headers: {\n    Authorization: `Bearer ${auths.slack.oauth_access_token}`,\n    \"Content-Type\": \"application/x-www-form-urlencoded\",\n  },\n  params: data,\n};\nconst user = await require(\"@pipedreamhq/platform\").axios(this, config);\n\nif (user.ok !== true) {\n  $end(\"Failed to get user information\");\n}\n\nthis.userName = user.user.real_name;\nthis.userEmail = user.user.profile.email;\n\nreturn;"}]},{"type":"heading","attrs":{"level":3,"id":"step-5-add-to-google-calendar-event"},"content":[{"type":"text","text":"Step 5. Add to Google Calendar Event"}]},{"type":"paragraph","content":[{"type":"text","text":"Finally, we want to add them to the invite! Unfortunately you need to hardcode some values here, one identifier for each event. I''m sure there''s a way to do this programmatically with the Google Calendar API, but I''ve not worked that out yet."}]},{"type":"paragraph","content":[{"type":"text","text":"If the channel isn''t one of the expected channels we have an event for; we exit early with "},{"type":"text","marks":[{"type":"code"}],"text":"$end()"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"For channels we do understand, we add the email address to the event. This is idempotent, so we don''t need to check if the user already exists on the invite."}]},{"type":"paragraph","content":[{"type":"text","text":"Pipedream allows us to fetch variables from the previous steps, which we use to get the users name and email address. Neat, huh?"}]},{"type":"paragraph","content":[{"type":"text","text":"This looks like "},{"type":"text","marks":[{"type":"code"}],"text":"steps.slack_get_user_info.userEmail"},{"type":"text","text":", where "},{"type":"text","marks":[{"type":"code"}],"text":"slack_get_user_info"},{"type":"text","text":" is the name of the previous step, and "},{"type":"text","marks":[{"type":"code"}],"text":"userEmail"},{"type":"text","text":" is the variable I \"exposed\" with the "},{"type":"text","marks":[{"type":"code"}],"text":"this.userEmail ="},{"type":"text","text":" syntax."}]},{"type":"codeBlock","attrs":{"language":"javascript","title":null,"meta":null},"content":[{"type":"text","text":"const axios = require(\"axios\");\n\nswitch (steps.slack_get_channel_info.channelName) {\n  case \"sig-kubernetes\":\n    eventId = \"EventID from Google Calendar\";\n    break;\n\n  case \"sig-opentelemetry\":\n    eventId = \"EventID from Google Calendar\";\n    break;\n\n  case \"sig-ml\":\n    eventId = \"EventID from Google Calendar\";\n    break;\n\n  default:\n    $end(\"Not a SIG channel.\");\n    return;\n}\n\ncalendarId = params.calendarId;\n\nevent = await require(\"@pipedreamhq/platform\").axios(this, {\n  url: `https://www.googleapis.com/calendar/v3/calendars/${calendarId}/events/${eventId}`,\n  headers: {\n    Authorization: `Bearer ${auths.google_calendar.oauth_access_token}`,\n  },\n  method: \"GET\",\n});\n\nnewAttendee = {\n  email: steps.slack_get_user_info.userEmail,\n  name: steps.slack_get_user_info.userName,\n};\n\nif (event.attendees) event.attendees.push(newAttendee);\nelse event.attendees = [newAttendee];\ndata = event;\n\nreturn await require(\"@pipedreamhq/platform\").axios(this, {\n  url: `https://www.googleapis.com/calendar/v3/calendars/${calendarId}/events/${eventId}`,\n  headers: {\n    Authorization: `Bearer ${auths.google_calendar.oauth_access_token}`,\n  },\n  method: \"PUT\",\n  data: data,\n});"}]}]}', 'tutorial', 0, 0, NULL, '[]', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1594771200000, 1594771200000, 1790346206000);
