INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('automate-google-calendar-invitations-with-slack-and-pipedream', 'node', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('automate-google-calendar-invitations-with-slack-and-pipedream', 'javascript', 1);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('automate-google-calendar-invitations-with-slack-and-pipedream', 'pipedream', 2);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('automate-google-calendar-invitations-with-slack-and-pipedream', 'slack', 3);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('cgroups-from-chaos-to-control', 'cgroups: From Chaos to Control', NULL, 'Learn Linux cgroups v2 through Docker and Kubernetes examples: memory.max, pids.max, cgroup.subtree_control, OOM kills, and resource-limit debugging.', '', 'guide', 0, 0, NULL, '[]', '[]', 'https://content.rawkode.academy/articles/cgroups-from-chaos-to-control/cover.webp', 'Diagram showing the evolution from fragmented cgroupsv1 hierarchies to the unified cgroupsv2 tree', 1536, 1024, 'Linux cgroups v2: Docker & Kubernetes Resource Control', 'The kernel subsystem under every container', '[]', '[]', 1779062400000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('cgroups-from-chaos-to-control', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('cgroups-from-chaos-to-control', 'kubernetes', 0);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('fluxcd-the-inevitable-choice', 'FluxCD: Why the GitOps Pioneer Remains Its Future', NULL, 'A definitive look at FluxCD''s controller-first design and why its architectural alignment with Kubernetes offers superior security, efficiency, and operational maturity over ArgoCD.', '{"type":"doc","content":[{"type":"aside","attrs":{"variant":"info"},"content":[{"type":"paragraph","content":[{"type":"text","text":"This article is an opinion piece based on the author''s experience. We encourage readers to explore multiple perspectives and form their own informed opinions."}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"The Flux Advantage in 60 Seconds:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Architecture:"},{"type":"text","text":" Flux is a set of discrete, single-purpose controllers that mirror Kubernetes'' own design. Argo is a monolithic bundle of inter-dependent services."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Operations:"},{"type":"text","text":" Flux provides structural failure isolation and precise, per-component scaling. Argo''s bundled design creates systemic failure modes and complex scaling logic."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Security:"},{"type":"text","text":" Flux’s compartmentalized controllers create a minimal, defensible attack surface. Argo''s monolithic "},{"type":"text","marks":[{"type":"code"}],"text":"repo-server"},{"type":"text","text":" is a well-documented source of critical, system-wide CVEs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Extensibility:"},{"type":"text","text":" Flux extends via composable, independent controllers. Argo relies on plugins that create tight operational coupling with its core "},{"type":"text","marks":[{"type":"code"}],"text":"repo-server"},{"type":"text","text":" process."}]}]}]},{"type":"horizontalRule"},{"type":"paragraph","content":[{"type":"text","text":"FluxCD and ArgoCD both promise Git-driven, declarative delivery, but only one of them "},{"type":"text","marks":[{"type":"bold"}],"text":"embraces the DNA of Kubernetes instead of merely co-existing with it"},{"type":"text","text":". Flux''s architecture, composed of single-purpose controllers, is a natural extension of the platform it runs on. If you prioritize operational clarity, security, and long-term cost of ownership, Flux isn''t just another option - it''s the inevitable choice."}]},{"type":"heading","attrs":{"level":3,"id":"lets-be-honest-the-appeal-of-argocd-is-real"},"content":[{"type":"text","text":"Let''s Be Honest: The Appeal of ArgoCD is Real"}]},{"type":"paragraph","content":[{"type":"text","text":"ArgoCD''s popularity isn''t an accident. Its all-in-one installation and polished, built-in user interface provide an outstanding out-of-the-box experience. For teams adopting GitOps for the first time, the "},{"type":"text","marks":[{"type":"code"}],"text":"Application"},{"type":"text","text":" CRD and the web UI offer a shallow learning curve and immediate visual feedback."}]},{"type":"paragraph","content":[{"type":"text","text":"These are significant advantages. However, this initial convenience comes with long-term architectural and operational costs - trade-offs that are often overlooked until a team is operating at scale, where they become impossible to ignore."}]},{"type":"heading","attrs":{"level":3,"id":"architectural-alignment-the-picture-is-clear"},"content":[{"type":"text","text":"Architectural Alignment: The Picture Is Clear"}]},{"type":"paragraph","content":[{"type":"text","text":"Kubernetes succeeds because every task - scheduling, autoscaling, networking - is handled by a dedicated, single-purpose controller. Flux extends this contract seamlessly."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Flux Controller"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Purpose"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Source"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Fetches Git/Helm/OCI artifacts"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Kustomize"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Reconciles Kustomizations"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Helm"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Manages "},{"type":"text","marks":[{"type":"code"}],"text":"HelmRelease"},{"type":"text","text":" objects declaratively"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Notification"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Routes events to Slack, Teams, and webhooks"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Image Automation"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Automatically updates image tags in Git"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Each controller is its own Deployment, upgraded, scaled, and RBAC-scoped in isolation. This gives operators surgical precision. ArgoCD, by contrast, bundles its core logic into three main inter-dependent services - "},{"type":"text","marks":[{"type":"code"}],"text":"repo-server"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"application-controller"},{"type":"text","text":", and "},{"type":"text","marks":[{"type":"code"}],"text":"argocd-server"},{"type":"text","text":" - and often relies on optional Redis and Dex components to handle caching and auth."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"},{"type":"italic"}],"text":"Visualizing the Difference"}]},{"type":"paragraph","content":[{"type":"text","text":"The diagram below illustrates the core architectural divide. On one side, Flux''s controllers operate as independent agents, each with a direct line to the Kubernetes API. On the other, Argo''s core services are bundled, interacting internally before presenting a unified front to the API."}]},{"type":"paragraph","content":[{"type":"text","text":"This distinction isn''t merely academic; it''s the root cause of the operational differences that follow."}]},{"type":"image","attrs":{"src":"https://content.rawkode.academy/articles/fluxcd-the-inevitable-choice/comparison.png","alt":"Architectural diagram comparing Flux''s distributed controllers to Argo''s monolithic services","title":null,"width":1536,"height":1024,"darkSrc":null,"zoomable":false}},{"type":"heading","attrs":{"level":3,"id":"day-two-operations-precision-beats-one-size-scales-all"},"content":[{"type":"text","text":"Day-Two Operations: Precision Beats \"One Size Scales All\""}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Resource Footprint:"},{"type":"text","text":" Flux maintainers state that controllers use "},{"type":"text","marks":[{"type":"bold"}],"text":"~30 MiB of RAM each"},{"type":"text","text":" after bootstrap, though actual usage can vary based on workload. In contrast, ArgoCD''s documentation shows default resource requests of "},{"type":"text","marks":[{"type":"bold"}],"text":"256Mi for the"},{"type":"text","text":" "},{"type":"text","marks":[{"type":"code"}],"text":"repo-server"},{"type":"text","text":" "},{"type":"text","marks":[{"type":"bold"}],"text":"and 1Gi for the"},{"type":"text","text":" "},{"type":"text","marks":[{"type":"code"}],"text":"application-controller"},{"type":"text","text":" - before accounting for Redis. While these are defaults that can be tuned, the architectural difference is clear."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Failure Isolation:"},{"type":"text","text":" If Flux''s "},{"type":"text","marks":[{"type":"code"}],"text":"helm-controller"},{"type":"text","text":" crashes, your Git and Kustomize reconciliations continue to flow. If Argo''s "},{"type":"text","marks":[{"type":"code"}],"text":"repo-server"},{"type":"text","text":" experiences a failure, it can stall manifest rendering for "},{"type":"text","marks":[{"type":"italic"}],"text":"every single application"},{"type":"text","text":" simultaneously."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Scaling:"},{"type":"text","text":" Need to handle more Helm repositories? Simply increase the "},{"type":"text","marks":[{"type":"code"}],"text":"replicas"},{"type":"text","text":" for Flux''s "},{"type":"text","marks":[{"type":"code"}],"text":"source-controller"},{"type":"text","text":". In ArgoCD, scaling often requires enabling and configuring more complex controller sharding logic, managed via environment variables and replica count adjustments."}]}]}]},{"type":"heading","attrs":{"level":3,"id":"security-posture-smaller-binaries-smaller-blast-radius"},"content":[{"type":"text","text":"Security Posture: Smaller Binaries, Smaller Blast Radius"}]},{"type":"paragraph","content":[{"type":"text","text":"Both Flux and ArgoCD achieved "},{"type":"text","marks":[{"type":"bold"}],"text":"CNCF Graduation in late 2022"},{"type":"text","text":", demonstrating their security, governance, and stability. Flux graduated on November 30, 2022, with ArgoCD following shortly after in December 2022."}]},{"type":"paragraph","content":[{"type":"text","text":"Flux''s decomposed architecture means each binary has a limited scope and a smaller attack surface. Meanwhile, Argo''s "},{"type":"text","marks":[{"type":"code"}],"text":"repo-server"},{"type":"text","text":" has experienced several vulnerabilities. For example, "},{"type":"text","marks":[{"type":"bold"}],"text":"CVE-2024-29893"},{"type":"text","text":" allowed a malicious Helm registry to trigger a Denial-of-Service by causing the repo-server to run out of memory during unbounded data fetching. When a single component is responsible for fetching and rendering untrusted multi-tenant resources, its broad scope increases the potential blast radius."}]},{"type":"heading","attrs":{"level":3,"id":"extensibility-rendering-philosophies-reveal-design-principles"},"content":[{"type":"text","text":"Extensibility: Rendering Philosophies Reveal Design Principles"}]},{"type":"paragraph","content":[{"type":"text","text":"Flux''s approach to configuration languages is straightforward: each gets its own dedicated controller. Need KCL support? Deploy the kcl-controller. Want CUE? Add the cue-controller. These controllers operate independently, following the same patterns as every other Flux component. ArgoCD takes a different path. While it can leverage the same operators Flux uses (like External Secrets Operator), its approach to configuration rendering reveals its monolithic nature. Support for languages like KCL or CUE requires either:"}]},{"type":"paragraph","content":[{"type":"text","text":"Config Management Plugins (CMPs) - Scripts that run inside the repo-server, inheriting its permissions and failure modes Sidecar containers - Additional processes coupled to the repo-server''s lifecycle"}]},{"type":"paragraph","content":[{"type":"text","text":"This isn''t just an implementation detail. When your KCL rendering logic crashes in a CMP, it can affect the repo-server''s ability to process other applications. When a Flux kcl-controller crashes, your Helm and Kustomize deployments continue unaffected. The architectural divide is clear: Flux extends through composition of independent controllers, while ArgoCD extends through augmentation of its central rendering service. One scales horizontally with clear failure boundaries; the other scales vertically with shared failure modes."}]},{"type":"paragraph","content":[{"type":"text","text":"Of course, the elephant in the room is that KCL and CUE controllers may not exist yet. But the point is that Flux''s architecture allows for their creation without introducing new monolithic components. This is a design principle that aligns with Kubernetes'' own extensibility philosophy."}]},{"type":"heading","attrs":{"level":3,"id":"but-what-about-applicationsets"},"content":[{"type":"text","text":"But What About ApplicationSets?"}]},{"type":"paragraph","content":[{"type":"text","text":"ArgoCD''s "},{"type":"text","marks":[{"type":"code"}],"text":"ApplicationSet"},{"type":"text","text":" controller is an elegant solution for managing applications across a fleet of clusters. It is, deservedly, a killer feature."}]},{"type":"paragraph","content":[{"type":"text","text":"Flux achieves the same outcome, albeit in a more Kubernetes-native way, by composing its existing APIs. Using a combination of the "},{"type":"text","marks":[{"type":"bold"}],"text":"Flux "},{"type":"text","marks":[{"type":"bold"},{"type":"code"}],"text":"Provider"},{"type":"text","marks":[{"type":"bold"}],"text":" for Terraform"},{"type":"text","text":" or by templating "},{"type":"text","marks":[{"type":"code"}],"text":"Kustomization"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"HelmRelease"},{"type":"text","text":" objects, a single source of truth can be used to stamp out configuration for dozens of clusters. While this may require a deeper understanding of the underlying tools, it avoids introducing another proprietary abstraction layer and keeps the management paradigm consistent with Kubernetes itself."}]},{"type":"heading","attrs":{"level":3,"id":"the-gui-a-red-herring"},"content":[{"type":"text","text":"The GUI: A Red Herring"}]},{"type":"paragraph","content":[{"type":"text","text":"Argo''s built-in dashboard is excellent, but this convenience isn''t exclusive. The GitOps ecosystem provides purpose-built front-ends for Flux, such as "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/gimlet-io/capacitor","target":null,"rel":null,"class":null,"title":null}},{"type":"bold"}],"text":"Capacitor"},{"type":"text","text":" and the "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/headlamp-k8s/plugins/tree/main/flux","target":null,"rel":null,"class":null,"title":null}},{"type":"bold"}],"text":"Headlamp Flux plugin"},{"type":"text","text":". This gives Flux users a choice of UIs "},{"type":"text","marks":[{"type":"bold"}],"text":"without forcing them to run and secure an always-on web server in every production cluster."}]},{"type":"heading","attrs":{"level":3,"id":"conclusion-choose-the-tool-that-aligns-with-your-future"},"content":[{"type":"text","text":"Conclusion: Choose the Tool That Aligns With Your Future"}]},{"type":"paragraph","content":[{"type":"text","text":"ArgoCD is an excellent tool that provides a fantastic on-ramp to GitOps. Both projects have proven their production readiness through CNCF graduation. But production engineering isn''t about on-ramps; it''s about "},{"type":"text","marks":[{"type":"bold"}],"text":"mean-time-to-recover, total cost of ownership, and security posture"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"On the metrics that matter for mature, at-scale operations - architecture, security, and efficiency - FluxCD offers compelling advantages. It is built not just to integrate with Kubernetes, but to reflect its core design principles."}]},{"type":"paragraph","content":[{"type":"text","text":"Stop paying a long-term operational tax for short-term convenience. Run GitOps the Kubernetes way."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Choose FluxCD."}]}]}', 'article', 0, 0, NULL, '[]', '[]', 'https://content.rawkode.academy/articles/fluxcd-the-inevitable-choice/cover.png', 'Neon-outline illustration of the Flux logo (diamond with upward arrow) on a dark grid, emitting glowing blue-to-purple streams that flow into a neon Kubernetes wheel inside a hexagon - conveying a dynamic GitOps pipeline from Flux to Kubernetes.', 1536, 1024, 'FluxCD vs. ArgoCD: The Final Word', 'Beyond initial convenience lies architectural truth.', '[]', '[]', 1752537600000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('fluxcd-the-inevitable-choice', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('fluxcd-the-inevitable-choice', 'fluxcd', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('fluxcd-the-inevitable-choice', 'kubernetes', 1);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('contributing-to-nixpkgs', 'Contributing to nixpkgs', NULL, 'I''ve been using NixOS, on and off, for around 2 years now. It''s got its challenges, which usually mea...', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I''ve been using "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://nixos.org/","target":null,"rel":null,"class":null,"title":null}}],"text":"NixOS"},{"type":"text","text":", on and off, for around 2 years now. It''s got its challenges, which usually means I switch back to Arch after a few weeks; but not this time ... I''m not switching back."}]},{"type":"paragraph","content":[{"type":"text","text":"As I stumble my way through the trials and tribulations of Nix, NixOS, and nixpkgs; I''ll document my path so that others can learn from my misery. Starting right now ..."}]},{"type":"heading","attrs":{"level":2,"id":"what-is-nix--nixos"},"content":[{"type":"text","text":"What is Nix / NixOS?"}]},{"type":"paragraph","content":[{"type":"text","text":"This is from the NixOS website:"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Nix is a powerful package manager for Linux and other Unix systems that makes package management reliable and reproducible. Share your development and build environments across different machines."}]},{"type":"paragraph","content":[{"type":"text","text":"NixOS is a Linux distribution with a unique approach to package and configuration management. Built on top of the Nix package manager, it is completely declarative, makes upgrading systems reliable, and has many other advantages."}]}]},{"type":"heading","attrs":{"level":2,"id":"contributing-a-gnome-extension-to-nixpkgs"},"content":[{"type":"text","text":"Contributing a GNOME Extension to nixpkgs"}]},{"type":"paragraph","content":[{"type":"text","text":"In this article, I am going to walk you through the steps I''ve taken to contribute a GNOME Extension to the nixpkgs repository. The extension is one that I just CAN''T live without, the "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/maoschanz/emoji-selector-for-gnome","target":null,"rel":null,"class":null,"title":null}}],"text":"emoji selector"},{"type":"text","text":" 😹🌟🥰"}]},{"type":"paragraph","content":[{"type":"text","text":"This wasn''t my first contribution to "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/NixOS/nixpkgs/pulls?q=is%3Apr+author%3Arawkode+is%3Aclosed","target":null,"rel":null,"class":null,"title":null}}],"text":"nixpkgs"},{"type":"text","text":", I''ve sent 16 pull requests to nixpkgs since August 2018 ... and I still have no idea what I''m doing 😂"}]},{"type":"paragraph","content":[{"type":"text","text":"OK. That''s a lie, I know enough to be dangerous, but not enough to be smart."}]},{"type":"paragraph","content":[{"type":"text","text":"Lets try this, one step at a time."}]},{"type":"heading","attrs":{"level":3,"id":"step-1-clone-the-repository"},"content":[{"type":"text","text":"Step 1. Clone the Repository"}]},{"type":"paragraph","content":[{"type":"text","text":"Not much needs said about this, right?"}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"git clone https://github.com/NixOS/nixpkgs"}]},{"type":"heading","attrs":{"level":3,"id":"step-2-find-something-similiar"},"content":[{"type":"text","text":"Step 2. Find Something Similiar"}]},{"type":"paragraph","content":[{"type":"text","text":"I''m not a huge fan of reinventing the wheel. I''m certainly not going to type a bunch of Nix code that shares about 95% of it''s logic with many other packages already contributed to the nixpkgs repository."}]},{"type":"paragraph","content":[{"type":"text","text":"Fortunately for us, this repository is segmented really well."}]},{"type":"paragraph","content":[{"type":"text","text":"First, all packages live under "},{"type":"text","marks":[{"type":"code"}],"text":"./pkgs"},{"type":"text","text":"."}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"drwxr-xr-x - rawkode 11 Jul 13:34 -- applications\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- build-support\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- common-updater\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- data\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- desktops\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- development\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- games\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- misc\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- os-specific\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- servers\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- shells\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- stdenv\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- test\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- tools\ndrwxr-xr-x - rawkode 14 Jul 23:40 -- top-level"}]},{"type":"paragraph","content":[{"type":"text","text":"As you can see, there''s directories for desktop applications, development stuff, games, and a few other categories."}]},{"type":"paragraph","content":[{"type":"text","text":"Inside of "},{"type":"text","marks":[{"type":"code"}],"text":"desktops"},{"type":"text","text":", we can see:"}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"drwxr-xr-x - rawkode 11 Jul 13:34 -- cdesktopenv\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- cinnamon\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- deepin\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- enlightenment\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- gnome-2\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- gnome-3\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- gnustep\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- lumina\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- lxde\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- lxqt\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- mate\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- pantheon\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- plasma-5\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- rox\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- surf-display\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- xfce"}]},{"type":"paragraph","content":[{"type":"text","text":"Pretty much every desktop environment there is ... and if you''re shouting in your head \"WHAT ABOUT MY SHITTY ESOTERIC TILING WINDOW MANAGER?\" ... then I''ve got you; it''s under "},{"type":"text","marks":[{"type":"code"}],"text":"./applications/window-managers"},{"type":"text","text":". I love i3, but it''s also quite nice being able to change the volume or pair bluetooth headphones without having to put my beer down and grep some shell history."}]},{"type":"paragraph","content":[{"type":"text","text":"Notice how I delicately said \"shell history\" and not "},{"type":"text","marks":[{"type":"code"}],"text":"zsh"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"bash"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"fish"},{"type":"text","text":", or "},{"type":"text","marks":[{"type":"code"}],"text":"nu"},{"type":"text","text":" ... I can''t be bothered getting into another shell debate; 2020''s been shit enough."}]},{"type":"paragraph","content":[{"type":"text","text":"Sorry, I''ve digressed."}]},{"type":"paragraph","content":[{"type":"text","text":"Lets move forward. I''ve found some similiar packages. I''ve redacted some of the extensions below ... mostly at random; but you can see that we''re in the "},{"type":"text","marks":[{"type":"code"}],"text":"./pkgs/desktops/gnome-3/extensions"},{"type":"text","text":" directory and we have a fair number of example packages to use as a base for our new one."}]},{"type":"paragraph","content":[{"type":"text","text":"Perfect."}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"pwd\n\n/home/rawkode/Code/src/github.com/NixOS/nixpkgs/pkgs/desktops/gnome-3/extensions"}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"ll\n\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- appindicator\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- arc-menu\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- caffeine\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- dash-to-dock\ndrwxr-xr-x - rawkode 11 Jul 21:39 -- dash-to-panel\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- paperwm\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- sound-output-device-chooser\ndrwxr-xr-x - rawkode 11 Jul 13:34 -- topicons-plus"}]},{"type":"heading","attrs":{"level":3,"id":"step-3-creating-our-package"},"content":[{"type":"text","text":"Step 3. Creating Our Package"}]},{"type":"paragraph","content":[{"type":"text","text":"I need to create a new directory with a "},{"type":"text","marks":[{"type":"code"}],"text":"default.nix"},{"type":"text","text":" and copy over my example Nix from the sample extension. I started with "},{"type":"text","marks":[{"type":"code"}],"text":"dash-to-panel"},{"type":"text","text":", as I like that extension. The code for that looks like so:"}]},{"type":"codeBlock","attrs":{"language":"nix","title":null,"meta":null},"content":[{"type":"text","text":"{ stdenv, fetchFromGitHub, glib, gettext }:\n\nstdenv.mkDerivation rec {\n  pname = \"gnome-shell-dash-to-panel\";\n  version = \"31\";\n\n  src = fetchFromGitHub {\n    owner = \"home-sweet-gnome\";\n    repo = \"dash-to-panel\";\n    rev = \"v${version}\";\n    sha256 = \"0vh36mdncjvfp1jbinifznj5dw3ahsswwm3m9sjw5gydsbx6vh83\";\n  };\n\n  buildInputs = [\n    glib gettext\n  ];\n\n  makeFlags = [ \"INSTALLBASE=$(out)/share/gnome-shell/extensions\" ];\n\n  uuid = \"dash-to-panel@jderose9.github.com\";\n\n  meta = with stdenv.lib; {\n    description = \"An icon taskbar for Gnome Shell\";\n    license = licenses.gpl2;\n    maintainers = with maintainers; [ mounium ];\n    homepage = \"https://github.com/jderose9/dash-to-panel\";\n  };\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"Unfortunately, there was a problem. This extension uses a "},{"type":"text","marks":[{"type":"code"}],"text":"Makefile"},{"type":"text","text":" to document its build steps (which I recommend for ALL repositories), but unfortunately; emoji-selector doesn''t ship with a "},{"type":"text","marks":[{"type":"code"}],"text":"Makefile"},{"type":"text","text":" 😢"}]},{"type":"paragraph","content":[{"type":"text","text":"So I''m going to copy the \"core\" sections and make up the rest from another example shortly."}]},{"type":"paragraph","content":[{"type":"text","text":"What I copied looked like so:"}]},{"type":"codeBlock","attrs":{"language":"nix","title":null,"meta":null},"content":[{"type":"text","text":"{ stdenv, fetchFromGitHub, glib, gettext }:\n\nstdenv.mkDerivation rec {\n  pname = \"gnome-shell-emoji-selector\";\n  version = \"19\";\n\n  src = fetchFromGitHub {\n    owner = \"maoschanz\";\n    repo = \"emoji-selector-for-gnome\";\n    rev = \"${version}\";\n    sha256 = \"0x60pg5nl5d73av494dg29hyfml7fbf2d03wm053vx1q8a3pxbyb\";\n  };\n\n  buildInputs = [ glib ];\n\n  meta = with stdenv.lib; {\n    description =\n      \"This GNOME shell extension provides a searchable popup menu displaying most emojis\";\n    license = licenses.gpl3;\n    maintainers = with maintainers; [ rawkode ];\n    homepage = \"https://github.com/maoschanz/emoji-selector-for-gnome\";\n  };\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"Lets break this down."}]},{"type":"codeBlock","attrs":{"language":"nix","title":null,"meta":null},"content":[{"type":"text","text":"{ stdenv, fetchFromGitHub, glib, gettext }:"}]},{"type":"paragraph","content":[{"type":"text","text":"This first line of Nix is in almost every Nix file you''ll work with. It''s the imports / dependencies that our Nix script needs from the environment / runtime."}]},{"type":"paragraph","content":[{"type":"text","text":"I like to think of it as similiar to JavaScript''s destructing syntax; selecting only the values we need from the global list. If that''s a terrible way to think about it, I''m sure someone from HackerNews will be along shortly."}]},{"type":"codeBlock","attrs":{"language":"nix","title":null,"meta":null},"content":[{"type":"text","text":"stdenv.mkDerivation rec {\n  ...\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"Next up, we need to create a derivation. That''s fancy functional talk for a set of values that allow for some output to be derived."}]},{"type":"paragraph","content":[{"type":"text","text":"The set that we need to build our GNOME Extension contain some obvious facts:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"GitHub Repository"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Version / Branch"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dependencies (Inputs)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Meta Description"}]}]}]},{"type":"codeBlock","attrs":{"language":"nix","title":null,"meta":null},"content":[{"type":"text","text":"  pname = \"gnome-shell-emoji-selector\";\n  version = \"19\";"}]},{"type":"paragraph","content":[{"type":"text","text":"We define the package name and the version. The version is a tag / branch name that you can get from the Git repository or the GitHub UI."}]},{"type":"codeBlock","attrs":{"language":"nix","title":null,"meta":null},"content":[{"type":"text","text":"  src = fetchFromGitHub {\n    owner = \"maoschanz\";\n    repo = \"emoji-selector-for-gnome\";\n    rev = \"${version}\";\n    sha256 = \"0x60pg5nl5d73av494dg29hyfml7fbf2d03wm053vx1q8a3pxbyb\";\n  };"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"fetchFromGitHub"},{"type":"text","text":" is a function that grabs some source code from GitHub. The owner, repo, and rev are hopefully self-explanitory. However, we also have "},{"type":"text","marks":[{"type":"code"}],"text":"sha256"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Nix requires builds to be idempotent. That means it uses the sha to verify that the downloaded and extracted code is what we expected. If it''s different, it''ll let us know and we can decide what we want to do."}]},{"type":"heading","attrs":{"level":4,"id":"warning"},"content":[{"type":"text","text":"Warning"}]},{"type":"paragraph","content":[{"type":"text","text":"Word of warning ... if the sha that you use already exists in the Nix store (meaning you copied it from another example that you had installed), then Nix bypasses the download step and reuses the local files. This means that I ... you, will install some random extension instead of getting the actual download you expected."}]},{"type":"heading","attrs":{"level":4,"id":"how-do-we-get-the-sha"},"content":[{"type":"text","text":"How Do We Get the Sha?"}]},{"type":"paragraph","content":[{"type":"text","text":"The simplest way is to use lots of 0''s. When you try to build this derivation, Nix will complain that your sha256 doesn''t match the repositories download. You can then copy the sha and update in your derivation."}]},{"type":"paragraph","content":[{"type":"text","text":"Another approach is to calculate the actual sha yourself, using "},{"type":"text","marks":[{"type":"code"}],"text":"nix-prefetch-url"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Go to GitHub and grab the URL for the "},{"type":"text","marks":[{"type":"code"}],"text":"tar.gz"},{"type":"text","text":" artefact on the releases page for the revision or version that you want to add to the repository. Now you can run:"}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"nix-prefetch-url --unpack https://github.com/maoschanz/emoji-selector-for-gnome/archive/19.tar.gz\n\nunpacking...\n[1.0 MiB DL]\npath is ''/nix/store/694kcbsz38rni0lykffv89ndivgcccks-19.tar.gz''\n0x60pg5nl5d73av494dg29hyfml7fbf2d03wm053vx1q8a3pxbyb"}]},{"type":"heading","attrs":{"level":4,"id":"meta"},"content":[{"type":"text","text":"Meta"}]},{"type":"paragraph","content":[{"type":"text","text":"This is mostly self-explanitory. Just remember to check the license of the package you''re adding and update "},{"type":"text","marks":[{"type":"code"}],"text":"license ="},{"type":"text","text":". I use the "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/NixOS/nixpkgs/blob/master/lib/licenses.nix","target":null,"rel":null,"class":null,"title":null}}],"text":"source code"},{"type":"text","text":" to check the correct way to reference the licenses."}]},{"type":"codeBlock","attrs":{"language":"nix","title":null,"meta":null},"content":[{"type":"text","text":"  meta = with stdenv.lib; {\n    description =\n      \"This GNOME shell extension provides a searchable popup menu displaying most emojis\";\n    license = licenses.gpl3Plus;\n    maintainers = with maintainers; [ rawkode ];\n    homepage = \"https://github.com/maoschanz/emoji-selector-for-gnome\";\n  };"}]},{"type":"heading","attrs":{"level":4,"id":"dependencies"},"content":[{"type":"text","text":"Dependencies"}]},{"type":"paragraph","content":[{"type":"text","text":"Understanding the dependencies you need to build a new Nix package can be a little intimidating."}]},{"type":"paragraph","content":[{"type":"text","text":"Fortunately for GNOME Extensions, these don''t vary too much and our example actually had this listed."}]},{"type":"codeBlock","attrs":{"language":"nix","title":null,"meta":null},"content":[{"type":"text","text":"buildInputs = [ glib ];"}]},{"type":"paragraph","content":[{"type":"text","text":"If you need to work this out for another package and you don''t know where to start? Follow these steps:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clone Code"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enter directory"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Create a Nix Shell (nix-shell -p depenendency1 depenendency2 ...)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Run Build Command"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Repeat this, adding whatever you need to "},{"type":"text","marks":[{"type":"code"}],"text":"nix-shell -p"},{"type":"text","text":" until the build step works."}]},{"type":"paragraph","content":[{"type":"text","text":"If you don''t know what your dependency you need is called, search on the "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://nixos.org/nixos/packages.html?channel=nixpkgs-unstable","target":null,"rel":null,"class":null,"title":null}}],"text":"Nix Package"},{"type":"text","text":" page."}]},{"type":"paragraph","content":[{"type":"text","text":"Example, if I need to build some code that needs Rust, Make, and bash - I''d run: "},{"type":"text","marks":[{"type":"code"}],"text":"nix-shell -p bash cargo gnumake rustc"}]},{"type":"paragraph","content":[{"type":"text","text":"To use our repository as an example, if I ran "},{"type":"text","marks":[{"type":"code"}],"text":"nix-shell"},{"type":"text","text":" with no dependencies and then ran "},{"type":"text","marks":[{"type":"code"}],"text":"./install.sh"},{"type":"text","text":" - then our install would have failed with "},{"type":"text","marks":[{"type":"code"}],"text":"glib-compile-schemas"},{"type":"text","text":" command not found; which is provided by "},{"type":"text","marks":[{"type":"code"}],"text":"glib"},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":4,"id":"skipped-makefile"},"content":[{"type":"text","text":"Skipped Makefile"}]},{"type":"paragraph","content":[{"type":"text","text":"So I said that we had a problem, the problem was that our example extension used "},{"type":"text","marks":[{"type":"code"}],"text":"make"},{"type":"text","text":" and our current extension doesn''t. We know this because our example Nix contained:"}]},{"type":"codeBlock","attrs":{"language":"nix","title":null,"meta":null},"content":[{"type":"text","text":"makeFlags = [ \"INSTALLBASE=$(out)/share/gnome-shell/extensions\" ];"}]},{"type":"paragraph","content":[{"type":"text","text":"and our extension repository doesn''t have a "},{"type":"text","marks":[{"type":"code"}],"text":"Makefile"},{"type":"text","text":", it only has "},{"type":"text","marks":[{"type":"code"}],"text":"./install.sh"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Drats."}]},{"type":"paragraph","content":[{"type":"text","text":"Fortunately, I looked at another example (caffeine) and came across the following code. It turns out that we can manually configure the build steps ourself. Sweet! 🥞"}]},{"type":"codeBlock","attrs":{"language":"nix","title":null,"meta":null},"content":[{"type":"text","text":"  uuid = \"caffeine@patapon.info\";\n\n  nativeBuildInputs = [\n    glib gettext\n  ];\n\n  buildPhase = ''''\n    ${bash}/bin/bash ./update-locale.sh\n    glib-compile-schemas --strict --targetdir=caffeine@patapon.info/schemas/ caffeine@patapon.info/schemas\n  '''';\n\n  installPhase = ''''\n    mkdir -p $out/share/gnome-shell/extensions\n    cp -r ${uuid} $out/share/gnome-shell/extensions\n  '''';"}]},{"type":"heading","attrs":{"level":5,"id":"customizing-the-build"},"content":[{"type":"text","text":"Customizing the Build"}]},{"type":"paragraph","content":[{"type":"text","text":"In the code above, we''ve removed the "},{"type":"text","marks":[{"type":"code"}],"text":"makeFlags"},{"type":"text","text":" configuration that we found in the "},{"type":"text","marks":[{"type":"code"}],"text":"dash-to-panel"},{"type":"text","text":" Nix package, because "},{"type":"text","marks":[{"type":"code"}],"text":"emoji-selector"},{"type":"text","text":" doesn''t have a "},{"type":"text","marks":[{"type":"code"}],"text":"Makefile"},{"type":"text","text":". We''ve instead provided "},{"type":"text","marks":[{"type":"code"}],"text":"buildPhase"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"installPhase"},{"type":"text","text":" configuration. These two different \"examples\" also used slightly different inputs: "},{"type":"text","marks":[{"type":"code"}],"text":"buildInputs"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"nativeBuildInputs"}]},{"type":"paragraph","content":[{"type":"text","text":"Argh. What?"}]},{"type":"paragraph","content":[{"type":"text","text":"First, "},{"type":"text","marks":[{"type":"code"}],"text":"buildInputs"},{"type":"text","text":" vs "},{"type":"text","marks":[{"type":"code"}],"text":"nativeBuildInputs"},{"type":"text","text":". This was tricky to track down, it''s not that well documented. However, I did "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://nixos.org/nixpkgs/manual/#ssec-stdenv-dependencies","target":null,"rel":null,"class":null,"title":null}}],"text":"find the following"},{"type":"text","text":":"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"nativeBuildInputs A list of dependencies whose host platform is the new derivation''s build platform, and target platform is the new derivation''s host platform. This means a -1 host offset and 0 target offset from the new derivation''s platforms. These are programs and libraries used at build-time that, if they are a compiler or similar tool, produce code to run at run-time—i.e. tools used to build the new derivation. If the dependency doesn''t care about the target platform (i.e. isn''t a compiler or similar tool), put it here, rather than in depsBuildBuild or depsBuildTarget. This could be called depsBuildHost but nativeBuildInputs is used for historical continuity."}]}]},{"type":"paragraph","content":[{"type":"text","text":"That''s a mouthful. As I understand it, we use "},{"type":"text","marks":[{"type":"code"}],"text":"nativeBuildInputs"},{"type":"text","text":" when we expect the inputs to be build for the platform on our local machine; and can use "},{"type":"text","marks":[{"type":"code"}],"text":"buildInputs"},{"type":"text","text":" for when we don''t have such a constraint. I definitely need to understand this more and I''ll write more on this parameter soon; once I''ve done some more digging 😃"}]},{"type":"paragraph","content":[{"type":"text","text":"Next, those phases!"}]},{"type":"paragraph","content":[{"type":"text","text":"From the "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://nixos.org/nixpkgs/manual/#ssec-stdenv-attributes","target":null,"rel":null,"class":null,"title":null}}],"text":"documentation"},{"type":"text","text":"; we can see that there''s many phases in a build:"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"$prePhases unpackPhase patchPhase $preConfigurePhases configurePhase $preBuildPhases buildPhase checkPhase $preInstallPhases installPhase fixupPhase installCheckPhase $preDistPhases distPhase $postPhases."}]}]},{"type":"paragraph","content":[{"type":"text","text":"Each of these are called in this order, unless specifically overridden by the Nix package by providing "},{"type":"text","marks":[{"type":"code"}],"text":"phases = []"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"We need to override the "},{"type":"text","marks":[{"type":"code"}],"text":"buildPhase"},{"type":"text","text":" because "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://nixos.org/nixpkgs/manual/#build-phase","target":null,"rel":null,"class":null,"title":null}}],"text":"by default"},{"type":"text","text":" it runs "},{"type":"text","marks":[{"type":"code"}],"text":"make"},{"type":"text","text":"."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"The default buildPhase simply calls make if a file named Makefile, makefile or GNUmakefile exists in the current directory (or the makefile is explicitly set); otherwise it does nothing."}]}]},{"type":"paragraph","content":[{"type":"text","text":"This is also true for "},{"type":"text","marks":[{"type":"code"}],"text":"installPhase"},{"type":"text","text":", only it tries to run the "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://nixos.org/nixpkgs/manual/#ssec-install-phase","target":null,"rel":null,"class":null,"title":null}}],"text":"install target"},{"type":"text","text":"."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"The default installPhase creates the directory $out and calls make install."}]}]},{"type":"paragraph","content":[{"type":"text","text":"It''s a little less magic when you break it down; right? 🧙"}]},{"type":"heading","attrs":{"level":3,"id":"testing-our-package"},"content":[{"type":"text","text":"Testing Our Package"}]},{"type":"paragraph","content":[{"type":"text","text":"Using the commands inside of "},{"type":"text","marks":[{"type":"code"}],"text":"./install.sh"},{"type":"text","text":", I was able to piece together the config we needed for our extension to be successfully build and installed by "},{"type":"text","marks":[{"type":"code"}],"text":"nix"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"The only \"gotcha\" here is that Nix provides "},{"type":"text","marks":[{"type":"code"}],"text":"$out"},{"type":"text","text":" variable that provides the directory our package should install things into."}]},{"type":"codeBlock","attrs":{"language":"nix","title":null,"meta":null},"content":[{"type":"text","text":"{ stdenv, fetchFromGitHub, glib, gettext }:\n\nstdenv.mkDerivation rec {\n  pname = \"gnome-shell-emoji-selector\";\n  version = \"19\";\n\n  src = fetchFromGitHub {\n    owner = \"maoschanz\";\n    repo = \"emoji-selector-for-gnome\";\n    rev = \"${version}\";\n    sha256 = \"0x60pg5nl5d73av494dg29hyfml7fbf2d03wm053vx1q8a3pxbyb\";\n  };\n\n  uuid = \"emoji-selector@maestroschan.fr\";\n\n  nativeBuildInputs = [ glib ];\n\n  buildPhase = ''''\n    runHooks preBuild\n    glib-compile-schemas ./${uuid}/schemas\n    runHooks postBuild\n  '''';\n\n  installPhase = ''''\n    runHook preInstall\n    mkdir -p $out/share/gnome-shell/extensions\n    cp -r ${uuid} $out/share/gnome-shell/extensions\n    runHook postInstall\n  '''';\n\n  meta = with stdenv.lib; {\n    description =\n      \"This GNOME shell extension provides a searchable popup menu displaying most emojis\";\n    license = licenses.gpl3Plus;\n    maintainers = with maintainers; [ rawkode ];\n    homepage = \"https://github.com/maoschanz/emoji-selector-for-gnome\";\n  };\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"So how do we test this to make sure it works?"}]},{"type":"paragraph","content":[{"type":"text","text":"We can install it 😁"}]},{"type":"paragraph","content":[{"type":"text","text":"To do that, we need to "},{"type":"text","marks":[{"type":"code"}],"text":"cd"},{"type":"text","text":" into the "},{"type":"text","marks":[{"type":"code"}],"text":"nixpkgs"},{"type":"text","text":" directory; then install our package using "},{"type":"text","marks":[{"type":"code"}],"text":"nix-env"},{"type":"text","text":" and the package name we declared above."}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"cd ~/Code/src/github.com/NixOS/nixpkgs\nnix-env -f $(pwd) -i gnome-shell-emoji-selector"}]},{"type":"paragraph","content":[{"type":"text","text":"Assuming all goes to plan, you''ll see something like:"}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"installing ''gnome-shell-emoji-selector-19''\nnix-env -f $(pwd) -i gnome-shell-emoji-selector  5.30s user 0.43s system 97% cpu 5.873 total"}]},{"type":"paragraph","content":[{"type":"text","text":"🎉🎉🎉 We did it! 🎉🎉🎉"}]},{"type":"paragraph","content":[{"type":"text","text":"Our package installed. Well done. Fire open GitHub and submit a PR."}]},{"type":"heading","attrs":{"level":2,"id":"whats-next"},"content":[{"type":"text","text":"What''s Next?"}]},{"type":"paragraph","content":[{"type":"text","text":"There''s still a fair amount to cover. When you submit a PR, you''ll be presented with this checklist:"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"- [ ] Tested using sandboxing ([nix.useSandbox](https://nixos.org/nixos/manual/options.html#opt-nix.useSandbox) on NixOS, or option `sandbox` in [`nix.conf`](https://nixos.org/nix/manual/#sec-conf-file) on non-NixOS linux)\n- Built on platform(s)\n   - [x] NixOS\n   - [ ] macOS\n   - [ ] other Linux distributions\n- [ ] Tested via one or more NixOS test(s) if existing and applicable for the change (look inside [nixos/tests](https://github.com/NixOS/nixpkgs/blob/master/nixos/tests))\n- [ ] Tested compilation of all pkgs that depend on this change using `nix-shell -p nixpkgs-review --run \"nixpkgs-review wip\"`\n- [x] Tested execution of all binary files (usually in `./result/bin/`)\n- [ ] Determined the impact on package closure size (by running `nix path-info -S` before and after)\n- [ ] Ensured that relevant documentation is up to date\n- [ ] Fits [CONTRIBUTING.md](https://github.com/NixOS/nixpkgs/blob/master/.github/CONTRIBUTING.md)."}]},{"type":"paragraph","content":[{"type":"text","text":"We''ve only covered 2 measely steps. In the coming articles, we''ll look at:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sandbox"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"macOS Builds"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nixpkgs on Arch Linux"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Until next time"}]}]}', 'tutorial', 0, 0, NULL, '[]', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1594771200000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('contributing-to-nixpkgs', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('contributing-to-nixpkgs', 'nix', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('contributing-to-nixpkgs', 'nixos', 1);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('contributing-to-nixpkgs', 'nixpkgs', 2);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('building-rust-cue-library', 'Building a Rust Library for CUE: Architecture & Lessons', NULL, 'Inside cuengine, a Rust library wrapping Go''s CUE evaluator via FFI. Memory safety, structured errors, and production-grade architecture.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I love shiny things, and when it comes to build tools, I''m always looking for a better way. That''s what led me to create "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/cuenv/cuenv","target":null,"rel":null,"class":null,"title":null}}],"text":"cuenv"},{"type":"text","text":", a modern toolchain built around CUE''s powerful constraint-based system. There was just one problem: I''m building "},{"type":"text","marks":[{"type":"code"}],"text":"cuenv"},{"type":"text","text":" in Rust, and CUE''s only mature evaluator is written in Go."}]},{"type":"paragraph","content":[{"type":"text","text":"So, what do you do when you want the best of both worlds? You build a bridge."}]},{"type":"paragraph","content":[{"type":"text","text":"This is the story of how I built "},{"type":"text","marks":[{"type":"bold"}],"text":"cuengine"},{"type":"text","text":", a high-performance, production-grade FFI library that lets Rust speak Go. We''ll dive into the nitty-gritty of FFI, memory safety, and how to create a safe, ergonomic API on top of a completely different runtime. Let''s get into it."}]},{"type":"heading","attrs":{"level":2,"id":"the-core-problem-two-runtimes-one-library"},"content":[{"type":"text","text":"The Core Problem: Two Runtimes, One Library"}]},{"type":"paragraph","content":[{"type":"text","text":"If you haven''t used it, CUE (Configure, Unify, Execute) is a fantastically powerful configuration language with a sophisticated type system. The official Go implementation is mature and battle-tested. But my build toolchain, "},{"type":"text","marks":[{"type":"code"}],"text":"cuenv"},{"type":"text","text":", had to be in Rust. For me, the reasons were clear:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Memory Safety"},{"type":"text","text":": Rust''s ownership model wipes out entire classes of bugs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Performance"},{"type":"text","text":": I wanted zero-cost abstractions and predictable performance."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Ecosystem"},{"type":"text","text":": The crate ecosystem for CLI tools and system integration is second to none."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Cross-Compilation"},{"type":"text","text":": First-class support for targeting multiple platforms is a must."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"So the question was never "},{"type":"text","marks":[{"type":"italic"}],"text":"if"},{"type":"text","text":" I should use Rust, but "},{"type":"text","marks":[{"type":"italic"}],"text":"how"},{"type":"text","text":" to bring CUE along for the ride."}]},{"type":"heading","attrs":{"level":3,"id":"why-not-just-port-cue-to-rust"},"content":[{"type":"text","text":"Why Not Just Port CUE to Rust?"}]},{"type":"paragraph","content":[{"type":"text","text":"Look, I''m not a masochist—at least not for this kind of punishment. Porting an entire language implementation is a multi-year odyssey of parser rewrites, type system reimplementation, and endless compatibility testing. Even if I pulled it off, I''d be chained to maintaining it against every upstream CUE change forever."}]},{"type":"paragraph","content":[{"type":"text","text":"No, thanks. I chose pragmatism: build a thin, safe FFI layer that uses the existing Go implementation while exposing a clean, native Rust API."}]},{"type":"heading","attrs":{"level":3,"id":"what-about-libcue"},"content":[{"type":"text","text":"What About libcue?"}]},{"type":"paragraph","content":[{"type":"text","text":"The CUE team has been working on "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/cue-lang/libcue","target":null,"rel":null,"class":null,"title":null}}],"text":"libcue"},{"type":"text","text":", an official C library for using CUE from C and C-like languages. It''s a great initiative, but it didn''t fit my needs for a few reasons:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Low-level API"},{"type":"text","text":": libcue exposes primitives like "},{"type":"text","marks":[{"type":"code"}],"text":"cue_compile_string"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"cue_unify"},{"type":"text","text":" for working with CUE values directly. It''s designed for fine-grained control, not high-level package evaluation."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"No package loading"},{"type":"text","text":": For "},{"type":"text","marks":[{"type":"code"}],"text":"cuenv"},{"type":"text","text":", I need to load entire CUE packages from directories with full module resolution, imports, and registry support. libcue compiles strings and bytes—you''d have to build the package loading yourself."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Still maturing"},{"type":"text","text":": The libcue README explicitly warns \"expect constant churn and breakage.\" For a production tool, I needed something stable today."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Different abstraction level"},{"type":"text","text":": I wanted a Rust-idiomatic API with caching, retry logic, structured errors, and tracing built in—not a thin C binding."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"That said, libcue is worth watching. As it matures and potentially adds higher-level features like package loading, cuengine could be reimplemented on top of it. For now, building my own FFI bridge gave me exactly the abstraction level I needed."}]},{"type":"heading","attrs":{"level":2,"id":"my-solution-a-three-layer-architecture"},"content":[{"type":"text","text":"My Solution: A Three-Layer Architecture"}]},{"type":"paragraph","content":[{"type":"text","text":"I settled on an architecture with three carefully designed layers, each with a very specific job:"}]},{"type":"heading","attrs":{"level":3,"id":"layer-1-the-go-bridge-bridgego"},"content":[{"type":"text","text":"Layer 1: The Go Bridge ("},{"type":"text","marks":[{"type":"code"}],"text":"bridge.go"},{"type":"text","text":")"}]},{"type":"paragraph","content":[{"type":"text","text":"Over on the Go side, I wrote a simple bridge that handles the CUE evaluation and hands back structured JSON responses."}]},{"type":"codeBlock","attrs":{"language":"go","title":null,"meta":null},"content":[{"type":"text","text":"type BridgeResponse struct {\n    Version string           `json:\"version\"`\n    Ok      *json.RawMessage `json:\"ok,omitempty\"`\n    Error   *BridgeError     `json:\"error,omitempty\"`\n}\n\n//export cue_eval_package\nfunc cue_eval_package(dirPath *C.char, packageName *C.char) *C.char {\n    // Evaluate CUE and return structured envelope\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"A few key decisions made this work reliably:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Structured Envelopes"},{"type":"text","text":": Every response is a predictable JSON object. You either get success data ("},{"type":"text","marks":[{"type":"code"}],"text":"ok"},{"type":"text","text":") or a typed error ("},{"type":"text","marks":[{"type":"code"}],"text":"error"},{"type":"text","text":"). No guessing."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Ordered JSON"},{"type":"text","text":": CUE''s field order can be significant, so I couldn''t rely on Go''s randomized map ordering. I had to build the JSON string manually to keep it deterministic."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Panic Recovery"},{"type":"text","text":": An FFI boundary should "},{"type":"text","marks":[{"type":"italic"}],"text":"never"},{"type":"text","text":" panic. I wrapped the core logic in a recover block to catch any panics and turn them into proper errors."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Typed Error Codes"},{"type":"text","text":": I created a set of error codes (and synced them with the Rust side) to let the caller know exactly what went wrong."}]}]}]},{"type":"heading","attrs":{"level":3,"id":"layer-2-the-ffi-boundary-librs"},"content":[{"type":"text","text":"Layer 2: The FFI Boundary ("},{"type":"text","marks":[{"type":"code"}],"text":"lib.rs"},{"type":"text","text":")"}]},{"type":"paragraph","content":[{"type":"text","text":"This is where the real magic (and danger) happens. FFI in Rust means "},{"type":"text","marks":[{"type":"code"}],"text":"unsafe"},{"type":"text","text":" code, and you have to treat it with respect. My approach was to contain it as much as possible inside a safe wrapper."}]},{"type":"codeBlock","attrs":{"language":"rust","title":null,"meta":null},"content":[{"type":"text","text":"pub struct CStringPtr {\n    ptr: *mut c_char,\n    _marker: PhantomData<*const ()>, // !Send + !Sync\n}\n\nimpl Drop for CStringPtr {\n    fn drop(&mut self) {\n        if !self.ptr.is_null() {\n            unsafe { cue_free_string(self.ptr); }\n        }\n    }\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"I built this "},{"type":"text","marks":[{"type":"code"}],"text":"CStringPtr"},{"type":"text","text":" as a RAII wrapper. It''s a smart pointer that:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Automatically calls the Go "},{"type":"text","marks":[{"type":"code"}],"text":"cue_free_string"},{"type":"text","text":" function when it goes out of scope."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Prevents use-after-free bugs by tying the memory to Rust''s ownership system."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Uses "},{"type":"text","marks":[{"type":"code"}],"text":"PhantomData"},{"type":"text","text":" to mark the type as "},{"type":"text","marks":[{"type":"code"}],"text":"!Send"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"!Sync"},{"type":"text","text":", which prevents it from being used across threads. This is critical because Go''s runtime isn''t thread-safe in the way Rust expects."}]}]}]},{"type":"heading","attrs":{"level":3,"id":"layer-3-the-safe-application-layer-builderrs"},"content":[{"type":"text","text":"Layer 3: The Safe Application Layer ("},{"type":"text","marks":[{"type":"code"}],"text":"builder.rs"},{"type":"text","text":")"}]},{"type":"paragraph","content":[{"type":"text","text":"This is the public-facing API. I designed it to completely hide the FFI complexity behind a friendly builder pattern."}]},{"type":"codeBlock","attrs":{"language":"rust","title":null,"meta":null},"content":[{"type":"text","text":"let evaluator = CueEvaluator::builder().build()?;\nlet result = evaluator.evaluate(path, \"cuenv\")?;"}]},{"type":"paragraph","content":[{"type":"text","text":"Anyone using the "},{"type":"text","marks":[{"type":"code"}],"text":"cuengine"},{"type":"text","text":" crate never sees a raw pointer, a C string, or any "},{"type":"text","marks":[{"type":"code"}],"text":"unsafe"},{"type":"text","text":" code. They get a safe, ergonomic Rust API that provides:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Input validation before FFI calls."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Output size limits to prevent abuse."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rich, structured error types."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"tackling-the-hard-problems"},"content":[{"type":"text","text":"Tackling the Hard Problems"}]},{"type":"paragraph","content":[{"type":"text","text":"Building this wasn''t exactly a walk in the park. Here are some of the biggest hurdles I had to overcome."}]},{"type":"heading","attrs":{"level":3,"id":"hurdle-1-taming-memory-across-runtimes"},"content":[{"type":"text","text":"Hurdle #1: Taming Memory Across Runtimes"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"The Challenge"},{"type":"text","text":": Go has a garbage collector. Rust has ownership. When Go allocates memory and gives Rust a pointer, who is responsible for cleaning it up?"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"My Solution"},{"type":"text","text":": Explicit ownership transfer with my "},{"type":"text","marks":[{"type":"code"}],"text":"CStringPtr"},{"type":"text","text":" RAII wrapper."}]},{"type":"paragraph","content":[{"type":"text","text":"When the Go bridge allocates a C string, it hands ownership over to Rust. My "},{"type":"text","marks":[{"type":"code"}],"text":"CStringPtr"},{"type":"text","text":" wrapper takes that ownership, and its "},{"type":"text","marks":[{"type":"code"}],"text":"Drop"},{"type":"text","text":" implementation guarantees that the memory is freed exactly once, even if errors occur."}]},{"type":"codeBlock","attrs":{"language":"rust","title":null,"meta":null},"content":[{"type":"text","text":"let result_ptr = unsafe { cue_eval_package(c_dir.as_ptr(), c_package.as_ptr()) };\nlet result = unsafe { CStringPtr::new(result_ptr) }; // Takes ownership\n// result is automatically freed when it goes out of scope. Magic!"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","marks":[{"type":"code"}],"text":"PhantomData"},{"type":"text","text":" marker is the unsung hero here, preventing any accidental use of the pointer across threads that could lead to subtle, horrifying bugs."}]},{"type":"heading","attrs":{"level":3,"id":"hurdle-2-dont-lose-the-error-context"},"content":[{"type":"text","text":"Hurdle #2: Don''t Lose the Error Context!"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"The Challenge"},{"type":"text","text":": A simple string like "},{"type":"text","marks":[{"type":"code"}],"text":"\"CUE evaluation failed\""},{"type":"text","text":" is a useless error. Go''s errors have rich context, and I needed to preserve it across the FFI boundary."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"My Solution"},{"type":"text","text":": Structured error envelopes with typed codes."}]},{"type":"paragraph","content":[{"type":"text","text":"Instead of just returning an error string, the Go bridge sends back a full JSON object for errors."}]},{"type":"codeBlock","attrs":{"language":"json","title":null,"meta":null},"content":[{"type":"text","text":"{\n  \"version\": \"bridge/1\",\n  \"error\": {\n    \"code\": \"LOAD_INSTANCE\",\n    \"message\": \"Failed to load CUE instance: undefined field foo\",\n    \"hint\": \"Check CUE syntax and import statements\"\n  }\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"I synchronized the error codes (like "},{"type":"text","marks":[{"type":"code"}],"text":"LOAD_INSTANCE"},{"type":"text","text":") as constants in both Go and Rust. This allows the Rust code to deserialize the error and map it into a proper, typed Rust "},{"type":"text","marks":[{"type":"code"}],"text":"Error"},{"type":"text","text":"."}]},{"type":"codeBlock","attrs":{"language":"rust","title":null,"meta":null},"content":[{"type":"text","text":"match bridge_error.code.as_str() {\n    ERROR_CODE_INVALID_INPUT | ERROR_CODE_REGISTRY_INIT => Err(Error::configuration(full_message)),\n    ERROR_CODE_LOAD_INSTANCE | ERROR_CODE_BUILD_VALUE => Err(Error::cue_parse(dir_path, full_message)),\n    _ => Err(Error::ffi(\"cue_eval_package\", full_message)),\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"It''s more work, but it makes debugging a thousand times easier."}]},{"type":"heading","attrs":{"level":3,"id":"hurdle-3-making-it-build-everywhere"},"content":[{"type":"text","text":"Hurdle #3: Making it Build... Everywhere"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"The Challenge"},{"type":"text","text":": My build process now needed a Go compiler, a C toolchain, and the Rust compiler, all playing nicely together. How could I make this work for other developers without a 30-step setup guide?"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"My Solution"},{"type":"text","text":": A smart "},{"type":"text","marks":[{"type":"code"}],"text":"build.rs"},{"type":"text","text":" script with fallbacks."}]},{"type":"paragraph","content":[{"type":"text","text":"I put a lot of effort into the "},{"type":"text","marks":[{"type":"code"}],"text":"build.rs"},{"type":"text","text":" script to make it as robust as possible:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"First, it checks for pre-built artifacts from my Nix-based workflow."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If it can''t find any, it falls back to building the Go bridge from source."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It then configures platform-specific linking, because macOS, Linux, and Windows all need different system libraries."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This approach gives me fast, reproducible builds in my environment while still allowing anyone with "},{"type":"text","marks":[{"type":"code"}],"text":"go"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"rustc"},{"type":"text","text":" installed to build the crate from scratch."}]},{"type":"heading","attrs":{"level":2,"id":"safety-and-observability"},"content":[{"type":"text","text":"Safety and Observability"}]},{"type":"paragraph","content":[{"type":"text","text":"What separates a quick hack from a production-grade library? For me, it''s about getting the fundamentals right: memory safety, fail-fast validation, and comprehensive observability. Here''s what makes "},{"type":"text","marks":[{"type":"code"}],"text":"cuengine"},{"type":"text","text":" solid:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Comprehensive Validation"},{"type":"text","text":": The API validates all inputs "},{"type":"text","marks":[{"type":"italic"}],"text":"before"},{"type":"text","text":" they hit the FFI boundary. Path traversal attempts, oversized inputs, and invalid names are all rejected early with clear error messages."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Structured Tracing"},{"type":"text","text":": I instrumented every important operation with "},{"type":"text","marks":[{"type":"code"}],"text":"tracing"},{"type":"text","text":", providing detailed observability for debugging and monitoring in production environments."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"my-testing-strategy"},"content":[{"type":"text","text":"My Testing Strategy"}]},{"type":"paragraph","content":[{"type":"text","text":"I''m a firm believer in a multi-layered testing strategy. For "},{"type":"text","marks":[{"type":"code"}],"text":"cuengine"},{"type":"text","text":", that meant:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Unit Tests"},{"type":"text","text":": For testing the small stuff, like my "},{"type":"text","marks":[{"type":"code"}],"text":"CStringPtr"},{"type":"text","text":" wrapper and UTF-8 conversions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Integration Tests"},{"type":"text","text":": For end-to-end evaluation of real CUE files, making sure the whole pipeline works."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Property Tests"},{"type":"text","text":": Using "},{"type":"text","marks":[{"type":"code"}],"text":"proptest"},{"type":"text","text":" to throw randomized inputs at my validation and parsing logic to shake out edge cases."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Stress Tests"},{"type":"text","text":": Running the FFI calls in tight loops to check for memory leaks or race conditions."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"performance-characteristics"},"content":[{"type":"text","text":"Performance Characteristics"}]},{"type":"paragraph","content":[{"type":"text","text":"The FFI bridge obviously adds some overhead, but for evaluating configuration files, it''s more than acceptable. I ran benchmarks using "},{"type":"text","marks":[{"type":"code"}],"text":"criterion"},{"type":"text","text":" to see what I was dealing with:"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Configuration Size"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Time"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Notes"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"10 variables"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"~3.7ms"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Small config"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"100 variables"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"~4.1ms"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Minimal parsing overhead"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"1,000 variables"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"~9.8ms"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Medium config"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"10,000 variables"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"~136ms"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Large config"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"100,000 variables"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"~11.3s"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Extreme scale test"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The benchmarks show performance scales linearly with the size of the configuration, which is exactly what I was hoping for. For a build tool, where you evaluate config once per run, this overhead is a tiny price to pay for the power of CUE."}]},{"type":"heading","attrs":{"level":2,"id":"my-key-takeaways"},"content":[{"type":"text","text":"My Key Takeaways"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"FFI is Unsafe, So Contain It."},{"type":"text","text":" The public API of "},{"type":"text","marks":[{"type":"code"}],"text":"cuengine"},{"type":"text","text":" is 100% safe. All the "},{"type":"text","marks":[{"type":"code"}],"text":"unsafe"},{"type":"text","text":" code is an internal detail, carefully documented and wrapped in safe abstractions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Good Errors are Worth the Effort."},{"type":"text","text":" Moving from simple error strings to structured JSON envelopes was extra work, but it made the library immensely more robust and easier to debug."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Build Scripts are First-Class Code."},{"type":"text","text":" I spent almost as much time on "},{"type":"text","marks":[{"type":"code"}],"text":"build.rs"},{"type":"text","text":" as on some of the library features. A good build experience is a feature in itself."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Fail Fast with Clear Errors."},{"type":"text","text":" Input validation and structured tracing aren''t things you bolt on later. Building them in from the start makes debugging infinitely easier."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"whats-next"},"content":[{"type":"text","text":"What''s Next"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"cuengine"},{"type":"text","text":" is the solid foundation, but the real fun is the rest of the "},{"type":"text","marks":[{"type":"code"}],"text":"cuenv"},{"type":"text","text":" project I''m building on top of it:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"A full-featured CLI"},{"type":"text","text":" for task execution and environment management."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Nix Integration"},{"type":"text","text":" for automatic software provisioning."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Pluggable secret management"},{"type":"text","text":" for 1Password, AWS Secrets Manager, and more."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"try-it-yourself"},"content":[{"type":"text","text":"Try It Yourself"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"cuengine"},{"type":"text","text":" is available on "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://crates.io/crates/cuengine","target":null,"rel":null,"class":null,"title":null}}],"text":"crates.io"},{"type":"text","text":" with full "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://docs.rs/crate/cuengine/latest","target":null,"rel":null,"class":null,"title":null}}],"text":"API documentation"},{"type":"text","text":" on docs.rs. The complete source is available at "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/cuenv/cuenv","target":null,"rel":null,"class":null,"title":null}}],"text":"github.com/cuenv/cuenv"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"To use it in your Rust project:"}]},{"type":"codeBlock","attrs":{"language":"toml","title":null,"meta":null},"content":[{"type":"text","text":"[dependencies]\ncuengine = \"0.4\""}]},{"type":"codeBlock","attrs":{"language":"rust","title":null,"meta":null},"content":[{"type":"text","text":"use cuengine::CueEvaluator;\nuse std::path::Path;\n\nlet evaluator = CueEvaluator::builder().build()?;\nlet json = evaluator.evaluate(Path::new(\"./config\"), \"mypackage\")?;"}]},{"type":"heading","attrs":{"level":2,"id":"conclusion"},"content":[{"type":"text","text":"Conclusion"}]},{"type":"paragraph","content":[{"type":"text","text":"Building this FFI bridge was a fascinating journey. It taught me that you don''t have to choose between safety and pragmatism. By carefully containing "},{"type":"text","marks":[{"type":"code"}],"text":"unsafe"},{"type":"text","text":" code, designing for robust error handling, and thinking about production features from the start, it''s possible to bring two very different ecosystems together and get the best of both."}]},{"type":"paragraph","content":[{"type":"text","text":"If you''re building tools that need CUE in Rust, I hope "},{"type":"text","marks":[{"type":"code"}],"text":"cuengine"},{"type":"text","text":" gives you a solid foundation. And if you''re tackling any FFI project, I hope my story helps you sidestep some of the pitfalls I stumbled into!"}]},{"type":"paragraph","content":[{"type":"text","text":"The full source code, including all the safety invariants and production features I discussed, is available under the AGPL-3.0-or-later license. Contributions, feedback, and questions are always welcome. Don''t be a stranger—come and join the chat on our "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://chat.rawkode.academy","target":null,"rel":null,"class":null,"title":null}}],"text":"Zulip"},{"type":"text","text":" server!"}]}]}', 'article', 0, 0, NULL, '[]', '[]', 'https://content.rawkode.academy/articles/building-rust-cue-library/cover.png', 'Making CUE Available in Rust - Everything is better with Rust. Ferris the crab and the Gopher celebrating together with text overlaid.', 1280, 720, 'Building a Rust Library for CUE: Architecture & Lessons', 'FFI, memory safety, and production-grade architecture', '[]', '[{"id":"1","title":"cuengine on crates.io","description":"Install cuengine in your Rust project","type":"url","url":"https://crates.io/crates/cuengine","category":"documentation"},{"id":"2","title":"cuengine API Documentation","description":"Complete API reference and usage examples","type":"url","url":"https://docs.rs/crate/cuengine/latest","category":"documentation"},{"id":"3","title":"cuenv GitHub Repository","description":"Complete source code and documentation","type":"url","url":"https://github.com/cuenv/cuenv","category":"documentation"},{"id":"4","title":"CUE Language Documentation","description":"Official CUE language specification and guides","type":"url","url":"https://cuelang.org","category":"documentation"},{"id":"5","title":"Rust FFI Guide","description":"The Rust FFI Omnibus - a comprehensive guide to FFI in Rust","type":"url","url":"https://jakegoulding.com/rust-ffi-omnibus/","category":"documentation"},{"id":"6","title":"libcue - Official CUE C Library","description":"The official C library for using CUE from C and C-like languages","type":"url","url":"https://github.com/cue-lang/libcue","category":"documentation"}]', 1764201600000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('building-rust-cue-library', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('building-rust-cue-library', 'cue', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('building-rust-cue-library', 'rust', 1);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('dagger-gitlab-cloudflare-deployment', 'Deploy to Cloudflare from GitLab CI with Dagger (Tutorial)', NULL, 'Build a portable GitLab CI pipeline with Dagger that deploys to Cloudflare Workers. Containerless caching, local-runnable, full source included.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"At Rawkode Academy, we''ve built a modern deployment pipeline that combines the power of Dagger for containerized builds, GitLab CI for orchestration, and Cloudflare Workers for hosting. This setup gives us fast, reliable deployments with automatic preview environments for every merge request."}]},{"type":"heading","attrs":{"level":2,"id":"why-this-stack"},"content":[{"type":"text","text":"Why This Stack?"}]},{"type":"paragraph","content":[{"type":"text","text":"At the Rawkode Academy, one of our values is \"Future Facing\". We strive to use the best tools available to ensure our projects are maintainable, scalable, and developer-friendly. Our latest deployment pipeline is a testament to this value, combining Dagger, GitLab CI, and Cloudflare Workers to create a robust and efficient workflow."}]},{"type":"heading","attrs":{"level":3,"id":"dagger"},"content":[{"type":"text","text":"Dagger"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Dagger"},{"type":"text","text":" leverages BuildKit''s powerful caching mechanisms while providing an \"as code\" approach to CI/CD pipelines. Instead of writing YAML configurations, we can define our build and deployment logic using TypeScript and Dagger Shell, making pipelines more maintainable, testable, and reusable across different environments."}]},{"type":"paragraph","content":[{"type":"text","text":"While we use Dagger for CICD, it also can work as a local development tool, a task runner, and pretty much anything else you can think of. In due course, it will replace many tools:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Make / Just"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Docker Compose"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tilt / DevSpace / Skaffold"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The Dagger team ship new features and improvements at an incredible pace, and the community is growing rapidly. It''s a great time to get involved!"}]},{"type":"heading","attrs":{"level":3,"id":"gitlab"},"content":[{"type":"text","text":"GitLab"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"GitLab CI"},{"type":"text","text":" offers robust pipeline orchestration with excellent integration features. It allows us to automate the entire deployment process, from code changes to production deployment. GitLab CI''s powerful rules and triggers help us manage complex workflows efficiently."}]},{"type":"paragraph","content":[{"type":"text","text":"We love what GitHub are doing these days, but the Rawkode Academy team had an urge to host our own forge and integrate it into our entire SDLC and platform itself; and GitLab was a great choice. We explored Gitea and Forgejo too, both fantastic options, but GitLab''s complete feature set, including security scanning, code quality checks, and built-in CI/CD, made it the best fit for our needs."}]},{"type":"heading","attrs":{"level":3,"id":"cloudflare-workers"},"content":[{"type":"text","text":"Cloudflare Workers"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Cloudflare Workers"},{"type":"text","text":" delivers fast, global content delivery with generous free tiers. It provides a reliable and scalable hosting solution that ensures our content is accessible worldwide with minimal latency. It''s widely supported by modern web frameworks and integrates seamlessly with our CI/CD pipeline."}]},{"type":"heading","attrs":{"level":2,"id":"architecture-overview"},"content":[{"type":"text","text":"Architecture Overview"}]},{"type":"paragraph","content":[{"type":"text","text":"Our deployment pipeline follows this flow:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Code Changes"},{"type":"text","text":": Developers create merge requests in GitLab, triggering the CI pipeline. Nothing terribly exciting here."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Build Stage"},{"type":"text","text":": GitLab CI uses Dagger to build the website, leveraging Bun."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Deploy Stage"},{"type":"text","text":": Custom Dagger module deploys to Cloudflare Workers"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Preview/Production"},{"type":"text","text":": Automatic deployment to preview URLs or production"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"notes"},"content":[{"type":"text","text":"Notes"}]},{"type":"paragraph","content":[{"type":"text","text":"Ideally, the GitLab CI configuration would be a single job that calls "},{"type":"text","marks":[{"type":"code"}],"text":"dagger ci"},{"type":"text","text":". However, there''s a few challenges at the moment that we need to give time to mature:"}]},{"type":"paragraph","content":[{"type":"text","text":"Dagger caching is not that great yet, we''re hoping they release a managed service for this soon."}]},{"type":"paragraph","content":[{"type":"text","text":"The lack of caching means a "},{"type":"text","marks":[{"type":"code"}],"text":"dagger ci"},{"type":"text","text":" call would likely run everything, even though only a small portion of our repository has changed."}]},{"type":"heading","attrs":{"level":2,"id":"dagger-configuration"},"content":[{"type":"text","text":"Dagger Configuration"}]},{"type":"heading","attrs":{"level":3,"id":"website-build-module"},"content":[{"type":"text","text":"Website Build Module"}]},{"type":"paragraph","content":[{"type":"text","text":"Our website build is handled by a Dagger module that ensures consistent builds across environments."}]},{"type":"paragraph","content":[{"type":"text","text":"We currently duplicate this module across multiple projects, but this won''t be required soon as Dagger has a working prototype of "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/dagger/dagger/pull/10453","target":null,"rel":null,"class":null,"title":null}}],"text":"Inline Modules"},{"type":"text","text":" which will hopefully land soon."}]},{"type":"codeBlock","attrs":{"language":"typescript","title":".dagger/src/index.ts","meta":null},"content":[{"type":"text","text":"import {\n\targument,\n\tdag,\n\tDirectory,\n\tfunc,\n\tobject,\n} from \"@dagger.io/dagger\";\n\n@object()\nexport class Website {\n\t/**\n\t * Build the website and get the output directory.\n\t */\n\t@func()\n\tasync build(\n\t\t@argument({ defaultPath: \".\", ignore: [\"node_modules\"] }) source: Directory,\n\t): Promise<Directory> {\n\t\treturn dag.bun()\n\t\t\t.withCache()\n\t\t\t.install(source)\n\t\t\t.withMountedFile(\n\t\t\t\t\"/usr/local/bin/d2\",\n\t\t\t\tdag.container()\n\t\t\t\t\t.from(\"terrastruct/d2\")\n\t\t\t\t\t.file(\"/usr/local/bin/d2\"),\n\t\t\t)\n\t\t\t.withExec([\n\t\t\t\t\"bun\",\n\t\t\t\t\"run\",\n\t\t\t\t\"build\",\n\t\t\t]).directory(\"dist\");\n\t}\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"This module:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Uses Bun for fast package management and builds"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Includes D2 for diagram generation in our content"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Leverages Dagger''s caching for faster subsequent builds"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Returns a directory containing the built static assets"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"cloudflare-deployment-module"},"content":[{"type":"text","text":"Cloudflare Deployment Module"}]},{"type":"paragraph","content":[{"type":"text","text":"We''ve created a reusable Dagger module for Cloudflare Workers deployments."}]},{"type":"paragraph","content":[{"type":"text","text":"This module can be used across all projects, it lives at the root of our monorepo."}]},{"type":"paragraph","content":[{"type":"text","text":"It can be added to projects with:"}]},{"type":"codeBlock","attrs":{"language":"shell","title":null,"meta":null},"content":[{"type":"text","text":"dagger install ../../dagger/cloudflare"}]},{"type":"paragraph","content":[{"type":"text","text":"We provide two functions in this module: "},{"type":"text","marks":[{"type":"code"}],"text":"deploy"},{"type":"text","text":" for production deployments and "},{"type":"text","marks":[{"type":"code"}],"text":"preview"},{"type":"text","text":" for merge request previews. Both functions use the Cloudflare Wrangler CLI to handle deployments."}]},{"type":"codeBlock","attrs":{"language":"typescript","title":"/dagger/cloudflare/src/index.ts","meta":null},"content":[{"type":"text","text":"import {\n\tdag,\n\tDirectory,\n\tFile,\n\tfunc,\n\tobject,\n\tSecret,\n} from \"@dagger.io/dagger\";\n\n@object()\nexport class Cloudflare {\n\t/**\n\t * Deploy a website to Cloudflare Workers.\n\t */\n\t@func()\n\tasync deploy(\n\t\tdist: Directory,\n\t\twranglerConfig: File,\n\t\tcloudflareApiToken: Secret,\n\t): Promise<string> {\n\t\tconst cloudflareAccountId = await dag.config().cloudflareAccountId();\n\n\t\tconst wranglerFilename = await wranglerConfig.name();\n\n\t\tconst deploymentResult = await dag.container()\n\t\t\t.from(\"node:22\")\n\t\t\t.withWorkdir(\"/deploy\")\n\t\t\t// Only doing this to cache the wrangler installation\n\t\t\t.withExec([\n\t\t\t\t\"npx\",\n\t\t\t\t\"wrangler\",\n\t\t\t\t\"--version\",\n\t\t\t])\n\t\t\t.withMountedDirectory(\"/deploy/dist\", dist)\n\t\t\t.withMountedFile(\n\t\t\t\t`/deploy/${wranglerFilename}`,\n\t\t\t\twranglerConfig,\n\t\t\t)\n\t\t\t.withEnvVariable(\"CLOUDFLARE_ACCOUNT_ID\", cloudflareAccountId)\n\t\t\t.withSecretVariable(\"CLOUDFLARE_API_TOKEN\", cloudflareApiToken)\n\t\t\t.withExec([\n\t\t\t\t\"npx\",\n\t\t\t\t\"wrangler\",\n\t\t\t\t\"deploy\",\n\t\t\t]);\n\n\t\tif (await deploymentResult.exitCode() !== 0) {\n\t\t\tthrow new Error(\n\t\t\t\t\"Deployment failed. Error: \" + await deploymentResult.stdout() +\n\t\t\t\tawait deploymentResult.stderr(),\n\t\t\t);\n\t\t}\n\n\t\treturn deploymentResult.stdout();\n\t}\n\n\t/**\n\t * Deploy a preview website to Cloudflare Workers.\n\t */\n\t@func()\n\tasync preview(\n\t\tdist: Directory,\n\t\twranglerConfig: File,\n\t\tcloudflareApiToken: Secret,\n\t\tgitlabApiToken: Secret,\n\t\tmergeRequestId: string,\n\t): Promise<string> {\n\t\tconst cloudflareAccountId = await dag.config().cloudflareAccountId();\n\n\t\tconst wranglerFilename = await wranglerConfig.name();\n\n\t\tconst deploymentResult = await dag.container()\n\t\t\t.from(\"node:22\")\n\t\t\t.withWorkdir(\"/deploy\")\n\t\t\t// Only doing this to cache the wrangler installation\n\t\t\t.withExec([\n\t\t\t\t\"npx\",\n\t\t\t\t\"wrangler\",\n\t\t\t\t\"--version\",\n\t\t\t])\n\t\t\t.withMountedDirectory(\"/deploy/dist\", dist)\n\t\t\t.withMountedFile(\n\t\t\t\t`/deploy/${wranglerFilename}`,\n\t\t\t\twranglerConfig,\n\t\t\t)\n\t\t\t.withEnvVariable(\"CLOUDFLARE_ACCOUNT_ID\", cloudflareAccountId)\n\t\t\t.withSecretVariable(\"CLOUDFLARE_API_TOKEN\", cloudflareApiToken)\n\t\t\t.withExec([\n\t\t\t\t\"npx\",\n\t\t\t\t\"wrangler\",\n\t\t\t\t\"versions\",\n\t\t\t\t\"upload\",\n\t\t\t]);\n\n\t\tif (await deploymentResult.exitCode() !== 0) {\n\t\t\tthrow new Error(\n\t\t\t\t\"Deployment failed. Error: \" + await deploymentResult.stdout() +\n\t\t\t\tawait deploymentResult.stderr(),\n\t\t\t);\n\t\t}\n\n\t\tconst allOutput = await deploymentResult.stdout();\n\n\t\treturn dag.gitlab().postMergeRequestComment(\n\t\t\tgitlabApiToken,\n\t\t\tmergeRequestId,\n\t\t\tallOutput,\n\t\t).stdout();\n\t}\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"Key features of this module:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Branch-based deployments"},{"type":"text","text":": Supports both production and preview deployments based on the context (merge request or main branch)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Wrangler integration"},{"type":"text","text":": Leverages Cloudflare''s official CLI tool, "},{"type":"text","marks":[{"type":"code"}],"text":"wrangler"},{"type":"text","text":", for robust deployments."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"We use "},{"type":"text","marks":[{"type":"code"}],"text":"wrangler deploy"},{"type":"text","text":" for production deployments."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For preview deployments, we use "},{"type":"text","marks":[{"type":"code"}],"text":"wrangler versions upload"},{"type":"text","text":", which allows us to deploy a version of the site without affecting the production environment."}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Automatic MR comments"},{"type":"text","text":": For preview deployments, it posts the deployment URL as a comment on the merge request, making it easy for reviewers to access the preview environment."}]}]}]},{"type":"heading","attrs":{"level":3,"id":"the-config-module-pattern"},"content":[{"type":"text","text":"The Config Module Pattern"}]},{"type":"paragraph","content":[{"type":"text","text":"You might have noticed the line "},{"type":"text","marks":[{"type":"code"}],"text":"dag.config().cloudflareAccountId()"},{"type":"text","text":" in our deployment module. This demonstrates a powerful pattern in Dagger for managing configuration across multiple modules."}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","marks":[{"type":"code"}],"text":"dag.config()"},{"type":"text","text":" pattern allows us to:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Centralize configuration"},{"type":"text","text":": Store all environment-specific values in one place"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Avoid hardcoding"},{"type":"text","text":": Keep sensitive or environment-specific data out of our modules"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Enable reusability"},{"type":"text","text":": Share the same modules across different environments"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Here''s how we implement our config module:"}]},{"type":"codeBlock","attrs":{"language":"typescript","title":"/dagger/config/src/index.ts","meta":null},"content":[{"type":"text","text":"import { func, object } from \"@dagger.io/dagger\";\n\n@object()\nexport class Config {\n  /**\n   * Get the Cloudflare account ID for deployments\n   */\n  @func()\n  cloudflareAccountId(): string {\n    // In production, this could read from environment variables\n    // or fetch from a secret management system\n    return \"your-cloudflare-account-id\";\n  }\n\n  /**\n   * Get the GitLab project ID for API calls\n   */\n  @func()\n  gitlabProjectId(): string {\n    return \"your-gitlab-project-id\";\n  }\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"This config module is installed in our repository root and can be accessed by any other module via "},{"type":"text","marks":[{"type":"code"}],"text":"dag.config()"},{"type":"text","text":". This pattern is particularly useful when:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Managing different environments (dev, staging, production)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sharing configuration across multiple deployment modules"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Keeping sensitive data separate from your module logic"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"To use this pattern in your own projects:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Create a config module at your repository root"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Install it: "},{"type":"text","marks":[{"type":"code"}],"text":"dagger install ./dagger/config"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Access it from any module: "},{"type":"text","marks":[{"type":"code"}],"text":"await dag.config().yourConfigMethod()"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"gitlab-ci-pipeline"},"content":[{"type":"text","text":"GitLab CI Pipeline"}]},{"type":"paragraph","content":[{"type":"text","text":"Our GitLab CI configuration orchestrates the entire deployment process."}]},{"type":"paragraph","content":[{"type":"text","text":"Firstly, we configure some base jobs that will be used by all other jobs. This includes setting up Docker-in-Docker for building images and installing Dagger."}]},{"type":"codeBlock","attrs":{"language":"yaml","title":".dagger/.gitlab-ci.yml","meta":null},"content":[{"type":"text","text":".docker:\n  image: docker:latest\n  services:\n    - name: docker:${DOCKER_VERSION}-dind\n      command: [\"--registry-mirror\", \"https://mirror.gcr.io\"]\n  variables:\n    DOCKER_HOST: tcp://docker:2376\n    DOCKER_DRIVER: overlay2\n    DOCKER_VERSION: \"27.2.0\"\n    DOCKER_TLS_VERIFY: \"1\"\n    DOCKER_TLS_CERTDIR: \"/certs\"\n    DOCKER_CERT_PATH: \"/certs/client\"\n  before_script:\n    - until docker info > /dev/null 2>&1; do sleep 1; done\n\n.dagger:\n  extends: [.docker]\n  before_script:\n    - apk add ca-certificates curl git\n    - curl -fsSL https://dl.dagger.io/dagger/install.sh | BIN_DIR=/usr/local/bin sh"}]},{"type":"paragraph","content":[{"type":"text","text":"Next, we define the deploy and preview jobs for each project. These are orchestrated with Dagger Shell, which is a really nice way to interact with Dagger without having to build custom modules."}]},{"type":"codeBlock","attrs":{"language":"yaml","title":".dagger/.gitlab-ci.yml","meta":null},"content":[{"type":"text","text":"website-deploy-production:\n  extends: [.dagger]\n  stage: deploy\n  environment:\n    name: rawkode-academy-production\n    url: https://rawkode.academy\n  rules:\n    - if: ''$CI_COMMIT_BRANCH == \"main\"''\n      changes:\n        - projects/rawkode.academy/website/**/*\n  script:\n    - cd projects/rawkode.academy/website\n    - |\n      dagger <<.\n        . | build | export dist\n\n        ../../../dagger/cloudflare | deploy \\\n          ./dist \\\n          wrangler.jsonc \\\n          env:CLOUDFLARE_WORKERS_TOKEN\n      .\n\nwebsite-deploy-merge-request:\n  extends: [.dagger]\n  stage: deploy\n  rules:\n    - if: \"$CI_MERGE_REQUEST_ID\"\n      changes:\n        - projects/rawkode.academy/website/**/*\n  script:\n    - cd projects/rawkode.academy/website\n    - |\n      dagger <<.\n        . | build | export dist\n\n        ../../../dagger/cloudflare | preview \\\n          ./dist \\\n          wrangler.jsonc \\\n          env:CLOUDFLARE_WORKERS_TOKEN \\\n          env:CICD_COMMENT_TOKEN \\\n          $CI_MERGE_REQUEST_ID\n      ."}]},{"type":"paragraph","content":[{"type":"text","text":"Dagger Shell has full access to modules and their dependencies, enabling us to build and deploy our website with a single command. The "},{"type":"text","marks":[{"type":"code"}],"text":"build"},{"type":"text","text":" function compiles the website which can be exported and stored within a variable; while the "},{"type":"text","marks":[{"type":"code"}],"text":"deploy"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"preview"},{"type":"text","text":" functions handle the deployment to Cloudflare Workers and take our export/variable as input."}]},{"type":"heading","attrs":{"level":2,"id":"local-development"},"content":[{"type":"text","text":"Local Development"}]},{"type":"paragraph","content":[{"type":"text","text":"Developers can run the exact same build process locally:"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"# Build the website locally\n# (Assuming you are in the ''projects/rawkode.academy/website'' directory)\ndagger . build\n\n# Deploy to a preview environment (requires tokens)\n# This command also assumes you are in the ''projects/rawkode.academy/website'' directory.\n# It uses ''dagger call'' to invoke the ''deploy'' function in the shared Cloudflare Dagger module.\n# The path ''../../../dagger/cloudflare'' points to this module relative to the current directory.\ndagger call -m ../../../dagger/cloudflare deploy \\\n  --dist ./dist \\\n  --wrangler-config wrangler.jsonc \\\n  --cloudflare-api-token env:CLOUDFLARE_PAGES_TOKEN"}]},{"type":"heading","attrs":{"level":2,"id":"security-considerations"},"content":[{"type":"text","text":"Security Considerations"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Secret Management"},{"type":"text","text":": All sensitive tokens are managed through GitLab CI variables. This ensures that secrets are not hardcoded in the codebase, reducing the risk of accidental exposure. We use GitLab''s built-in secret management to securely store and access tokens, API keys, and other sensitive information."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Branch Protection"},{"type":"text","text":": Production deployments only happen from the main branch. This practice ensures that only thoroughly reviewed and tested code reaches production. We enforce branch protection rules to prevent direct pushes to the main branch, requiring all changes to go through a merge request process."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Access Control"},{"type":"text","text":": Cloudflare API tokens are scoped to specific resources. This principle of least privilege ensures that each token has the minimum permissions necessary to perform its function, reducing the potential impact of a compromised token. We regularly review and rotate tokens to maintain security."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Environment Isolation"},{"type":"text","text":": We use separate environments for development, staging, and production. This isolation helps prevent accidental changes to production systems and allows for thorough testing before deployment."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Regular Audits"},{"type":"text","text":": We conduct regular security audits of our CI/CD pipeline and infrastructure. This includes reviewing access controls, secret management practices, and deployment processes to identify and address potential vulnerabilities."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"performance-optimizations"},"content":[{"type":"text","text":"Performance Optimizations"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Docker Layer Caching"},{"type":"text","text":": The pipeline uses Docker-in-Docker with proper caching"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Dagger Caching"},{"type":"text","text":": Build dependencies are cached between runs"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Change Detection"},{"type":"text","text":": Deployments only trigger when relevant files change"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Parallel Execution"},{"type":"text","text":": Multiple projects can deploy simultaneously"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"conclusion"},"content":[{"type":"text","text":"Conclusion"}]},{"type":"paragraph","content":[{"type":"text","text":"This Dagger + GitLab + Cloudflare Workers setup provides us with a robust, fast, and developer-friendly deployment pipeline. The combination of containerized builds, automatic preview environments, and integrated notifications creates an excellent developer experience while maintaining production reliability."}]},{"type":"paragraph","content":[{"type":"text","text":"The modular approach with Dagger also means we can easily extend this pipeline to support additional deployment targets or build processes as our needs evolve. This flexibility ensures that our deployment pipeline can grow and adapt with our projects, making it a future-proof solution."}]},{"type":"paragraph","content":[{"type":"text","text":"If you''re looking to modernize your deployment pipeline, this stack offers a great balance of simplicity, power, and developer experience. By adopting this setup, you can achieve faster, more reliable deployments, reduce manual overhead, and focus on what truly matters—building great software."}]},{"type":"paragraph","content":[{"type":"text","text":"We''re excited about the possibilities this pipeline opens up and look forward to seeing how it can help other teams achieve similar results. The future of CI/CD is here, and it''s more powerful and developer-friendly than ever before."}]}]}', 'tutorial', 0, 0, NULL, '[]', '[]', 'https://content.rawkode.academy/articles/dagger-gitlab-cloudflare-deployment/cover.png', 'Dagger Logo, with Cloudflare and GitLab Logos', 2240, 1260, 'Deploy to Cloudflare from GitLab CI with Dagger (Tutorial)', 'Containerized builds, automatic previews, and zero-config deployments', '[]', '[]', 1748476800000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('dagger-gitlab-cloudflare-deployment', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('dagger-gitlab-cloudflare-deployment', 'dagger', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('dagger-gitlab-cloudflare-deployment', 'gitlab', 1);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('dagger-gitlab-cloudflare-deployment', 'docker', 2);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('lazyjournal-log-viewer', 'Lazyjournal: A Log Viewer for Cloud Native Environments', NULL, 'Lazyjournal is a TUI log viewer that aggregates logs from various sources, providing a unified interface for developers and system administrators.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lazyjournal is a "},{"type":"text","marks":[{"type":"bold"}],"text":"terminal user interface (TUI) log viewer"},{"type":"text","text":" that provides centralized access to logs from journald, auditd, file systems, Docker containers, Podman, and Kubernetes pods. Created by Alex Kup (Lifailon), this Go-based tool offers a modern alternative to traditional log viewing methods with advanced filtering, real-time streaming, and syntax coloring capabilities."}]},{"type":"image","attrs":{"src":"https://content.rawkode.academy/articles/lazyjournal-log-viewer/screenshot-light-mode.png","alt":"Lazyjournal interface showing log filtering and navigation","title":null,"width":3568,"height":2096,"darkSrc":"https://content.rawkode.academy/articles/lazyjournal-log-viewer/screenshot-dark-mode.png","zoomable":false}},{"type":"heading","attrs":{"level":2,"id":"what-problems-lazyjournal-solves"},"content":[{"type":"text","text":"What Problems Lazyjournal Solves"}]},{"type":"paragraph","content":[{"type":"text","text":"Traditional log management in cloud-native environments requires juggling multiple tools and commands across different systems. Developers typically need to switch between "},{"type":"text","marks":[{"type":"code"}],"text":"journalctl"},{"type":"text","text":" for system logs, "},{"type":"text","marks":[{"type":"code"}],"text":"docker logs"},{"type":"text","text":" for containers, "},{"type":"text","marks":[{"type":"code"}],"text":"kubectl logs"},{"type":"text","text":" for Kubernetes pods, and various file viewers for application logs. This fragmentation creates friction during debugging and incident response."}]},{"type":"paragraph","content":[{"type":"text","text":"Lazyjournal addresses this by providing "},{"type":"text","marks":[{"type":"bold"}],"text":"a single unified interface"},{"type":"text","text":" for all log sources. Instead of remembering different commands and syntaxes, developers can navigate through system services, containers, and pod logs using consistent keyboard shortcuts and filtering mechanisms. The tool''s fuzzy search and regex capabilities make finding specific log entries significantly faster than traditional grep-based approaches."}]},{"type":"paragraph","content":[{"type":"text","text":"The real-time streaming feature with automatic reconnection eliminates the need to manually restart log tailing when containers restart or network connections drop. This is particularly valuable during active debugging sessions where maintaining continuous log visibility is crucial."}]},{"type":"heading","attrs":{"level":2,"id":"key-features--capabilities"},"content":[{"type":"text","text":"Key Features & Capabilities"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Multi-source log aggregation"},{"type":"text","text":" stands as lazyjournal''s core strength. The tool seamlessly integrates with journald for systemd logs, reads audit logs from auditd with human-readable interpretation, accesses file system logs from "},{"type":"text","marks":[{"type":"code"}],"text":"/var/log"},{"type":"text","text":" and user directories, streams Docker and Podman container logs, and connects to Kubernetes pods via kubectl. Support for archived logs in gz, xz, bz2, pcap, and asl formats extends its utility to historical analysis."}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","marks":[{"type":"bold"}],"text":"filtering system"},{"type":"text","text":" offers four distinct modes. Default mode provides case-sensitive exact matching, fuzzy search enables inexact case-insensitive matching similar to fzf, regex mode supports full regular expression patterns, and timestamp filtering allows date/time range selection. These modes can be switched on-the-fly during log viewing, enabling rapid refinement of search criteria."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Performance optimizations"},{"type":"text","text":" include configurable line limits from 200 to 200,000 lines, intelligent switching between filesystem and API-based log reading for containers, color disabling for improved performance with large logs exceeding 100,000 lines, and background update intervals adjustable from 2 to 10 seconds. The tool maintains memory efficiency even when handling massive log volumes."}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","marks":[{"type":"bold"}],"text":"interactive interface"},{"type":"text","text":" features vim-style navigation with hjkl keys, mouse support with Alt+Shift text selection, real-time log output updates with visual loading indicators, and color-coded output for improved readability. The interface adapts to terminal size changes and provides contextual help with the ? key."}]},{"type":"heading","attrs":{"level":2,"id":"installation"},"content":[{"type":"text","text":"Installation"}]},{"type":"paragraph","content":[{"type":"text","text":"Want to install lazyjournal? The process is straightforward across various distributions and platforms. For "},{"type":"text","marks":[{"type":"bold"}],"text":"Linux"},{"type":"text","text":", you can use the following command to download the latest release directly from GitHub with "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/zyedidia/eget","target":null,"rel":null,"class":null,"title":null}}],"text":"eget"},{"type":"text","text":" or via curl:"}]},{"type":"codeBlock","attrs":{"language":"shell","title":null,"meta":null},"content":[{"type":"text","text":"eget lifailon/lazyjournal --to ~/.local/bin"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"arch=$( [ \"$(uname -m)\" = \"aarch64\" ] && echo \"arm64\" || echo \"amd64\" )\nversion=$(curl -L -sS -H ''Accept: application/json'' https://github.com/Lifailon/lazyjournal/releases/latest | sed -e ''s/.*\"tag_name\":\"\\([^\"]*\\)\".*/\\1/'')\nsudo curl -L -sS https://github.com/Lifailon/lazyjournal/releases/download/$version/lazyjournal-$version-linux-$arch -o lazyjournal"}]},{"type":"paragraph","content":[{"type":"text","text":"For developers preferring source installation, Go''s package manager provides: "},{"type":"text","marks":[{"type":"code"}],"text":"go install github.com/Lifailon/lazyjournal@latest"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Package manager options"},{"type":"text","text":" include:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Arch Linux (AUR) ("},{"type":"text","marks":[{"type":"code"}],"text":"paru -S lazyjournal"},{"type":"text","text":")"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Conda ("},{"type":"text","marks":[{"type":"code"}],"text":"conda install conda-forge::lazyjournal"},{"type":"text","text":")"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Homebrew ("},{"type":"text","marks":[{"type":"code"}],"text":"brew install lazyjournal"},{"type":"text","text":")"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Snap ("},{"type":"text","marks":[{"type":"code"}],"text":"snap install lazyjournal"},{"type":"text","text":")."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Windows users can use PowerShell with "},{"type":"text","marks":[{"type":"code"}],"text":"Invoke-RestMethod https://raw.githubusercontent.com/Lifailon/lazyjournal/main/install.ps1 | Invoke-Expression"},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2,"id":"how-it-works-technically"},"content":[{"type":"text","text":"How it Works Technically"}]},{"type":"paragraph","content":[{"type":"text","text":"Built with Go and the awesome-gocui library (a fork of gocui), lazyjournal employs an event-driven architecture that efficiently handles UI updates and log streaming. The single-threaded design keeps the binary small (~5MB) while maintaining responsiveness through intelligent buffering and update strategies."}]},{"type":"paragraph","content":[{"type":"text","text":"The tool implements "},{"type":"text","marks":[{"type":"bold"}],"text":"dual-mode container log reading"},{"type":"text","text":". When filesystem permissions allow, it directly parses JSON log files for better performance. Otherwise, it falls back to Docker/Podman API streaming. This adaptive approach ensures functionality across different permission scenarios without requiring elevated privileges in all cases."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Log source discovery"},{"type":"text","text":" happens automatically on startup. The tool scans for available systemd units, Docker containers, Podman containers, Kubernetes pods, and filesystem logs. Sources are presented in categorized lists that users navigate with arrow keys or vim bindings. The centralized search feature (Ctrl+S) enables searching across all discovered sources simultaneously."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Encoding detection"},{"type":"text","text":" supports UTF-8, UTF-16 with and without BOM, and Windows-1251, ensuring compatibility with logs from various applications and platforms. The tool automatically detects and converts encodings, preventing garbled output from non-standard log files."}]},{"type":"heading","attrs":{"level":2,"id":"usage-examples-and-workflows"},"content":[{"type":"text","text":"Usage Examples and Workflows"}]},{"type":"paragraph","content":[{"type":"text","text":"For "},{"type":"text","marks":[{"type":"bold"}],"text":"basic system log viewing"},{"type":"text","text":", launch lazyjournal and navigate to journald logs. Select a service like nginx or ssh, then use fuzzy search (Ctrl+Z) to find specific patterns. The interface updates in real-time as new log entries arrive."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Container debugging workflows"},{"type":"text","text":" benefit from the unified view. Select a Docker container from the list, toggle between stdout and stderr streams if needed, apply regex filtering to isolate error messages, and monitor multiple containers by quickly switching between them with navigation keys."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Kubernetes pod analysis"},{"type":"text","text":" follows a similar pattern. Navigate to the Kubernetes section, select the target pod and container, enable timestamp filtering to focus on a specific incident timeframe, and use the streaming view to watch logs during deployment or debugging."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Advanced filtering scenarios"},{"type":"text","text":" showcase the tool''s power. For complex pattern matching, switch to regex mode and use patterns like "},{"type":"text","marks":[{"type":"code"}],"text":"error|warning|critical"},{"type":"text","text":". Timestamp filtering helps isolate issues to specific time windows: "},{"type":"text","marks":[{"type":"code"}],"text":"2024-06-15 14:00"},{"type":"text","text":". Combine multiple filters by first applying timestamp constraints, then adding pattern filters."}]},{"type":"heading","attrs":{"level":2,"id":"unique-advantages-over-alternatives"},"content":[{"type":"text","text":"Unique Advantages over Alternatives"}]},{"type":"paragraph","content":[{"type":"text","text":"Compared to "},{"type":"text","marks":[{"type":"bold"}],"text":"lnav"},{"type":"text","text":", lazyjournal offers broader source integration including containers and Kubernetes, while lnav provides more sophisticated log analysis features like SQL queries. Against "},{"type":"text","marks":[{"type":"bold"}],"text":"stern"},{"type":"text","text":" for Kubernetes, lazyjournal provides a unified interface for all log sources, not just pods. Unlike web-based tools like "},{"type":"text","marks":[{"type":"bold"}],"text":"Dozzle"},{"type":"text","text":", lazyjournal requires no additional infrastructure or exposed ports."}]},{"type":"paragraph","content":[{"type":"text","text":"The tool''s "},{"type":"text","marks":[{"type":"bold"}],"text":"single binary deployment"},{"type":"text","text":" eliminates dependency management compared to solutions requiring databases or web servers. The "},{"type":"text","marks":[{"type":"bold"}],"text":"interactive TUI"},{"type":"text","text":" provides a more intuitive experience than command-line tools while maintaining terminal-native efficiency. "},{"type":"text","marks":[{"type":"bold"}],"text":"Cross-platform support"},{"type":"text","text":" with native binaries for Linux, macOS, Windows, and BSD systems ensures broad compatibility."}]},{"type":"heading","attrs":{"level":2,"id":"value-for-cloud-native-developers"},"content":[{"type":"text","text":"Value for Cloud Native Developers"}]},{"type":"paragraph","content":[{"type":"text","text":"For teams working with "},{"type":"text","marks":[{"type":"bold"}],"text":"Kubernetes"},{"type":"text","text":", lazyjournal streamlines pod log access without complex kubectl commands. The ability to quickly switch between pods and containers accelerates debugging in microservices architectures. Integration with both Docker and Podman supports diverse container runtime environments."}]},{"type":"paragraph","content":[{"type":"text","text":"The tool''s "},{"type":"text","marks":[{"type":"bold"}],"text":"lightweight footprint"},{"type":"text","text":" makes it ideal for debugging directly on production nodes when necessary. The unified interface reduces context switching during incident response, where time is critical. Support for both streaming and historical logs enables both real-time monitoring and post-mortem analysis."}]},{"type":"paragraph","content":[{"type":"text","text":"While lazyjournal is written in Go rather than Rust, it effectively supports debugging "},{"type":"text","marks":[{"type":"bold"}],"text":"Rust applications"},{"type":"text","text":" running in containers or writing to system logs. The tool can analyze WebAssembly application logs when they''re routed through traditional logging mechanisms, though it lacks specific WASM-aware features."}]},{"type":"heading","attrs":{"level":2,"id":"community--ecosystem"},"content":[{"type":"text","text":"Community & Ecosystem"}]},{"type":"paragraph","content":[{"type":"text","text":"With over 553 GitHub stars and inclusion in Awesome-Go, Awesome-TUIs, and Awesome-Docker lists, lazyjournal has gained recognition in the developer community. Active maintenance with regular releases ensures compatibility with evolving container and Kubernetes ecosystems. The project welcomes contributions, with several community members maintaining packages for various distributions."}]},{"type":"paragraph","content":[{"type":"text","text":"The tool''s inspiration from LazyDocker and LazyGit is evident in its user-friendly approach to complex system interactions. As the author''s first Go project, it demonstrates impressive functionality while maintaining clean, understandable code that encourages community contributions."}]},{"type":"heading","attrs":{"level":2,"id":"conclusion"},"content":[{"type":"text","text":"Conclusion"}]},{"type":"paragraph","content":[{"type":"text","text":"Lazyjournal represents a practical solution to the fragmented log viewing experience in modern cloud-native environments. By unifying access to diverse log sources through an intuitive terminal interface, it reduces operational friction for developers and system administrators. The combination of powerful filtering capabilities, real-time streaming, and broad platform support makes it particularly valuable for teams managing containerized applications and Kubernetes deployments. While specialized tools may offer deeper analysis features for specific use cases, lazyjournal''s strength lies in providing fast, unified access to logs exactly when developers need it most."}]}]}', 'article', 0, 0, NULL, '[]', '[]', 'https://content.rawkode.academy/articles/lazyjournal-log-viewer/cover.png', 'Lazyjournal log viewer interface', 1960, 1237, 'Lazyjournal: A Log Viewer for Cloud Native Environments', 'Centralized log access for developers and system administrators', '[]', '[]', 1750032000000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('lazyjournal-log-viewer', 'rawkode', 0);
