INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('lazyjournal-log-viewer', 'docker', 1);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('dockerfile-tip-1-define-a-base-layer', 'Dockerfile Tip 1: Define a Base Layer', NULL, 'With the advent of the Multi Stage Dockerfile, it''s very common for people to ver...', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"With the advent of the Multi Stage Dockerfile, it''s very common for people to very specific layers that do a single task; which often utilise the same \"primary\" base layer."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Example:"}]},{"type":"codeBlock","attrs":{"language":"dockerfile","title":null,"meta":null},"content":[{"type":"text","text":"FROM elixir:1.8 AS deps\n\nRUN mix deps.get\n\nFROM elixir:1.8 AS compile\n\nCOPY --from=deps ...\n\nRUN mix compile"}]},{"type":"paragraph","content":[{"type":"text","text":"This allows lengthy tasks to utilise the build cache and pass artefacts between layers, without rerunning the lengthy task. However, I often see this \"primary\" layer duplicated 4/6/10 times in a single Dockerfile; making maintenance cumbersome."}]},{"type":"heading","attrs":{"level":2,"id":"the-tip"},"content":[{"type":"text","text":"The Tip"}]},{"type":"paragraph","content":[{"type":"text","text":"Create an empty layer with your primary image:"}]},{"type":"codeBlock","attrs":{"language":"dockerfile","title":null,"meta":null},"content":[{"type":"text","text":"FROM elixir:1.8 AS base\n\nFROM base AS deps\n\n# ...\n\nFROM base AS compile\n\n# ..."}]},{"type":"paragraph","content":[{"type":"text","text":"This reduces duplication and makes maintenance, and pull-requests, easier to review/manage/change."}]},{"type":"paragraph","content":[{"type":"text","text":"Until next time :metal:"}]}]}', 'tutorial', 0, 0, NULL, '[]', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1556841600000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('dockerfile-tip-1-define-a-base-layer', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('dockerfile-tip-1-define-a-base-layer', 'docker', 0);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('federated-graphql-microservices', 'Federated GraphQL for Microservice Architecture', NULL, 'Learn how federated GraphQL simplifies data access across service boundaries in a microservice architecture.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In this article, we''ll explore the design and implementation of our federated GraphQL API. This API serves as a single, unified interface to our microservice architecture, allowing clients to query and retrieve data from multiple services in a single request. If you''re unfamiliar with GraphQL federation, it''s an architectural pattern that combines multiple GraphQL schemas into a unified graph, enabling seamless data access across service boundaries."}]},{"type":"aside","attrs":{"variant":"info"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Want to play with our API? No problem! We have a public API available at "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://api.rawkode.academy","target":null,"rel":null,"class":null,"title":null}}],"text":"https://api.rawkode.academy"},{"type":"text","text":". You can explore the schema and run queries using the GraphQL Playground."}]}]},{"type":"paragraph","content":[{"type":"text","text":"We''ll cover the benefits of using a federated GraphQL API, the challenges we faced during implementation, and the tools and techniques we used to build and deploy our solution. You''ll see practical examples of how clients can interact with our API and how it dramatically simplifies the process of querying data from across multiple microservices."}]},{"type":"paragraph","content":[{"type":"text","text":"By the end of this article, you''ll understand how federated GraphQL APIs work and how they can create a more efficient and flexible API layer in a microservice architecture."}]},{"type":"heading","attrs":{"level":2,"id":"why-federated-graphql"},"content":[{"type":"text","text":"Why Federated GraphQL?"}]},{"type":"paragraph","content":[{"type":"text","text":"In a microservice architecture, multiple services are responsible for different domains of an application. Each service has its own database and API, which can lead to clients needing to make multiple requests to different services to retrieve all necessary data."}]},{"type":"paragraph","content":[{"type":"text","text":"A federated GraphQL API solves this problem by providing a single, unified interface to multiple services. Clients send a single GraphQL query to the federation layer, which handles fetching data from the appropriate services and aggregating it into a cohesive response."}]},{"type":"paragraph","content":[{"type":"text","text":"This approach offers several significant benefits:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Reduced network requests"},{"type":"text","text":": Clients make just one request to the federated API instead of multiple requests to different services, reducing latency and bandwidth usage."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Simplified client code"},{"type":"text","text":": Developers write a single GraphQL query to retrieve data across service boundaries, eliminating complex data-fetching orchestration code."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Centralized data fetching logic"},{"type":"text","text":": The federation layer manages complex data retrieval patterns, including cross-service relationships, without burdening client applications."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Enhanced caching"},{"type":"text","text":": The federation layer can implement intelligent caching strategies, reducing load on downstream services and improving response times."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Incremental adoption"},{"type":"text","text":": Teams can add services to the federation incrementally, without disrupting existing functionality."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"example"},"content":[{"type":"text","text":"Example"}]},{"type":"paragraph","content":[{"type":"text","text":"To understand our API and its federation, it makes sense to first see an example query."}]},{"type":"codeBlock","attrs":{"language":"graphql","title":null,"meta":null},"content":[{"type":"text","text":"query {\n  getLatestVideos(limit: 2) {\n    id # videos-service\n\n    title # videos-service\n\n    creditsForRole(role: \"host\") {\n      person {\n        forename # people-service\n        surname # people-service\n\n        biography  # people-biographies-service\n\n        links {\n          url  # people-links-service\n        }\n      }\n    }\n\n    likes  # video-likes-service\n  }\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"As you can see from the comments above, this single query is fetching data from multiple services. The "},{"type":"text","marks":[{"type":"code"}],"text":"getLatestVideos"},{"type":"text","text":" field is from the "},{"type":"text","marks":[{"type":"code"}],"text":"videos-service"},{"type":"text","text":", and it''s returning the "},{"type":"text","marks":[{"type":"code"}],"text":"id"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"title"},{"type":"text","text":" of the video. We''re also fetching the "},{"type":"text","marks":[{"type":"code"}],"text":"creditsForRole"},{"type":"text","text":" from the "},{"type":"text","marks":[{"type":"code"}],"text":"people-service"},{"type":"text","text":", the "},{"type":"text","marks":[{"type":"code"}],"text":"biography"},{"type":"text","text":" from the "},{"type":"text","marks":[{"type":"code"}],"text":"people-biographies-service"},{"type":"text","text":", and the "},{"type":"text","marks":[{"type":"code"}],"text":"links"},{"type":"text","text":" from the "},{"type":"text","marks":[{"type":"code"}],"text":"people-links-service"},{"type":"text","text":". Finally, we''re fetching the "},{"type":"text","marks":[{"type":"code"}],"text":"likes"},{"type":"text","text":" from the "},{"type":"text","marks":[{"type":"code"}],"text":"video-likes-service"},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":3,"id":"adding-columns-with-a-service"},"content":[{"type":"text","text":"Adding Columns with a Service?!"}]},{"type":"paragraph","content":[{"type":"text","text":"Yes! It''s pretty common to need to add new fields to an existing entity. Now, you could modify your micro-service and add a new column, but this requires a database migration ... which is usually OK; right? 😅"}]},{"type":"paragraph","content":[{"type":"text","text":"What if we can avoid modifying a service, writing a database migration, and potentially invalditing all presently existing backups? 🤔"}]},{"type":"paragraph","content":[{"type":"text","text":"Well, we can. We can write a new service that persists the new column, all on its own and use some GraphQL magic to stitch it all together."}]},{"type":"paragraph","content":[{"type":"text","text":"This approach allows you to be more agile, take risks, and be experimental without impacting the stability of your existing services. Added a new column via a service and want to get rid of it? Easy done. Just remove the service and the column is gone."}]},{"type":"heading","attrs":{"level":2,"id":"our-federated-graphql-stack"},"content":[{"type":"text","text":"Our Federated GraphQL Stack"}]},{"type":"paragraph","content":[{"type":"text","text":"Our federated GraphQL API is built using Apollo Federation''s specification, but we''ve chosen to implement it using a fully open-source stack."}]},{"type":"diagram","attrs":{"id":"federated-graphql-stack","title":"Federated GraphQL service stack","description":"An API client sends requests through WunderGraph Cosmo to two services. Each service uses GraphQL Yoga, Drizzle ORM, and its own libSQL or Turso database.","language":"d2","source":"API Client -> WunderGraph Cosmo\n\nWunderGraph Cosmo -> Service A\nWunderGraph Cosmo -> Service B\nService A -> GraphQL Yoga A\nGraphQL Yoga A -> Drizzle ORM A\nDrizzle ORM A -> libSQL / Turso A\n\nService B -> GraphQL Yoga B\nGraphQL Yoga B -> Drizzle ORM B\nDrizzle ORM B -> libSQL / Turso B\n","meta":"sketch","src":"https://content.rawkode.academy/articles/federated-graphql-microservices/diagrams/576d733ce064c31b.svg"}},{"type":"heading","attrs":{"level":3,"id":"graphql-yoga"},"content":[{"type":"text","text":"GraphQL Yoga"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://the-guild.dev/graphql/yoga-server","target":null,"rel":null,"class":null,"title":null}}],"text":"GraphQL Yoga"},{"type":"text","text":" serves as our GraphQL server, chosen for its:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Flexibility"},{"type":"text","text":": Runs anywhere JavaScript can run, including Cloudflare Workers and Deno (our preferred environment over Node.js)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Simplicity"},{"type":"text","text":": Offers straightforward setup with sensible defaults"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Extensibility"},{"type":"text","text":": Supports a rich plugin ecosystem"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Federation support"},{"type":"text","text":": Natively implements Apollo Federation specifications"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"pothos"},"content":[{"type":"text","text":"Pothos"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://pothos-graphql.dev/","target":null,"rel":null,"class":null,"title":null}}],"text":"Pothos"},{"type":"text","text":" is our TypeScript schema builder, selected after evaluating several alternatives. Key advantages include:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Type safety"},{"type":"text","text":": Provides end-to-end type safety from database to GraphQL schema"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Code-first approach"},{"type":"text","text":": Enables us to define schemas in TypeScript rather than SDL"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Plugin architecture"},{"type":"text","text":": Offers modular functionality including direct Drizzle ORM integration"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Developer experience"},{"type":"text","text":": Excellent autocompletion and type inference"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"wundergraph-cosmo"},"content":[{"type":"text","text":"WunderGraph Cosmo"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://wundergraph.com","target":null,"rel":null,"class":null,"title":null}}],"text":"WunderGraph Cosmo"},{"type":"text","text":" manages our federated graph lifecycle, offering:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Composition checks"},{"type":"text","text":": Validates schema changes against the complete federated graph"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Router"},{"type":"text","text":": Efficiently directs queries to the appropriate subgraphs"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Analytics"},{"type":"text","text":": Provides insights into API usage patterns"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Distributed tracing"},{"type":"text","text":": Helps identify performance bottlenecks across services"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Schema registry"},{"type":"text","text":": Maintains a history of schema changes and enables rollbacks"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Caching"},{"type":"text","text":": Implements intelligent caching strategies to improve performance, at the service, row, and even column level."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"building-our-federated-graphql-api"},"content":[{"type":"text","text":"Building Our Federated GraphQL API"}]},{"type":"paragraph","content":[{"type":"text","text":"To demonstrate the power of our approach, let''s walk through a real-world example: adding a new field to an existing entity without modifying the original service. We''ll add thumbnail capabilities to videos by creating a dedicated thumbnails service."}]},{"type":"heading","attrs":{"level":3,"id":"defining-the-database-schema"},"content":[{"type":"text","text":"Defining the Database Schema"}]},{"type":"paragraph","content":[{"type":"text","text":"We use "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://orm.drizzle.team/","target":null,"rel":null,"class":null,"title":null}}],"text":"Drizzle ORM"},{"type":"text","text":" for all our database interactions, providing type-safe queries and automated migrations."}]},{"type":"paragraph","content":[{"type":"text","text":"Here''s the existing schema from our "},{"type":"text","marks":[{"type":"code"}],"text":"videos"},{"type":"text","text":" service:"}]},{"type":"codeBlock","attrs":{"language":"typescript","title":null,"meta":null},"content":[{"type":"text","text":"import { createId } from ''@paralleldrive/cuid2'';\nimport { integer, sqliteTable, text } from ''drizzle-orm/sqlite-core'';\n\nexport const videosTable = sqliteTable(''videos'', {\n  id: text(''id'').primaryKey().$default(createId),\n  title: text(''title'').notNull(),\n  subtitle: text(''subtitle'').notNull(),\n  slug: text(''slug'').notNull().unique(),\n  description: text(''description'').notNull(),\n  duration: integer({ mode: ''number'' }).notNull(),\n  publishedAt: integer({ mode: ''timestamp'' }).notNull(),\n});"}]},{"type":"paragraph","content":[{"type":"text","text":"Now, we''ll create a new service, "},{"type":"text","marks":[{"type":"code"}],"text":"thumbnails"},{"type":"text","text":", with its own schema:"}]},{"type":"codeBlock","attrs":{"language":"typescript","title":null,"meta":null},"content":[{"type":"text","text":"import { sqliteTable, text } from ''drizzle-orm/sqlite-core'';\n\nexport const thumbnailsTable = sqliteTable(''video-thumbnails'', {\n  // References the video ID from the videos service\n  id: text(''id'').notNull().unique(),\n  // URL to the thumbnail image\n  url: text(''url'').notNull(),\n});"}]},{"type":"paragraph","content":[{"type":"text","text":"This simple schema allows us to store thumbnail URLs associated with video IDs. Drizzle''s "},{"type":"text","marks":[{"type":"code"}],"text":"drizzle-kit"},{"type":"text","text":" handles migration generation and application for us. Drizzle also has a wonderful plugin ecosystem, allowing us to convert out Drizzle types to many other formats, as well as defining DTOs for other APIs based on the database schema."}]},{"type":"heading","attrs":{"level":3,"id":"defining-the-graphql-schema"},"content":[{"type":"text","text":"Defining the GraphQL Schema"}]},{"type":"paragraph","content":[{"type":"text","text":"Next, we transform our database schema into a GraphQL type using Pothos with its Drizzle plugin. The key to federation is how we reference and extend existing types. As our "},{"type":"text","marks":[{"type":"code"}],"text":"Video"},{"type":"text","text":" type is defined in the "},{"type":"text","marks":[{"type":"code"}],"text":"videos"},{"type":"text","text":" service, we need to reference it in our new service to be able to extend it with our new columns / fields."}]},{"type":"codeBlock","attrs":{"language":"typescript","title":null,"meta":null},"content":[{"type":"text","text":"import drizzlePlugin from ''@pothos/plugin-drizzle'';\nimport { eq } from ''drizzle-orm'';\nimport * as dataSchema from ''./schema.ts'';\n\n// Create a GraphQL schema builder with Drizzle plugin\nconst builder = new SchemaBuilder({\n  plugins: [drizzlePlugin()],\n});\n\n// Reference and extend the Video type from another service\nbuilder.externalRef(\n  ''Video'',\n  builder.selection<{ id: string }>(''id''),\n).implement({\n  // The ''id'' field is defined in the original videos service\n  externalFields: (t) => ({\n    id: t.string(),\n  }),\n  // Add our new thumbnail field to the Video type\n  fields: (t) => ({\n    thumbnail: t.field({\n      type: ''String'',\n      nullable: true,\n      resolve: async (video) => {\n        // Use Drizzle to query the thumbnail for this video\n        const result = await db.query.videoThumbnails.findFirst({\n          columns: {\n            url: true,\n          },\n          where: eq(dataSchema.videoThumbnails.id, video.id),\n        });\n\n        return result?.url || '''';\n      },\n    }),\n  }),\n});"}]},{"type":"paragraph","content":[{"type":"text","text":"The magic of federation happens in these few lines. We''re:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Declaring that we know about an external "},{"type":"text","marks":[{"type":"code"}],"text":"Video"},{"type":"text","text":" type"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Specifying that we need the "},{"type":"text","marks":[{"type":"code"}],"text":"id"},{"type":"text","text":" field to resolve references"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Adding our new "},{"type":"text","marks":[{"type":"code"}],"text":"thumbnail"},{"type":"text","text":" field to the existing "},{"type":"text","marks":[{"type":"code"}],"text":"Video"},{"type":"text","text":" type"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Providing a resolver that fetches the thumbnail URL from our database"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This approach follows Apollo Federation''s "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://www.apollographql.com/docs/federation/entities/","target":null,"rel":null,"class":null,"title":null}}],"text":"entity resolution pattern"},{"type":"text","text":", allowing the federation layer to \"stitch together\" data from multiple services."}]},{"type":"heading","attrs":{"level":3,"id":"publishing-the-schema-changes"},"content":[{"type":"text","text":"Publishing the Schema Changes"}]},{"type":"paragraph","content":[{"type":"text","text":"After defining our schema, we need to register it with WunderGraph Cosmo. First, we generate an SDL representation of our schema:"}]},{"type":"codeBlock","attrs":{"language":"typescript","title":null,"meta":null},"content":[{"type":"text","text":"import { printSchemaWithDirectives } from ''@graphql-tools/utils'';\nimport { lexicographicSortSchema } from ''graphql'';\nimport { getSchema } from ''./schema.ts'';\n\n// Convert our code-first schema to SDL format\nconst schemaAsString = printSchemaWithDirectives(\n  lexicographicSortSchema(getSchema()),\n  {\n    pathToDirectivesInExtensions: [''''],\n  },\n);\n\n// Write the schema to a file\nDeno.writeFileSync(\n  `${import.meta.dirname}/schema.gql`,\n  new TextEncoder().encode(schemaAsString),\n);"}]},{"type":"paragraph","content":[{"type":"text","text":"Then, we publish this schema to Cosmo using the WunderGraph CLI:"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"bunx wgc subgraph publish ${SERVICE_NAME} \\\n  --namespace production \\\n  --schema ./read-model/schema.gql \\\n  --routing-url https://${SERVICE_NAME}-read-458678766461.europe-west2.run.app"}]},{"type":"paragraph","content":[{"type":"text","text":"Cosmo then:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Validates our schema against the existing federation"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Checks for breaking changes"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Updates the router configuration"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Notifies us of any issues or successful completion"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"why-we-love-this-approach"},"content":[{"type":"text","text":"Why We Love This Approach"}]},{"type":"paragraph","content":[{"type":"text","text":"This architecture has transformed how we build and expose our services:"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Incremental evolution"},{"type":"text","text":": We can add fields and capabilities without modifying existing services, enabling parallel development by multiple teams."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Type safety throughout"},{"type":"text","text":": With Drizzle and Pothos, we have end-to-end type safety from database to API, catching errors at compile time rather than runtime."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Developer autonomy"},{"type":"text","text":": Teams can evolve their domains independently while maintaining a cohesive API for consumers."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Operational visibility"},{"type":"text","text":": WunderGraph Cosmo provides comprehensive monitoring, alerting, and tracing, making it easier to identify and resolve issues."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Read-write separation"},{"type":"text","text":": By focusing our federation on read operations, we''ve simplified our architecture while maintaining clear command responsibility in individual services."}]},{"type":"heading","attrs":{"level":2,"id":"challenges"},"content":[{"type":"text","text":"Challenges"}]},{"type":"paragraph","content":[{"type":"text","text":"We''ll be honest, we''ve not hit any huge problems yet with this architecture; it''s allowed us to move fast and make mistakes without compromising the system."}]},{"type":"paragraph","content":[{"type":"text","text":"We will admit that the setup of a new service is currently a lot of copy and paste and duplicate code within our repository that could be easily generated. We''re actively exploring the "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://projen.io/","target":null,"rel":null,"class":null,"title":null}}],"text":"Projen"},{"type":"text","text":" project to help us build out a template for read-layer APIs that are generated when you run "},{"type":"text","marks":[{"type":"code"}],"text":"bun"},{"type":"text","text":" or "},{"type":"text","marks":[{"type":"code"}],"text":"deno"},{"type":"text","text":" install."}]},{"type":"paragraph","content":[{"type":"text","text":"This will allow us to remove the duplicated code and each read-layer service would be just the Drizzle objects and the GraphQL extension points; nice, right?"}]},{"type":"heading","attrs":{"level":2,"id":"conclusion"},"content":[{"type":"text","text":"Conclusion"}]},{"type":"paragraph","content":[{"type":"text","text":"Federated GraphQL has proven to be a powerful solution for our microservice architecture, providing a unified API that simplifies client development while preserving service autonomy. By leveraging open-source tools like GraphQL Yoga, Pothos, and WunderGraph Cosmo, we''ve built a robust, scalable system that supports rapid development across multiple teams."}]},{"type":"paragraph","content":[{"type":"text","text":"If you''re facing challenges with API integration in a microservice environment, we highly recommend considering a federated GraphQL approach. The initial investment in setting up the federation layer pays dividends in development speed, code quality, and system performance. Thanks for reading, we promise not to leave it as long next time for the next article."}]},{"type":"paragraph","content":[{"type":"text","text":"We''ll be back with you right after KubeCon London, 2025."}]}]}', 'article', 0, 0, NULL, '[]', '[]', 'https://content.rawkode.academy/articles/federated-graphql-microservices/cover.png', 'Multiple semi-transparent layers, each with a different abstract pattern or texture. As the layers stack towards the center, they blend and become more unified, representing the abstraction process.', 1472, 832, 'GraphQL Federation for Microservice Architectures', 'Seamless Data Access Across Service Boundaries Without Compromise', '[]', '[]', 1742774400000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('federated-graphql-microservices', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('federated-graphql-microservices', 'wundergraph', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('federated-graphql-microservices', 'dgraph', 1);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('federated-graphql-microservices', 'kubernetes', 2);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('how-i-git', 'How I Git', NULL, 'I''ve been slinging code for nearly 20 years now. I''ve navigated the murky waters of version control,...', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I''ve been slinging code for nearly 20 years now. I''ve navigated the murky waters of version control, starting with CVS, Subversion, Perforce, and Git; with the latter being my de-facto since around 2010."}]},{"type":"heading","attrs":{"level":3,"id":"mild-rant-about-git"},"content":[{"type":"text","text":"Mild Rant About Git"}]},{"type":"paragraph","content":[{"type":"text","text":"Git isn''t the version control system I want, but it is the version control system I have. I won''t complain too much, but why does Git require an email address to identify authors and why can''t a commit have multiple authors? Pfft."}]},{"type":"paragraph","content":[{"type":"text","text":"I firmly believe that we''re stuck with Git. The only company that can change that is GitHub; providing a newer better VCS that would allow interoperability with Git while we all migrate over."}]},{"type":"paragraph","content":[{"type":"text","text":"Will that ever happen? Doubtful :disappointed:"}]},{"type":"heading","attrs":{"level":3,"id":"cloning-repositories"},"content":[{"type":"text","text":"Cloning Repositories"}]},{"type":"paragraph","content":[{"type":"text","text":"First, we''ll start with the simplest of concerns ..."}]},{"type":"heading","attrs":{"level":4,"id":"clone-to-where"},"content":[{"type":"text","text":"Clone to Where?"}]},{"type":"paragraph","content":[{"type":"text","text":"I clone all my repositories to "},{"type":"text","marks":[{"type":"code"}],"text":"~/Code/src"},{"type":"text","text":". This is also my "},{"type":"text","marks":[{"type":"code"}],"text":"GOPATH"},{"type":"text","text":". For Go developers, this is likely unsurprising."}]},{"type":"paragraph","content":[{"type":"text","text":"I used to keep my Go projects and other code in separate directories, but eventually this become quite natural to adopt the \"Go way\"."}]},{"type":"paragraph","content":[{"type":"text","text":"Inside of "},{"type":"text","marks":[{"type":"code"}],"text":"~/Code/src"},{"type":"text","text":" is a directory for every host that I clone repositories from. Inside their, orgs/usernames. Inside them, individual repositories."}]},{"type":"paragraph","content":[{"type":"text","text":"It looks like this:"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"~/Code/src:\n\n├── aur.archlinux.org\n│  ├── fluxlang\n│  ├── pulumi-bin\n│  └── yay\n├── github.com\n│  ├── chaoss\n│  │  └── augur\n│  ├── influxdata\n│  │  ├── flux\n│  │  ├── influxdb\n│  │  ├── telegraf\n│  ├── pulumi\n│  │  └── pulumi\n│  ├── rawkode\n│  │  ├── dotfiles\n│  │  ├── influxdb-examples\n│  │  ├── kubernetes-workshop\n│  │  ├── modern-life\n│  │  ├── php-stat-influxdb\n│  │  └── saltstack-dotfiles\n└── golang.org\n   └── x\n      ├── lint\n      └── tools"}]},{"type":"heading","attrs":{"level":4,"id":"the-actual-cloning"},"content":[{"type":"text","text":"The Actual Cloning"}]},{"type":"paragraph","content":[{"type":"text","text":"There are two rules when cloning repositories:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clone Over HTTPs"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Never clone a fork directly"}]}]}]},{"type":"heading","attrs":{"level":4,"id":"clone-over-https"},"content":[{"type":"text","text":"Clone Over HTTPS"}]},{"type":"paragraph","content":[{"type":"text","text":"I''m a rather cautious person. I''ve got into the habit of only cloning public repositories over HTTPs so that I never accidentally push to master. Even if I don''t own the repository, i''ve made this my default and it keeps me sane."}]},{"type":"paragraph","content":[{"type":"text","text":"NB: This is a \"whenever possible\" rule. For private repositories, you will need to use ssh cloning; so always adopt the rule below too."}]},{"type":"heading","attrs":{"level":4,"id":"never-clone-a-fork-directly"},"content":[{"type":"text","text":"Never Clone a Fork Directly"}]},{"type":"paragraph","content":[{"type":"text","text":"If you fork a repository, always clone the origin first."}]},{"type":"paragraph","content":[{"type":"text","text":"As an example. I have a fork of my companies primary product, InfluxDB."}]},{"type":"paragraph","content":[{"type":"text","text":"I clone this with "},{"type":"text","marks":[{"type":"code"}],"text":"git clone https://github.com/influxdb/influxdb"}]},{"type":"paragraph","content":[{"type":"text","text":"I then add my fork as a remote with "},{"type":"text","marks":[{"type":"code"}],"text":"git remote add rawkode git@github.com:rawkode/influxdb"}]},{"type":"paragraph","content":[{"type":"text","text":"Now, when you''ve made your awesome changes to some OSS project; you push with "},{"type":"text","marks":[{"type":"code"}],"text":"git push rawkode"},{"type":"text","text":". Simples! :tada:"}]},{"type":"heading","attrs":{"level":5,"id":"tip"},"content":[{"type":"text","text":"Tip"}]},{"type":"paragraph","content":[{"type":"text","text":"GitHub has a cool CLI command called "},{"type":"text","marks":[{"type":"code"}],"text":"hub"},{"type":"text","text":" that allows you perform the above with "},{"type":"text","marks":[{"type":"code"}],"text":"hub fork"}]},{"type":"heading","attrs":{"level":3,"id":"working-with-git"},"content":[{"type":"text","text":"Working with Git"}]},{"type":"paragraph","content":[{"type":"text","text":"Now that I''ve got lots of code available to work on, how do I work with it?"}]},{"type":"heading","attrs":{"level":4,"id":"gpg-signing"},"content":[{"type":"text","text":"GPG Signing"}]},{"type":"paragraph","content":[{"type":"text","text":"I always ensure that I sign my commits with my GPG key. If you aren''t comfortable provisioning your own GPG key, checkout "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://keybase.io","target":null,"rel":null,"class":null,"title":null}}],"text":"Keybase"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Very little is required to configure GPG signing. Some people specify their key in the config, but as I only have one secret key available locally, as you probably will too, it''s not required."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"[gpg]\n  program = gpg\n[commit]\n  gpgsign = true"}]},{"type":"heading","attrs":{"level":4,"id":"commit-template"},"content":[{"type":"text","text":"Commit Template"}]},{"type":"paragraph","content":[{"type":"text","text":"My Git commits are terrible. I''ve been using a template lately to remind myself when the commit screen pops up that I should do better."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"[commit]\n  template = ~/.git/templates/commit"}]},{"type":"paragraph","content":[{"type":"text","text":"I''ve got an old "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/rawkode/saltstack-dotfiles/blob/master/states/development/git/files/templates/commit.txt","target":null,"rel":null,"class":null,"title":null}}],"text":"template"},{"type":"text","text":" that I''ve used for years, but more recently I''ve been trying to adopt "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://seesparkbox.com/foundry/semantic_commit_messages","target":null,"rel":null,"class":null,"title":null}}],"text":"Semantic Commits"},{"type":"text","text":", such as:"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"feat: add hat wobble\n^--^  ^------------^\n|     |\n|     +-> Summary in present tense.\n|\n+-------> Type: chore, docs, feat, fix, refactor, style, or test."}]},{"type":"heading","attrs":{"level":4,"id":"default-editor"},"content":[{"type":"text","text":"Default Editor"}]},{"type":"paragraph","content":[{"type":"text","text":"I use VSCode for all my editing now, even Git commits :smile:"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"[core]\n  editor = code --wait"}]},{"type":"heading","attrs":{"level":4,"id":"aliases"},"content":[{"type":"text","text":"Aliases"}]},{"type":"paragraph","content":[{"type":"text","text":"Here are some of my favourite aliases."}]},{"type":"heading","attrs":{"level":5,"id":"pull"},"content":[{"type":"text","text":"Pull"}]},{"type":"paragraph","content":[{"type":"text","text":"I really like dislike merge commits. So much so, I always do a pull with a rebase to neatly, and cleanly, merge in missing changes; keeping my commits at the top."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"[alias]\n  pl = pull --rebase"}]},{"type":"heading","attrs":{"level":5,"id":"cane"},"content":[{"type":"text","text":"Cane"}]},{"type":"paragraph","content":[{"type":"text","text":"Ever committed something and forgot to add a file? Ever committed a fix that wasn''t actually the fix and then had to add a new commit with the actual fix? Yep. You need "},{"type":"text","marks":[{"type":"code"}],"text":"git cane"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"This will add / stage changes and add them to your previous commit."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"[alias]\n  cane = commit --amend --no-edit"}]},{"type":"heading","attrs":{"level":5,"id":"the-rest"},"content":[{"type":"text","text":"The Rest"}]},{"type":"paragraph","content":[{"type":"text","text":"These are all rather simple short cuts."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"[alias]\n  cm = commit -v\n  co = checkout\n  ps = push\n  st = status"}]},{"type":"horizontalRule"},{"type":"paragraph","content":[{"type":"text","text":"That''s it! That''s \"How I Git\" :smile: If you found this useful, let me know on "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://twitter.com/rawkode","target":null,"rel":null,"class":null,"title":null}}],"text":"Twitter"},{"type":"text","text":" and I''ll follow up some with new Git tips."}]},{"type":"paragraph","content":[{"type":"text","text":"Thanks for reading :wave:"}]}]}', 'article', 0, 0, NULL, '[]', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1569196800000, 1569196800000, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('how-i-git', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('how-i-git', 'git', 0);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('how-to-ask-for-help', 'How to ask for help', NULL, 'Master the art of asking technical questions that get helpful responses', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When you are asking a bunch of strangers for help on the internet, there are tricks to get people to be more willing to help you."}]},{"type":"paragraph","content":[{"type":"text","text":"Unless you are paying for support, you need to make it as easy as possible for volunteers to help you."}]},{"type":"paragraph","content":[{"type":"text","text":"Here''s some advice to help people help you."}]},{"type":"heading","attrs":{"level":2,"id":"make-it-easy-to-read"},"content":[{"type":"text","text":"Make it Easy to Read"}]},{"type":"paragraph","content":[{"type":"text","text":"Learn the system you''re writing on so you can convey the information clearly. Having to read badly formatted text is not a nice introduction to your problem."}]},{"type":"paragraph","content":[{"type":"text","text":"Separate your question from the log outputs, most systems will have a way to enter code. Use that code format for logs, code, config, etc. Keep each type of sample separate, or at least spaced out well enough, with a comment to show what it is."}]},{"type":"heading","attrs":{"level":3,"id":"example"},"content":[{"type":"text","text":"Example"}]},{"type":"codeBlock","attrs":{"language":"plaintext","title":"dmesg log with error","meta":null},"content":[{"type":"text","text":"[331337.438088] hub 4-0:1.0: 2 ports detected\n[331337.465300] ACPI: bus type thunderbolt registered\n[331337.612428] thunderbolt 0000:08:00.0: 0: DROM device_rom_revision 0x0 unknown\n[331337.613424] thunderbolt 0-0: ignoring unnecessary extra entries in DROM\n[331342.334285] ieee80211 phy0: brcmf_inetaddr_changed: fail to get arp ip table err:-52\n[331357.956017] xhci_hcd 0000:3e:00.0: Unable to change power state from D3cold to D0, device inaccessible\n[331357.956034] xhci_hcd 0000:3e:00.0: Controller not ready at resume -19\n[331357.956035] xhci_hcd 0000:3e:00.0: PCI post-resume error -19!\n[331357.956037] xhci_hcd 0000:3e:00.0: HC died; cleaning up\n# partial results from lspci\n00:1c.0 PCI bridge: Intel Corporation 100 Series/C230 Series Chipset Family PCI Express Root Port #1 (rev f1)\n00:1c.1 PCI bridge: Intel Corporation 100 Series/C230 Series Chipset Family PCI Express Root Port #2 (rev f1)"}]},{"type":"heading","attrs":{"level":2,"id":"reproducible-issue"},"content":[{"type":"text","text":"Reproducible Issue"}]},{"type":"paragraph","content":[{"type":"text","text":"Where possible create a minimal reproduction of the issue. This lets people try recreate the issue with your config and prevents you from leaking secrets that might need to stay secret."}]},{"type":"paragraph","content":[{"type":"text","text":"Unless you are certain the problem exists in just one file, make people''s lives easier by giving as much info as possible."}]},{"type":"paragraph","content":[{"type":"text","text":"The best way to do that is a cut down, reproducible sample."}]},{"type":"heading","attrs":{"level":2,"id":"explain-environment"},"content":[{"type":"text","text":"Explain Environment"}]},{"type":"paragraph","content":[{"type":"text","text":"Explain the environment you are running in, it may well be an environmental issue you are facing. Things like what hardware, software and config (where you can) it''s running - i.e. Docker version 24.0.2, build cb74dfcd85 on a laptop running Debian 11.7 stable, an AWS VM "},{"type":"text","marks":[{"type":"code"}],"text":"m7g.large"},{"type":"text","text":" running Amazon Linux, etc."}]},{"type":"heading","attrs":{"level":2,"id":"make-it-quick--easy-for-people"},"content":[{"type":"text","text":"Make it Quick & Easy for People"}]},{"type":"paragraph","content":[{"type":"text","text":"Be conscious of the amount of time people have to spend to get up to speed. This ties in with the reproducible sample. Don''t post a link to an instruction you followed. If you do that and nothing else you are expecting people to read through that article which takes precious time. Even after reading it, unless there is an obvious mistake in the article, it may not assist you as chances are you''ve done something different to the article. Maybe you missed a step, maybe you made a typo, used different hosting options, used different versions of software. Feel free to add that you followed an article, but don''t expect people helping you to have to read that article before getting started."}]},{"type":"heading","attrs":{"level":2,"id":"explain-your-steps-so-far"},"content":[{"type":"text","text":"Explain Your Steps so Far"}]},{"type":"paragraph","content":[{"type":"text","text":"State what you have tried and what you think it might be, there is nothing less rewarding than helping someone who''s tried nothing for themselves and given up."}]},{"type":"heading","attrs":{"level":2,"id":"provide-useful-information"},"content":[{"type":"text","text":"Provide Useful Information"}]},{"type":"paragraph","content":[{"type":"text","text":"If someone is helping you, please reply with more than just \"that doesn''t work\". Show how you followed their advice and what the result was. If you aren''t paying in cash for the help, pay in effort, show people you''ve done as they asked and the exact result of what happened."}]},{"type":"heading","attrs":{"level":2,"id":"make-single-changes"},"content":[{"type":"text","text":"Make Single Changes"}]},{"type":"paragraph","content":[{"type":"text","text":"Change one thing at a time. If more than one person responds, don''t apply more than one suggestion at a time. You need to see what each change does. The exception is when you are explicitly told to apply more than one fix as they can see you have more than one issue. Even then though, it''s just good practice to make a single change and see what it does."}]}]}', 'guide', 1, 0, NULL, '[]', '[]', NULL, NULL, NULL, NULL, 'Need Help?', 'Learn to ask questions that people want to answer', '[]', '[]', 1698710400000, 1699574400000, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('how-to-ask-for-help', 'russellwaite', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('how-to-ask-for-help', 'kubernetes', 0);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('introducing-cuenv', 'Introducing cuenv: Type-Safe Environments and Parallel Tasks with CUE', NULL, 'Meet cuenv, a modern CLI tool that brings type-safe environment variables, secure secret management, and intelligent parallel task execution to your development workflow. All powered by CUE''s constraint-based configuration.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Look at your development toolchain. You''re probably running direnv for environment variables, Just or Make for tasks, mise or asdf for tool versions, and maybe Turborepo for monorepo orchestration. Each tool has its own configuration format, its own quirks, and none of them talk to each other."}]},{"type":"paragraph","content":[{"type":"text","text":"I got tired of this fragmentation. I wanted one tool that could handle environments, tasks, and secrets with proper type safety and a configuration model that actually works for monorepos."}]},{"type":"paragraph","content":[{"type":"text","text":"That''s why I built "},{"type":"text","marks":[{"type":"bold"}],"text":"cuenv"},{"type":"text","text":". It leverages CUE''s greatest strength: its hierarchical configuration model. Configuration flows naturally from the module root down to your current working directory, exactly what you need when managing complex project structures. No more copy-pasting Justfiles or fighting with direnv''s "},{"type":"text","marks":[{"type":"code"}],"text":".envrc"},{"type":"text","text":" inheritance."}]},{"type":"paragraph","content":[{"type":"text","text":"The final piece of the puzzle was the release of the "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://cue.dev/products/central-registry/","target":null,"rel":null,"class":null,"title":null}}],"text":"CUE Central Registry"},{"type":"text","text":". That was the catalyst I needed to start building."}]},{"type":"aside","attrs":{"variant":"caution"},"content":[{"type":"paragraph","content":[{"type":"text","text":"In case you want to know up front, cuenv has been heavily made possible by guiding my army of AI agents. Please note, I have been a developer for over 20 years. I can code. I can mentor and guide. I use AI agents to make building things go from taking months to weeks. If that is a red flag for you, I''ve saved you some time. Enjoy your day."}]}]},{"type":"heading","attrs":{"level":2,"id":"what-development-environments-actually-need"},"content":[{"type":"text","text":"What Development Environments Actually Need"}]},{"type":"paragraph","content":[{"type":"text","text":"Think about what you need when you sit down to work on a project:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Software"},{"type":"text","text":": compilers, runtimes, databases, CLI tools"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Environment variables"},{"type":"text","text":": configuration that tells your app how to behave"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Secrets"},{"type":"text","text":": API keys, database passwords, credentials you can''t commit"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Most developers cobble together solutions: direnv for variables, mise or asdf for tool versions, some combination of "},{"type":"text","marks":[{"type":"code"}],"text":".env"},{"type":"text","text":" files and shell scripts for secrets. It works, but it''s fragmented. Nothing validates your config. Nothing ensures consistency across your team."}]},{"type":"paragraph","content":[{"type":"text","text":"cuenv handles all three concerns in a single, type-safe configuration file:"}]},{"type":"codeBlock","attrs":{"language":"cue","title":null,"meta":null},"content":[{"type":"text","text":"package cuenv\n\nimport \"github.com/cuenv/cuenv/schema\"\n\nschema.#Cuenv\n\nhooks: onEnter: nix: schema.#NixFlake\n\nenv: {\n    DATABASE_URL: \"postgres://localhost/mydb\"\n    DEBUG:        true\n    PORT:         3000\n    // Interpolation\n    BASE_URL:     \"https://api.example.com\"\n    API_ENDPOINT: \"\\(BASE_URL)/v1\"\n}\n\ntasks: dev: { command: \"bun\", args: [\"run\", \"dev\"] }"}]},{"type":"paragraph","content":[{"type":"text","text":"Let''s walk through what''s happening here:"}]},{"type":"heading","attrs":{"level":3,"id":"hooks-setup-your-environment-automatically"},"content":[{"type":"text","text":"Hooks: Setup Your Environment Automatically"}]},{"type":"codeBlock","attrs":{"language":"cue","title":null,"meta":null},"content":[{"type":"text","text":"hooks: onEnter: nix: schema.#NixFlake"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","marks":[{"type":"code"}],"text":"hooks.onEnter"},{"type":"text","text":" block runs when you enter a directory. Here, "},{"type":"text","marks":[{"type":"code"}],"text":"nix: schema.#NixFlake"},{"type":"text","text":" tells cuenv to automatically activate your Nix flake environment, installing all your project''s software dependencies in the background. No manual "},{"type":"text","marks":[{"type":"code"}],"text":"nix develop"},{"type":"text","text":", no forgetting to activate."}]},{"type":"paragraph","content":[{"type":"text","text":"cuenv supports multiple hooks: Nix flakes, devenv, or custom shell commands. Your tools are just "},{"type":"text","marks":[{"type":"italic"}],"text":"there"},{"type":"text","text":" when you need them."}]},{"type":"heading","attrs":{"level":3,"id":"env-configuration-without-the-guesswork"},"content":[{"type":"text","text":"Env: Configuration Without the Guesswork"}]},{"type":"codeBlock","attrs":{"language":"cue","title":null,"meta":null},"content":[{"type":"text","text":"env: {\n    DATABASE_URL: \"postgres://localhost/mydb\"\n    DEBUG:        true\n    PORT:         3000\n    BASE_URL:     \"https://api.example.com\"\n    API_ENDPOINT: \"\\(BASE_URL)/v1\"\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"Environment variables are declared explicitly. CUE gives you string interpolation (notice how "},{"type":"text","marks":[{"type":"code"}],"text":"API_ENDPOINT"},{"type":"text","text":" builds on "},{"type":"text","marks":[{"type":"code"}],"text":"BASE_URL"},{"type":"text","text":"), type coercion, and, as we''ll see later, powerful constraints to validate values before they ever reach your application."}]},{"type":"heading","attrs":{"level":3,"id":"tasks-commands-you-run-every-day"},"content":[{"type":"text","text":"Tasks: Commands You Run Every Day"}]},{"type":"codeBlock","attrs":{"language":"cue","title":null,"meta":null},"content":[{"type":"text","text":"tasks: dev: { command: \"bun\", args: [\"run\", \"dev\"] }"}]},{"type":"paragraph","content":[{"type":"text","text":"Tasks are named commands. Instead of remembering "},{"type":"text","marks":[{"type":"code"}],"text":"bun run dev"},{"type":"text","text":" or whatever incantation your project needs, you run "},{"type":"text","marks":[{"type":"code"}],"text":"cuenv task dev"},{"type":"text","text":". Simple, consistent, and as your project grows, these tasks can depend on each other, run in parallel, and cache their results."}]},{"type":"paragraph","content":[{"type":"text","text":"This simple example covers the basics. Now let''s see how cuenv exposes these capabilities through its CLI."}]},{"type":"heading","attrs":{"level":2,"id":"two-commands-infinite-possibilities"},"content":[{"type":"text","text":"Two Commands, Infinite Possibilities"}]},{"type":"paragraph","content":[{"type":"text","text":"cuenv is built around two core commands that handle everything you need:"}]},{"type":"heading","attrs":{"level":3,"id":"cuenv-exec----command-run-anything-securely"},"content":[{"type":"text","marks":[{"type":"code"}],"text":"cuenv exec -- <command>"},{"type":"text","text":": Run Anything, Securely"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"cuenv exec -- npm start\ncuenv exec -e production -- ./deploy.sh\ncuenv exec -- cargo build --release"}]},{"type":"paragraph","content":[{"type":"text","text":"Here''s what happens when you run "},{"type":"text","marks":[{"type":"code"}],"text":"cuenv exec"},{"type":"text","text":":"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Hooks run to completion"},{"type":"text","text":": All "},{"type":"text","marks":[{"type":"code"}],"text":"onEnter"},{"type":"text","text":" hooks execute first. Nix flakes activate, devenv spins up, shell commands run. The first time takes a moment while packages install; subsequent runs are near-instant as everything is already cached and ready."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Secrets resolve"},{"type":"text","text":": Every secret in your "},{"type":"text","marks":[{"type":"code"}],"text":"env:"},{"type":"text","text":" block is fetched from its provider (1Password, GCP, custom CLI) right before execution. No disk writes, no shell exports, just secure, ephemeral values."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Your command executes"},{"type":"text","text":": With hooks complete and the validated, secret-enriched environment in place, your command runs exactly as intended."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"No more hoping your configuration is correct. CUE constraints ensure it is. No more \"works on my machine\". Everyone gets the same environment, every time."}]},{"type":"heading","attrs":{"level":3,"id":"cuenv-task-name-orchestrated-parallel-cached"},"content":[{"type":"text","marks":[{"type":"code"}],"text":"cuenv task <name>"},{"type":"text","text":": Orchestrated, Parallel, Cached"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"cuenv task build\ncuenv task test\ncuenv task -e production deploy"}]},{"type":"paragraph","content":[{"type":"text","text":"Tasks follow the same bulletproof flow:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Hooks run to completion"},{"type":"text","text":": Same as "},{"type":"text","marks":[{"type":"code"}],"text":"exec"},{"type":"text","text":". Your Nix flake or devenv activates, ensuring all tools are available. After the first run, this step is essentially instantaneous."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Secrets resolve"},{"type":"text","text":": Any secrets referenced in "},{"type":"text","marks":[{"type":"code"}],"text":"env:"},{"type":"text","text":" are resolved just-in-time, available to your task but never persisted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Dependencies execute"},{"type":"text","text":": Tasks specified in "},{"type":"text","marks":[{"type":"code"}],"text":"dependsOn"},{"type":"text","text":" run first, with their own caching respected."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Your task runs"},{"type":"text","text":": With the full environment ready, your task executes with automatic dependency resolution, parallel execution, and content-aware caching."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Your CI gets faster without you lifting a finger, and you get the confidence that every run is reproducible."}]},{"type":"heading","attrs":{"level":2,"id":"type-safe-environment-variables"},"content":[{"type":"text","text":"Type-Safe Environment Variables"}]},{"type":"paragraph","content":[{"type":"text","text":"Here''s where CUE truly shines, and why I chose it as cuenv''s foundation. CUE''s "},{"type":"text","marks":[{"type":"bold"}],"text":"hierarchical configuration model"},{"type":"text","text":" was built for exactly this problem: configuration that flows naturally from a module root down through nested directories. This is monorepo nirvana."}]},{"type":"heading","attrs":{"level":3,"id":"configuration-flows-downward"},"content":[{"type":"text","text":"Configuration Flows Downward"}]},{"type":"paragraph","content":[{"type":"text","text":"When you run cuenv, it doesn''t just read the "},{"type":"text","marks":[{"type":"code"}],"text":"env.cue"},{"type":"text","text":" in your current directory. It evaluates "},{"type":"text","marks":[{"type":"bold"}],"text":"all CUE files"},{"type":"text","text":" from your module root down to where you''re standing, unifying them into a single configuration. Define something once at the root, and every subdirectory inherits it automatically."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"my-monorepo/\n├── cue.mod/                    # CUE module root\n├── env.cue                     # Root config: shared across everything\n├── projects/\n│   ├── env.cue                 # Projects config: extends root\n│   ├── api/\n│   │   └── env.cue             # API-specific config\n│   └── web/\n│       └── env.cue             # Web-specific config\n└── infrastructure/\n    └── env.cue                 # Infra-specific config"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Root "},{"type":"text","marks":[{"type":"bold"},{"type":"code"}],"text":"env.cue"},{"type":"text","text":": organization-wide defaults:"}]},{"type":"codeBlock","attrs":{"language":"cue","title":null,"meta":null},"content":[{"type":"text","text":"package cuenv\n\nimport \"github.com/cuenv/cuenv/schema\"\n\nschema.#Cuenv\n\nenv: {\n    // Every project in the monorepo inherits these\n    CLOUDFLARE_ACCOUNT_ID: \"abc123def456\"\n    GCP_PROJECT:           \"rawkode-academy\"\n    GCP_REGION:            \"europe-west2\"\n\n    // Type constraints inherited everywhere\n    LOG_LEVEL: \"debug\" | \"info\" | \"warn\" | \"error\" | *\"info\"\n    NODE_ENV:  \"development\" | \"staging\" | \"production\"\n}"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"},{"type":"code"}],"text":"projects/api/env.cue"},{"type":"text","text":": service-specific overrides:"}]},{"type":"codeBlock","attrs":{"language":"cue","title":null,"meta":null},"content":[{"type":"text","text":"package cuenv\n\nenv: {\n    // Inherits CLOUDFLARE_ACCOUNT_ID, GCP_PROJECT, GCP_REGION from root\n    // Adds API-specific configuration\n    PORT:         8080\n    SERVICE_NAME: \"api\"\n    DATABASE_URL: \"postgres://\\(GCP_REGION)-sql.example.com/api\"\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"When you "},{"type":"text","marks":[{"type":"code"}],"text":"cd projects/api && cuenv exec -- go run ."},{"type":"text","text":", the environment contains "},{"type":"text","marks":[{"type":"bold"}],"text":"everything"},{"type":"text","text":": the root''s "},{"type":"text","marks":[{"type":"code"}],"text":"GCP_PROJECT"},{"type":"text","text":", the API''s "},{"type":"text","marks":[{"type":"code"}],"text":"PORT"},{"type":"text","text":", all unified and validated."}]},{"type":"heading","attrs":{"level":3,"id":"type-constraints-that-travel"},"content":[{"type":"text","text":"Type Constraints That Travel"}]},{"type":"paragraph","content":[{"type":"text","text":"The real magic is that "},{"type":"text","marks":[{"type":"bold"}],"text":"constraints flow downward too"},{"type":"text","text":". Define "},{"type":"text","marks":[{"type":"code"}],"text":"NODE_ENV: \"development\" | \"staging\" | \"production\""},{"type":"text","text":" at the root, and every subdirectory is bound by that constraint. A developer can''t accidentally set "},{"type":"text","marks":[{"type":"code"}],"text":"NODE_ENV: \"prod\""},{"type":"text","text":" in their service config. CUE catches it immediately."}]},{"type":"codeBlock","attrs":{"language":"cue","title":null,"meta":null},"content":[{"type":"text","text":"env: {\n    // Constrained values - violations caught at evaluation time\n    NODE_ENV:  \"development\" | \"staging\" | \"production\"\n    LOG_LEVEL: \"debug\" | \"info\" | \"warn\" | \"error\"\n\n    // Pattern matching for URLs and connection strings\n    DATABASE_URL: string & =~\"^postgresql://\"\n    API_ENDPOINT: string & =~\"^https://\"\n\n    // Numeric bounds with defaults\n    PORT:    >0 & <65536 & *3000\n    TIMEOUT: string | *\"30s\"\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"If someone violates a constraint, cuenv tells them immediately, not at 3 AM when production is on fire."}]},{"type":"heading","attrs":{"level":3,"id":"string-interpolation-across-boundaries"},"content":[{"type":"text","text":"String Interpolation Across Boundaries"}]},{"type":"paragraph","content":[{"type":"text","text":"CUE''s interpolation works across the unified configuration, so you can compose values from any level:"}]},{"type":"codeBlock","attrs":{"language":"cue","title":null,"meta":null},"content":[{"type":"text","text":"env: {\n    // Defined at root\n    GCP_PROJECT: \"rawkode-academy\"\n    GCP_REGION:  \"europe-west2\"\n\n    // Composed in a subdirectory - references flow up the hierarchy\n    STORAGE_BUCKET: \"gs://\\(GCP_PROJECT)-assets-\\(GCP_REGION)\"\n    API_ENDPOINT:   \"https://\\(GCP_REGION)-\\(GCP_PROJECT).cloudfunctions.net\"\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"No more copy-pasting your project ID into every service. Define it once, reference it everywhere."}]},{"type":"heading","attrs":{"level":2,"id":"secrets-without-the-hassle"},"content":[{"type":"text","text":"Secrets Without the Hassle"}]},{"type":"paragraph","content":[{"type":"text","text":"Secrets are often a pain. Wrapping every command with "},{"type":"text","marks":[{"type":"code"}],"text":"op run"},{"type":"text","text":" gets old fast:"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"op run -- bun run dev"}]},{"type":"paragraph","content":[{"type":"text","text":"cuenv handles this for you. Declare your secrets in "},{"type":"text","marks":[{"type":"code"}],"text":"env:"},{"type":"text","text":" and they''re resolved automatically:"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"cuenv exec -- bun run dev"}]},{"type":"heading","attrs":{"level":3,"id":"multiple-providers-one-config"},"content":[{"type":"text","text":"Multiple Providers, One Config"}]},{"type":"paragraph","content":[{"type":"text","text":"The real power is mixing providers. Your database password lives in 1Password, your API keys are in GCP Secret Manager, and that legacy system uses a custom CLI. No problem, declare them all together:"}]},{"type":"codeBlock","attrs":{"language":"cue","title":null,"meta":null},"content":[{"type":"text","text":"env: {\n    // 1Password\n    DB_PASSWORD: schema.#OnePasswordRef & {\n        ref: \"op://vault/database/password\"\n    }\n\n    // Google Cloud Secret Manager\n    STRIPE_KEY: schema.#GcpSecret & {\n        project: \"my-project\"\n        secret:  \"stripe-api-key\"\n        version: \"latest\"\n    }\n\n    // AWS Secrets Manager\n    AWS_SECRET: schema.#AwsSecret & {\n        region: \"us-east-1\"\n        secret: \"prod/api/credentials\"\n    }\n}"}]},{"type":"heading","attrs":{"level":3,"id":"custom-providers"},"content":[{"type":"text","text":"Custom Providers"}]},{"type":"paragraph","content":[{"type":"text","text":"Got an internal secrets tool? A custom vault? Any CLI that can output a secret works:"}]},{"type":"codeBlock","attrs":{"language":"cue","title":null,"meta":null},"content":[{"type":"text","text":"env: {\n    CUSTOM_SECRET: schema.#ExecResolver & {\n        command: \"my-secret-tool\"\n        args: [\"fetch\", \"my-secret\"]\n    }\n\n    VAULT_TOKEN: schema.#ExecResolver & {\n        command: \"vault\"\n        args: [\"kv\", \"get\", \"-field=token\", \"secret/myapp\"]\n    }\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"All your secrets, from any source, resolved together. One command, everything just works."}]},{"type":"heading","attrs":{"level":2,"id":"parallel-task-execution"},"content":[{"type":"text","text":"Parallel Task Execution"}]},{"type":"paragraph","content":[{"type":"text","text":"cuenv''s task model is elegantly simple:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Object keys run in parallel"},{"type":"text","text":" (they have no ordering)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Arrays run sequentially"},{"type":"text","text":" (order matters)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Dependencies are respected automatically"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Defaults control which subtask runs"}]}]}]},{"type":"codeBlock","attrs":{"language":"cue","title":null,"meta":null},"content":[{"type":"text","text":"tasks: {\n    // These three run at the same time when you run `cuenv task lint`\n    lint: {\n        check:  { command: \"eslint\",   args: [\"src/\"] }\n        types:  { command: \"tsc\",      args: [\"--noEmit\"] }\n        format: { command: \"prettier\", args: [\"--check\", \".\"] }\n    }\n\n    // With a default, only `fix` runs when you call `cuenv task fmt`\n    // Run `cuenv task fmt.check` explicitly when needed\n    fmt: {\n        default: \"fix\"\n        check:   { command: \"treefmt\", args: [\"--fail-on-change\"] }\n        fix:     { command: \"treefmt\" }\n    }\n\n    // These run one after another\n    deploy: [\n        { command: \"npm\",     args: [\"run\", \"build\"] }\n        { command: \"docker\",  args: [\"build\", \"-t\", \"app\", \".\"] }\n        { command: \"docker\",  args: [\"push\", \"app\"] }\n        { command: \"kubectl\", args: [\"rollout\", \"restart\", \"deployment/app\"] }\n    ]\n\n    // This waits for lint to complete first\n    build: {\n        command:   \"npm\"\n        args:      [\"run\", \"build\"]\n        dependsOn: [\"lint\"]\n        inputs:    [\"src/**/*\", \"package.json\"]\n        outputs:   [\"dist/**/*\"]\n    }\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","marks":[{"type":"code"}],"text":"inputs"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"outputs"},{"type":"text","text":" fields enable "},{"type":"text","marks":[{"type":"bold"}],"text":"content-aware caching"},{"type":"text","text":". If your source files haven''t changed, cuenv skips the task and uses cached results. Your CI just got a lot faster."}]},{"type":"heading","attrs":{"level":2,"id":"a-real-world-example"},"content":[{"type":"text","text":"A Real-World Example"}]},{"type":"paragraph","content":[{"type":"text","text":"Here''s a snippet from cuenv''s own configuration (yes, cuenv is built with cuenv):"}]},{"type":"codeBlock","attrs":{"language":"cue","title":null,"meta":null},"content":[{"type":"text","text":"package cuenv\n\nimport (\n    \"list\"\n    \"github.com/cuenv/cuenv/schema\"\n)\n\nschema.#Cuenv\n\nhooks: {\n    onEnter: {\n        nix: schema.#NixFlake  // Auto-load Nix environment when entering directory\n    }\n}\n\ntasks: {\n    // Shared input definition\n    #BaseInputs: [\"Cargo.toml\", \"Cargo.lock\", \"crates\"]\n\n    lint: {\n        command: \"cargo\"\n        args: [\"clippy\", \"--workspace\", \"--all-targets\", \"--\", \"-D\", \"warnings\"]\n        inputs: #BaseInputs\n    }\n\n    test: {\n        unit: {\n            command: \"cargo\"\n            args: [\"nextest\", \"run\", \"--workspace\", \"--all-features\"]\n            inputs: list.Concat([#BaseInputs, [\"tests\", \"features\", \"examples\"]])\n        }\n        doc: {\n            command: \"cargo\"\n            args: [\"test\", \"--doc\", \"--workspace\"]\n            inputs: #BaseInputs\n        }\n        bdd: {\n            command: \"cargo\"\n            args: [\"test\", \"--test\", \"bdd\"]\n            inputs: list.Concat([#BaseInputs, [\"tests\", \"features\"]])\n        }\n    }\n\n    build: {\n        command: \"cargo\"\n        args: [\"build\", \"--workspace\", \"--all-features\"]\n        inputs: #BaseInputs\n    }\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"Notice a few things:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"},{"type":"code"}],"text":"#BaseInputs"},{"type":"text","text":" is a CUE definition that''s reused across tasks, no copy-paste"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"},{"type":"code"}],"text":"list.Concat"},{"type":"text","text":" combines input lists dynamically"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"},{"type":"code"}],"text":"test"},{"type":"text","marks":[{"type":"bold"}],"text":" has nested tasks"},{"type":"text","text":" ("},{"type":"text","marks":[{"type":"code"}],"text":"unit"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"doc"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"bdd"},{"type":"text","text":") that run in parallel"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Nix integration"},{"type":"text","text":" automatically sets up the development environment"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Run "},{"type":"text","marks":[{"type":"code"}],"text":"cuenv task test"},{"type":"text","text":" and all three test suites run simultaneously. Run "},{"type":"text","marks":[{"type":"code"}],"text":"cuenv task build"},{"type":"text","text":" and it just works."}]},{"type":"heading","attrs":{"level":3,"id":"simplify-with-shared-configs"},"content":[{"type":"text","text":"Simplify with Shared Configs"}]},{"type":"paragraph","content":[{"type":"text","text":"That''s a lot of boilerplate for standard Rust tasks. cuenv ships defaults for common languages, so you can simplify to:"}]},{"type":"codeBlock","attrs":{"language":"cue","title":null,"meta":null},"content":[{"type":"text","text":"package cuenv\n\nimport \"github.com/cuenv/cuenv/schema\"\n\nschema.#Cuenv\n\nhooks: onEnter: nix: schema.#NixFlake\n\n// Use Rust defaults: lint, test, build, fmt, etc.\ntasks: schema.#Rust"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"schema.#Rust"},{"type":"text","text":" brings sensible defaults: "},{"type":"text","marks":[{"type":"code"}],"text":"clippy"},{"type":"text","text":" for linting, "},{"type":"text","marks":[{"type":"code"}],"text":"nextest"},{"type":"text","text":" for testing, proper input/output tracking for caching. Need to customize? CUE''s unification lets you extend:"}]},{"type":"codeBlock","attrs":{"language":"cue","title":null,"meta":null},"content":[{"type":"text","text":"tasks: schema.#Rust\n\n// Add a custom BDD test task alongside the defaults\ntasks: test: bdd: {\n    command: \"cargo\"\n    args: [\"test\", \"--test\", \"bdd\"]\n    inputs: [\"Cargo.toml\", \"Cargo.lock\", \"crates\", \"tests\", \"features\"]\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"The defaults handle the 80% case. You extend when you need to. Same pattern works for "},{"type":"text","marks":[{"type":"code"}],"text":"schema.#Go"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"schema.#Node"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"schema.#Python"},{"type":"text","text":", and more."}]},{"type":"heading","attrs":{"level":2,"id":"ci-pipeline-definitions"},"content":[{"type":"text","text":"CI Pipeline Definitions"}]},{"type":"paragraph","content":[{"type":"text","text":"cuenv can also define your CI pipelines declaratively:"}]},{"type":"codeBlock","attrs":{"language":"cue","title":null,"meta":null},"content":[{"type":"text","text":"ci: pipelines: [\n    {\n        name: \"default\"\n        when: {\n            branch: [\"main\", \"master\"]\n            defaultBranch: true\n        }\n        tasks: [\n            \"fmt.check\",\n            \"lint\",\n            \"test.unit\",\n            \"security.audit\",\n            \"build\",\n        ]\n    },\n    {\n        name: \"pull-request\"\n        when: {\n            pullRequest: true\n        }\n        tasks: [\n            \"fmt.check\",\n            \"lint\",\n            \"test.unit\",\n            \"build\",\n        ]\n    },\n]"}]},{"type":"paragraph","content":[{"type":"text","text":"Same task definitions, different execution contexts. No more maintaining separate CI configs and local scripts."}]},{"type":"heading","attrs":{"level":2,"id":"containerized-tasks-with-dagger"},"content":[{"type":"text","text":"Containerized Tasks with Dagger"}]},{"type":"paragraph","content":[{"type":"text","text":"Want your tasks to run in containers? cuenv has a "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/cuenv/cuenv/pull/105","target":null,"rel":null,"class":null,"title":null}}],"text":"Dagger backend"},{"type":"text","text":" that lets you execute tasks in isolated, reproducible container environments:"}]},{"type":"codeBlock","attrs":{"language":"cue","title":null,"meta":null},"content":[{"type":"text","text":"tasks: {\n    build: {\n        command: \"cargo\"\n        args: [\"build\", \"--release\"]\n\n        // Run this task in a container\n        dagger: {\n            image: \"rust:1.83-slim\"\n            \n            // Mount cache volumes for faster rebuilds\n            cacheVolumes: [\n                { path: \"/usr/local/cargo/registry\", name: \"cargo-registry\" }\n                { path: \"target\", name: \"cargo-target\" }\n            ]\n        }\n    }\n\n    test: {\n        command: \"cargo\"\n        args: [\"test\"]\n\n        dagger: {\n            // Chain from the build container - reuse its cache\n            from: \"build\"\n        }\n    }\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"The Dagger backend gives you:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Container isolation"},{"type":"text","text":": Tasks run in clean, reproducible environments"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Container chaining"},{"type":"text","text":": Use "},{"type":"text","marks":[{"type":"code"}],"text":"from"},{"type":"text","text":" to build on previous task containers, sharing caches"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Cache volumes"},{"type":"text","text":": Persist build artifacts across runs for faster iterations"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Secret injection"},{"type":"text","text":": Secrets from your "},{"type":"text","marks":[{"type":"code"}],"text":"env:"},{"type":"text","text":" block are securely mounted into containers"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Run locally or in CI: same config, same behavior, same results."}]},{"type":"heading","attrs":{"level":2,"id":"quick-start"},"content":[{"type":"text","text":"Quick Start"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"# Install with Nix (recommended)\nnix profile install github:cuenv/cuenv\n\n# Or with Homebrew\nbrew install cuenv/tap/cuenv\n\n# Or with Cargo\ncargo install cuenv"}]},{"type":"paragraph","content":[{"type":"text","text":"Create an "},{"type":"text","marks":[{"type":"code"}],"text":"env.cue"},{"type":"text","text":" file:"}]},{"type":"codeBlock","attrs":{"language":"cue","title":null,"meta":null},"content":[{"type":"text","text":"package cuenv\n\nimport \"github.com/cuenv/cuenv/schema\"\n\nschema.#Cuenv\n\nenv: {\n    NODE_ENV: \"development\" | \"production\" | *\"development\"\n    PORT: >0 & <65536 & *3000\n}\n\ntasks: {\n    dev:   { command: \"npm\", args: [\"run\", \"dev\"] }\n    build: { command: \"npm\", args: [\"run\", \"build\"] }\n    test:  { command: \"npm\", args: [\"test\"] }\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"Start using it:"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"# Run commands with validated environment\ncuenv exec -- npm install\n\n# Run tasks\ncuenv task dev\ncuenv task build\n\n# List available tasks\ncuenv task"}]},{"type":"heading","attrs":{"level":2,"id":"shell-integration"},"content":[{"type":"text","text":"Shell Integration"}]},{"type":"paragraph","content":[{"type":"text","text":"Add automatic environment loading when you "},{"type":"text","marks":[{"type":"code"}],"text":"cd"},{"type":"text","text":" into a project:"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"# Add to .zshrc / .bashrc\neval \"$(cuenv shell init zsh)\"\n\n# Now just cd into your project\ncd ~/projects/myapp\n# → Environment loaded automatically\n# → Nix packages available (if configured)\n# → Ready to work"}]},{"type":"heading","attrs":{"level":3,"id":"starship-integration"},"content":[{"type":"text","text":"Starship Integration"}]},{"type":"paragraph","content":[{"type":"text","text":"See your hook status right in your prompt with a custom Starship module:"}]},{"type":"codeBlock","attrs":{"language":"toml","title":null,"meta":null},"content":[{"type":"text","text":"[custom.cuenv_hooks]\ncommand = \"cuenv env status --hooks --format=starship\"\nformat = \"$output\"\nwhen = \"true\"\ndisabled = false\ndescription = \"cuenv hooks status\""}]},{"type":"paragraph","content":[{"type":"text","text":"Your prompt shows at a glance whether hooks are running, complete, or need attention."}]},{"type":"heading","attrs":{"level":2,"id":"current-status"},"content":[{"type":"text","text":"Current Status"}]},{"type":"paragraph","content":[{"type":"text","text":"cuenv is currently in "},{"type":"text","marks":[{"type":"bold"}],"text":"alpha"},{"type":"text","text":". The core CUE evaluation engine ("},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://crates.io/crates/cuengine","target":null,"rel":null,"class":null,"title":null}}],"text":"cuengine"},{"type":"text","text":") is complete and production-ready. The CLI and task runner are in active development."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Component"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Status"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"CUE Evaluation Engine"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"✅ Complete"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"CLI + Task Runner"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"🚧 Development"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Secret Management"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"🚧 Development"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Shell Integration"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"🚧 Development"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Security Isolation"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"📋 Planned"}]}]}]}]},{"type":"heading","attrs":{"level":2,"id":"why-i-built-this"},"content":[{"type":"text","text":"Why I Built This"}]},{"type":"paragraph","content":[{"type":"text","text":"The \"Aha!\" moment for me wasn''t just about frustration. It was about realizing that we could do better with very little effort if we just chose the right foundation."}]},{"type":"paragraph","content":[{"type":"text","text":"I spent years dealing with the friction of environment management. Every project had its own approach, its own conventions, and none of them talked to each other. I wanted type-safety so misconfigurations fail fast. I wanted shareable defaults so we''re not all reinventing the same Rust or Node task definitions. And honestly, I just wanted "},{"type":"text","marks":[{"type":"code"}],"text":"cd"},{"type":"text","text":"-ing into a project to be less annoying."}]},{"type":"paragraph","content":[{"type":"text","text":"CUE gave me the constraint system and hierarchical model I needed to solve this properly. Rust gave me the performance and safety guarantees to build a robust tool. And the CUE Central Registry provided the ecosystem to make it shareable."}]},{"type":"paragraph","content":[{"type":"text","text":"cuenv is the tool I wish I''d had for the last decade. It''s built "},{"type":"text","marks":[{"type":"italic"}],"text":"with"},{"type":"text","text":" cuenv, for cuenv, but my primary driver was to tame the "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/rawkode-academy/rawkode-academy","target":null,"rel":null,"class":null,"title":null}}],"text":"Rawkode Academy"},{"type":"text","text":" monorepo. I use it daily to manage everything from our Astro-based frontend to our Rust backend services, ensuring type-safety and seamless parallel execution across the entire stack."}]},{"type":"paragraph","content":[{"type":"text","text":"If you''re tired of the same environment management headaches, give cuenv a try. It''s open source under AGPL-3.0, and I''d love your feedback."}]},{"type":"paragraph","content":[{"type":"text","text":"Check out the "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/cuenv/cuenv","target":null,"rel":null,"class":null,"title":null}}],"text":"GitHub repository"},{"type":"text","text":" to get started, or read about the "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/read/building-rust-cue-library","target":null,"rel":null,"class":null,"title":null}}],"text":"technical journey of building cuengine"},{"type":"text","text":" if you''re curious about the Rust/Go FFI bridge that powers it all."}]}]}', 'article', 0, 0, NULL, '[]', '[]', 'https://content.rawkode.academy/articles/introducing-cuenv/cover.png', 'cuenv - Type-safe environments and parallel tasks powered by CUE', 2816, 1536, 'Introducing cuenv', 'Type-safe environments, secrets that never leak, and parallel tasks', '[]', '[{"id":"1","title":"cuenv GitHub Repository","description":"Complete source code and documentation","type":"url","url":"https://github.com/cuenv/cuenv","category":"documentation"},{"id":"2","title":"cuengine on crates.io","description":"The Rust CUE evaluation engine powering cuenv","type":"url","url":"https://crates.io/crates/cuengine","category":"documentation"},{"id":"3","title":"CUE Language Documentation","description":"Official CUE language specification and guides","type":"url","url":"https://cuelang.org","category":"documentation"},{"id":"4","title":"Building a Rust Library for CUE: Architecture & Lessons","description":"The technical story behind cuengine, the FFI bridge powering cuenv","type":"url","url":"/read/building-rust-cue-library","category":"documentation"}]', 1764547200000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('introducing-cuenv', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('introducing-cuenv', 'cue', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('introducing-cuenv', 'rust', 1);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('introducing-cuenv', 'dagger', 2);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('introducing-technology-matrix', 'Introducing the Technology Matrix', NULL, 'Your new compass for the Cloud Native landscape. Explore, filter, and learn about the technologies that power modern platforms.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I''m tired. Genuinely exhausted. Navigating the Cloud Native landscape has become absolutely maddening. We''ve all seen the Always Sunny meme, and honestly? It hits harder every year."}]},{"type":"paragraph","content":[{"type":"text","text":"The CNCF Landscape lists hundreds of projects. Hundreds. New tools pop up every week. Every conference brings another dozen \"game-changers.\" And somehow, you''re supposed to figure out what actually matters for your platform while also, you know, doing your actual job."}]},{"type":"paragraph","content":[{"type":"text","text":"I''ve spent years drowning in this chaos. Evaluating tools. Getting burned by hype. Watching projects I loved die slow deaths. And I kept thinking: there has to be a better way to track all this. To share what I''ve actually learned. So I built one."}]},{"type":"paragraph","content":[{"type":"text","text":"Welcome to the "},{"type":"text","marks":[{"type":"bold"}],"text":"Technology Matrix"},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2,"id":"what-is-the-technology-matrix"},"content":[{"type":"text","text":"What is the Technology Matrix?"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/technology/matrix","target":null,"rel":null,"class":null,"title":null}}],"text":"Technology Matrix"},{"type":"text","text":" is not another list. I''m so sick of lists. It''s my "},{"type":"text","marks":[{"type":"bold"}],"text":"personal, opinionated tech radar"},{"type":"text","text":". A living map of how I actually navigate this mess of an ecosystem. Every technology in here has a story. When I first touched it. Why I rate it the way I do. Where I think it''s going (and sometimes, where I think it deserves to go)."}]},{"type":"paragraph","content":[{"type":"text","text":"Think of it as the CNCF Landscape if someone actually had opinions. If someone would just tell you \"yeah, I used this in production and it was a nightmare\" instead of neutral marketing speak."}]},{"type":"paragraph","content":[{"type":"text","text":"Today I''m releasing the first iteration. It''s rough around the edges. I know. But the core is there, and I''ll keep adding spicier takes and better features as I go."}]},{"type":"heading","attrs":{"level":2,"id":"the-pipeline-a-journey-through-technology"},"content":[{"type":"text","text":"The Pipeline: A Journey Through Technology"}]},{"type":"paragraph","content":[{"type":"text","text":"Here''s the thing that frustrated me about every tech radar I''ve seen: they just label stuff \"adopt\" or \"hold\" like technology decisions are binary. They''re not. My relationship with tools changes over time. Sometimes dramatically."}]},{"type":"paragraph","content":[{"type":"text","text":"So at the heart of the Matrix is what I call the "},{"type":"text","marks":[{"type":"bold"}],"text":"Pipeline"},{"type":"text","text":". Seven stages that represent where I actually am with each technology:"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Stage"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"What It Means"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Skip"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Not for me right now. Maybe it doesn''t fit my use cases, maybe I tried it and walked away. No hard feelings."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Watch"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"On my radar. I''m paying attention, reading release notes, lurking in the Discord."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Explore"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Worth a look. I''m actually trying this out, running tutorials, kicking the tires."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Learn"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"I''m investing real time here. This technology earned my attention and I''m going deep."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Adopt"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Production-ready in my head. I''d confidently use this on a real project tomorrow."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Advocate"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"I''m not just using it, I''m actively telling people about it. I believe in this one."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Graveyard"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"The end of the road. Deprecated, abandoned, or it burned me badly enough that I''m done. Rest in peace."}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Things move through this pipeline. Something in \"Watch\" today might be in \"Adopt\" next month. Or it might crater into the Graveyard. I''ve seen both happen more times than I can count. The Matrix captures that journey, and I''ll annotate it with my thoughts as things evolve."}]},{"type":"heading","attrs":{"level":2,"id":"the-story-behind-each-tech"},"content":[{"type":"text","text":"The Story Behind Each Tech"}]},{"type":"paragraph","content":[{"type":"text","text":"Click on any technology and you get the full picture. This is where it gets personal:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Why"},{"type":"text","text":": My actual rationale for the rating. Not marketing copy. Real opinions from real experience, including the painful parts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Spicy Takes"},{"type":"text","text":" 🌶️: The hot opinions. Things I might not say on a conference stage but you deserve to know."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Makes Me Feel"},{"type":"text","text":": An emoji reaction. Sometimes you just need to know the vibe, you know?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"First Used / Last Used"},{"type":"text","text":": When did I actually start using this? Have I been running Kubernetes since 2016 or did I just discover this project last month? Context matters."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This metadata turns a list into a story. You''re not just seeing what I think. You''re seeing "},{"type":"text","marks":[{"type":"italic"}],"text":"why"},{"type":"text","text":" I think it, how I got here, and how that opinion has changed over the years."}]},{"type":"heading","attrs":{"level":2,"id":"advanced-explorer"},"content":[{"type":"text","text":"Advanced Explorer"}]},{"type":"paragraph","content":[{"type":"text","text":"For the folks who want to really dig in, the "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/technology/matrix/advanced","target":null,"rel":null,"class":null,"title":null}}],"text":"Advanced Explorer"},{"type":"text","text":" is where things get interesting:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Filter by Anything"},{"type":"text","text":": Pipeline stage, CNCF status, trajectory, confidence. Slice it however makes sense for you."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Multiple Views"},{"type":"text","text":": See technologies as a grid by category, or explore other ways to organize the chaos."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Preset Views"},{"type":"text","text":": Quick configs like \"Pipeline View\" (my journey) or \"CNCF Maturity\" (project lifecycle)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Shareable URLs"},{"type":"text","text":": Found a useful filter combination? The URL updates as you explore. Share your exact view."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The Advanced Explorer turns the Matrix from something you browse into something you interrogate. Ask it hard questions."}]},{"type":"heading","attrs":{"level":2,"id":"deep-content-integration"},"content":[{"type":"text","text":"Deep Content Integration"}]},{"type":"paragraph","content":[{"type":"text","text":"The Matrix isn''t a standalone database. It''s wired into everything I create at Rawkode Academy."}]},{"type":"paragraph","content":[{"type":"text","text":"Every technology links to its dedicated page:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Deep-dive Videos"},{"type":"text","text":": Tutorials, \"Show & Tell\" sessions, and \"Klustered\" episodes where I actually use the tool."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Articles & Guides"},{"type":"text","text":": Written content to help you understand the concepts and trade-offs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Related Technologies"},{"type":"text","text":": See how tools fit together in the broader stack."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"If I''ve covered it, you''ll find it. The Matrix is your index into the content library."}]},{"type":"heading","attrs":{"level":2,"id":"whats-coming"},"content":[{"type":"text","text":"What''s Coming"}]},{"type":"paragraph","content":[{"type":"text","text":"What you see today is Phase 1. Here''s what''s on my roadmap:"}]},{"type":"heading","attrs":{"level":3,"id":"phase-2-new-perspectives"},"content":[{"type":"text","text":"Phase 2: New Perspectives"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Scatter Plot View"},{"type":"text","text":": A proper \"Tech Radar\" visualization. Plot technologies by stage vs trajectory to see where momentum is actually building."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Timeline View"},{"type":"text","text":": See my journey chronologically. When did I adopt Kubernetes? When did I finally give up on Docker Swarm? The timeline tells the story."}]}]}]},{"type":"heading","attrs":{"level":3,"id":"phase-3-deep-exploration"},"content":[{"type":"text","text":"Phase 3: Deep Exploration"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Treemap View"},{"type":"text","text":": Drill down through categories hierarchically. See how the ecosystem is weighted at a glance."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Sankey Diagrams"},{"type":"text","text":": Visualize the flow of technologies through pipeline stages over time. Watch the ecosystem evolve."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The Matrix will grow as the ecosystem grows. New views, new filters, new ways to make sense of the noise."}]},{"type":"heading","attrs":{"level":2,"id":"why-i-built-it"},"content":[{"type":"text","text":"Why I Built It"}]},{"type":"paragraph","content":[{"type":"text","text":"Look, I built this because I was frustrated. As someone who constantly evaluates tools, creates content, and advises teams on platform choices, I needed somewhere to put all of this. A structured way to capture what I know and share it without the corporate filter."}]},{"type":"paragraph","content":[{"type":"text","text":"The CNCF Landscape is comprehensive. I respect the work. But it''s deliberately neutral. It won''t tell you what''s worth your time and what''s a waste of it. I needed something opinionated. Something that says \"I deployed this in production and here''s the truth.\""}]},{"type":"paragraph","content":[{"type":"text","text":"My goal is simple: help you make better technology decisions by sharing my perspective honestly. Not as gospel. Not as the definitive answer. Just as one data point from someone who''s been doing this for a while and has the scars to prove it."}]},{"type":"heading","attrs":{"level":2,"id":"start-exploring"},"content":[{"type":"text","text":"Start Exploring"}]},{"type":"paragraph","content":[{"type":"text","text":"The Technology Matrix is live. Go poke around."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"/technology/matrix","target":null,"rel":null,"class":null,"title":null}},{"type":"bold"}],"text":"Visit the Matrix"},{"type":"text","text":": See the full pipeline view with every technology I track."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"/technology/matrix/advanced","target":null,"rel":null,"class":null,"title":null}},{"type":"bold"}],"text":"Try the Advanced Explorer"},{"type":"text","text":": Filter, slice, and interrogate the data your way."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This is a living document. Technologies will move through the pipeline. New projects will appear. My opinions will change. That''s the whole point. The Matrix captures the journey, not a frozen snapshot."}]},{"type":"paragraph","content":[{"type":"text","text":"Dive in. Disagree with me. Tell me I''m wrong. Tell me what I''m missing. Let''s figure this out together."}]}]}', 'article', 0, 0, NULL, '[]', '[]', 'https://content.rawkode.academy/articles/introducing-technology-matrix/cover.png', 'The Rawkode Academy Technology Matrix', 1280, 720, 'Introducing the Technology Matrix', 'A curated, interactive guide to the Cloud Native ecosystem', '[]', '[]', 1764633600000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('introducing-technology-matrix', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('introducing-technology-matrix', 'kubernetes', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('introducing-technology-matrix', 'docker', 1);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('introduction-to-webassembly-on-kubernetes-with-krustlet', 'Introduction to WebAssembly on Kubernetes with Krustlet', NULL, 'Welcome! 👋 This article will aim to introduce you to something wild and wonderful - running WebAssem...', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Welcome! 👋"}]},{"type":"paragraph","content":[{"type":"text","text":"This article will aim to introduce you to something wild and wonderful - running WebAssembly binaries on Kubernetes, with Krustlet."}]},{"type":"heading","attrs":{"level":2,"id":"why"},"content":[{"type":"text","text":"Why?"}]},{"type":"paragraph","content":[{"type":"text","text":"WebAssembly is bytecode that can be executed in your browser, regardless of operating system or architecture; this has opened up a, potentially, whole new era of web programming; one that doesn''t need transpiled to JavaScript."}]},{"type":"paragraph","content":[{"type":"text","text":"Thus far, a few languages have trialed and tested support for compiling their code to WASM for usage within the browser. You can learn about some of these efforts by checking out these links."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"http://kripken.github.io/emscripten-site/","target":null,"rel":null,"class":null,"title":null}}],"text":"C/C++"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/golang/go/wiki/WebAssembly","target":null,"rel":null,"class":null,"title":null}}],"text":"Go"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/oraoto/pib","target":null,"rel":null,"class":null,"title":null}}],"text":"PHP"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/rustwasm","target":null,"rel":null,"class":null,"title":null}}],"text":"Rust"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://swiftwasm.org/","target":null,"rel":null,"class":null,"title":null}}],"text":"Swift"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"http://assemblyscript.org/","target":null,"rel":null,"class":null,"title":null}}],"text":"TypeScript"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"There are more, but I think that''s enough to pique your interest."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"ANY"},{"type":"text","text":" language, in the browser ... that''s a pretty interesting idea, right? 😉"}]},{"type":"paragraph","content":[{"type":"text","text":"One thing we don''t often talk about when discussing the browser ... it''s pretty darn secure. Running JavaScript in your browser can''t actually do much damage to your host system. This is because the JavaScript engines, such as v8 or SpiderMonkey, run the JavaScript code in a sandbox; much like modern Linux container systems, like containerd."}]},{"type":"paragraph","content":[{"type":"text","text":"So what if we want to leverage WASM, in our many languages, and benefit from the sandbox out the browser ... but without the browser?"}]},{"type":"paragraph","content":[{"type":"text","text":"Enter, WASI and "},{"type":"text","marks":[{"type":"code"}],"text":"wasmtime"},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":3,"id":"webassembly-system-interface-wasi"},"content":[{"type":"text","text":"WebAssembly System Interface (WASI)"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://wasi.dev/","target":null,"rel":null,"class":null,"title":null}}],"text":"WASI"},{"type":"text","text":" provides an interface for running WASM code as a process on your operating system, rather than browsers; which allows us to interact with all the things the browser doesn''t: files and filesystems, Berkeley sockets, clocks, and random numbers."}]},{"type":"paragraph","content":[{"type":"text","text":"WASI does this in a fashion that still gives us similiar security boundaries that we get within the browser, but through a capabilities model defined by the runtime. WASI is not a runtime, but the interface that runtimes must adhere too. This is handled by a capability-based security model."}]},{"type":"paragraph","content":[{"type":"text","text":"How do capabilities work? Lets use an example. Most applications open a file by some reference, which is usually a file path on the filesystem. Any application that has that reference (file path) can interact with that file, provided the "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://en.wikipedia.org/wiki/Ambient_authority","target":null,"rel":null,"class":null,"title":null}}],"text":"Ambient Authority"},{"type":"text","text":" allows."}]},{"type":"paragraph","content":[{"type":"text","text":"What does that mean? It means that if user "},{"type":"text","marks":[{"type":"code"}],"text":"rawkode"},{"type":"text","text":" executes a binary, and "},{"type":"text","marks":[{"type":"code"}],"text":"rawkode"},{"type":"text","text":" has permissions to read a file; then that binary can read that file."}]},{"type":"paragraph","content":[{"type":"text","text":"That''s not ideal."}]},{"type":"paragraph","content":[{"type":"text","text":"WASI uses a "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://en.wikipedia.org/wiki/Capability-based_security","target":null,"rel":null,"class":null,"title":null}}],"text":"Capability model"},{"type":"text","text":", rather than ambient authority. When you execute a WASI binary, it can ONLY access the files that you have given that binary the permission to."}]},{"type":"paragraph","content":[{"type":"text","text":"What does that mean? Think about container images when executed, they can only access the files within the container image, or explictly bind mounted in. WASI is the same. WASI binaries can only access files if the binary is given permission to access them, usually by providing a directory root."}]},{"type":"heading","attrs":{"level":3,"id":"wasmtime"},"content":[{"type":"text","text":"wasmtime"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"wasmtime"},{"type":"text","text":" is an implemention of WASI. You can think of "},{"type":"text","marks":[{"type":"code"}],"text":"wasmtime"},{"type":"text","text":" much like "},{"type":"text","marks":[{"type":"code"}],"text":"node"},{"type":"text","text":". In the same way that "},{"type":"text","marks":[{"type":"code"}],"text":"node"},{"type":"text","text":" allowed us to execute JavaScript outside of the browser, "},{"type":"text","marks":[{"type":"code"}],"text":"wasmtime"},{"type":"text","text":" does that for WASM."}]},{"type":"heading","attrs":{"level":3,"id":"krustlet"},"content":[{"type":"text","text":"Krustlet"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/deislabs/krustlet","target":null,"rel":null,"class":null,"title":null}}],"text":"Krustlet"},{"type":"text","text":" is a Kubelet implementation for Kubernetes that supports running WASM bytecode, with the "},{"type":"text","marks":[{"type":"code"}],"text":"wasmtime"},{"type":"text","text":" runtime, instead of container images with a container runtime."}]},{"type":"heading","attrs":{"level":2,"id":"getting-started"},"content":[{"type":"text","text":"Getting Started"}]},{"type":"heading","attrs":{"level":3,"id":"getting-a-kubernetes-cluster"},"content":[{"type":"text","text":"Getting a Kubernetes cluster"}]},{"type":"paragraph","content":[{"type":"text","text":"For today''s tutorial, we''re going to use "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/kubernetes/minikube","target":null,"rel":null,"class":null,"title":null}}],"text":"minikube"},{"type":"text","text":". "},{"type":"text","marks":[{"type":"code"}],"text":"minikube"},{"type":"text","text":" gives us a full Kubernetes cluster, in a VM, on our local machine. With "},{"type":"text","marks":[{"type":"code"}],"text":"minikube"},{"type":"text","text":" installed, create a cluster with the following command."}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"minikube start"}]},{"type":"heading","attrs":{"level":3,"id":"building-krustlet"},"content":[{"type":"text","text":"Building Krustlet"}]},{"type":"paragraph","content":[{"type":"text","text":"As this is rather experimental / early stages, you''ll need to compile the Krustlet from source. Depending on your machine, this can take anywhere from 3 minutes to 10 minutes; so you make want to go make a coffee or something ⏰"}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"# Clone the Krustlet source code to a local directory and enter it\ngit clone https://github.com/deislabs/krustlet\ncd krustlet\n\n# Using Rust''s build tool, Cargo, to build the application\ncargo build"}]},{"type":"heading","attrs":{"level":4,"id":"bootstrapping"},"content":[{"type":"text","text":"Bootstrapping"}]},{"type":"paragraph","content":[{"type":"text","text":"Now that we have the binaries needed to run our Krustlet, we need to perform some initial bootstrapping."}]},{"type":"paragraph","content":[{"type":"text","text":"Bootstrapping is important, because Kubernetes restricts access to the control plane. We need to provide enough configuration for our Krustlet to register itself with the control plane, so it can become a \"Node\" within the cluster."}]},{"type":"paragraph","content":[{"type":"text","text":"You can create this bootstrap configuration with the following command. "},{"type":"text","marks":[{"type":"bold"}],"text":"PLEASE"},{"type":"text","text":" ensure your "},{"type":"text","marks":[{"type":"code"}],"text":"KUBECONFIG"},{"type":"text","text":" context is pointing to your development cluster, and not something in production."}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"./docs/howto/assets/bootstrap.sh"}]},{"type":"paragraph","content":[{"type":"text","text":"You''ll see some output, like so:"}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"secret/bootstrap-token-x4jygy created\nSwitched to context \"minikube\".\nContext \"minikube\" renamed to \"tls-bootstrap-token-user@kubernetes\".\nUser \"tls-bootstrap-token-user\" set.\nContext \"tls-bootstrap-token-user@kubernetes\" modified.\nContext \"tls-bootstrap-token-user@kubernetes\" modified."}]},{"type":"paragraph","content":[{"type":"text","text":"What does this all mean? 🤓"}]},{"type":"paragraph","content":[{"type":"text","text":"First, this bootstrap script creates a secret inside of our cluster; using our default "},{"type":"text","marks":[{"type":"code"}],"text":"KUBECONFIG"},{"type":"text","text":". This will be setup for you when you spin up "},{"type":"text","marks":[{"type":"code"}],"text":"minikube"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"This secret is very similiar to a Kubelets bootstrap secret. It''s all very 😴"}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"auth-extra-groups:                         # system:bootstrappers:kubeadm:default-node-token\nexpiration: MjAyMC0wNy0wMlQxMzozOTo0OVo=   # 2020-07-02T13:39:49Z (1 hour from bootstrap)\ntoken-id: eDRqeWd5                         # x4jygy\ntoken-secret: OWR1enFtamdvM3BlaXQ3YQ==     # 9duzqmjgo3peit7a\nusage-bootstrap-authentication: dHJ1ZQ==   # true\nusage-bootstrap-signing: dHJ1ZQ==          # true"}]},{"type":"paragraph","content":[{"type":"text","text":"Next, the bootstrap script grabs your existing "},{"type":"text","marks":[{"type":"code"}],"text":"KUBECONFIG"},{"type":"text","text":", copies it, crates a new user within your cluster, modifies the context to use that new user, and stores it at "},{"type":"text","marks":[{"type":"code"}],"text":"~/.krustlet/config/bootstrap.conf"},{"type":"text","text":". This "},{"type":"text","marks":[{"type":"code"}],"text":"bootstrap.conf"},{"type":"text","text":" can now be used to provide authentication for our Krustlet to the control plane."}]},{"type":"heading","attrs":{"level":4,"id":"running-the-krustlet"},"content":[{"type":"text","text":"Running the Krustlet"}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"KUBECONFIG=~/.krustlet/config/bootstrap.conf krustlet-wasi --node-ip $(minikube ip) --port 3000 --bootstrap-file ~/.krustlet/config/bootstrap.conf"}]},{"type":"paragraph","content":[{"type":"text","text":"The first time this runs, it will generate the required TLS certificates. You''ll need to approve the CSR in another terminal tab / window."}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"kubectl certificate approve $(uname -n)-tls"}]},{"type":"paragraph","content":[{"type":"text","text":"Lets confirm everything looks good, we should see 2 \"nodes\" now."}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"NAME       STATUS   ROLES    AGE     VERSION   INTERNAL-IP     EXTERNAL-IP   OS-IMAGE               KERNEL-VERSION   CONTAINER-RUNTIME\narch       Ready    agent    3m15s   0.3.0     192.168.39.37   <none>        <unknown>              <unknown>        mvp\nminikube   Ready    master   57m     v1.18.3   192.168.39.37   <none>        Buildroot 2019.02.10   4.19.107         docker://19.3.8"}]},{"type":"paragraph","content":[{"type":"text","text":"Congratulations, you''ve got a Krustlet running on "},{"type":"text","marks":[{"type":"code"}],"text":"minikube"}]},{"type":"heading","attrs":{"level":2,"id":"building-a-wasi-application"},"content":[{"type":"text","text":"Building a WASI Application"}]},{"type":"paragraph","content":[{"type":"text","text":"Next, we''re going to throw together a quick \"Hello World\" style application. Unfortunately, WASI hasn''t defined what networking / Berkeley sockets will look like yet within WASI-land; so we can''t run a web server or anything more interesting (yet)."}]},{"type":"paragraph","content":[{"type":"text","text":"All in good time though 😁"}]},{"type":"heading","attrs":{"level":3,"id":"tldr"},"content":[{"type":"text","text":"TL;DR"}]},{"type":"paragraph","content":[{"type":"text","text":"If you don''t want to follow the DIY steps below, you can clone my repository and jump straight to the "},{"type":"text","marks":[{"type":"link","attrs":{"href":"#Building","target":null,"rel":null,"class":null,"title":null}}],"text":"Building"},{"type":"text","text":" section."}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"git clone https://gitlab.com/rawkode/wasi-hello-world"}]},{"type":"heading","attrs":{"level":3,"id":"diy"},"content":[{"type":"text","text":"DIY"}]},{"type":"paragraph","content":[{"type":"text","text":"First, create a Rust project. This command generates a skeleton Rust project."}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"cargo new --bin wasi-hello-world"}]},{"type":"paragraph","content":[{"type":"text","text":"You''ll want to update "},{"type":"text","marks":[{"type":"code"}],"text":"main.rs"},{"type":"text","text":" with the following code. This code prints a message, and sleeps for 5 seconds; it then loops this process indefinitely."}]},{"type":"codeBlock","attrs":{"language":"rust","title":null,"meta":null},"content":[{"type":"text","text":"// Code from\n// https://github.com/deislabs/krustlet/blob/master/docs/intro/tutorial01.md\nuse std::thread::sleep;\nuse std::time::Duration;\n\nfn main() {\n    loop {\n        println!(\"Hello, from WASI and Krustlet!\");\n        sleep(Duration::from_secs(5));\n    }\n}"}]},{"type":"heading","attrs":{"level":3,"id":"building"},"content":[{"type":"text","text":"Building"}]},{"type":"paragraph","content":[{"type":"text","text":"We need to enable the WASI target, which we''ll do with "},{"type":"text","marks":[{"type":"code"}],"text":"rustup"},{"type":"text","text":". We also need to build our application, targetting WASI as a runtime."}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"# Enable  wasm32-wasi as a compilation targeht\nrustup target add wasm32-wasi\n\n# Build WASI bytecode\ncargo build --target wasm32-wasi"}]},{"type":"heading","attrs":{"level":3,"id":"running--publishing"},"content":[{"type":"text","text":"Running & Publishing"}]},{"type":"paragraph","content":[{"type":"text","text":"When we build a WASI compatible binary, what we get is a "},{"type":"text","marks":[{"type":"code"}],"text":"wasm"},{"type":"text","text":" file."}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"❯ ls target/wasm32-wasi/debug\n... wasi-hello-world.wasm ..."}]},{"type":"paragraph","content":[{"type":"text","text":"In order to run WASI bytecode, we use a WASI runtime; like "},{"type":"text","marks":[{"type":"code"}],"text":"wasmtime"},{"type":"text","text":"."}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"❯ wasmtime ./target/wasm32-wasi/debug/wasi-hello-world.wasm\nHello, from WASI and Krustlet!\n^C"}]},{"type":"paragraph","content":[{"type":"text","text":"Oooh, shiny! 🌠"}]},{"type":"paragraph","content":[{"type":"text","text":"However, that''s not what we want to do. We want to run this on Kubernetes using our Krustlet."}]},{"type":"paragraph","content":[{"type":"text","text":"In-order to do so, we need to \"publish\" our image to \"somewhere\"."}]},{"type":"paragraph","content":[{"type":"text","text":"Fortunately, there''s "},{"type":"text","marks":[{"type":"code"}],"text":"wasm-to-oci"},{"type":"text","text":" which allows publishing wasm binaries to OCI compatible registries."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Note:"},{"type":"text","text":" Docker Hub and Quay do not support these artifacts at the time of writing, but GitLab, Google Cloud, and Azure Cloud do."}]},{"type":"paragraph","content":[{"type":"text","text":"Sadly, we do need to build this ourselves too; fortunately, it''s I''ve prepared the commands 😃"}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"git clone https://github.com/engineerd/wasm-to-oci\ncd wasm-to-oci\nmake\nsudo cp ./bin/wasm-to-oci /usr/local/bin/wasm-to-oci"}]},{"type":"paragraph","content":[{"type":"text","text":"Now, lets go back to our "},{"type":"text","marks":[{"type":"code"}],"text":"wasi-hello-world"},{"type":"text","text":" directory and push an image with our WASI binary."}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"# You can use this image if you want, it''s public\nwasm-to-oci push ./target/wasm32-wasi/debug/wasi-hello-world.wasm registry.gitlab.com:rawkode/wasi-hello-world:latest\n\nINFO[0008] Pushed: registry.gitlab.com/rawkode/wasi-hello-world:latest\nINFO[0008] Size: 1808571\nINFO[0008] Digest: sha256:a9617d29b859994cc4b6f5ea73f7d68096921f7225ed31e645f0dda7b27163ed"}]},{"type":"heading","attrs":{"level":2,"id":"the-last-kilometer"},"content":[{"type":"text","text":"The Last Kilometer"}]},{"type":"paragraph","content":[{"type":"text","text":"OK. We''re almost there. Thus far, we''ve:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☑ Created a Kubernetes cluster with "},{"type":"text","marks":[{"type":"code"}],"text":"minikube"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☑ Cloned, compiled, and ran a Krustlet from source"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☑ Created a Rust application and compiled it to WASI"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☑ Converted our WASI binary to an OCI compatible image and pushed it to the GitLab Container Registry"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"❌ Run our Rust WASI targetting binary on Kubernetes"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"OK, so now we need to schedule our WASI workload on the Krustlet. Like ALL Kubernetes resources, we need YAML for this."}]},{"type":"paragraph","content":[{"type":"text","text":"Save the following to "},{"type":"text","marks":[{"type":"code"}],"text":"pod.yaml"},{"type":"text","text":"."}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"apiVersion: v1\nkind: Pod\nmetadata:\n  name: wasi-hello-world\nspec:\n  containers:\n    - name: wasi-hello-world\n      image: registry.gitlab.com/rawkode/wasi-hello-world:latest\n      imagePullPolicy: IfNotPresent\n  tolerations:\n    - key: \"krustlet/arch\"\n      operator: \"Equal\"\n      value: \"wasm32-wasi\"\n      effect: \"NoExecute\""}]},{"type":"paragraph","content":[{"type":"text","text":"Apply this YAML file to your Kubernetes cluster."}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"kubectl apply -f pod.yaml"}]},{"type":"paragraph","content":[{"type":"text","text":"💥 DONE 💥"}]},{"type":"paragraph","content":[{"type":"text","text":"We''ve now deployed a WASI binary, via Krustlet, to our Kubernetes cluster."}]},{"type":"heading","attrs":{"level":3,"id":"confirm-the-awesome"},"content":[{"type":"text","text":"Confirm the Awesome"}]},{"type":"paragraph","content":[{"type":"text","text":"To confirm your WASI binary is running, you can use the Kubernetes tooling to check a few things."}]},{"type":"paragraph","content":[{"type":"text","text":"First, is the pod scheduled and running and do we have log output? Run the following commands."}]},{"type":"codeBlock","attrs":{"language":"console","title":null,"meta":null},"content":[{"type":"text","text":"kubectl get pods\nkubectl logs -f wasi-hello-world"}]},{"type":"paragraph","content":[{"type":"text","text":"Awesome! I hope this helps you on your path to understanding, getting excited, and adopting WASM, WASI, and Krustlet."}]},{"type":"paragraph","content":[{"type":"text","text":"If you have any questions, grab me on "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://twitter.com/rawkode","target":null,"rel":null,"class":null,"title":null}}],"text":"Twitter"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Until next time 🤘"}]}]}', 'tutorial', 0, 0, NULL, '[]', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1593648000000, 1594512000000, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('introduction-to-webassembly-on-kubernetes-with-krustlet', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('introduction-to-webassembly-on-kubernetes-with-krustlet', 'kubernetes', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('introduction-to-webassembly-on-kubernetes-with-krustlet', 'webassembly', 1);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('kep-2831-kubelet-tracing', 'KEP-2831: Kubelet Tracing Finally Brings Node-Level Observability to Kubernetes', NULL, 'Kubernetes 1.34 will deliver distributed tracing in the kubelet, providing unprecedented visibility into node-level operations that have been a debugging black box until now.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kubernetes 1.34, scheduled for release on August 27, 2025, will bring a significant enhancement to cluster observability. KEP-2831 introduces distributed tracing directly into the kubelet—Kubernetes'' node-level workhorse that manages pods, pulls images, and orchestrates container lifecycles."}]},{"type":"paragraph","content":[{"type":"text","text":"While Kubernetes has provided structured JSON logs, metrics, and events for debugging node-level issues, correlating these signals to understand complex failure scenarios has remained time-consuming. When pods get stuck in Pending or ContainerCreating status, you might spend significant time piecing together logs and events to understand the sequence and timing of operations."}]},{"type":"paragraph","content":[{"type":"text","text":"KEP-2831 changes this by adding OpenTelemetry-based distributed tracing to the kubelet. This means you can now visualize the entire lifecycle of pod operations, see exact timings for each step, and quickly identify bottlenecks—all while correlating these traces with your existing application-level observability."}]},{"type":"heading","attrs":{"level":2,"id":"what-kubelet-tracing-actually-does-and-why-you-should-care"},"content":[{"type":"text","text":"What Kubelet Tracing Actually Does (And Why You Should Care)"}]},{"type":"paragraph","content":[{"type":"text","text":"Think about the last time you had a pod stuck in Pending or ContainerCreating status. While kubectl describe and kubelet logs could tell you what happened, understanding the why often required correlating timestamps across multiple log entries and events."}]},{"type":"paragraph","content":[{"type":"text","text":"With KEP-2831''s distributed tracing, you get structured visibility into:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pod lifecycle operations: From scheduling to running state with precise timing"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Container runtime interactions: Image pulls, container creation, and startup sequences with duration metrics"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Volume operations: Mount/unmount operations and storage interactions with latency data"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Resource management: CPU, memory, and storage allocation processes with performance insights"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The key advantage is seeing these operations as connected traces rather than isolated log entries. A single trace shows you that an image pull took 45 seconds, followed by a 10-second volume mount, making it immediately clear where your pod startup time is being spent. This is especially powerful when combined with your application traces, giving you true end-to-end observability from user request to container startup."}]},{"type":"heading","attrs":{"level":2,"id":"the-technical-deep-dive-opentelemetry-integration"},"content":[{"type":"text","text":"The Technical Deep Dive: OpenTelemetry Integration"}]},{"type":"paragraph","content":[{"type":"text","text":"KEP-2831 leverages OpenTelemetry for its tracing implementation, following the established pattern used throughout the Kubernetes ecosystem."}]},{"type":"paragraph","content":[{"type":"text","text":"Here''s what this means for platform teams:"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Vendor Neutrality: Your Tools, Your Choice."},{"type":"text","text":" By using OpenTelemetry, traces can be exported to any compatible backend—Jaeger, Zipkin, Grafana Tempo, or commercial solutions. This flexibility allows teams to choose the best tools for their needs without being locked into a specific vendor."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Ecosystem Compatibility: No More Silos."},{"type":"text","text":" The integration ensures seamless compatibility with existing observability stacks, making it easier for teams to incorporate kubelet tracing into their current workflows and correlate infrastructure traces with application traces."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Standards-Based Approach."},{"type":"text","text":" Using OpenTelemetry aligns with Kubernetes'' broader observability strategy and ensures kubelet tracing will benefit from ongoing improvements to the OpenTelemetry project."}]},{"type":"paragraph","content":[{"type":"text","text":"With this integration, you can finally connect the dots between a slow API response in your application and a delayed volume mount on the node—providing the full-stack visibility that''s been missing from Kubernetes debugging."}]},{"type":"heading","attrs":{"level":2,"id":"current-status-beta-and-production-ready-with-caveats"},"content":[{"type":"text","text":"Current Status: Beta and Production-Ready (With Caveats)"}]},{"type":"paragraph","content":[{"type":"text","text":"Let''s set the record straight on where KEP-2831 stands today. As of Kubernetes v1.27, kubelet tracing has reached Beta status, with General Availability targeted for v1.34 (releasing August 27, 2025)."}]},{"type":"paragraph","content":[{"type":"text","text":"What Beta means for you:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"✅ Production use is supported (though not recommended for mission-critical workloads without careful monitoring)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"⚠️ API changes are possible but unlikely to be breaking."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"🔄 Feature flags may be required depending on your Kubernetes distribution."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"📈 Active development continues with community feedback driving improvements."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"For early adopters and platform teams looking to gain a competitive advantage in observability, now is an excellent time to start experimenting. Just ensure you have rollback plans and aren''t betting critical operations on Beta features."}]},{"type":"heading","attrs":{"level":2,"id":"real-world-impact-beyond-individual-clusters"},"content":[{"type":"text","text":"Real-World Impact: Beyond Individual Clusters"}]},{"type":"paragraph","content":[{"type":"text","text":"The implications of kubelet tracing extend far beyond solving individual debugging sessions. This capability represents a fundamental shift in how we approach Kubernetes observability at scale."}]},{"type":"heading","attrs":{"level":3,"id":"for-platform-teams"},"content":[{"type":"text","text":"For Platform Teams"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Faster incident resolution: Trace-driven debugging reduces MTTR significantly."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Proactive optimization: Identify performance bottlenecks before they impact users."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Better capacity planning: Understand actual resource utilization patterns at the node level."}]}]}]},{"type":"heading","attrs":{"level":3,"id":"for-the-cloud-native-ecosystem"},"content":[{"type":"text","text":"For the Cloud-Native Ecosystem"}]},{"type":"paragraph","content":[{"type":"text","text":"KEP-2831 positions Kubernetes as a leader in infrastructure observability. As organizations increasingly adopt cloud-native architectures, the ability to trace operations across the entire stack—from application code down to container runtime interactions—becomes a competitive advantage."}]},{"type":"paragraph","content":[{"type":"text","text":"This also aligns with the broader industry trend toward observability-driven development, where teams use telemetry data to inform architectural decisions and optimize system performance proactively."}]},{"type":"heading","attrs":{"level":2,"id":"getting-started-what-you-need-to-know"},"content":[{"type":"text","text":"Getting Started: What You Need to Know"}]},{"type":"paragraph","content":[{"type":"text","text":"Ready to experiment with kubelet tracing? Here''s your roadmap:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check your Kubernetes version: Ensure you''re running v1.27 or later."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Configure OpenTelemetry: Set up your preferred tracing backend."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enable the feature: Configure kubelet tracing through feature gates or configuration files."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Start small: Begin with non-production clusters to understand the data volume and performance impact."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Keep an eye on the Kubernetes release notes and engage with the community through SIG Node discussions for the latest updates and best practices."}]},{"type":"heading","attrs":{"level":2,"id":"the-future-of-kubernetes-observability"},"content":[{"type":"text","text":"The Future of Kubernetes Observability"}]},{"type":"paragraph","content":[{"type":"text","text":"KEP-2831 isn''t just about adding another observability tool—it''s about completing the observability story for Kubernetes. By bridging the gap between application-level and infrastructure-level tracing, it enables a new level of system understanding that wasn''t possible before."}]},{"type":"heading","attrs":{"level":3,"id":"kubernetes-134-release-timeline"},"content":[{"type":"text","text":"Kubernetes 1.34 Release Timeline"}]},{"type":"paragraph","content":[{"type":"text","text":"The journey to GA is well underway with these key milestones:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Enhancements Freeze"},{"type":"text","text":": June 20, 2025 - All KEPs locked in"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Code Freeze"},{"type":"text","text":": July 25, 2025 - Implementation complete"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"GA Release"},{"type":"text","text":": August 27, 2025 - Kubelet tracing becomes production-ready"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"As we approach the v1.34 GA release, expect to see:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enhanced integration with popular observability platforms."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Performance optimizations to reduce overhead."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Additional instrumentation points based on community feedback."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"For DevOps engineers, platform engineers, and SREs, kubelet tracing represents an opportunity to level up your debugging capabilities and gain deeper insights into your Kubernetes infrastructure. The question isn''t whether you should adopt it—it''s how quickly you can start experimenting and learning."}]},{"type":"paragraph","content":[{"type":"text","text":"The future of Kubernetes observability is here, and it''s more transparent than ever."}]}]}', 'news', 0, 0, NULL, '[]', '["kubernetes","observability","release","tracing"]', 'https://content.rawkode.academy/articles/kep-2831-kubelet-tracing/cover.png', 'Stylized illustration representing Kubernetes Kubelet with 1.34 OTEL integration. On the left, the Kubernetes logo appears above the word ''kubelet'' in bold white text on a blue-to-green gradient background. On the right, a futuristic isometric design shows interconnected nodes and servers with flowing lines, symbolizing telemetry and observability connections.', 1472, 832, 'Kubelet Tracing Coming in K8s 1.34!', 'GA release brings node-level observability to Kubernetes', '[]', '[]', 1752451200000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('kep-2831-kubelet-tracing', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('kep-2831-kubelet-tracing', 'kubernetes', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('kep-2831-kubelet-tracing', 'opentelemetry', 1);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('klustered-winter-2026', 'Klustered Winter 2026 starts 30 October', NULL, 'Klustered returns on Friday, 30 October 2026. Contestants race the clock to diagnose and fix deliberately broken Kubernetes clusters.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Klustered is back. Winter 2026 starts on Friday, 30 October."}]},{"type":"paragraph","content":[{"type":"text","text":"Contestants race against the clock to diagnose and fix deliberately broken Kubernetes clusters. The community can sabotage the clusters, so the rest of us get to watch the troubleshooting unfold live."}]},{"type":"paragraph","content":[{"type":"text","text":"Want to compete? Applications for Winter 2026 are open. Click "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/shows/klustered/apply","target":null,"rel":null,"class":null,"title":null}}],"text":"Apply"},{"type":"text","text":", choose Solo or Team, and sign in to submit your application."}]},{"type":"paragraph","content":[{"type":"text","text":"Put 30 October in your calendar. We’ll see who can get the cluster back on its feet."}]}]}', 'article', 0, 0, NULL, '[]', '[]', 'https://content.rawkode.academy/articles/klustered-winter-2026/cover.webp', 'Connected server racks in a glowing cluster network, with one node fractured by red light', 1734, 907, 'Klustered Winter 2026 starts 30 October', 'The live Kubernetes troubleshooting show returns Friday, 30 October.', '[]', '[]', 1790294400000, NULL, 1790348835000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('klustered-winter-2026', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('klustered-winter-2026', 'kubernetes', 0);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('kubernetes-operators-rust-kube-rs', 'Building Kubernetes Operators in Rust with kube-rs: Why Your Next Controller Shouldn''t Be Written in Go', NULL, 'A practical guide to building production-grade Kubernetes operators in Rust using kube-rs. Learn why Rust''s memory safety, performance, and type system make it an excellent choice for the next generation of cloud native controllers.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Look, I love Rust. I''m always talking about Rust. So today, we''re talking about Rust."}]},{"type":"paragraph","content":[{"type":"text","text":"I''ve been building Kubernetes operators for years, mostly in Go. It''s the obvious choice: Kubernetes itself is written in Go, and "},{"type":"text","marks":[{"type":"code"}],"text":"controller-runtime"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"kubebuilder"},{"type":"text","text":" make scaffolding easy. But \"path of least resistance\" and \"best tool for the job\" aren''t always the same thing."}]},{"type":"paragraph","content":[{"type":"text","text":"Since CoreOS introduced the operator pattern in 2016, operators have proliferated across the ecosystem, managing databases, message queues, certificates, and increasingly complex stateful workloads. As they become more critical to production infrastructure, the language they''re written in matters more than ever."}]},{"type":"paragraph","content":[{"type":"text","text":"I recently joined CoreWeave, and I''m thinking a lot about how operators scale when you''re managing GPU infrastructure across hundreds of clusters. Rust''s memory efficiency and safety guarantees aren''t nice-to-haves at that scale. They''re operational necessities."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"kube-rs"},{"type":"text","text":" is a mature, production-ready Rust client for Kubernetes. It gives you everything you need to build operators with Rust''s memory safety, zero-cost abstractions, and fearless concurrency. The type system catches so many bugs that would be runtime panics in Go. If you''re building controllers that need to be reliable, efficient, and correct, it''s time to look beyond Go."}]},{"type":"heading","attrs":{"level":2,"id":"why-rust-for-kubernetes-operators"},"content":[{"type":"text","text":"Why Rust for Kubernetes Operators?"}]},{"type":"paragraph","content":[{"type":"text","text":"The obvious question: why choose Rust over Go for something so deeply embedded in the Go ecosystem?"}]},{"type":"heading","attrs":{"level":3,"id":"memory-safety-without-a-garbage-collector"},"content":[{"type":"text","text":"Memory Safety Without a Garbage Collector"}]},{"type":"paragraph","content":[{"type":"text","text":"Go''s garbage collector is good, but it introduces latency spikes. For most applications, this is irrelevant. For a controller reconciling thousands of resources under pressure during a cluster incident, those pauses matter. Rust gives you deterministic memory management with zero garbage collection pauses. Your controller''s performance is predictable under load."}]},{"type":"paragraph","content":[{"type":"text","text":"More importantly, Rust''s ownership model eliminates entire classes of bugs at compile time. No null pointer dereferences. No data races. No use-after-free. When your operator is managing production databases or handling secrets rotation, these guarantees aren''t academic. They''re operational necessities."}]},{"type":"heading","attrs":{"level":3,"id":"type-system-as-documentation-and-guardrail"},"content":[{"type":"text","text":"Type System as Documentation and Guardrail"}]},{"type":"paragraph","content":[{"type":"text","text":"Go''s type system is intentionally simple. Rust''s is intentionally expressive. When you''re defining Custom Resource Definitions (CRDs), Rust''s type system (with enums, pattern matching, and trait-based generics) lets you model your domain with precision that Go''s structs and interfaces can''t match."}]},{"type":"paragraph","content":[{"type":"text","text":"Consider modeling the state of a managed database:"}]},{"type":"codeBlock","attrs":{"language":"rust","title":null,"meta":null},"content":[{"type":"text","text":"#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]\npub enum DatabasePhase {\n    Provisioning {\n        started_at: String,\n        progress: ProvisioningStep,\n    },\n    Running {\n        endpoint: String,\n        version: String,\n        last_backup: Option<String>,\n    },\n    Upgrading {\n        from_version: String,\n        to_version: String,\n        rollback_snapshot: String,\n    },\n    Failed {\n        reason: String,\n        last_healthy_at: String,\n        recovery_attempts: u32,\n    },\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"In Go, you''d represent this as a string phase field with a collection of optional fields, losing the compiler''s ability to enforce that you handle every state transition correctly. In Rust, a "},{"type":"text","marks":[{"type":"code"}],"text":"match"},{"type":"text","text":" on "},{"type":"text","marks":[{"type":"code"}],"text":"DatabasePhase"},{"type":"text","text":" forces you to handle every variant. You can''t forget an edge case."}]},{"type":"heading","attrs":{"level":3,"id":"resource-efficiency"},"content":[{"type":"text","text":"Resource Efficiency"}]},{"type":"paragraph","content":[{"type":"text","text":"Rust binaries are compact and start fast. A typical kube-rs operator compiles to a binary often under 20 MB with release optimizations, starts in milliseconds, and uses a fraction of the memory of its Go equivalent. When you''re running operators across hundreds of clusters, this efficiency compounds into real cost savings."}]},{"type":"heading","attrs":{"level":2,"id":"getting-started-with-kube-rs"},"content":[{"type":"text","text":"Getting Started with kube-rs"}]},{"type":"paragraph","content":[{"type":"text","text":"I''m going to walk you through building a real operator. We''ll create a controller that manages a custom "},{"type":"text","marks":[{"type":"code"}],"text":"WebApp"},{"type":"text","text":" resource: a simplified abstraction that creates and manages a Deployment, Service, and optionally an Ingress for web applications."}]},{"type":"heading","attrs":{"level":3,"id":"project-setup"},"content":[{"type":"text","text":"Project Setup"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"cargo init webapp-operator\ncd webapp-operator"}]},{"type":"paragraph","content":[{"type":"text","text":"Add the essential dependencies to your "},{"type":"text","marks":[{"type":"code"}],"text":"Cargo.toml"},{"type":"text","text":":"}]},{"type":"codeBlock","attrs":{"language":"toml","title":null,"meta":null},"content":[{"type":"text","text":"[dependencies]\nkube = { version = \"3.0\", features = [\"runtime\", \"derive\"] }\nk8s-openapi = { version = \"0.27\", features = [\"latest\", \"schemars\"] }\nschemars = \"1\"\nserde = { version = \"1\", features = [\"derive\"] }\nserde_json = \"1\"\ntokio = { version = \"1\", features = [\"full\"] }\ntracing = \"0.1\"\ntracing-subscriber = { version = \"0.3\", features = [\"env-filter\"] }\nthiserror = \"2\"\nfutures = \"0.3\""}]},{"type":"heading","attrs":{"level":3,"id":"defining-your-custom-resource"},"content":[{"type":"text","text":"Defining Your Custom Resource"}]},{"type":"paragraph","content":[{"type":"text","text":"The CRD is where Rust''s type system really shines. kube-rs uses derive macros to generate the full CRD schema from your Rust types:"}]},{"type":"codeBlock","attrs":{"language":"rust","title":null,"meta":null},"content":[{"type":"text","text":"use kube::CustomResource;\nuse schemars::JsonSchema;\nuse serde::{Deserialize, Serialize};\n\n#[derive(CustomResource, Debug, Clone, Serialize, Deserialize, JsonSchema)]\n#[kube(\n    group = \"apps.rawkode.academy\",\n    version = \"v1\",\n    kind = \"WebApp\",\n    plural = \"webapps\",\n    status = \"WebAppStatus\",\n    namespaced,\n    printcolumn = r#\"{\"name\":\"Phase\",\"type\":\"string\",\"jsonPath\":\".status.phase\"}\"#,\n    printcolumn = r#\"{\"name\":\"Replicas\",\"type\":\"integer\",\"jsonPath\":\".spec.replicas\"}\"#\n)]\npub struct WebAppSpec {\n    /// Container image to deploy\n    pub image: String,\n\n    /// Number of replicas\n    #[serde(default = \"default_replicas\")]\n    pub replicas: i32,\n\n    /// Port the application listens on\n    #[serde(default = \"default_port\")]\n    pub port: i32,\n\n    /// Optional hostname for Ingress creation\n    pub hostname: Option<String>,\n\n    /// Environment variables to inject\n    #[serde(default)]\n    pub env: Vec<EnvVar>,\n\n    /// Resource requirements\n    pub resources: Option<ResourceRequirements>,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]\npub struct EnvVar {\n    pub name: String,\n    pub value: String,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]\npub struct ResourceRequirements {\n    pub cpu: String,\n    pub memory: String,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]\npub struct WebAppStatus {\n    pub phase: String,\n    pub ready_replicas: i32,\n    pub message: Option<String>,\n    pub last_reconciled: Option<String>,\n}\n\nfn default_replicas() -> i32 { 3 }\nfn default_port() -> i32 { 8080 }"}]},{"type":"paragraph","content":[{"type":"text","text":"That "},{"type":"text","marks":[{"type":"code"}],"text":"#[derive(CustomResource)]"},{"type":"text","text":" macro generates a complete "},{"type":"text","marks":[{"type":"code"}],"text":"WebApp"},{"type":"text","text":" struct with metadata, spec, and status, plus methods to generate the CRD YAML. Call "},{"type":"text","marks":[{"type":"code"}],"text":"WebApp::crd()"},{"type":"text","text":" and you get a fully-typed "},{"type":"text","marks":[{"type":"code"}],"text":"CustomResourceDefinition"},{"type":"text","text":" ready to apply to your cluster."}]},{"type":"heading","attrs":{"level":3,"id":"the-reconciliation-loop"},"content":[{"type":"text","text":"The Reconciliation Loop"}]},{"type":"paragraph","content":[{"type":"text","text":"The heart of any operator is its reconciliation function. kube-rs provides a "},{"type":"text","marks":[{"type":"code"}],"text":"Controller"},{"type":"text","text":" runtime that handles watch events, requeueing, and error backoff. Your job is to implement the reconcile function:"}]},{"type":"codeBlock","attrs":{"language":"rust","title":null,"meta":null},"content":[{"type":"text","text":"use kube::{\n    api::{Api, Patch, PatchParams, ResourceExt},\n    runtime::controller::{Action, Controller},\n    Client, Resource,\n};\nuse std::sync::Arc;\nuse tokio::time::Duration;\n\n// Shared state for the controller\nstruct Context {\n    client: Client,\n}\n\nasync fn reconcile(\n    webapp: Arc<WebApp>,\n    ctx: Arc<Context>,\n) -> Result<Action, Error> {\n    let client = &ctx.client;\n    let name = webapp.name_any();\n    let namespace = webapp.namespace().unwrap_or_default();\n\n    tracing::info!(\n        name = %name,\n        namespace = %namespace,\n        \"Reconciling WebApp\"\n    );\n\n    // Step 1: Ensure the Deployment exists and is up-to-date\n    reconcile_deployment(client, &webapp).await?;\n\n    // Step 2: Ensure the Service exists\n    reconcile_service(client, &webapp).await?;\n\n    // Step 3: If hostname is specified, ensure Ingress exists\n    if webapp.spec.hostname.is_some() {\n        reconcile_ingress(client, &webapp).await?;\n    }\n\n    // Step 4: Update status\n    update_status(client, &webapp).await?;\n\n    // Re-reconcile every 5 minutes to catch drift\n    Ok(Action::requeue(Duration::from_secs(300)))\n}\n\nfn error_policy(\n    _webapp: Arc<WebApp>,\n    error: &Error,\n    _ctx: Arc<Context>,\n) -> Action {\n    tracing::error!(%error, \"Reconciliation failed\");\n    // Fixed retry interval of 10 seconds\n    Action::requeue(Duration::from_secs(10))\n}"}]},{"type":"heading","attrs":{"level":3,"id":"building-the-deployment"},"content":[{"type":"text","text":"Building the Deployment"}]},{"type":"paragraph","content":[{"type":"text","text":"This is where Rust''s type safety pays off. Instead of constructing untyped JSON objects, you build fully-typed Kubernetes resources:"}]},{"type":"codeBlock","attrs":{"language":"rust","title":null,"meta":null},"content":[{"type":"text","text":"use k8s_openapi::api::apps::v1::{Deployment, DeploymentSpec};\nuse k8s_openapi::api::core::v1::{\n    Container, ContainerPort, PodSpec, PodTemplateSpec,\n};\nuse k8s_openapi::apimachinery::pkg::apis::meta::v1::LabelSelector;\nuse std::collections::BTreeMap;\n\nasync fn reconcile_deployment(\n    client: &Client,\n    webapp: &WebApp,\n) -> Result<(), Error> {\n    let namespace = webapp.namespace().unwrap_or_default();\n    let name = webapp.name_any();\n    let deployments: Api<Deployment> =\n        Api::namespaced(client.clone(), &namespace);\n\n    let labels: BTreeMap<String, String> = BTreeMap::from([\n        (\"app.kubernetes.io/name\".into(), name.clone()),\n        (\"app.kubernetes.io/managed-by\".into(), \"webapp-operator\".into()),\n    ]);\n\n    let deployment = Deployment {\n        metadata: kube::api::ObjectMeta {\n            name: Some(name.clone()),\n            namespace: Some(namespace.clone()),\n            labels: Some(labels.clone()),\n            owner_references: Some(\n                webapp.controller_owner_ref(&()).into_iter().collect()\n            ),\n            ..Default::default()\n        },\n        spec: Some(DeploymentSpec {\n            replicas: Some(webapp.spec.replicas),\n            selector: LabelSelector {\n                match_labels: Some(labels.clone()),\n                ..Default::default()\n            },\n            template: PodTemplateSpec {\n                metadata: Some(kube::api::ObjectMeta {\n                    labels: Some(labels),\n                    ..Default::default()\n                }),\n                spec: Some(PodSpec {\n                    containers: vec![Container {\n                        name: \"app\".into(),\n                        image: Some(webapp.spec.image.clone()),\n                        ports: Some(vec![ContainerPort {\n                            container_port: webapp.spec.port,\n                            ..Default::default()\n                        }]),\n                        ..Default::default()\n                    }],\n                    ..Default::default()\n                }),\n            },\n            ..Default::default()\n        }),\n        ..Default::default()\n    };\n\n    deployments\n        .patch(\n            &name,\n            &PatchParams::apply(\"webapp-operator\"),\n            &Patch::Apply(deployment),\n        )\n        .await?;\n\n    Ok(())\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"Notice the "},{"type":"text","marks":[{"type":"code"}],"text":"owner_references"},{"type":"text","text":" line. This sets up Kubernetes garbage collection so that when a "},{"type":"text","marks":[{"type":"code"}],"text":"WebApp"},{"type":"text","text":" is deleted, its Deployment is automatically cleaned up. kube-rs provides "},{"type":"text","marks":[{"type":"code"}],"text":"controller_owner_ref"},{"type":"text","text":" as a convenience method that returns an "},{"type":"text","marks":[{"type":"code"}],"text":"Option<OwnerReference>"},{"type":"text","text":". The "},{"type":"text","marks":[{"type":"code"}],"text":".into_iter().collect()"},{"type":"text","text":" pattern cleanly converts it into the "},{"type":"text","marks":[{"type":"code"}],"text":"Vec"},{"type":"text","text":" that "},{"type":"text","marks":[{"type":"code"}],"text":"owner_references"},{"type":"text","text":" expects."}]},{"type":"heading","attrs":{"level":2,"id":"architecture-how-it-all-fits-together"},"content":[{"type":"text","text":"Architecture: How It All Fits Together"}]},{"type":"paragraph","content":[{"type":"text","text":"Here''s how the operator interacts with the Kubernetes API and manages its resources:"}]},{"type":"diagram","attrs":{"id":null,"title":null,"description":null,"language":"d2","source":"direction: right\n\nuser: User {\n  shape: person\n}\n\napiserver: Kubernetes API Server {\n  style.fill: \"#326CE5\"\n  style.font-color: \"#ffffff\"\n}\n\noperator: WebApp Operator {\n  style.fill: \"#CE412B\"\n  style.font-color: \"#ffffff\"\n\n  watcher: Watch Stream\n  reconciler: Reconcile Loop\n  queue: Work Queue\n\n  watcher -> queue: enqueue events\n  queue -> reconciler: dequeue\n}\n\nwebapp_crd: WebApp CR {\n  style.fill: \"#DEA584\"\n}\n\ndeployment: Deployment {\n  style.fill: \"#4A9BD9\"\n}\n\nservice: Service {\n  style.fill: \"#4A9BD9\"\n}\n\ningress: Ingress {\n  style.fill: \"#4A9BD9\"\n}\n\nuser -> apiserver: kubectl apply WebApp\napiserver -> webapp_crd: stores\napiserver -> operator.watcher: watch events\noperator.reconciler -> apiserver: create/update resources\napiserver -> deployment: stores\napiserver -> service: stores\napiserver -> ingress: stores (if hostname set)","meta":"sketch","src":"https://content.rawkode.academy/articles/kubernetes-operators-rust-kube-rs/diagrams/2000ba267a04c76f.svg"}},{"type":"paragraph","content":[{"type":"text","text":"The operator watches for changes to "},{"type":"text","marks":[{"type":"code"}],"text":"WebApp"},{"type":"text","text":" custom resources. When a change is detected, the watcher enqueues a reconciliation event. The reconciler then ensures the actual state (Deployments, Services, Ingresses) matches the desired state defined in the "},{"type":"text","marks":[{"type":"code"}],"text":"WebApp"},{"type":"text","text":" spec. This is the standard level-triggered reconciliation pattern, the same one that powers every built-in Kubernetes controller."}]},{"type":"heading","attrs":{"level":2,"id":"testing-your-operator"},"content":[{"type":"text","text":"Testing Your Operator"}]},{"type":"paragraph","content":[{"type":"text","text":"One of kube-rs''s underrated strengths is its testing story. The library provides utilities for both unit testing with mocked API responses and integration testing against real clusters."}]},{"type":"heading","attrs":{"level":3,"id":"unit-testing-with-mocked-responses"},"content":[{"type":"text","text":"Unit Testing with Mocked Responses"}]},{"type":"codeBlock","attrs":{"language":"rust","title":null,"meta":null},"content":[{"type":"text","text":"#[cfg(test)]\nmod tests {\n    use super::*;\n    use kube::api::ObjectMeta;\n\n    fn test_webapp() -> WebApp {\n        WebApp {\n            metadata: ObjectMeta {\n                name: Some(\"test-app\".into()),\n                namespace: Some(\"default\".into()),\n                ..Default::default()\n            },\n            spec: WebAppSpec {\n                image: \"nginx:latest\".into(),\n                replicas: 2,\n                port: 80,\n                hostname: Some(\"test.example.com\".into()),\n                env: vec![],\n                resources: None,\n            },\n            status: None,\n        }\n    }\n\n    #[test]\n    fn test_crd_generation() {\n        // Verify CRD schema is valid\n        let crd = WebApp::crd();\n        assert_eq!(crd.metadata.name, Some(\"webapps.apps.rawkode.academy\".into()));\n    }\n\n    #[test]\n    fn test_default_values() {\n        let spec: WebAppSpec = serde_json::from_str(r#\"{\n            \"image\": \"nginx:latest\"\n        }\"#).unwrap();\n        assert_eq!(spec.replicas, 3);\n        assert_eq!(spec.port, 8080);\n    }\n}"}]},{"type":"heading","attrs":{"level":3,"id":"integration-testing"},"content":[{"type":"text","text":"Integration Testing"}]},{"type":"paragraph","content":[{"type":"text","text":"For integration tests, kube-rs works well with tools like "},{"type":"text","marks":[{"type":"code"}],"text":"k3d"},{"type":"text","text":" or "},{"type":"text","marks":[{"type":"code"}],"text":"kind"},{"type":"text","text":". Spin up an ephemeral cluster in CI:"}]},{"type":"codeBlock","attrs":{"language":"rust","title":null,"meta":null},"content":[{"type":"text","text":"#[tokio::test]\n#[ignore = \"requires cluster\"]\nasync fn test_full_reconciliation() {\n    let client = Client::try_default().await.unwrap();\n    let webapps: Api<WebApp> = Api::namespaced(client.clone(), \"default\");\n\n    // Create a WebApp\n    let webapp = WebApp::new(\"integration-test\", WebAppSpec {\n        image: \"nginx:latest\".into(),\n        replicas: 1,\n        port: 80,\n        hostname: None,\n        env: vec![],\n        resources: None,\n    });\n\n    webapps.create(&Default::default(), &webapp).await.unwrap();\n\n    // Wait for reconciliation\n    tokio::time::sleep(Duration::from_secs(5)).await;\n\n    // Verify Deployment was created\n    let deployments: Api<Deployment> =\n        Api::namespaced(client.clone(), \"default\");\n    let deploy = deployments.get(\"integration-test\").await.unwrap();\n    assert_eq!(\n        deploy.spec.unwrap().replicas,\n        Some(1)\n    );\n}"}]},{"type":"heading","attrs":{"level":2,"id":"the-main-function-wiring-it-all-together"},"content":[{"type":"text","text":"The Main Function: Wiring It All Together"}]},{"type":"paragraph","content":[{"type":"text","text":"Here''s the complete entrypoint that starts the controller:"}]},{"type":"codeBlock","attrs":{"language":"rust","title":null,"meta":null},"content":[{"type":"text","text":"use futures::StreamExt;\n\n#[tokio::main]\nasync fn main() -> Result<(), Box<dyn std::error::Error>> {\n    tracing_subscriber::fmt()\n        .with_env_filter(\"webapp_operator=info,kube=info\")\n        .json()\n        .init();\n\n    let client = Client::try_default().await?;\n\n    // Ensure CRD exists (or apply it separately)\n    let webapps: Api<WebApp> = Api::all(client.clone());\n    let deployments: Api<Deployment> = Api::all(client.clone());\n\n    tracing::info!(\"Starting WebApp operator\");\n\n    Controller::new(webapps, Default::default())\n        // Watch owned Deployments for changes\n        .owns(deployments, Default::default())\n        .run(reconcile, error_policy, Arc::new(Context { client }))\n        .for_each(|result| async move {\n            match result {\n                Ok(obj) => tracing::info!(resource = ?obj, \"Reconciled\"),\n                Err(err) => tracing::error!(%err, \"Reconciliation error\"),\n            }\n        })\n        .await;\n\n    Ok(())\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","marks":[{"type":"code"}],"text":".owns(deployments, Default::default())"},{"type":"text","text":" call is crucial. It tells the controller to also watch Deployments and trigger reconciliation of the owning "},{"type":"text","marks":[{"type":"code"}],"text":"WebApp"},{"type":"text","text":" if a managed Deployment changes. This is how your operator detects drift: if someone manually edits a Deployment, the controller immediately reconciles it back to the desired state."}]},{"type":"heading","attrs":{"level":2,"id":"containerizing-and-deploying"},"content":[{"type":"text","text":"Containerizing and Deploying"}]},{"type":"paragraph","content":[{"type":"text","text":"Rust''s compilation model makes containerization straightforward. Here''s a multi-stage Dockerfile:"}]},{"type":"codeBlock","attrs":{"language":"dockerfile","title":null,"meta":null},"content":[{"type":"text","text":"FROM rust:1.93 AS builder\nWORKDIR /build\nCOPY . .\nRUN cargo build --release\n\nFROM gcr.io/distroless/cc-debian12:nonroot\nCOPY --from=builder /build/target/release/webapp-operator /\nENTRYPOINT [\"/webapp-operator\"]"}]},{"type":"paragraph","content":[{"type":"text","text":"The final image is typically under 30 MB. Compare this to Go operator images, which with similar distroless builds land around 30-50 MB, or larger when you start including debugging tools. Java-based operators (yes, they exist) can exceed 300 MB."}]},{"type":"heading","attrs":{"level":2,"id":"when-to-choose-rust-over-go"},"content":[{"type":"text","text":"When to Choose Rust Over Go"}]},{"type":"paragraph","content":[{"type":"text","text":"I want to be straight with you. Rust isn''t always the right choice for every operator."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Choose Rust when:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your operator manages security-sensitive resources (secrets, certificates, network policies)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You need predictable, low-latency reconciliation under high load"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your team already has Rust experience"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You''re building a long-lived project where compile-time correctness pays dividends"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Resource efficiency matters (edge deployments, large-scale multi-cluster)"}]}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Stick with Go when:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You''re prototyping and need maximum iteration speed"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your team is Go-native and switching would slow delivery"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You need deep integration with controller-runtime''s ecosystem (e.g., Kubebuilder scaffolding)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The operator is simple enough that Go''s simplicity is an advantage"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The ecosystem around kube-rs is growing steadily. "},{"type":"text","marks":[{"type":"bold"}],"text":"kopium"},{"type":"text","text":" generates Rust types from existing CRDs, and the broader kube-rs project (a CNCF Sandbox project) continues to add tooling that reduces boilerplate. The community is smaller than Go''s operator ecosystem, but it''s active, welcoming, and shipping real production software."}]},{"type":"heading","attrs":{"level":2,"id":"production-readiness-checklist"},"content":[{"type":"text","text":"Production Readiness Checklist"}]},{"type":"paragraph","content":[{"type":"text","text":"Before shipping your Rust operator to production, make sure you''ve covered these essentials:"}]},{"type":"taskList","content":[{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"RBAC manifests"},{"type":"text","text":": Generate ClusterRole/ClusterRoleBinding with minimum required permissions"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Leader election"},{"type":"text","text":": Use a leader election crate such as "},{"type":"text","marks":[{"type":"code"}],"text":"kube-leader-election"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"kube-coordinate"},{"type":"text","text":", or "},{"type":"text","marks":[{"type":"code"}],"text":"kube-lease-manager"},{"type":"text","text":" to prevent split-brain in HA deployments"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Metrics endpoint"},{"type":"text","text":": Expose Prometheus metrics for reconciliation duration, queue depth, and errors"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Health probes"},{"type":"text","text":": Implement "},{"type":"text","marks":[{"type":"code"}],"text":"/healthz"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"/readyz"},{"type":"text","text":" endpoints for Kubernetes liveness and readiness checks"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Graceful shutdown"},{"type":"text","text":": Handle SIGTERM to complete in-flight reconciliations before exiting"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Finalizers"},{"type":"text","text":": Add finalizers to handle custom cleanup logic when resources are deleted"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Status subresource"},{"type":"text","text":": Always write meaningful status conditions so users can "},{"type":"text","marks":[{"type":"code"}],"text":"kubectl get webapps"},{"type":"text","text":" and understand state"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Owner references"},{"type":"text","text":": Set owner references on all created resources for automatic garbage collection"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Event recording"},{"type":"text","text":": Emit Kubernetes Events so "},{"type":"text","marks":[{"type":"code"}],"text":"kubectl describe"},{"type":"text","text":" shows what the operator is doing"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"E2E tests in CI"},{"type":"text","text":": Run integration tests against an ephemeral cluster (k3d/kind) on every PR"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"CRD versioning strategy"},{"type":"text","text":": Plan for how you''ll handle CRD schema evolution (conversion webhooks if needed)"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Container image signing"},{"type":"text","text":": Sign images with cosign and publish SBOMs for supply chain security"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"the-bigger-picture"},"content":[{"type":"text","text":"The Bigger Picture"}]},{"type":"paragraph","content":[{"type":"text","text":"We''re past the point where \"it works\" is good enough for operators. They need to be secure, efficient, and maintainable over years of production use. Rust''s guarantees align perfectly with those requirements."}]},{"type":"paragraph","content":[{"type":"text","text":"kube-rs has proven itself in production at scale. It''s maintained by an active community, has excellent documentation, and the tooling ecosystem keeps growing. If you''ve been curious about Rust but haven''t found the right project to start with, a Kubernetes operator is a great place to begin. You get practical Rust experience while building something genuinely useful for your infrastructure."}]},{"type":"paragraph","content":[{"type":"text","text":"The cloud native world doesn''t have to be a Go monoculture. Diversity in implementation languages leads to diversity in ideas and approaches. Your next operator might just be your first Rust project."}]},{"type":"paragraph","content":[{"type":"text","text":"Give it a try. Your future on-call self will thank you."}]}]}', 'article', 0, 0, NULL, '[]', '[]', 'https://content.rawkode.academy/articles/kubernetes-operators-rust-kube-rs/cover.png', 'Stylized illustration showing the Rust crab mascot Ferris interacting with Kubernetes pods and controllers, with flowing lines representing reconciliation loops on a dark gradient background.', 1376, 768, 'Kubernetes Operators in Rust with kube-rs', 'Why I''m building my next controller in Rust', '[]', '[]', 1778803200000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('kubernetes-operators-rust-kube-rs', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('kubernetes-operators-rust-kube-rs', 'rust', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('kubernetes-operators-rust-kube-rs', 'kube-rs', 1);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('kubernetes-operators-rust-kube-rs', 'kubernetes', 2);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('kyverno-cel-validating-policy', 'Kyverno ValidatingPolicy with CEL: Working Examples (2026)', NULL, 'Replace ClusterPolicy with Kyverno ValidatingPolicy using CEL expressions. Real examples for image verification, label rules, and replica limits.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kyverno 1.14 (released April 25, 2025) introduces dedicated ValidatingPolicy and ImageValidatingPolicy types that leverage CEL (Common Expression Language) - the same validation language Kubernetes now uses natively, creating a unified policy experience across your entire stack."}]},{"type":"paragraph","content":[{"type":"text","text":"For platform engineers and security teams implementing policy-as-code in Kubernetes, this convergence represents a fundamental shift toward standardization and performance. Let''s explore why this matters and how to get started."}]},{"type":"heading","attrs":{"level":2,"id":"the-cel-convergence"},"content":[{"type":"text","text":"The CEL Convergence"}]},{"type":"paragraph","content":[{"type":"text","text":"Kubernetes'' adoption of CEL for native validation creates an unprecedented opportunity for policy engines like Kyverno to standardize on the same language. This convergence delivers three critical benefits:"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"One expression language"},{"type":"text","text":" to learn across Kubernetes and Kyverno means your team invests in skills that transfer between CRD validation rules, ValidatingAdmissionPolicies, and now Kyverno policies."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Better performance"},{"type":"text","text":" - CEL expressions are parsed once and compiled to bytecode, providing significant speed improvements over traditional validation methods."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Reusable validation logic"},{"type":"text","text":" between native Kubernetes and Kyverno policies eliminates the need to maintain separate validation implementations."}]},{"type":"paragraph","content":[{"type":"text","text":"Kubernetes now uses CEL in multiple contexts:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CRD validation rules (beta in 1.25, GA in 1.29)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ValidatingAdmissionPolicies (beta in 1.28, GA in 1.30)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Future features like ResourceQuota expressions and RBAC conditions"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This means mastering CEL for Kyverno directly translates to expertise across the entire Kubernetes ecosystem."}]},{"type":"heading","attrs":{"level":2,"id":"your-first-validatingpolicy"},"content":[{"type":"text","text":"Your First ValidatingPolicy"}]},{"type":"paragraph","content":[{"type":"text","text":"Let''s start with a practical example that demonstrates the power and simplicity of Kyverno''s new ValidatingPolicy with CEL:"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"apiVersion: policies.kyverno.io/v1alpha1\nkind: ValidatingPolicy\nmetadata:\n  name: require-pod-resources\nspec:\n  matchConstraints:\n    resourceRules:\n    - apiGroups:   [\"\"]\n      apiVersions: [v1]\n      operations:  [CREATE, UPDATE]\n      resources:   [pods]\n  validations:\n  - expression: |\n      object.spec.containers.all(container,\n        has(container.resources.limits) &&\n        has(container.resources.limits.memory) &&\n        has(container.resources.limits.cpu)\n      )\n    message: \"All containers must have CPU and memory limits defined\"\n  - expression: |\n      object.spec.containers.all(container,\n        container.resources.limits.memory.matches(''^[0-9]+(Mi|Gi)$'') &&\n        size(container.resources.limits.memory) <= size(''8Gi'')\n      )\n    message: \"Memory limits must not exceed 8Gi\""}]},{"type":"paragraph","content":[{"type":"text","text":"This policy enforces two critical requirements:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"All containers must have CPU and memory limits defined"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Memory limits cannot exceed 8Gi"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The CEL expressions use familiar functional programming patterns like "},{"type":"text","marks":[{"type":"code"}],"text":"all()"},{"type":"text","text":" to iterate over collections, making the logic both readable and powerful."}]},{"type":"heading","attrs":{"level":2,"id":"why-this-matters-the-kubernetes-cel-native-story"},"content":[{"type":"text","text":"Why This Matters: The Kubernetes CEL Native Story"}]},{"type":"paragraph","content":[{"type":"text","text":"Understanding how CEL fits into the broader Kubernetes ecosystem helps appreciate why this standardization matters. Consider how the same validation logic can now work across different contexts."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"CRD Validation Example:"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"apiVersion: apiextensions.k8s.io/v1\nkind: CustomResourceDefinition\nmetadata:\n  name: applications.platform.io\nspec:\n  validation:\n    openAPIV3Schema:\n      properties:\n        spec:\n          properties:\n            replicas:\n              type: integer\n              x-kubernetes-validations:\n              - rule: \"self <= 10\"\n                message: \"replicas cannot exceed 10\""}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Kyverno ValidatingPolicy Example:"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"apiVersion: policies.kyverno.io/v1alpha1\nkind: ValidatingPolicy\nmetadata:\n  name: replica-limit\nspec:\n  matchConstraints:\n    resourceRules:\n    - operations: [\"CREATE\", \"UPDATE\"]\n      apiGroups: [\"apps\"]\n      apiVersions: [\"v1\"]\n      resources: [\"deployments\"]\n  validations:\n  - expression: \"object.spec.replicas <= 10\"\n    message: \"replicas cannot exceed 10\""}]},{"type":"paragraph","content":[{"type":"text","text":"Notice how the core CEL expression "},{"type":"text","marks":[{"type":"code"}],"text":"object.spec.replicas <= 10"},{"type":"text","text":" remains identical across all three contexts. This consistency dramatically reduces the learning curve and enables teams to reuse validation logic."}]},{"type":"heading","attrs":{"level":2,"id":"advanced-pattern-cross-resource-validation"},"content":[{"type":"text","text":"Advanced Pattern: Cross-Resource Validation"}]},{"type":"paragraph","content":[{"type":"text","text":"CEL''s power becomes evident when handling complex validation scenarios that require external data or cross-resource relationships:"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"apiVersion: policies.kyverno.io/v1alpha1\nkind: ValidatingPolicy\nmetadata:\n  name: namespace-resource-quotas\nspec:\n  matchConstraints:\n    resourceRules:\n    - operations: [\"CREATE\", \"UPDATE\"]\n      apiGroups: [\"apps\"]\n      apiVersions: [\"v1\"]\n      resources: [\"deployments\", \"statefulsets\"]\n  variables:\n  - name: configs\n    expression: >\n      resource.Get(\"v1\", \"configmaps\", \"platform\", \"team-configs\")\n  validations:\n      - expression: |\n          has(object.metadata.labels.team) &&\n          object.metadata.labels.team in variables.configs.data &&\n          object.spec.replicas <= int(variables.configs.data[object.metadata.labels.team])\n        message: \"Replica count exceeds team quota defined in platform/team-configs\"\n      - expression: |\n          has(object.metadata.labels.environment) &&\n          object.metadata.labels.environment in [''dev'', ''staging'', ''prod'']\n        message: \"Must specify valid environment label: dev, staging, or prod\""}]},{"type":"paragraph","content":[{"type":"text","text":"This policy demonstrates advanced CEL patterns:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"External parameter references"},{"type":"text","text":" using "},{"type":"text","marks":[{"type":"code"}],"text":"paramKind"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"paramRef"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Data validation"},{"type":"text","text":" against external ConfigMap values"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Multi-expression validation"},{"type":"text","text":" with distinct error messages"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Complex boolean logic"},{"type":"text","text":" combining multiple conditions"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The referenced ConfigMap might look like:"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"apiVersion: v1\nkind: ConfigMap\nmetadata:\n  name: team-configs\n  namespace: platform\ndata:\n  frontend: \"5\"\n  backend: \"10\"\n  data: \"3\""}]},{"type":"heading","attrs":{"level":2,"id":"imagevalidatingpolicy-in-action"},"content":[{"type":"text","text":"ImageValidatingPolicy in Action"}]},{"type":"paragraph","content":[{"type":"text","text":"Kyverno 1.14 also introduces ImageValidatingPolicy for specialized image security validation:"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"# https://github.com/kyverno/policies/blob/main/other/verify-image-ivpol/verify-image-ivpol.yaml\napiVersion: policies.kyverno.io/v1alpha1\nkind: ImageValidatingPolicy\nmetadata:\n  name: verify-image-ivpol\n  annotations:\n    policies.kyverno.io/title: Verify Image\n    policies.kyverno.io/category: Software Supply Chain Security, EKS Best Practices\n    policies.kyverno.io/severity: medium\n    policies.kyverno.io/subject: Pod\n    policies.kyverno.io/minversion: 1.14.0\n    policies.kyverno.io/description: >-\n      Using the Cosign project, OCI images may be signed to ensure supply chain\n      security is maintained. Those signatures can be verified before pulling into\n      a cluster. This policy checks the signature of an image repo called\n      ghcr.io/kyverno/test-verify-image to ensure it has been signed by verifying\n      its signature against the provided public key. This policy serves as an illustration for\n      how to configure a similar rule and will require replacing with your image(s) and keys.\nspec:\n  webhookConfiguration:\n    timeoutSeconds: 30\n  evaluation:\n   background:\n    enabled: false\n  validationActions: [Deny]\n  matchConstraints:\n    resourceRules:\n      - apiGroups: [\"\"]\n        apiVersions: [\"v1\"]\n        operations: [\"CREATE\", \"UPDATE\"]\n        resources: [\"pods\"]\n  matchImageReferences:\n        - glob : \"docker.io/mohdcode/kyverno*\"\n  attestors:\n  - name: cosign\n    cosign:\n     key:\n      data: |\n                -----BEGIN PUBLIC KEY-----\n                MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAE6QsNef3SKYhJVYSVj+ZfbPwJd0pv\n                DLYNHXITZkhIzfE+apcxDjCCkDPcJ3A3zvhPATYOIsCxYPch7Q2JdJLsDQ==\n                -----END PUBLIC KEY-----\n  validations:\n    - expression: >-\n       images.containers.map(image, verifyImageSignatures(image, [attestors.cosign])).all(e ,e > 0)\n      message: >-\n       failed the verification"}]},{"type":"paragraph","content":[{"type":"text","text":"This policy combines signature verification with CEL-based attestation validation, ensuring:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Images are signed with the specified public key"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Build provenance follows SLSA standards"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dependencies meet stability requirements"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"migration-guide-from-clusterpolicy-to-validatingpolicy"},"content":[{"type":"text","text":"Migration Guide: From ClusterPolicy to ValidatingPolicy"}]},{"type":"paragraph","content":[{"type":"text","text":"Migrating existing ClusterPolicy resources to the new ValidatingPolicy type often simplifies your policy definitions. Here''s a before/after comparison:"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Before (ClusterPolicy):"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"apiVersion: kyverno.io/v1\nkind: ClusterPolicy\nmetadata:\n  name: require-labels\nspec:\n  rules:\n  - name: require-labels\n    match:\n      any:\n      - resources:\n          kinds:\n          - Deployment\n    validate:\n      failureAction: Enforce\n      message: \"Environment label must be dev, staging, or prod\"\n      anyPattern:\n      - metadata:\n          labels:\n            environment: \"dev\" # Changed label key to ''environment'' to match message\n      - metadata:\n          labels:\n            environment: \"staging\"\n      - metadata:\n          labels:\n            environment: \"prod\""}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"After (ValidatingPolicy):"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"apiVersion: policies.kyverno.io/v1alpha1\nkind: ValidatingPolicy\nmetadata:\n  name: require-labels\nspec:\n  matchConstraints:\n    resourceRules:\n    - operations: [\"CREATE\", \"UPDATE\"]\n      apiGroups: [\"apps\"]\n      apiVersions: [\"v1\"]\n      resources: [\"deployments\"]\n  validations:\n    - expression: \"has(object.metadata.labels.team) && object.metadata.labels.team != ''''\"\n      message: \"Deployments must have a team label\"\n    - expression: \"has(object.metadata.labels.environment) && object.metadata.labels.environment in [''dev'', ''staging'', ''prod'']\"\n      message: \"Environment label must be dev, staging, or prod\""}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Migration Benefits:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Reduced complexity"},{"type":"text","text":": Single rule instead of multiple rules"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Better performance"},{"type":"text","text":": CEL compilation vs pattern matching"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Clearer logic"},{"type":"text","text":": Explicit boolean expressions vs pattern inference"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Enhanced readability"},{"type":"text","text":": Self-documenting validation conditions"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"performance-implications"},"content":[{"type":"text","text":"Performance Implications"}]},{"type":"paragraph","content":[{"type":"text","text":"CEL''s compilation model provides significant performance advantages over traditional validation approaches. Kyverno maintainers report substantial improvements in policy evaluation speed, though specific benchmarks vary by workload:"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"ClusterPolicy Pattern Matching:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Parse YAML patterns at runtime"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Recursive object traversal for each validation"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Variable performance depending on pattern complexity"}]}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"ValidatingPolicy CEL:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Compile expressions once at policy load"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Direct object field access via compiled bytecode"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Faster execution for complex validation logic"}]}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Real-world Impact:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Measurably faster policy evaluation"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reduced CPU usage during peak admission loads"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Better cluster responsiveness under policy-heavy workloads"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"For clusters with hundreds of policies and high pod creation rates, these performance improvements directly translate to reduced latency and improved user experience."}]},{"type":"heading","attrs":{"level":2,"id":"getting-started-checklist"},"content":[{"type":"text","text":"Getting Started Checklist"}]},{"type":"paragraph","content":[{"type":"text","text":"Ready to adopt Kyverno 1.14''s ValidatingPolicy? Follow this implementation path:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Upgrade Kyverno"},{"type":"text","text":" to version 1.14 or later"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Start with simple policies"},{"type":"text","text":" using basic CEL expressions"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Gradually migrate"},{"type":"text","text":" existing ClusterPolicy resources"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Leverage external parameters"},{"type":"text","text":" for dynamic validation"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Implement ImageValidatingPolicy"},{"type":"text","text":" for supply chain security"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Monitor performance"},{"type":"text","text":" improvements in your cluster"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The convergence of CEL across Kubernetes and Kyverno represents more than just a technical upgrade - it''s a fundamental shift toward a unified policy ecosystem. By adopting these new ValidatingPolicy types, you''re investing in skills and patterns that will serve your platform engineering efforts across the entire Kubernetes landscape."}]},{"type":"paragraph","content":[{"type":"text","text":"Start experimenting with CEL today, and experience the power of unified validation logic across your cloud native stack."}]}]}', 'article', 0, 0, NULL, '[]', '[]', 'https://content.rawkode.academy/articles/kyverno-cel-validating-policy/cover.png', 'Kyverno CEL ValidatingPolicy visualization', 1536, 1024, 'Kyverno ValidatingPolicy with CEL: Working Examples (2026)', 'Migrating from ClusterPolicy with side-by-side examples', '[{"date":"2025-06-04T00:00:00.000Z","description":"Claude article review changed policies for the worst. This has been corrected"}]', '[]', 1748822400000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('kyverno-cel-validating-policy', 'rawkode', 0);
