INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('kyverno-cel-validating-policy', 'kubernetes', 1);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('news-digest-250804', 'News Digest for August 4th, 2025', NULL, 'A dispatch from the cloud-native world, where the height of innovation is apparently pointlessly reinventing YAML while shaking down the community for container images like a common street mugger', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The cloud-native landscape continues its rapid evolution, bringing significant shifts in core technologies, a new vision for AI-assisted development, and strategic realignments from key players."}]},{"type":"paragraph","content":[{"type":"text","text":"Grab a coffee, let''s dive in."}]},{"type":"heading","attrs":{"level":2,"id":"kubernetes-v134-stability-smart-tokens-and-a-new-yaml-dialect"},"content":[{"type":"text","text":"Kubernetes v1.34: Stability, Smart Tokens, and a New YAML Dialect"}]},{"type":"heading","attrs":{"level":3,"id":"the-facts"},"content":[{"type":"text","text":"The Facts"}]},{"type":"paragraph","content":[{"type":"text","text":"Kubernetes v1.34 releases August 27, 2025, with zero removals or deprecations. Key graduations include:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Dynamic Resource Allocation"},{"type":"text","text":" hitting stable ("},{"type":"text","marks":[{"type":"code"}],"text":"resource.k8s.io/v1"},{"type":"text","text":")"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"ServiceAccount tokens for image pull authentication"},{"type":"text","text":" reaching beta (enabled by default)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Kubelet and API Server tracing"},{"type":"text","text":" graduating to stable with OpenTelemetry integration"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Traffic distribution"},{"type":"text","text":" gets beta "},{"type":"text","marks":[{"type":"code"}],"text":"PreferSameNode"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"PreferSameZone"},{"type":"text","text":" options"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"HPA tolerance field"},{"type":"text","text":" targeting beta for fine-grained scaling control"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Kubernetes is also introducing "},{"type":"text","marks":[{"type":"bold"}],"text":"KYAML"},{"type":"text","text":" - a Kubernetes dialect of YAML - as a new kubectl output format."}]},{"type":"heading","attrs":{"level":3,"id":"the-editorial"},"content":[{"type":"text","text":"The Editorial"}]},{"type":"paragraph","content":[{"type":"text","text":"Look, I get it. KYAML maintains backward compatibility while addressing YAML''s notorious footguns. It''s not forcing new APIs on anyone, and it works with existing tooling. It''s a boring and sensible decision."}]},{"type":"paragraph","content":[{"type":"text","text":"But this still feels like classic NIH syndrome. "},{"type":"text","marks":[{"type":"bold"}],"text":"CUE"},{"type":"text","text":" already exists and elegantly solves every problem KYAML is trying to address - yes, even if you need a PhD in type theory to write it effectively. The CNCF even has "},{"type":"text","marks":[{"type":"bold"}],"text":"KCL"},{"type":"text","text":" sitting right there. Both are mature, battle-tested solutions."}]},{"type":"paragraph","content":[{"type":"text","text":"I wish this could be different, I wish the project could take more risks and bring in better solutions, but I emphasise with what they have to work with. maybe Kubernetes 2.0 can make the right decision."}]},{"type":"heading","attrs":{"level":2,"id":"the-dawn-of-vibe-coding-and-ai-assisted-development"},"content":[{"type":"text","text":"The Dawn of \"Vibe Coding\" and AI-Assisted Development"}]},{"type":"heading","attrs":{"level":3,"id":"the-facts-1"},"content":[{"type":"text","text":"The Facts"}]},{"type":"paragraph","content":[{"type":"text","text":"Gene Kim declares AI coding \"10 to 100 times bigger than DevOps.\" His book \"Vibe Coding\" (co-authored with Steve Yegge) was created using 70 million AI tokens. Their FAAFO framework promises five superpowers:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Fast:"},{"type":"text","text":" Ship features in minutes"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Ambitious:"},{"type":"text","text":" Weekend achievement of long-term goals"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Autonomous:"},{"type":"text","text":" Single developers functioning as teams"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Fun:"},{"type":"text","text":" Eliminate tedious work"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Optionality:"},{"type":"text","text":" Cheap parallel experimentation"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Adidas reports 2x increase in developer \"happy time\" across 700 developers using GitHub Copilot daily."}]},{"type":"heading","attrs":{"level":3,"id":"the-editorial-1"},"content":[{"type":"text","text":"The Editorial"}]},{"type":"paragraph","content":[{"type":"text","text":"Whether you buy into the \"vibe coding\" hype or not, the data is compelling. Kim''s prediction that this increases developer demand rather than decreasing it feels counterintuitive but tracks with historical automation trends. The question isn''t if AI will transform development - it''s whether \"vibe coding\" will be what we actually call it in five years."}]},{"type":"heading","attrs":{"level":2,"id":"building-the-internet-of-agents-with-agntcy"},"content":[{"type":"text","text":"Building the \"Internet of Agents\" with AGNTCY"}]},{"type":"heading","attrs":{"level":3,"id":"the-facts-2"},"content":[{"type":"text","text":"The Facts"}]},{"type":"paragraph","content":[{"type":"text","text":"Cisco donated AGNTCY to the Linux Foundation with backing from Dell, Google Cloud, Oracle, and Red Hat. The project aims to build open, interoperable, quantum-safe infrastructure for collaborative AI agents, including components for:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Agent discovery"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Identity management"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Messaging protocols"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Observability standards"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"the-editorial-2"},"content":[{"type":"text","text":"The Editorial"}]},{"type":"paragraph","content":[{"type":"text","text":"Smart move putting this under neutral governance. The agent ecosystem is currently a fragmented mess, and interoperability is make-or-break for this technology scaling beyond toy demos. The Linux Foundation''s track record with Kubernetes gives some hope this won''t devolve into vendor politics."}]},{"type":"paragraph","content":[{"type":"text","text":"Honestly, Cisco is embracing Open Source and the community and proving to be a good steward. Broadcom, take notes!"}]},{"type":"heading","attrs":{"level":2,"id":"kubesphere-adjusts-open-source-project-focus"},"content":[{"type":"text","text":"KubeSphere Adjusts Open Source Project Focus"}]},{"type":"heading","attrs":{"level":3,"id":"the-facts-3"},"content":[{"type":"text","text":"The Facts"}]},{"type":"paragraph","content":[{"type":"text","text":"KubeSphere announced changes effective July 31, 2025:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Discontinuing download links for open-source version"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ceasing free technical support"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Code remains Apache 2.0 licensed (for now)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pushing users toward commercial solutions"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"the-editorial-3"},"content":[{"type":"text","text":"The Editorial"}]},{"type":"paragraph","content":[{"type":"text","text":"In news that will surely impact someone, somewhere, KubeSphere - the cloud-native platform you may or may not have heard of - is essentially abandoning its open-source community; assuming one exists..."}]},{"type":"paragraph","content":[{"type":"text","text":"The \"we need to concentrate resources\" line is corporate speak for \"this isn''t making us money.\" At least they''re keeping the code open source... for now."}]},{"type":"paragraph","content":[{"type":"text","text":"Real talk though: Open Source needs to be sustainable and frankly, it isn''t. Again, I emphasise with these difficult decisions. These orgs place a huge amount of risk on Open Source being a viable marketing strategy and it continues to prove time and time again that it isn''t. It''s not the quick path to adoption, nor inbound sales."}]},{"type":"heading","attrs":{"level":2,"id":"bitnami-announces-major-catalog-changes"},"content":[{"type":"text","text":"Bitnami Announces Major Catalog Changes"}]},{"type":"heading","attrs":{"level":3,"id":"the-facts-4"},"content":[{"type":"text","text":"The Facts"}]},{"type":"paragraph","content":[{"type":"text","text":"Effective August 28, 2025, Bitnami implements massive catalog changes:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Debian-based images:"},{"type":"text","text":" Discontinued and moved to unsupported \"Bitnami Legacy\" repository"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Free tier:"},{"type":"text","text":" Reduced to \"latest\" tag only, development use only"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"All existing versions:"},{"type":"text","text":" Moved to "},{"type":"text","marks":[{"type":"code"}],"text":"docker.io/bitnamilegacy"},{"type":"text","text":" with zero updates"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Production images:"},{"type":"text","text":" Now require \"Bitnami Secure Images\" commercial subscription"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Timeline:"},{"type":"text","text":" Users have until August 28 to update all CI/CD pipelines"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"the-editorial-4"},"content":[{"type":"text","text":"The Editorial"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"This is a disaster."}]},{"type":"paragraph","content":[{"type":"text","text":"Broadcom has somehow managed to make Cloud Native "},{"type":"text","marks":[{"type":"italic"}],"text":"even worse"},{"type":"text","text":" than VMware did - a title I didn''t think could be claimed. This isn''t just bad; it''s catastrophically stupid."}]},{"type":"paragraph","content":[{"type":"text","text":"Millions of deployments depend on Bitnami images. Countless tutorials, documentation, and automation scripts reference them. And Broadcom''s solution? Pay us or get fucked."}]},{"type":"paragraph","content":[{"type":"text","text":"The \"legacy\" repository is particularly insulting - it''s not maintained, not supported, just a graveyard where your production dependencies go to die. They''re not even pretending to care about the community impact."}]},{"type":"paragraph","content":[{"type":"text","text":"This is worse than Docker Hub''s rate limiting fiasco. At least Docker gave people workable alternatives and time to adjust."}]},{"type":"paragraph","content":[{"type":"text","text":"Broadcom is essentially holding the community hostage: pay for enterprise licenses or scramble to rebuild your entire container strategy in less than a month."}]},{"type":"paragraph","content":[{"type":"text","text":"Google stepped in and provided a Docker Hub mirror, which is a lot easier to handle than maintaining thousands of Open Source charts. I''m not entirely sure any single entity can ease the burden of this disaster."}]},{"type":"paragraph","content":[{"type":"text","text":"The message is crystal clear: Broadcom views open source not as a community to nurture, but as a customer acquisition funnel to squeeze. They''ve taken one of the most trusted brands in cloud-native and turned it into a cautionary tale about what happens when private equity mindset meets open source infrastructure."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Start migrating now."},{"type":"text","text":" Seriously. August 28 will come faster than you think, and Broadcom has made it abundantly clear they don''t give a single damn about your production workloads."}]}]}', 'news', 0, 0, NULL, '[]', '["kubernetes","open-source"]', 'https://content.rawkode.academy/articles/news-digest-250804/cover.png', 'Rawkode Academy Newspaper dated August 4th, 2025', 1200, 675, 'News Digest for August 4th, 2025', 'A dispatch from the cloud-native world, where the height of innovation is apparently pointlessly reinventing YAML while shaking down the community for container images like a common street mugger', '[]', '[]', 1754179200000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('news-digest-250804', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('news-digest-250804', 'kubernetes', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('news-digest-250804', 'docker', 1);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('packet-metadata-for-saltstack', 'Packet Metadata for SaltStack', NULL, 'In my last article, we spun up some bare metal compute on Packet with Pulumi and installed SaltStack....', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In my last "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/read/saltstack-on-packet-with-pulumi","target":null,"rel":null,"class":null,"title":null}}],"text":"article"},{"type":"text","text":", we spun up some bare metal compute on "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://www.packet.com","target":null,"rel":null,"class":null,"title":null}}],"text":"Packet"},{"type":"text","text":" with "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://www.pulumi.com","target":null,"rel":null,"class":null,"title":null}}],"text":"Pulumi"},{"type":"text","text":" and installed "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://www.saltstack.com","target":null,"rel":null,"class":null,"title":null}}],"text":"SaltStack"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"In order to use SaltStack to provision our workloads on our servers, we need a way to identify which machines should be provisioned with what workload. SaltStack uses "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://docs.saltstack.com/en/latest/topics/grains/","target":null,"rel":null,"class":null,"title":null}}],"text":"Grains"},{"type":"text","text":" to do this ... and there''s a metadata grain that can read metadata from cloud providers; unfortunately, it doesn''t support Packet."}]},{"type":"paragraph","content":[{"type":"text","text":"Drats ☹️"}]},{"type":"paragraph","content":[{"type":"text","text":"Happy news though, SaltStack is rather extensible; as long as you don''t mind getting your hands a little dirty with Python."}]},{"type":"heading","attrs":{"level":2,"id":"writing-a-custom-grain"},"content":[{"type":"text","text":"Writing a Custom Grain"}]},{"type":"paragraph","content":[{"type":"text","text":"Writing a SaltStack grain module is SUPER easy. Lets take a look at the simplest implementation I can put together."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"def test():\n    return dict(test={\n        \"name\": \"David\",\n        \"age\": \"18\",\n    })\n"}]},{"type":"paragraph","content":[{"type":"text","text":"Yeah, yeah. I know I''m not 18 anymore. Shush."}]},{"type":"paragraph","content":[{"type":"text","text":"Grain modules are Python functions that return key value pairs. This code above returns a grain named \"test\" with the key/value pairs "},{"type":"text","marks":[{"type":"code"}],"text":"name = David"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"age = 18"},{"type":"text","text":". This means we can run "},{"type":"text","marks":[{"type":"code"}],"text":"salt minion-1 grains.item test"},{"type":"text","text":" and we''ll see:"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"minion-1:\n    ----------\n    test:\n        ----------\n        name:\n            David\n        age:\n            18\n"}]},{"type":"paragraph","content":[{"type":"text","text":"Of course, we don''t want to return hared coded key values! We want to return information about our servers from Packet''s "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://www.packet.com/developers/docs/servers/key-features/metadata/","target":null,"rel":null,"class":null,"title":null}}],"text":"metadata API"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"The code to handle this isn''t particularly complicated. In-fact, performing a HTTP request in Python is really simple 😀"}]},{"type":"paragraph","content":[{"type":"text","text":"Lets take a look."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"import json\nimport logging\nimport salt.utils.http as http\n\n# Setup logging\nlog = logging.getLogger( __name__ )\n\n# metadata server information\nHOST = \"https://metadata.packet.net/metadata\"\n\ndef packet_metadata():\n    response = http.query(HOST)\n    metadata = json.loads(response[\"body\"])\n\n    log.error(metadata)\n\n    grains = {}\n    grains[\"id\"] = metadata[\"id\"]\n    grains[\"iqn\"] = metadata[\"iqn\"]\n    grains[\"plan\"] = metadata[\"plan\"]\n    grains[\"class\"] = metadata[\"class\"]\n    grains[\"facility\"] = metadata[\"facility\"]\n\n    grains[\"tags\"] = metadata[\"tags\"]\n\n    return dict(packet_metadata=grains)\n"}]},{"type":"paragraph","content":[{"type":"text","text":"The important lines here are these three:"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"HOST = \"https://metadata.packet.net/metadata\"\n\nresponse = http.query(HOST)\nmetadata = json.loads(response[\"body\"])\n"}]},{"type":"paragraph","content":[{"type":"text","text":"We first query the metadata API endpoint, defined by the variable "},{"type":"text","marks":[{"type":"code"}],"text":"HOST"},{"type":"text","text":". We then decode the body of the response into a Python dict, using "},{"type":"text","marks":[{"type":"code"}],"text":"json.loads"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"This gives us access to every bit of metadata returned by the Packet metadata API. That looks like:"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"{\n  \"id\": \"c5ce85c5-1eef-4581-90b6-88a91e47e207\",\n  \"hostname\": \"master-1\",\n  \"iqn\": \"iqn.2020-08.net.packet:device.c5ce85c5\",\n  \"operating_system\": {\n    \"slug\": \"debian_9\",\n    \"distro\": \"debian\",\n    \"version\": \"9\",\n    \"license_activation\": {\n      \"state\": \"unlicensed\"\n    },\n    \"image_tag\": \"b32a1f31b127ef631d6ae31af9c6d8b69dcaa9e9\"\n  },\n  \"plan\": \"c2.medium.x86\",\n  \"class\": \"c2.medium.x86\",\n  \"facility\": \"ams1\",\n  \"private_subnets\": [\"10.0.0.0/8\"],\n  \"tags\": [\"role/salt-master\"],\n  \"ssh_keys\": [\n    \"ecdsa-sha2-nistp256 AAAAE2VjZHNhLXNoYTItbmlzdHAyNTYAAAAIbmlzdHAyNTYAAABBBGf0w9b+lPcZhsNHU8Sw5hJPBhpNICTNkjlBz9jxtLbWNGvHTE1lBeXU5VA2/7cuYw48apHmMURHFtK5AZx3srg=\"\n  ],\n  \"storage\": {\n    \"disks\": [\n      {\n        \"device\": \"/dev/sdd\",\n        \"wipeTable\": true,\n        \"partitions\": [\n          {\n            \"label\": \"BIOS\",\n            \"number\": 1,\n            \"size\": \"512M\"\n          },\n          {\n            \"label\": \"SWAP\",\n            \"number\": 2,\n            \"size\": \"3993600\"\n          },\n          {\n            \"label\": \"ROOT\",\n            \"number\": 3,\n            \"size\": 0\n          }\n        ]\n      }\n    ],\n    \"filesystems\": [\n      {\n        \"mount\": {\n          \"device\": \"/dev/sdd1\",\n          \"format\": \"vfat\",\n          \"point\": \"/boot/efi\",\n          \"create\": {\n            \"options\": [\"32\", \"-n\", \"EFI\"]\n          }\n        }\n      },\n      {\n        \"mount\": {\n          \"device\": \"/dev/sdd3\",\n          \"format\": \"ext4\",\n          \"point\": \"/\",\n          \"create\": {\n            \"options\": [\"-L\", \"ROOT\"]\n          }\n        }\n      },\n      {\n        \"mount\": {\n          \"device\": \"/dev/sdd2\",\n          \"format\": \"swap\",\n          \"point\": \"none\",\n          \"create\": {\n            \"options\": [\"-L\", \"SWAP\"]\n          }\n        }\n      }\n    ]\n  },\n  \"network\": {\n    \"bonding\": {\n      \"mode\": 4,\n      \"link_aggregation\": \"bonded\",\n      \"mac\": \"50:6b:4b:b4:a9:3a\"\n    },\n    \"interfaces\": [\n      {\n        \"name\": \"eth0\",\n        \"mac\": \"50:6b:4b:b4:a9:3a\",\n        \"bond\": \"bond0\"\n      },\n      {\n        \"name\": \"eth1\",\n        \"mac\": \"50:6b:4b:b4:a9:3b\",\n        \"bond\": \"bond0\"\n      }\n    ],\n    \"addresses\": [\n      {\n        \"id\": \"5d28837b-29c5-4505-bb05-930fd3760bac\",\n        \"address_family\": 4,\n        \"netmask\": \"255.255.255.252\",\n        \"created_at\": \"2020-08-03T14:07:50Z\",\n        \"public\": true,\n        \"cidr\": 30,\n        \"management\": true,\n        \"enabled\": true,\n        \"network\": \"147.75.84.128\",\n        \"address\": \"147.75.84.130\",\n        \"gateway\": \"147.75.84.129\",\n        \"parent_block\": {\n          \"network\": \"147.75.84.128\",\n          \"netmask\": \"255.255.255.252\",\n          \"cidr\": 30,\n          \"href\": \"/ips/7a30c2bf-f0e5-402c-b0c0-b8ab03359e63\"\n        }\n      },\n      {\n        \"id\": \"937552c6-cf1a-474d-9866-9fb1e0525503\",\n        \"address_family\": 4,\n        \"netmask\": \"255.255.255.254\",\n        \"created_at\": \"2020-08-03T14:07:49Z\",\n        \"public\": false,\n        \"cidr\": 31,\n        \"management\": true,\n        \"enabled\": true,\n        \"network\": \"10.80.76.4\",\n        \"address\": \"10.80.76.5\",\n        \"gateway\": \"10.80.76.4\",\n        \"parent_block\": {\n          \"network\": \"10.80.76.0\",\n          \"netmask\": \"255.255.255.128\",\n          \"cidr\": 25,\n          \"href\": \"/ips/8f8cd919-165a-4e62-b461-af7c15a25ec4\"\n        }\n      }\n    ]\n  },\n  \"customdata\": {},\n  \"specs\": {\n    \"cpus\": [\n      {\n        \"count\": 1,\n        \"type\": \"AMD EPYC 7401P 24-Core Processor @ 2.0GHz\"\n      }\n    ],\n    \"memory\": {\n      \"total\": \"64GB\"\n    },\n    \"drives\": [\n      {\n        \"count\": 2,\n        \"size\": \"120GB\",\n        \"type\": \"SSD\",\n        \"category\": \"boot\"\n      },\n      {\n        \"count\": 2,\n        \"size\": \"480GB\",\n        \"type\": \"SSD\",\n        \"category\": \"storage\"\n      }\n    ],\n    \"nics\": [\n      {\n        \"count\": 2,\n        \"type\": \"10Gbps\"\n      }\n    ],\n    \"features\": {}\n  },\n  \"switch_short_id\": \"f8dd5e3f\",\n  \"volumes\": [],\n  \"api_url\": \"https://metadata.packet.net\",\n  \"phone_home_url\": \"http://tinkerbell.ams1.packet.net/phone-home\",\n  \"user_state_url\": \"http://tinkerbell.ams1.packet.net/events\"\n}\n"}]},{"type":"paragraph","content":[{"type":"text","text":"I decided not to make all of this available within the grains system, as only a few data points make sense for scheduling workloads. Hence, I cherry pick out the attributes I want for the next demo. You can pick and choose whatever you want too."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"grains = {}\ngrains[\"id\"] = metadata[\"id\"]\ngrains[\"iqn\"] = metadata[\"iqn\"]\ngrains[\"plan\"] = metadata[\"plan\"]\ngrains[\"class\"] = metadata[\"class\"]\ngrains[\"facility\"] = metadata[\"facility\"]\n\ngrains[\"tags\"] = metadata[\"tags\"]\n\nreturn dict(packet_metadata=grains)\n"}]},{"type":"heading","attrs":{"level":2,"id":"provisioning-the-custom-grain"},"content":[{"type":"text","text":"Provisioning the Custom Grain"}]},{"type":"paragraph","content":[{"type":"text","text":"Now that we have a custom grain, we need to update our Pulumi code to install this on our Salt master."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"NB"},{"type":"text","text":" : We "},{"type":"text","marks":[{"type":"bold"}],"text":"only"},{"type":"text","text":" need to make this grain available on our Salt master, as the Salt master takes responsibility for syncing custom grains to the minions."}]},{"type":"paragraph","content":[{"type":"text","text":"I''ve updated our "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://gitlab.com/rawkode/packet-examples/-/blob/master/pulumi-saltstack/src/salt-master/user-data.sh","target":null,"rel":null,"class":null,"title":null}}],"text":"user-data.sh"},{"type":"text","text":" to create the directory we need and added the mustache template syntax that allows us to inject the Python script. We use "},{"type":"text","marks":[{"type":"code"}],"text":"&"},{"type":"text","text":" before the variable name to request that mustache doesn''t escape our quotes to HTML entities ... I only learnt that today 😂"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"mkdir -p /srv/salt/_grains\n\ncat <<EOF >/srv/salt/_grains/packet_metadata.py\n{{ &PACKET_METADATA_PY }}\nEOF\n"}]},{"type":"paragraph","content":[{"type":"text","text":"Next up, we provide the Python script at render time and provide some tags for our servers when we create them."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"const pythonPacketMetadataGrain = fs\n  .readFileSync(path.join(__dirname, \"..\", \"salt\", \"packet_metadata.py\"))\n  .toString();\n\nconst saltMaster = new Device(`master-${name}`, {\n  // ... code omitted for brevity\n  userData: mustache.render(bootstrapString, {\n    PACKET_METADATA_PY: pythonPacketMetadataGrain,\n  }),\n  // Add tags to this server\n  tags: [\"role/salt-master\"],\n});\n"}]},{"type":"heading","attrs":{"level":3,"id":"syncing-custom-grains"},"content":[{"type":"text","text":"Syncing Custom Grains"}]},{"type":"paragraph","content":[{"type":"text","text":"Finally, we need to tell our Salt master to sync the grains to our minions."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"salt \"*\" saltutil.grains_sync\n"}]},{"type":"paragraph","content":[{"type":"text","text":"You can now confirm the custom grain is working with:"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"root@master-1:~# salt \"*\" grains.item packet_metadata\nminion-1:\n    ----------\n    packet_metadata:\n        ----------\n        class:\n            c2.medium.x86\n        facility:\n            ams1\n        id:\n            ab0bc2ba-557b-4d99-a1eb-0beec02adff2\n        iqn:\n            iqn.2020-08.net.packet:device.ab0bc2ba\n        plan:\n            c2.medium.x86\n        tags:\n            - role/salt-minion\nmaster-1:\n    ----------\n    packet_metadata:\n        ----------\n        class:\n            c2.medium.x86\n        facility:\n            ams1\n        id:\n            97ce9196-077d-4ce9-82a5-d58bf59d0dbc\n        iqn:\n            iqn.2020-08.net.packet:device.97ce9196\n        plan:\n            c2.medium.x86\n        tags:\n            - role/salt-master\n"}]},{"type":"paragraph","content":[{"type":"text","text":"That''s it! Next time we''ll take a look at using our tags to provision and schedule our workloads."}]},{"type":"paragraph","content":[{"type":"text","text":"See you then."}]}]}', 'tutorial', 0, 0, NULL, '[]', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1596412800000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('packet-metadata-for-saltstack', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('packet-metadata-for-saltstack', 'salt', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('packet-metadata-for-saltstack', 'equinix-metal', 1);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('questdb-on-kubernetes', 'QuestDB on Kubernetes', NULL, 'I was first introduced to QuestDB by my former colleague, David Simmons, who now runs their Developer...', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I was first introduced to QuestDB by my former colleague, "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://twitter.com/davidgsiot","target":null,"rel":null,"class":null,"title":null}}],"text":"David Simmons"},{"type":"text","text":", who now runs their Developer Relations team. As I''m a rather curious individual that is interested in databases, especially time-series, I wanted to have a play with it."}]},{"type":"paragraph","content":[{"type":"text","text":"I don''t, unless absolutely need to, have a JVM installed on my laptop. QuestDB is written in Java ... so I had two options: Docker or Kubernetes."}]},{"type":"paragraph","content":[{"type":"text","text":"I opted for Kubernetes, as there was no Helm chart currently available; this would give me a great opportunity to contribute to QuestDB."}]},{"type":"paragraph","content":[{"type":"text","text":"If you''d prefer to watch a video than read this blog, fear not! You can watch David and I run through this process in the following video, which also includes configuring Telegraf to write data to QuestDB."}]},{"type":"embed","attrs":{"src":"https://www.youtube-nocookie.com/embed/EFpZzgj8EfE","title":null,"width":560,"height":315,"allow":"accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture","allowFullscreen":true}},{"type":"heading","attrs":{"level":2,"id":"installing-questdb-on-kubernetes-with-helm"},"content":[{"type":"text","text":"Installing QuestDB on Kubernetes with Helm"}]},{"type":"paragraph","content":[{"type":"text","text":"In order to install QuestDB to Kubernetes, we need to clone the Helm chart locally. This step is currently required because a Helm chart repository isn''t currently being published by QuestDB yet, though this is something I expect to assist them with over the coming weeks with some further contributions."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"git clone https://github.com/questdb/questdb-kubernetes\n"}]},{"type":"paragraph","content":[{"type":"text","text":"The chart ships with a "},{"type":"text","marks":[{"type":"code"}],"text":"values.yaml"},{"type":"text","text":" that should be familiar to anyone that''s deployed a Kubernetes resource before. I cover each block in a little detail in the next section, should you be interested in that kinda thing."}]},{"type":"paragraph","content":[{"type":"text","text":"For those of you that don''t care, lets get to the fun bit. The following command assumes we''ve run the "},{"type":"text","marks":[{"type":"code"}],"text":"git clone"},{"type":"text","text":" above in the current working directory. If not, update the path at the end to wherever you cloned."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"helm upgrade --install questdb ./questdb-kubernetes/charts/questdb\n"}]},{"type":"paragraph","content":[{"type":"text","text":"This command takes only a second, or two, and will print something like so to the terminal."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"Release \"questdb\" does not exist. Installing it now.\nNAME: questdb\nLAST DEPLOYED: Mon Aug 24 11:15:15 2020\nNAMESPACE: default\nSTATUS: deployed\nREVISION: 1\nNOTES:\n1. Get the application URL by running these commands:\n  export POD_NAME=$(kubectl get pods --namespace default -l \"app.kubernetes.io/name=questdb,app.kubernetes.io/instance=questdb\" -o jsonpath=\"{.items[0].metadata.name}\")\n  echo \"Visit http://127.0.0.1:9000 to use your application\"\n  kubectl --namespace default port-forward $POD_NAME 9000:9000\n"}]},{"type":"heading","attrs":{"level":3,"id":"confirming-the-install"},"content":[{"type":"text","text":"Confirming the Install"}]},{"type":"paragraph","content":[{"type":"text","text":"The first thing we''ll want to do is ensure that the pods are scheduled and running. You may see the "},{"type":"text","marks":[{"type":"code"}],"text":"STATUS"},{"type":"text","text":" as "},{"type":"text","marks":[{"type":"code"}],"text":"ContainerCreating"},{"type":"text","text":" for a few moments, this means that the container image is still being pulled into your cluster."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"$ kubectl get pods\n\nNAME READY STATUS RESTARTS AGE\nquestdb-0 1/1 Running 0 3s\n"}]},{"type":"paragraph","content":[{"type":"text","text":"💥 Perfect."}]},{"type":"paragraph","content":[{"type":"text","text":"Now that QuestDB is running, we''ll want to port-forward to the service in-order to checkout the web UI."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"kubectl port-forward svc/questdb 8080:80\n"}]},{"type":"paragraph","content":[{"type":"text","text":"This setups a port-forward from our local machine into the Kubernetes cluster. We''re specifying that the local port "},{"type":"text","marks":[{"type":"code"}],"text":"8080"},{"type":"text","text":" should be forwarded to port "},{"type":"text","marks":[{"type":"code"}],"text":"80"},{"type":"text","text":" our QuestDB service, "},{"type":"text","marks":[{"type":"code"}],"text":"svc/questdb"},{"type":"text","text":", inside the Kubernetes cluster."}]},{"type":"paragraph","content":[{"type":"text","text":"As if by magic, you''ll now be able to browse to "},{"type":"text","marks":[{"type":"code"}],"text":"http://localhost:8080"},{"type":"text","text":" and see the QuestDB UI."}]},{"type":"paragraph","content":[{"type":"text","text":"Don''t believe me? Try it 🤪"}]},{"type":"heading","attrs":{"level":3,"id":"writing-data"},"content":[{"type":"text","text":"Writing Data"}]},{"type":"paragraph","content":[{"type":"text","text":"One of the really cool features of QuestDB, besides its ridiculous performance with large data sets, is the support for InfluxDB line protocol. That means we can use Telegraf to write data to QuestDB within a matter of minutes."}]},{"type":"paragraph","content":[{"type":"text","text":"Assuming we have this "},{"type":"text","marks":[{"type":"code"}],"text":"telegraf.conf"},{"type":"text","text":", which is configured with input plugins to gather metrics from our host; notable the "},{"type":"text","marks":[{"type":"code"}],"text":"cpu"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"disk"},{"type":"text","text":", and "},{"type":"text","marks":[{"type":"code"}],"text":"mem"},{"type":"text","text":" plugins."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"[agent]\n  interval = \"5s\"\n\n[[inputs.cpu]]\n[[inputs.disk]]\n[[inputs.mem]]\n"}]},{"type":"paragraph","content":[{"type":"text","text":"We can add Telegraf''s generic "},{"type":"text","marks":[{"type":"code"}],"text":"socket_writer"},{"type":"text","text":" output plugin to write our data."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"[[outputs.socket_writer]]\n  address = \"tcp://questdb:9009\"\n  data_format = \"influx\"\n"}]},{"type":"paragraph","content":[{"type":"text","text":"This output configuration specifies that we want Telegraf to use the line protocol data format and we want to write to a TCP socket on port "},{"type":"text","marks":[{"type":"code"}],"text":"9009"},{"type":"text","text":". This does require enabling one parameter within the "},{"type":"text","marks":[{"type":"code"}],"text":"values.yaml"},{"type":"text","text":" file."}]},{"type":"paragraph","content":[{"type":"text","text":"First, lets take a look at our QuestDB service."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"$ kubectl get svc\nNAME TYPE CLUSTER-IP EXTERNAL-IP PORT(S) AGE\nkubernetes ClusterIP 10.96.0.1 <none> 443/TCP 9d\nquestdb ClusterIP 10.105.188.157 <none> 80/TCP 52m\n"}]},{"type":"paragraph","content":[{"type":"text","text":"You can see that under "},{"type":"text","marks":[{"type":"code"}],"text":"PORT(S)"},{"type":"text","text":" that it only lists port "},{"type":"text","marks":[{"type":"code"}],"text":"80"},{"type":"text","text":", which is the web UI. So we need to upgrade our QuestDB deployment with a change that enables the InfluxDB line protocol support."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"cat <<EOF >> values.yaml\nservice:\n  type: ClusterIP\n  port: 80\n  expose:\n    influx:\n      enabled: true\n      port: 9009\nEOF\n\nhelm upgrade -f values.yaml questdb ./questdb-kubernetes/charts/questdb\n"}]},{"type":"paragraph","content":[{"type":"text","text":"We''ve used "},{"type":"text","marks":[{"type":"code"}],"text":"-f"},{"type":"text","text":" to specify our own values file, which is augmented / merged with the default one provided by the chart. Our "},{"type":"text","marks":[{"type":"code"}],"text":"values.yaml"},{"type":"text","text":" adds the configuration we need to enable the InfluxDB support; which exposes our port on the QuestDB service. Cool, huh? Now if we check out the service again ..."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"$ kubectl get svc\nNAME TYPE CLUSTER-IP EXTERNAL-IP PORT(S) AGE\nkubernetes ClusterIP 10.96.0.1 <none> 443/TCP 9d\nquestdb ClusterIP 10.105.188.157 <none> 80/TCP,9009/TCP 56m\n"}]},{"type":"paragraph","content":[{"type":"text","text":"We have port "},{"type":"text","marks":[{"type":"code"}],"text":"9009"},{"type":"text","text":" 😀"}]},{"type":"paragraph","content":[{"type":"text","text":"I''m not going to cover running Telegraf inside our Kubernetes cluster, at-least not in this article. I also maintain the chart that makes that easy-easy too; which you can find "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/influxdata/helm-charts","target":null,"rel":null,"class":null,"title":null}}],"text":"here"},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":3,"id":"easy-peasy"},"content":[{"type":"text","text":"Easy Peasy"}]},{"type":"paragraph","content":[{"type":"text","text":"That is all it takes to get QuestDB running on a Kubernetes cluster using the official Helm chart and write some data to it with Telegraf."}]},{"type":"paragraph","content":[{"type":"text","text":"Of course, there''s a variety of things to consider when making the leap to production; and I''ll explore that more as I continue my journey with QuestDB. Until then, go check it out for yourself."}]},{"type":"paragraph","content":[{"type":"text","text":"Below is the deeper dive into the configuration available, if you''re really keen."}]},{"type":"paragraph","content":[{"type":"text","text":"Have a great day!"}]},{"type":"heading","attrs":{"level":2,"id":"helm-chart-values-explanations"},"content":[{"type":"text","text":"Helm Chart Values Explanations"}]},{"type":"paragraph","content":[{"type":"text","text":"Firstly, we have the option to override which image and tag to use for our QuestDB deployment. By default, it''s configured to use "},{"type":"text","marks":[{"type":"code"}],"text":"questdb/questdb"},{"type":"text","text":", which is officially maintained by the QuestDB team. I would always recommend using officially maintained images, but if you''re in an air gapped environment or have compliance teams to appease, you can override as needed. This may require using "},{"type":"text","marks":[{"type":"code"}],"text":"imagePullSecrets"},{"type":"text","text":" to handle authentication for your private registry, which can also be provided. At the time of writing, the most recent version of QuestDB is "},{"type":"text","marks":[{"type":"code"}],"text":"5.0.1"},{"type":"text","text":"."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"image:\n  repository: questdb/questdb\n  pullPolicy: IfNotPresent\n  # Overrides the image tag whose default is the chart appVersion.\n  #tag: \"5.0.1\"\nimagePullSecrets: []\n"}]},{"type":"paragraph","content":[{"type":"text","text":"Next, we have "},{"type":"text","marks":[{"type":"code"}],"text":"nameOverride"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"fullnameOverride"},{"type":"text","text":". Pretty much every chart offers these and they''re strictly superficial. They allow configuring the name of your resources that are created as a result of the deployment. We''re not going to use them today."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"nameOverride: \"\"\nfullnameOverride: \"\"\n"}]},{"type":"paragraph","content":[{"type":"text","text":"Now we get a little more interesting. "},{"type":"text","marks":[{"type":"code"}],"text":"podAnnotations"},{"type":"text","text":" allow you to inject arbitrary annotations onto the pods. This can be useful for gathering metrics from your QuestDB deployment, primarily with Prometheus; which can use annotations for endpoint discovery."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"podAnnotations: {}\n"}]},{"type":"paragraph","content":[{"type":"text","text":"Now for some meaty security stuff. We can configure the user that our process within the containers run as, as well as the group ownership of the filesystems we need for storing our data. We also have the ability to be rather explicit about the capabilities our containers have at the kernel level. This is a "},{"type":"text","marks":[{"type":"bold"}],"text":"HUGE"},{"type":"text","text":" topic that needs to be handled gracefully, like a swan. "},{"type":"text","marks":[{"type":"bold"}],"text":"HONK"},{"type":"text","text":". There was a great "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://www.youtube.com/watch?v=ibrDDaLD6Ks","target":null,"rel":null,"class":null,"title":null}}],"text":"TGIK"},{"type":"text","text":" with "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://twitter.com/mauilion","target":null,"rel":null,"class":null,"title":null}}],"text":"Duffie Cooley"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://twitter.com/IanColdwater","target":null,"rel":null,"class":null,"title":null}}],"text":"Ian Coldwater"},{"type":"text","text":" recently that''s worth watching, if Kubernetes security is something that tickles your fancy."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"podSecurityContext: {}\n# fsGroup: 2000\nsecurityContext: {}\n# capabilities:\n# drop:\n# - ALL\n# readOnlyRootFilesystem: true\n# runAsNonRoot: true\n# runAsUser: 1000\n"}]},{"type":"paragraph","content":[{"type":"text","text":"OK. Now we get to configuring QuestDB itself. I''ll be honest, I don''t know much about this, yet. However, it is "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://questdb.io/docs/reference/configuration/server","target":null,"rel":null,"class":null,"title":null}}],"text":"documented"},{"type":"text","text":"."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"questdb:\n  config: #{}\n    enabled: true\n    options:\n      shared.worker.count: 2\n"}]},{"type":"paragraph","content":[{"type":"text","text":"Running QuestDB on Kubernetes is great ... but we also want to be able to consume it. We can use the "},{"type":"text","marks":[{"type":"code"}],"text":"service"},{"type":"text","text":" block to enable other pods within our cluster to access QuestDB. QuestDB runs a web server, to provide its API and UI, on port "},{"type":"text","marks":[{"type":"code"}],"text":"9000"},{"type":"text","text":". However, it''s quite common to expose that on the HTTP native port, "},{"type":"text","marks":[{"type":"code"}],"text":"80"},{"type":"text","text":", within Kubernetes. This means we can, from within the cluster, run "},{"type":"text","marks":[{"type":"code"}],"text":"curl http://questdb"},{"type":"text","text":" and get what we expect."}]},{"type":"paragraph","content":[{"type":"text","text":"QuestDB also offers a few other ports, which allow for support of InfluxDB line protocol and PostgreSQL; on ports "},{"type":"text","marks":[{"type":"code"}],"text":"9009"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"8812"},{"type":"text","text":" respectfully. I actually forgot to add this to the Helm chart and it was contributed by "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/solidnerd","target":null,"rel":null,"class":null,"title":null}}],"text":"Niclas Mietz"},{"type":"text","text":"; so thank you! 😃"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"service:\n  type: ClusterIP\n  port: 80\n  expose:\n    postgresql:\n      enabled: false\n      port: 8812\n    influx:\n      enabled: false\n      port: 9009\n"}]},{"type":"paragraph","content":[{"type":"text","text":"You know what''s more fun than accessing QuestDB internally within your cluster? Making it public ... ooooooh yeah."}]},{"type":"embed","attrs":{"src":"https://giphy.com/embed/aTx5OMKR7FCGQ","title":null,"width":480,"height":270,"allow":null,"allowFullscreen":true}},{"type":"paragraph","content":[{"type":"text","text":"The Helm chart allows you to leverage Kubernetes Ingress controllers to expose your services to the big bad world. In fact, QuestDB being rather bold ... actually runs their "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://questdb.io/blog/2020/07/01/we-put-a-sql-database-on-the-internet","target":null,"rel":null,"class":null,"title":null}}],"text":"own public QuestDB"},{"type":"text","text":" that allows you to query 2.6 billion records ... that''s wild. I don''t think anyone''s broken it ... yet 😂"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"ingress:\nenabled: false\nannotations: {}\n# kubernetes.io/ingress.class: nginx # kubernetes.io/tls-acme: \"true\"\n# hosts:\n# - host: chart-example.local\n# paths: []\n# tls: []\n# # - secretName: chart-example-tls\n# # hosts:\n# # - chart-example.local\n"}]},{"type":"paragraph","content":[{"type":"text","text":"You know what good a database is without state / persistence? "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://www.youtube.com/watch?v=e0r2Apn7OKA","target":null,"rel":null,"class":null,"title":null}}],"text":"NOTHING"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"We can configure our QuestDB deployment to use persistence through Kubernetes primitives, PVC/PV''s. Resizing these isn''t as easy as one might hope, but it does continually get easier (especially since Kubernetes 1.17). So think carefully about how much space to provision."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"persistence:\n  enabled: true\n  #storageClass: \"-\"\n  accessMode: ReadWriteOnce\n  size: 50Gi\n"}]},{"type":"paragraph","content":[{"type":"text","text":"QuestDB does some magic stuff with the JVM to disable GC, which means that it can run on limited resources. You can use the "},{"type":"text","marks":[{"type":"code"}],"text":"resources"},{"type":"text","text":" block to limit this explicitly. There''s no guessing these numbers, I''m afraid. You''ll need to run without these constraints and profile / monitor your pods to see what \"normal\" usage patterns look like. Then add a safety ceiling of (10|20|30)% and go with that. Best of luck ... resource constraints are tricky business."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"resources: {}\n# limits:\n# cpu: 100m\n# memory: 128Mi\n# requests:\n# cpu: 100m\n# memory: 128Mi\n"}]},{"type":"paragraph","content":[{"type":"text","text":"Finally, the last block. Like every Helm chart before it and every Helm chart that will come after it, we provide the ability to encourage the scheduling of your QuestDB pods to the nodes that you wish, whether it be for storage class support or locality to your other producing or consuming pods; you can do whatever you need with the following three keys."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"nodeSelector: {}\ntolerations: []\naffinity: {}\n"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/docs/concepts/scheduling-eviction/assign-pod-node/","target":null,"rel":null,"class":null,"title":null}}],"text":"Read more here"},{"type":"text","text":"."}]}]}', 'tutorial', 0, 0, NULL, '[]', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1598227200000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('questdb-on-kubernetes', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('questdb-on-kubernetes', 'questdb', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('questdb-on-kubernetes', 'kubernetes', 1);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('saltstack-on-packet-with-pulumi', 'SaltStack on Packet with Pulumi', NULL, 'WIP: You probably don''t want to read this yet 😂 I joined Packet on July 27th (4 days ago, at the tim...', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"WIP: You probably don''t want to read this yet 😂"}]},{"type":"paragraph","content":[{"type":"text","text":"I joined "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://packet.com","target":null,"rel":null,"class":null,"title":null}}],"text":"Packet"},{"type":"text","text":" on July 27th (4 days ago, at the time of writing) as a Senior Tech Evangelist. This is exciting! I get to work for a Cloud company that specialises in bare metal compute. So what should I do first?"}]},{"type":"paragraph","content":[{"type":"text","text":"I''m going to launch my favourite configuration management software with my favourite infrastructure as code software on my new favourite cloud provider. Sweet, right? 🍭🍬"}]},{"type":"paragraph","content":[{"type":"text","text":"If you don''t want to read the walk through, the "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://gitlab.com/rawkode/packet-examples/-/tree/master/pulumi-saltstack","target":null,"rel":null,"class":null,"title":null}}],"text":"code is available here"},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2,"id":"why-saltstack"},"content":[{"type":"text","text":"Why SaltStack?"}]},{"type":"paragraph","content":[{"type":"text","text":"Reasons"}]},{"type":"heading","attrs":{"level":2,"id":"why-pulumi"},"content":[{"type":"text","text":"Why Pulumi?"}]},{"type":"paragraph","content":[{"type":"text","text":"Reasons"}]},{"type":"heading","attrs":{"level":2,"id":"step-1-pulumi"},"content":[{"type":"text","text":"Step 1. Pulumi"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://pulumi.com","target":null,"rel":null,"class":null,"title":null}}],"text":"Pulumi"},{"type":"text","text":" is a Infrastructure as Code (IaaC) tool that allows you to describe your infrastructure, much like "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://terraform.io","target":null,"rel":null,"class":null,"title":null}}],"text":"Terraform"},{"type":"text","text":". Unlike Terraform, Pulumi doesn''t impose a specific DSL, HCL, on you; and instead, you can use your programmaing language of choice ... provided it''s supported."}]},{"type":"paragraph","content":[{"type":"text","text":"At the time of writing, Pulumi supports:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"C#"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"F#"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Go"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"JavaScript"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Python"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"TypeScript"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"VisualBasic"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"I know, I know. I''m disappinted "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://www.rust-lang.org/","target":null,"rel":null,"class":null,"title":null}}],"text":"Rust"},{"type":"text","text":" isn''t there either. "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/pulumi/pulumi/issues/3622","target":null,"rel":null,"class":null,"title":null}}],"text":"Maybe one day"},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":3,"id":"creating-the-stack"},"content":[{"type":"text","text":"Creating the Stack"}]},{"type":"paragraph","content":[{"type":"text","text":"So to create our stack, we need to generate a new Pulumi project. For this example, we''ll use the Pulumi \"local\" login, which stores the statefile on our local disk. The statefile is very similar to Terraform state. It is needed to build an execution plan for our "},{"type":"text","marks":[{"type":"code"}],"text":"apply"},{"type":"text","text":" commands. Using local will suffice today, but you should investigate using "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://www.pulumi.com/docs/intro/concepts/state/","target":null,"rel":null,"class":null,"title":null}}],"text":"alternative options"},{"type":"text","text":" for production deployments."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"pulumi login --local\n"}]},{"type":"paragraph","content":[{"type":"text","text":"We''re going to use the TypeScript template to get started. Unfortunately, there isn''t a template for all supported languages, but templates do exist for the following."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"packet-go # A minimal Packet.net Go Pulumi program\npacket-javascript # A minimal Packet.net JavaScript Pulumi program\npacket-python # A minimal Packet.net Python Pulumi program\npacket-typescript # A minimal Packet.net TypeScript Pulumi program\n"}]},{"type":"paragraph","content":[{"type":"text","text":"If you want to use one of the dotNet languages, you can use a generic template; then add the Packet provider manually. Generic templates for dotNet are called."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"csharp # A minimal C# Pulumi program\nfsharp # A minimal F# Pulumi program\nvisualbasic # A minimal VB.NET Pulumi program\n"}]},{"type":"paragraph","content":[{"type":"text","text":"To create our project from the TypeScript template, let''s run:"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"pulumi new packet-typescript\n"}]},{"type":"paragraph","content":[{"type":"text","text":"You''ll be walked through a couple of questions to create your stack, after which you''ll have a directory that looks like:"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"drwxr-xr-x - rawkode 30 Jul 18:07 node_modules\n.rw------- 286 rawkode 30 Jul 18:06 index.ts\n.rw-r--r-- 28k rawkode 30 Jul 18:07 package-lock.json\n.rw------- 201 rawkode 30 Jul 18:06 package.json\n.rw-r--r-- 85 rawkode 30 Jul 18:07 Pulumi.dev.yaml\n.rw------- 100 rawkode 30 Jul 18:06 Pulumi.yaml\n.rw------- 438 rawkode 30 Jul 18:06 tsconfig.json\n"}]},{"type":"paragraph","content":[{"type":"text","text":"If we take a look inside of "},{"type":"text","marks":[{"type":"code"}],"text":"index.ts"},{"type":"text","text":", we''ll see:"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"import * as pulumi from \"@pulumi/pulumi\";\nimport * as packet from \"@pulumi/packet\";\n\n// Create a Packet resource (Project)\nconst project = new packet.Project(\"my-test-project\", {\n  name: \"My Test Project\",\n});\n\n// Export the name of the project\nexport const projectName = project.name;\n"}]},{"type":"paragraph","content":[{"type":"text","text":"This TypeScript uses the Pulumi SDKs to provide a nice wrapper around the Packet API. Hopefully it''s pretty self-explanitory; you can see that it creates a new project and exports it by name."}]},{"type":"paragraph","content":[{"type":"text","text":"Exports are similar to Terraform outputs. We use an export when we want to make some attribute from our stack available outside of Pulumi. Pulumi provides the "},{"type":"text","marks":[{"type":"code"}],"text":"pulumi stack output"},{"type":"text","text":" command, which displays these exports."}]},{"type":"paragraph","content":[{"type":"text","text":"We''ll use these later."}]},{"type":"heading","attrs":{"level":3,"id":"cleaning-up-the-stack"},"content":[{"type":"text","text":"Cleaning Up the Stack"}]},{"type":"paragraph","content":[{"type":"text","text":"This step is completely subjective, but I don''t like my code just chilling in the top level directory with all the other stuff. What is this, Go? 😏"}]},{"type":"paragraph","content":[{"type":"text","text":"Fortunately, we can append "},{"type":"text","marks":[{"type":"code"}],"text":"main: src/index.ts"},{"type":"text","text":" to the "},{"type":"text","marks":[{"type":"code"}],"text":"Pulumi.yaml"},{"type":"text","text":" file, which tells Pulumi our entyrypoint for this stack lives somewhere else. I''m going to use a "},{"type":"text","marks":[{"type":"code"}],"text":"src"},{"type":"text","text":" directory."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"mkdir src\nmv index.ts src/\necho \"main: src/index.ts\" >> Pulumi.yaml\n"}]},{"type":"heading","attrs":{"level":3,"id":"creating-a-platform"},"content":[{"type":"text","text":"Creating a \"Platform\""}]},{"type":"paragraph","content":[{"type":"text","text":"I like to create a "},{"type":"text","marks":[{"type":"code"}],"text":"Platform"},{"type":"text","text":" object / type / class that can be used to pass around the Pulumi configuration and some other common types that my Pulumi projects often need. This saves my function signatures getting too gnarly as we add new components to our stacks."}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","marks":[{"type":"code"}],"text":"Platform"},{"type":"text","text":" object I''m using for this is pretty trivial. It loads the Pulumi configuration and stores our Packet Project, which means we can pass around "},{"type":"text","marks":[{"type":"code"}],"text":"Platform"},{"type":"text","text":" to other functions and it''s a single argument, rather than many."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"// ./src/platform.ts\nimport { Config } from \"@pulumi/pulumi\";\nimport { Project } from \"@pulumi/packet\";\n\nexport type Platform = {\n  project: Project;\n  config: Config;\n};\n\nexport const getPlatform = (project: Project): Platform => {\n  return {\n    project,\n    config: new Config(),\n  };\n};\n"}]},{"type":"paragraph","content":[{"type":"text","text":"Now we can update our "},{"type":"text","marks":[{"type":"code"}],"text":"./src/index.ts"},{"type":"text","text":" to look like so:"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"import * as packet from \"@pulumi/packet\";\nimport { getPlatform } from \"./platform\";\n\nconst project = new packet.Project(\"pulumi-saltstack-example\", {\n  name: \"pulumi-saltstack-example\",\n});\n\nconst platform = getPlatform(project);\n\nexport const projectName = platform.project.name;\n"}]},{"type":"heading","attrs":{"level":3,"id":"creating-the-saltmaster"},"content":[{"type":"text","text":"Creating the SaltMaster"}]},{"type":"paragraph","content":[{"type":"text","text":"Now we want to create the Salt Master server. For this, I create a new directory with an "},{"type":"text","marks":[{"type":"code"}],"text":"index.ts"},{"type":"text","text":" that exports a function called "},{"type":"text","marks":[{"type":"code"}],"text":"createSaltMaster"},{"type":"text","text":"; which I can consume in our "},{"type":"text","marks":[{"type":"code"}],"text":"./src/index.ts"},{"type":"text","text":", much like we did with our "},{"type":"text","marks":[{"type":"code"}],"text":"Platform"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Here''s the complete file, but I''ll run through each part seperately too; don''t worry! I''m not going to explain the imports, I''ll do that as we go."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"// ./src/salt-master/index.ts\nimport {\n  Device,\n  IpAddressTypes,\n  OperatingSystems,\n  Plans,\n  Facilities,\n  BillingCycles,\n} from \"@pulumi/packet\";\nimport { Platform } from \"../platform\";\nimport * as fs from \"fs\";\nimport * as path from \"path\";\nimport * as mustache from \"mustache\";\n\nexport type SaltMaster = {\n  device: Device;\n};\n\nexport const createSaltMaster = (\n  platform: Platform,\n  name: string\n): SaltMaster => {\n  // While we''re not interpolating anything in this script atm,\n  // might as well leave this code in for the time being; as\n  // we probably will shortly.\n  const bootstrapString = fs\n    .readFileSync(path.join(__dirname, \"./user-data.sh\"))\n    .toString();\n\n  const bootstrapScript = mustache.render(bootstrapString, {});\n\n  const saltMaster = new Device(`master-${name}`, {\n    hostname: name,\n    plan: Plans.C1LargeARM,\n    facilities: [Facilities.AMS1],\n    operatingSystem: OperatingSystems.Debian9,\n    billingCycle: BillingCycles.Hourly,\n    ipAddresses: [\n      { type: IpAddressTypes.PrivateIPv4, cidr: 31 },\n      {\n        type: IpAddressTypes.PublicIPv4,\n      },\n    ],\n    projectId: platform.project.id,\n    userData: bootstrapScript,\n  });\n\n  return {\n    device: saltMaster,\n  };\n};\n"}]},{"type":"heading","attrs":{"level":4,"id":"saltmaster-return-type"},"content":[{"type":"text","text":"SaltMaster Return Type"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"export type SaltMaster = {\n  device: Device;\n};\n"}]},{"type":"paragraph","content":[{"type":"text","text":"Because this is TypeScript, we want to be very explicit about the return types within our code. This allows us to catch errors before we ever run our Pulumi stack. As we''re using "},{"type":"text","marks":[{"type":"code"}],"text":"createSaltMaster"},{"type":"text","text":" function to create our SaltMaster, we want that function to return a type with the resources we create."}]},{"type":"paragraph","content":[{"type":"text","text":"While our function only returns a "},{"type":"text","marks":[{"type":"code"}],"text":"Device"},{"type":"text","text":", it''s still nice to encapsulate that in a named type that allows for our function to evolve over time."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"import { Platform } from \"../platform\";\n\nexport const createSaltMaster = (\n  platform: Platform,\n  name: string\n): SaltMaster =>\n"}]},{"type":"paragraph","content":[{"type":"text","text":"This is the function signature for "},{"type":"text","marks":[{"type":"code"}],"text":"createSaltMaster"},{"type":"text","text":". You can see our return type is the type we just created, "},{"type":"text","marks":[{"type":"code"}],"text":"SaltMaster"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Our function also takes a couple of parameters, namely "},{"type":"text","marks":[{"type":"code"}],"text":"platform"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"name"},{"type":"text","text":". The platform is our "},{"type":"text","marks":[{"type":"code"}],"text":"Platform"},{"type":"text","text":" object with our Pulumi configuration and the Packet Project, so we also need to import it. The "},{"type":"text","marks":[{"type":"code"}],"text":"name"},{"type":"text","text":" allows us to give our SaltMaster a name when we create the device on Packet. We could hardcode this inside the function as "},{"type":"text","marks":[{"type":"code"}],"text":"salt-master"},{"type":"text","text":", but then we can''t use "},{"type":"text","marks":[{"type":"code"}],"text":"createSaltMaster"},{"type":"text","text":" more than once for a highly available set up in a later tutorial."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"import * as fs from \"fs\";\nimport * as path from \"path\";\nimport * as mustache from \"mustache\";\n\nconst bootstrapString = fs\n  .readFileSync(path.join(__dirname, \"./user-data.sh\"))\n  .toString();\n\nconst bootstrapScript = mustache.render(bootstrapString, {});\n"}]},{"type":"paragraph","content":[{"type":"text","text":"I know what you''re thinking ... but trust me. As Pulumi allows us to use a programming language to describe our infrastructure, we also have access to that programming languages entire eco-system of libraries. As such, if I want to template some user data for a server ... say, to provision and install SaltStack ... I can use a popular templating tool, such as mustache, from npm 😉"}]},{"type":"paragraph","content":[{"type":"text","text":"My user data for the Salt Master looks like so:"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"# ./src/salt-master/user-data.sh\n#!/usr/bin/env sh\napt update\nDEBIAN_FRONTEND=noninteractive apt install -y python-zmq python-systemd python-tornado salt-common salt-master\n\nLOCAL_IPv4=$(ip addr | grep -E -o ''10\\.[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}'')\n\ncat <<EOF >/etc/salt/master.d/listen-interface.conf\ninterface: ${LOCAL_IPv4}\nEOF\n\nsystemctl restart salt-master\n"}]},{"type":"paragraph","content":[{"type":"text","text":"Lastly, we need to create the device with the Packet API. We use the Pulumi SDK to do so. I''m explictly importing the required types that I need to use as much of the type system as I can."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"import {\n  Device,\n  IpAddressTypes,\n  OperatingSystems,\n  Plans,\n  Facilities,\n  BillingCycles,\n} from \"@pulumi/packet\";\n\nconst saltMaster = new Device(`master-${name}`, {\n  hostname: name,\n  plan: Plans.C1LargeARM,\n  facilities: [Facilities.AMS1],\n  operatingSystem: OperatingSystems.Debian9,\n  billingCycle: BillingCycles.Hourly,\n  ipAddresses: [\n    { type: IpAddressTypes.PrivateIPv4, cidr: 31 },\n    {\n      type: IpAddressTypes.PublicIPv4,\n    },\n  ],\n  projectId: platform.project.id,\n  userData: bootstrapScript,\n});\n"}]},{"type":"paragraph","content":[{"type":"text","text":"Next up, we can call our "},{"type":"text","marks":[{"type":"code"}],"text":"createSaltMaster"},{"type":"text","text":" function from "},{"type":"text","marks":[{"type":"code"}],"text":"./src/index.ts"},{"type":"text","text":" and we''ll have a server with the correct user data for running our "},{"type":"text","marks":[{"type":"code"}],"text":"salt-master"},{"type":"text","text":"."}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"const saltMaster = createSaltMaster(platform, \"master-1\");\nexport const saltMasterPublicIp = saltMaster.device.accessPublicIpv4;\n"}]},{"type":"paragraph","content":[{"type":"text","text":"We''re going to export it''s public IPv4 address; so that we can access it easily later and SSH into the machine later."}]}]}', 'tutorial', 0, 0, NULL, '[]', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1596067200000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('saltstack-on-packet-with-pulumi', 'rawkode', 0);
