INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('seccomp-kubernetes', 'Seccomp for Kubernetes workloads: from RuntimeDefault to application profiles', NULL, 'Record, review, and roll out application seccomp profiles for Kubernetes, with errno compatibility, logging, distroless verification, and new-node handling.', '', 'guide', 0, 1, NULL, '[]', '[]', 'https://content.rawkode.academy/articles/seccomp-kubernetes/cover.png', 'A Kubernetes workload sends system calls through a seccomp filter, with permitted calls reaching the kernel and blocked calls stopping at the filter.', 1672, 941, NULL, NULL, '[]', '[]', 1790812800000, NULL, 1790888658000);
