INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('tip-1-per-directory-zshell-history', 'Tip 1: Per Directory ZShell History', NULL, 'You probably enter a lot of different commands into your terminal every day, right? Those commands co...', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"You probably enter a lot of different commands into your terminal every day, right? Those commands could be useful in every directory ... sure; but more often than not, they''re specific to the directory you''re in."}]},{"type":"paragraph","content":[{"type":"text","text":"So why do you use a global command history? That changes today:"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/jimhester/per-directory-history","target":null,"rel":null,"class":null,"title":null}}],"text":"https://github.com/jimhester/per-directory-history"}]},{"type":"paragraph","content":[{"type":"text","text":"If you find that you need to search your global history, you can switch back and forward with "},{"type":"text","marks":[{"type":"kbd"}],"text":"Ctrl + g"},{"type":"text","text":" Enjoy"}]},{"type":"horizontalRule"},{"type":"paragraph","content":[{"type":"text","text":"Want to see more history tips and tricks? Check out my "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://gitlab.com/rawkode/dotfiles/blob/master/dotfiles/zsh/includes/history.zsh","target":null,"rel":null,"class":null,"title":null}}],"text":"dotfiles"}]}]}', 'guide', 0, 0, NULL, '[]', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1577836800000, 1577836800000, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('tip-1-per-directory-zshell-history', 'rawkode', 0);
