INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('tip-2-history-forgets-common-commands', 'Tip 2: History Forgets Common Commands', NULL, 'With Tip 1, we looked at how we can switch our history between local directory and global. Regardles...', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"With "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/read/tip-1-per-directory-zshell-history","target":null,"rel":null,"class":null,"title":null}}],"text":"Tip 1"},{"type":"text","text":", we looked at how we can switch our history between local directory and global."}]},{"type":"paragraph","content":[{"type":"text","text":"Regardless of which you''re using, some stuff just doesn''t belong there; right?"}]},{"type":"paragraph","content":[{"type":"text","text":"Do you really use to "},{"type":"text","marks":[{"type":"kbd"}],"text":"Control + r"},{"type":"text","text":" or "},{"type":"text","marks":[{"type":"kbd"}],"text":"Up"},{"type":"text","text":" to find "},{"type":"text","marks":[{"type":"code"}],"text":"ls"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"cd"},{"type":"text","text":", or "},{"type":"text","marks":[{"type":"code"}],"text":"rm"},{"type":"text","text":"?"}]},{"type":"paragraph","content":[{"type":"text","text":"No. The answer is no."}]},{"type":"heading","attrs":{"level":2,"id":"keeping-history-clean"},"content":[{"type":"text","text":"Keeping History Clean"}]},{"type":"paragraph","content":[{"type":"text","text":"Here are 3 short and sweet options you can configure in your "},{"type":"text","marks":[{"type":"code"}],"text":"zshrc"},{"type":"text","text":" file to keep your history lean, mean, and clean."}]},{"type":"heading","attrs":{"level":3,"id":"forget-duplicate-commands"},"content":[{"type":"text","text":"Forget Duplicate Commands"}]},{"type":"paragraph","content":[{"type":"text","text":"Zsh can de-duplicate your command history :smile:"}]},{"type":"paragraph","content":[{"type":"text","text":"Enable this behaviour with "},{"type":"text","marks":[{"type":"code"}],"text":"setopt HIST_IGNORE_DUPS"}]},{"type":"heading","attrs":{"level":3,"id":"forget-common-commands"},"content":[{"type":"text","text":"Forget Common Commands"}]},{"type":"paragraph","content":[{"type":"text","text":"The next approach to keeping our history clean is using "},{"type":"text","marks":[{"type":"code"}],"text":"HISTIGNORE"},{"type":"text","text":"."}]},{"type":"codeBlock","attrs":{"language":"shell","title":null,"meta":null},"content":[{"type":"text","text":"HISTIGNORE=\"&:ls:[bf]g:exit:reset:clear:cd:cd ..:cd..:zh\""}]},{"type":"paragraph","content":[{"type":"text","text":"This is a global list of commands and patterns that you don''t want to keep."}]},{"type":"paragraph","content":[{"type":"text","text":"Use this for all your trivial commands that don''t warrant searching later."}]},{"type":"heading","attrs":{"level":3,"id":"forget-space-commands"},"content":[{"type":"text","text":"Forget Space Commands"}]},{"type":"paragraph","content":[{"type":"text","text":"Another great feature of Zsh is hiding commands preceding with a "},{"type":"text","marks":[{"type":"kbd"}],"text":"Space"}]},{"type":"paragraph","content":[{"type":"text","text":"Enable this behaviour with "},{"type":"text","marks":[{"type":"code"}],"text":"setopt HIST_IGNORE_SPACE"}]},{"type":"codeBlock","attrs":{"language":"shell","title":null,"meta":null},"content":[{"type":"text","text":"# Not stored in history\n ls\n\n# Stored in history\nls"}]},{"type":"horizontalRule"},{"type":"paragraph","content":[{"type":"text","text":"You can find more examples of tweaking your history "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://gitlab.com/rawkode/dotfiles/blob/master/dotfiles/zsh/includes/history.zsh","target":null,"rel":null,"class":null,"title":null}}],"text":"here"}]}]}', 'guide', 0, 0, NULL, '[]', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1577923200000, 1577923200000, 1790346206000);
