INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('tip-3-create-a-tmp-alias', 'Tip 3: Create a `tmp` Alias', NULL, 'Nobody ever tells you this, but it''s true for everyone ... you''ll need to trust me... There''s going...', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Nobody ever tells you this, but it''s true for everyone ... you''ll need to trust me..."}]},{"type":"paragraph","content":[{"type":"text","text":"There''s going to be a time in your life when you create a directory called "},{"type":"text","marks":[{"type":"code"}],"text":"stuff"},{"type":"text","text":" (or "},{"type":"text","marks":[{"type":"code"}],"text":"things"},{"type":"text","text":", or "},{"type":"text","marks":[{"type":"code"}],"text":"tmp"},{"type":"text","text":", or "},{"type":"text","marks":[{"type":"code"}],"text":"delete-me"},{"type":"text","text":", and so forth) to perform some random crappy test."}]},{"type":"paragraph","content":[{"type":"text","text":"You''ll "},{"type":"text","marks":[{"type":"bold"}],"text":"never"},{"type":"text","text":" delete this directory. Honestly. You''ll end up putting it in some "},{"type":"text","marks":[{"type":"code"}],"text":"archive"},{"type":"text","text":" directory and it''ll live forever."}]},{"type":"paragraph","content":[{"type":"text","text":"Well, enough is enough."}]},{"type":"paragraph","content":[{"type":"text","text":"Create this alias. Now."}]},{"type":"paragraph","content":[{"type":"text","text":"Use it with the same glutenous desire you feel when you''re reaching for that last piece of chocolate, from the bag you opened three and a half minutes ago."}]},{"type":"paragraph","content":[{"type":"text","text":"You''re welcome"}]},{"type":"codeBlock","attrs":{"language":"shell","title":null,"meta":null},"content":[{"type":"text","text":"alias tmp='' cd $(mktemp -d)''"}]}]}', 'guide', 0, 0, NULL, '[]', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1578009600000, 1578009600000, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('tip-3-create-a-tmp-alias', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('tip-3-create-a-tmp-alias', 'linux', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('tip-3-create-a-tmp-alias', 'dotfiles', 1);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('tip-4-git-commit-templates-conventional-commits', 'Tip 4: Git Commit Templates & Conventional Commits', NULL, 'Git commit messages are important. We all know that, yet ... in the heat of the moment, we''re prone t...', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Git commit messages are "},{"type":"text","marks":[{"type":"bold"}],"text":"important"},{"type":"text","text":". We all know that, yet ... in the heat of the moment, we''re prone to this non-sense:"}]},{"type":"codeBlock","attrs":{"language":"shell","title":null,"meta":null},"content":[{"type":"text","text":"git commit -m \"stuff\""}]},{"type":"codeBlock","attrs":{"language":"shell","title":null,"meta":null},"content":[{"type":"text","text":"git commit -m \"fix\""}]},{"type":"codeBlock","attrs":{"language":"shell","title":null,"meta":null},"content":[{"type":"text","text":"git commit -m \"it''ll work this time!\""}]},{"type":"paragraph","content":[{"type":"text","text":"Any of them look familiar? You bet your ass they do."}]},{"type":"heading","attrs":{"level":2,"id":"adding-a-git-commit-template"},"content":[{"type":"text","text":"Adding a Git Commit Template"}]},{"type":"paragraph","content":[{"type":"text","text":"This is nice and easy. First, create a text file for your template inside your "},{"type":"text","marks":[{"type":"code"}],"text":"~/.config/git"},{"type":"text","text":" directory ("},{"type":"text","marks":[{"type":"code"}],"text":"~/.git/"},{"type":"text","text":" on macOS I think)."}]},{"type":"codeBlock","attrs":{"language":"text","title":null,"meta":null},"content":[{"type":"text","text":"# ~/.config/git/commit.txt\nMy Commit Template"}]},{"type":"paragraph","content":[{"type":"text","text":"Then update your Git configuration. You can do this one of 2 ways:"}]},{"type":"codeBlock","attrs":{"language":"shell","title":null,"meta":null},"content":[{"type":"text","text":"git config --global commit.template ~/.config/git/commit.txt"}]},{"type":"paragraph","content":[{"type":"text","text":"Or you can update your configuration file:"}]},{"type":"codeBlock","attrs":{"language":"shell","title":null,"meta":null},"content":[{"type":"text","text":"[commit]\ntemplate=~/.config/git/commit.txt"}]},{"type":"heading","attrs":{"level":2,"id":"conventional-commits"},"content":[{"type":"text","text":"Conventional Commits"}]},{"type":"paragraph","content":[{"type":"text","text":"Now that you''ve got a simple template. What should you put there?"}]},{"type":"paragraph","content":[{"type":"text","text":"Let me introduce you to "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://www.conventionalcommits.org/en/v1.0.0/","target":null,"rel":null,"class":null,"title":null}}],"text":"Conventional Commits"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"You can find my template "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://gitlab.com/rawkode/dotfiles/raw/master/nix/includes/development/git-commit-template.txt","target":null,"rel":null,"class":null,"title":null}}],"text":"here"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"The following is the summary and some examples from the website linked above."}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":3,"id":"conventional-commits-1"},"content":[{"type":"text","text":"Conventional Commits"}]},{"type":"paragraph","content":[{"type":"text","text":"The Conventional Commits specification is a lightweight convention on top of commit messages. It provides an easy set of rules for creating an explicit commit history; which makes it easier to write automated tools on top of. This convention dovetails with SemVer, by describing the features, fixes, and breaking changes made in commit messages."}]},{"type":"paragraph","content":[{"type":"text","text":"The commit message should be structured as follows:"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"<type>[optional scope]: <description>\n\n[optional body]\n\n[optional footer(s)]"}]},{"type":"heading","attrs":{"level":4,"id":"examples"},"content":[{"type":"text","text":"Examples"}]},{"type":"heading","attrs":{"level":5,"id":"commit-message-with-description-and-breaking-change-footer"},"content":[{"type":"text","text":"Commit message with description and breaking change footer"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"feat: allow provided config object to extend other configs\n\nBREAKING CHANGE: `extends` key in config file is now used for extending other config files"}]},{"type":"heading","attrs":{"level":5,"id":"commit-message-with--to-draw-attention-to-breaking-change"},"content":[{"type":"text","text":"Commit message with "},{"type":"text","marks":[{"type":"code"}],"text":"!"},{"type":"text","text":" to draw attention to breaking change"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"refactor!: drop support for Node 6"}]},{"type":"heading","attrs":{"level":5,"id":"commit-message-with-both--and-breaking-change-footer"},"content":[{"type":"text","text":"Commit message with both "},{"type":"text","marks":[{"type":"code"}],"text":"!"},{"type":"text","text":" and BREAKING CHANGE footer"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"refactor!: drop support for Node 6\n\nBREAKING CHANGE: refactor to use JavaScript features not available in Node 6."}]},{"type":"heading","attrs":{"level":5,"id":"commit-message-with-no-body"},"content":[{"type":"text","text":"Commit message with no body"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"docs: correct spelling of CHANGELOG"}]},{"type":"heading","attrs":{"level":5,"id":"commit-message-with-scope"},"content":[{"type":"text","text":"Commit message with scope"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"feat(lang): add polish language"}]},{"type":"heading","attrs":{"level":5,"id":"commit-message-with-multi-paragraph-body-and-multiple-footers"},"content":[{"type":"text","text":"Commit message with multi-paragraph body and multiple footers"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"fix: correct minor typos in code\n\nsee the issue for details\n\non typos fixed.\n\nReviewed-by: Z\nRefs #133"}]}]}', 'guide', 0, 0, NULL, '[]', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1578268800000, NULL, 1790346206000);
