INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('tip-5-replacing-ls-with-exa', 'Tip 5: Replacing ls with exa', NULL, 'Rust ... slowly but surely, all applications are being rewritten in Rust. My next few tips will cove...', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rust ... slowly but surely, all applications are being rewritten in Rust."}]},{"type":"paragraph","content":[{"type":"text","text":"My next few tips will cover a few of these :)"}]},{"type":"heading","attrs":{"level":2,"id":"exa"},"content":[{"type":"text","text":"Exa"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/ogham/exa","target":null,"rel":null,"class":null,"title":null}}],"text":"Exa"},{"type":"text","text":" is an "},{"type":"text","marks":[{"type":"code"}],"text":"ls"},{"type":"text","text":" replacement written in Rust. As they say in their "},{"type":"text","marks":[{"type":"code"}],"text":"README"},{"type":"text","text":":"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"with more features and better defaults"}]}]},{"type":"paragraph","content":[{"type":"text","text":"What does it look like?"}]},{"type":"image","attrs":{"src":"https://thepracticaldev.s3.amazonaws.com/i/wpyyb12l52k2781dfb9k.png","alt":"Output from Exa","title":null,"width":null,"height":null,"darkSrc":null,"zoomable":false}},{"type":"image","attrs":{"src":"https://thepracticaldev.s3.amazonaws.com/i/wnscoi85yr3f8zbbduby.png","alt":"Alt Text","title":null,"width":null,"height":null,"darkSrc":null,"zoomable":false}},{"type":"paragraph","content":[{"type":"text","text":"Pretty shiny, eh?"}]},{"type":"paragraph","content":[{"type":"text","text":"Things worth noting:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Colours that distinguish directories, files, and executable files"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Colours for permissions, owners, and size of file"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Git status of each file in long output"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"trees-everywhere"},"content":[{"type":"text","text":"Trees Everywhere"}]},{"type":"paragraph","content":[{"type":"text","text":"When working with code, it can be pretty nice to get a "},{"type":"text","marks":[{"type":"code"}],"text":"tree"},{"type":"text","text":" style look at the repository. Exa surpasses expectations here too."}]},{"type":"paragraph","content":[{"type":"text","text":"First, here are a few aliases I have configured:"}]},{"type":"codeBlock","attrs":{"language":"shell","title":null,"meta":null},"content":[{"type":"text","text":"# ls\nTREE_IGNORE=\"cache|log|logs|node_modules|vendor\"\n\nalias ls='' exa --group-directories-first''\nalias la='' ls -a''\nalias ll='' ls --git -l''\nalias lt='' ls --tree -D -L 2 -I ${TREE_IGNORE}''\nalias ltt='' ls --tree -D -L 3 -I ${TREE_IGNORE}''\nalias lttt='' ls --tree -D -L 4 -I ${TREE_IGNORE}''\nalias ltttt='' ls --tree -D -L 5 -I ${TREE_IGNORE}''"}]},{"type":"paragraph","content":[{"type":"text","text":"Let me explain:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"--tree"},{"type":"text","text":" - Enables Tree display"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"-D"},{"type":"text","text":" - Show directories only (Useful for large trees)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"-L n"},{"type":"text","text":" - How many levels deep to display"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"-I ${TREE_IGNORE}"},{"type":"text","text":" - This omits/hides common vendor directories, as defined in the variable above the aliases"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Here''s a short "},{"type":"text","marks":[{"type":"code"}],"text":"asciinema"},{"type":"text","text":" of me using the "},{"type":"text","marks":[{"type":"code"}],"text":"lt"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"code"}],"text":"ltt"},{"type":"text","text":", and "},{"type":"text","marks":[{"type":"code"}],"text":"lttt"},{"type":"text","text":" aliases:"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://asciinema.org/a/292221","target":null,"rel":null,"class":null,"title":null}}],"text":"View terminal recording"}]}]}', 'guide', 0, 0, NULL, '[]', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1578355200000, 1578355200000, 1790346206000);
