INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('tip-6-bat-rip-skim', 'Tip 6: Bat, Rip, & Skim', NULL, 'Consider this the "Embrace Rust" tip post. If an app can be rewritten in Rust, then someone''s probabl...', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Consider this the \"Embrace Rust\" tip post. If an app can be rewritten in Rust, then someone''s probably done it already."}]},{"type":"paragraph","content":[{"type":"text","text":"Here are my top 3 (Besides "},{"type":"text","marks":[{"type":"code"}],"text":"exa"},{"type":"text","text":", as I covered that "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/read/tip-5-replacing-ls-with-exa","target":null,"rel":null,"class":null,"title":null}}],"text":"yesterday"},{"type":"text","text":")"}]},{"type":"heading","attrs":{"level":2,"id":"bat"},"content":[{"type":"text","text":"Bat"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/sharkdp/bat","target":null,"rel":null,"class":null,"title":null}}],"text":"Bat"},{"type":"text","text":" is a "},{"type":"text","marks":[{"type":"code"}],"text":"cat"},{"type":"text","text":" rewrite, in Rust. It has colours. Lots of colours."}]},{"type":"image","attrs":{"src":"https://thepracticaldev.s3.amazonaws.com/i/dumf43j50jpdah6agzk6.png","alt":"Alt Text","title":null,"width":null,"height":null,"darkSrc":null,"zoomable":false}},{"type":"heading","attrs":{"level":2,"id":"ripgrep"},"content":[{"type":"text","text":"Ripgrep"}]},{"type":"paragraph","content":[{"type":"text","text":"Ripgrep, as one can imagine, is a "},{"type":"text","marks":[{"type":"code"}],"text":"grep"},{"type":"text","text":" rewrite in Rust. Now, it''s not got as many colours (Well, why would it?), but it''s "},{"type":"text","marks":[{"type":"bold"}],"text":"crazy"},{"type":"text","text":" fast."}]},{"type":"image","attrs":{"src":"https://thepracticaldev.s3.amazonaws.com/i/2eqy6zv1awbt6jjnc9ym.png","alt":"Alt Text","title":null,"width":null,"height":null,"darkSrc":null,"zoomable":false}},{"type":"heading","attrs":{"level":2,"id":"skim"},"content":[{"type":"text","text":"Skim"}]},{"type":"paragraph","content":[{"type":"text","text":"Finally, one without a rusted name. Skim is a "},{"type":"text","marks":[{"type":"code"}],"text":"fzf"},{"type":"text","text":" alternative. It''s good for presenting lists of content in a filterable fashion. Lets take a look at "},{"type":"text","marks":[{"type":"code"}],"text":"kill -9"},{"type":"text","text":" followed by "},{"type":"text","marks":[{"type":"kbd"}],"text":"Tab"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://asciinema.org/a/292521","target":null,"rel":null,"class":null,"title":null}}],"text":"View terminal recording"}]},{"type":"horizontalRule"},{"type":"paragraph","content":[{"type":"text","text":"Thanks for tuning in, Until next time 🤘"}]}]}', 'guide', 0, 0, NULL, '[]', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1578441600000, NULL, 1790346206000);
