INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('introducing-wassette', 'Wassette: A New Era of Security for AI Agent Tooling', NULL, 'Wassette, a WebAssembly-based sandboxing technology for AI agent tools, and an analysis of why it represents a major step forward in security compared to traditional methods like Docker and direct execution.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"AI agents are becoming more capable and more dangerous. As they gain the ability to write files, execute code, and make network requests through the Model Context Protocol (MCP), the risk of exploitation increases. That power must be controlled."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/microsoft/wassette","target":null,"rel":null,"class":null,"title":null}},{"type":"bold"}],"text":"Wassette"},{"type":"text","text":" is a new open-source toolkit, announced by Microsoft''s Azure Core Upstream team yesterday (August 6, 2025), that offers a path forward by combining WebAssembly''s strong isolation with a capability-based security model. Here''s why it matters and how it stacks up against Docker and bunx."}]},{"type":"heading","attrs":{"level":2,"id":"what-is-wassette-webassembly-powered-isolation"},"content":[{"type":"text","text":"What is Wassette? WebAssembly-Powered Isolation"}]},{"type":"paragraph","content":[{"type":"text","text":"Wassette represents a new paradigm for MCP server security, leveraging WebAssembly''s sandboxing capabilities to provide browser-grade isolation for untrusted code."}]},{"type":"heading","attrs":{"level":3,"id":"how-wassette-locks-down-tooling"},"content":[{"type":"text","text":"How Wassette Locks Down Tooling"}]},{"type":"paragraph","content":[{"type":"text","text":"Wassette''s security is built on several foundations:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Capability-Based Security"},{"type":"text","text":": Fine-grained permissions for specific operations. Tools must declare the capabilities they need (e.g., access to a specific directory or network host), and the user or host system must explicitly grant them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Deny-by-Default"},{"type":"text","text":": No permissions are granted unless explicitly allowed. A tool has no access to the file system, network, or environment variables by default."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Memory Isolation"},{"type":"text","text":": Each WebAssembly module runs in its own linear memory space, completely isolated from the host process and other modules. It cannot read or write memory outside its sandbox."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"No Direct System Calls"},{"type":"text","text":": All system interactions are proxied through the host runtime via the WebAssembly System Interface (WASI). This allows the host to intercept and validate any attempt to interact with the underlying system."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Unlike traditional execution models where processes inherit full user permissions, Wassette components must explicitly declare their capabilities through WebAssembly Interface Types (WIT), and users must grant each permission individually at runtime."}]},{"type":"heading","attrs":{"level":3,"id":"why-webassembly-changes-everything"},"content":[{"type":"text","text":"Why WebAssembly Changes Everything"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Superior Isolation"},{"type":"text","text":": Wassette provides browser-grade sandboxing, a security model that has been battle-tested over years of web security research. The attack surface is minimal."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Runtime Independence"},{"type":"text","text":": Components are self-contained with zero host dependencies (no Node.js, Python, or system libraries needed). This eliminates runtime supply chain attacks, though components must still be fetched from OCI registries where cryptographic signing becomes critical."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Cross-Platform Consistency"},{"type":"text","text":": WebAssembly provides identical behavior across different operating systems and architectures."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Fine-Grained Permissions"},{"type":"text","text":": The capability-based model allows for precise, auditable control over what a tool can and cannot do."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Cryptographic Verification"},{"type":"text","text":": Wassette supports signed components via OCI distribution, ensuring authenticity and integrity."}]}]}]},{"type":"heading","attrs":{"level":3,"id":"runtime-requirements-and-limitations"},"content":[{"type":"text","text":"Runtime Requirements and Limitations"}]},{"type":"paragraph","content":[{"type":"text","text":"Wassette is built on the Wasmtime runtime and written in Rust, installable as a standalone binary with zero runtime dependencies. Current limitations:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Ecosystem Maturity"},{"type":"text","text":": Very few MCP servers are currently compiled to WebAssembly components"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"WASI Constraints"},{"type":"text","text":": No support for threads, limited async I/O, and restricted system call access"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Developer Experience"},{"type":"text","text":": Requires learning new toolchains (wasm-tools, cargo-component) compared to familiar npm/pip workflows"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Performance Overhead"},{"type":"text","text":": Wasmtime adds measurable overhead for system calls and memory operations compared to native execution"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"why-existing-security-models-fall-short"},"content":[{"type":"text","text":"Why Existing Security Models Fall Short"}]},{"type":"paragraph","content":[{"type":"text","text":"To understand Wassette''s significance, we need to examine the security gaps in today''s MCP server deployment methods."}]},{"type":"heading","attrs":{"level":3,"id":"approach-1-the-wild-west-with-bunx-direct-execution"},"content":[{"type":"text","text":"Approach 1: The Wild West with "},{"type":"text","marks":[{"type":"code"}],"text":"bunx"},{"type":"text","text":" (Direct Execution)"}]},{"type":"paragraph","content":[{"type":"text","text":"The simplest way to run an MCP server is to execute it directly on the host system using a runtime like "},{"type":"text","marks":[{"type":"code"}],"text":"bunx"},{"type":"text","text":" or "},{"type":"text","marks":[{"type":"code"}],"text":"npx"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Security Reality"},{"type":"text","text":": When you run "},{"type":"text","marks":[{"type":"code"}],"text":"bunx @modelcontextprotocol/server-filesystem"},{"type":"text","text":", the server process inherits the full permissions of your user account. It can read your SSH keys, access your documents, make arbitrary network connections, and spawn other processes. There is "},{"type":"text","marks":[{"type":"bold"}],"text":"no isolation"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"This approach is convenient for development but poses a massive security risk. A single compromised dependency in the tool''s supply chain could lead to a full system compromise. Unlike Wassette''s OCI-distributed signed components, "},{"type":"text","marks":[{"type":"code"}],"text":"bunx"},{"type":"text","text":" fetches arbitrary npm packages at runtime with no cryptographic verification beyond optional package signatures."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"bunx"},{"type":"text","text":" Pros"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"bunx"},{"type":"text","text":" Cons"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Simplicity & Performance"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"No Isolation"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Full Ecosystem Access"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Major Supply Chain Risks"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Familiar Developer Experience"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"No Resource Limits"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Verdict"},{"type":"text","text":": Unacceptable for running untrusted or third-party tools. Use only for trusted, first-party tools in controlled development environments."}]},{"type":"heading","attrs":{"level":3,"id":"approach-2-the-walled-garden-with-docker-containerization"},"content":[{"type":"text","text":"Approach 2: The Walled Garden with Docker (Containerization)"}]},{"type":"paragraph","content":[{"type":"text","text":"Docker improves upon direct execution by providing process isolation using Linux namespaces and cgroups. It’s a significant step up in security."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Security Reality"},{"type":"text","text":": A Docker container isolates the tool’s process, filesystem, and network. You can set resource limits (CPU, memory) and use security features like read-only filesystems and capability dropping."}]},{"type":"paragraph","content":[{"type":"text","text":"However, this security is not absolute:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Kernel-Level Sharing"},{"type":"text","text":": All containers on a host share the same Linux kernel. A kernel vulnerability could lead to a container escape."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Daemon Privileges"},{"type":"text","text":": The Docker daemon typically runs as root, representing a powerful target for attackers."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Coarse-Grained Permissions"},{"type":"text","text":": Permissions are generally applied at the container level. For example, if a tool needs to read a single file, you must mount its entire parent directory as a volume. The container then has access to everything in that directory, violating the principle of least privilege."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Unrestricted Network Access"},{"type":"text","text":": By default, a container can make outbound network connections to any destination on the internet. A malicious tool could easily exfiltrate sensitive data from a mounted volume to a remote server without any specific network permissions being granted."}]}]}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"# Docker gives us resource limits and some isolation\nservices:\n  mcp-server:\n    image: mcp-server:latest\n    read_only: true\n    security_opt:\n      - no-new-privileges:true\n    volumes:\n      - ./data:/data:ro # The container can read everything in ./data\n    # By default, this container can send the contents of ./data anywhere on the internet.\n    mem_limit: 512m"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Verdict"},{"type":"text","text":": A mature and robust solution suitable for production, but it lacks the fine-grained, deny-by-default security of WebAssembly. It’s a walled garden, but a determined attacker might still be able to climb the walls or send data over them."}]},{"type":"heading","attrs":{"level":2,"id":"comparative-analysis-wassette-vs-docker-vs-bunx"},"content":[{"type":"text","text":"Comparative Analysis: Wassette vs. Docker vs. bunx"}]},{"type":"paragraph","content":[{"type":"text","text":"Wassette''s capability-based model is fundamentally more secure than the isolation models of Docker or the complete lack of isolation with bunx."}]},{"type":"heading","attrs":{"level":3,"id":"security-comparison-matrix"},"content":[{"type":"text","text":"Security Comparison Matrix"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Aspect"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"bunx"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Docker"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Wassette"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Process Isolation"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"None"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Strong (namespaces/cgroups)"},{"type":"text","marks":[{"type":"superscript"}],"text":" "},{"type":"text","marks":[{"type":"link","attrs":{"href":"#resource-6","target":null,"rel":null,"class":null,"title":null}},{"type":"superscript"}],"text":"§"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Strongest (linear memory)"},{"type":"text","marks":[{"type":"superscript"}],"text":" "},{"type":"text","marks":[{"type":"link","attrs":{"href":"#resource-4","target":null,"rel":null,"class":null,"title":null}},{"type":"superscript"}],"text":"§"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"File System Access"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Unrestricted"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Volume-based"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Capability-based"},{"type":"text","marks":[{"type":"superscript"}],"text":" "},{"type":"text","marks":[{"type":"link","attrs":{"href":"#resource-5","target":null,"rel":null,"class":null,"title":null}},{"type":"superscript"}],"text":"§"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Network Control"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"None"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Network policies"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Per-domain permissions"},{"type":"text","marks":[{"type":"superscript"}],"text":" "},{"type":"text","marks":[{"type":"link","attrs":{"href":"#resource-1","target":null,"rel":null,"class":null,"title":null}},{"type":"superscript"}],"text":"§"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Resource Limits"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"None"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"cgroups"},{"type":"text","marks":[{"type":"superscript"}],"text":" "},{"type":"text","marks":[{"type":"link","attrs":{"href":"#resource-6","target":null,"rel":null,"class":null,"title":null}},{"type":"superscript"}],"text":"§"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Built-in memory limits; CPU via host"},{"type":"text","marks":[{"type":"superscript"}],"text":" "},{"type":"text","marks":[{"type":"link","attrs":{"href":"#resource-5","target":null,"rel":null,"class":null,"title":null}},{"type":"superscript"}],"text":"§"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Supply Chain Security"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"npm packages (runtime fetch)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Image scanning (opt-in signing)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"OCI-distributed (signed components)"},{"type":"text","marks":[{"type":"superscript"}],"text":" "},{"type":"text","marks":[{"type":"link","attrs":{"href":"#resource-2","target":null,"rel":null,"class":null,"title":null}},{"type":"superscript"}],"text":"§"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Permission Granularity"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"All or nothing"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Container-level"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Operation-level"},{"type":"text","marks":[{"type":"superscript"}],"text":" "},{"type":"text","marks":[{"type":"link","attrs":{"href":"#resource-4","target":null,"rel":null,"class":null,"title":null}},{"type":"superscript"}],"text":"§"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Escape Difficulty"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"N/A"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Moderate (CVEs exist)"},{"type":"text","marks":[{"type":"superscript"}],"text":" "},{"type":"text","marks":[{"type":"link","attrs":{"href":"#resource-7","target":null,"rel":null,"class":null,"title":null}},{"type":"superscript"}],"text":"§"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Very High"},{"type":"text","marks":[{"type":"superscript"}],"text":" "},{"type":"text","marks":[{"type":"link","attrs":{"href":"#resource-4","target":null,"rel":null,"class":null,"title":null}},{"type":"superscript"}],"text":"§"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Audit Capabilities"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"External tools"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Docker logs"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Built-in manifest"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Performance Overhead"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"None"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"5-15%"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"10-55%"},{"type":"text","marks":[{"type":"superscript"}],"text":" "},{"type":"text","marks":[{"type":"link","attrs":{"href":"#resource-8","target":null,"rel":null,"class":null,"title":null}},{"type":"superscript"}],"text":"§"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Setup Complexity"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Minimal"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Moderate"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Low-Moderate"}]}]}]}]},{"type":"heading","attrs":{"level":2,"id":"the-ecosystem-challenge-a-chicken-and-egg-problem"},"content":[{"type":"text","text":"The Ecosystem Challenge: A Chicken-and-Egg Problem"}]},{"type":"heading","attrs":{"level":3,"id":"sample-permission-policy"},"content":[{"type":"text","text":"Sample Permission Policy"}]},{"type":"paragraph","content":[{"type":"text","text":"Wassette uses YAML policy files to define what capabilities a component can access:"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"version: \"1.0\"\ndescription: \"Permission policy for fetch component\"\npermissions:\n  network:\n    allow:\n      - host: \"https://api.github.com/\"\n      - host: \"https://opensource.microsoft.com/\"\n  filesystem:\n    read:\n      - path: \"/tmp/cache\"\n    write:\n      - path: \"/tmp/output\"\n  environment:\n    allow:\n      - \"GITHUB_TOKEN\""}]},{"type":"paragraph","content":[{"type":"text","text":"This declarative approach makes security auditable before execution, contrasting sharply with Docker''s all-or-nothing volume mounts and bunx''s complete lack of restrictions."}]},{"type":"heading","attrs":{"level":3,"id":"the-adoption-problem"},"content":[{"type":"text","text":"The Adoption Problem"}]},{"type":"paragraph","content":[{"type":"text","text":"Wassette faces a classic adoption challenge: users need components to run, but developers need users to justify building components. While Wassette offers superior security through WebAssembly''s capability-based model, the ecosystem isn''t ready for production use."}]},{"type":"heading","attrs":{"level":3,"id":"current-limitations"},"content":[{"type":"text","text":"Current Limitations"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Limited Component Availability"},{"type":"text","text":": Few MCP servers exist as WebAssembly components"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Tooling Maturity"},{"type":"text","text":": Creating Wasm components requires specialized knowledge"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Performance Overhead"},{"type":"text","text":": Some workloads may run slower than native execution"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"what-you-should-use-today-and-why"},"content":[{"type":"text","text":"What You Should Use Today (and Why)"}]},{"type":"heading","attrs":{"level":3,"id":"today-use-docker-for-production"},"content":[{"type":"text","text":"Today: Use Docker for Production"}]},{"type":"paragraph","content":[{"type":"text","text":"Docker remains the recommended approach for production MCP servers. It''s mature, well-understood, and provides solid security boundaries when properly configured:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Implement strict security policies and resource limits"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use read-only filesystems where possible"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Regularly audit and update container images"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Monitor your supply chain for vulnerabilities"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"tomorrow-experiment-with-wassette"},"content":[{"type":"text","text":"Tomorrow: Experiment with Wassette"}]},{"type":"paragraph","content":[{"type":"text","text":"Start exploring Wassette in non-critical environments to prepare for the future:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Try simple tools first to understand the security model"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Build WebAssembly versions of basic MCP servers"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Share your experiences and patterns with the community"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Consider hybrid approaches for gradual migration"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"never-use-bunx-in-production"},"content":[{"type":"text","text":"Never: Use bunx in Production"}]},{"type":"paragraph","content":[{"type":"text","text":"Direct execution with "},{"type":"text","marks":[{"type":"code"}],"text":"bunx"},{"type":"text","text":" should be strictly limited to local development of trusted, first-party code where rapid iteration is essential."}]},{"type":"heading","attrs":{"level":2,"id":"beyond-security-portability-and-composability"},"content":[{"type":"text","text":"Beyond Security: Portability and Composability"}]},{"type":"paragraph","content":[{"type":"text","text":"While security is Wassette''s primary value proposition, WebAssembly brings additional benefits:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"True Portability"},{"type":"text","text":": Components run identically across Linux, macOS, Windows, and even edge environments"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Micro-tool Composition"},{"type":"text","text":": Build complex workflows from small, auditable components"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Agentic Workflows"},{"type":"text","text":": Wassette can serve as the default execution engine for autonomous agents, providing safe sandboxing without heavyweight solutions like gVisor or rootless Docker"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Edge Deployment"},{"type":"text","text":": WebAssembly''s small footprint enables running MCP servers in resource-constrained environments"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"conclusion"},"content":[{"type":"text","text":"Conclusion"}]},{"type":"paragraph","content":[{"type":"text","text":"Wassette represents the future of secure AI agent tooling, but that future isn''t here yet. Its WebAssembly-based, capability-driven security model is fundamentally superior to containerization, but the ecosystem needs time to mature."}]},{"type":"paragraph","content":[{"type":"text","text":"By being pragmatic today (using Docker) while investing in tomorrow (experimenting with Wassette), we can help build a more secure foundation for AI agents. The transition won''t happen overnight, but it''s a journey worth taking."}]},{"type":"paragraph","content":[{"type":"text","text":"I couldn''t be more excited about Wassette for MCP, and I''ll be exploring building my own components over the coming weeks. Check back for updates on my journey into WebAssembly-powered AI agent security."}]}]}', 'article', 0, 0, NULL, '[]', '[]', 'https://content.rawkode.academy/articles/introducing-wassette/cover.png', 'Wassette WebAssembly-based security for AI agent tooling', 1472, 832, 'Wassette: WebAssembly Security for AI Agents', 'How Microsoft''s new toolkit revolutionizes MCP server sandboxing', '[]', '[{"id":"1","title":"Wassette GitHub Repository","description":"Official repository with installation instructions and documentation","type":"url","url":"https://github.com/microsoft/wassette","category":"documentation"},{"id":"2","title":"Wassette Introduction Blog Post","description":"Microsoft''s announcement and technical overview of Wassette","type":"url","url":"https://opensource.microsoft.com/blog/2025/08/06/introducing-wassette-webassembly-based-tools-for-ai-agents/","category":"documentation"},{"id":"3","title":"Model Context Protocol Specification","description":"Official MCP specification and documentation","type":"url","url":"https://modelcontextprotocol.io/","category":"documentation"},{"id":"4","title":"WebAssembly Security Model","description":"Detailed explanation of WebAssembly''s security architecture","type":"url","url":"https://webassembly.org/docs/security/","category":"documentation"},{"id":"5","title":"Wasmtime Security Documentation","description":"Security features and considerations for the Wasmtime runtime","type":"url","url":"https://docs.wasmtime.dev/security.html","category":"documentation"},{"id":"6","title":"Docker Security Best Practices","description":"Official Docker security documentation and guidelines","type":"url","url":"https://docs.docker.com/engine/security/","category":"other"},{"id":"7","title":"OWASP Container Security Top 10","description":"Industry standard security risks for containerized applications","type":"url","url":"https://owasp.org/www-project-docker-top-10/","category":"other"},{"id":"8","title":"WebAssembly Performance Analysis","description":"USENIX paper analyzing WebAssembly vs native code performance","type":"url","url":"https://www.usenix.org/conference/atc19/presentation/jangda","category":"other"}]', 1754524800000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('introducing-wassette', 'rawkode', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('introducing-wassette', 'webassembly', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('introducing-wassette', 'docker', 1);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('your-guide-to-kubernetes-dra', 'Your Guide to Kubernetes DRA', NULL, 'Dynamic Resource Allocation lets Kubernetes match device claims to GPU properties. Here is what DRA changes for AI training and inference, and where it still falls short.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"DRA gives Kubernetes a richer device request than a GPU count. Some of the workload-level scheduling that makes this useful is still opt-in."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"nvidia.com/gpu: 8"},{"type":"text","text":" answers one question: how many? It does not, by itself, say which memory profile is acceptable, whether a partitioned device will work, or whether the workers need to fit a particular topology. Teams can encode some of that elsewhere, in node labels, separate resource names or vendor-specific schedulers. Then the hardware request is spread across the platform instead of stated with the workload."}]},{"type":"paragraph","content":[{"type":"text","text":"Dynamic Resource Allocation (DRA) gives Kubernetes a way to describe device requirements as claims and match them to hardware. The practical change is small but important: a workload can ask for a GPU with particular reported properties, not just a number of GPU resources. Here is what that request looks like, and where it still falls short for training and inference."}]},{"type":"heading","attrs":{"level":2,"id":"what-a-claim-tells-the-scheduler"},"content":[{"type":"text","text":"What a claim tells the scheduler"}]},{"type":"paragraph","content":[{"type":"text","text":"The core DRA API has been stable since Kubernetes 1.35. A device driver publishes inventory as "},{"type":"text","marks":[{"type":"code"}],"text":"ResourceSlice"},{"type":"text","text":" objects. A cluster administrator or driver exposes categories through "},{"type":"text","marks":[{"type":"code"}],"text":"DeviceClass"},{"type":"text","text":". A workload uses a "},{"type":"text","marks":[{"type":"code"}],"text":"ResourceClaim"},{"type":"text","text":", or a "},{"type":"text","marks":[{"type":"code"}],"text":"ResourceClaimTemplate"},{"type":"text","text":" when each Pod should get its own similar claim. The scheduler finds a matching device and places the Pod on a node that can access it; the node-local driver then prepares the device for the container. "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/docs/concepts/resource-management/dynamic-resource-allocation/","target":null,"rel":null,"class":null,"title":null}}],"text":"Kubernetes describes DRA as a claims-based allocation API, similar in shape to claiming storage through a PersistentVolumeClaim."}]},{"type":"paragraph","content":[{"type":"text","text":"This template selects a device advertised as a GPU with exactly 64Gi of memory:"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"apiVersion: resource.k8s.io/v1\nkind: ResourceClaimTemplate\nmetadata:\n  name: example-gpu-template\nspec:\n  spec:\n    devices:\n      requests:\n      - name: gpu\n        exactly:\n          deviceClassName: example-device-class\n          selectors:\n          - cel:\n              expression: |-\n                device.attributes[\"driver.example.com\"].type == \"gpu\" &&\n                device.capacity[\"driver.example.com\"].memory == quantity(\"64Gi\")"}]},{"type":"paragraph","content":[{"type":"text","text":"The example class and attribute names come from the installed driver and cluster configuration. The equality matters: this matches exactly 64Gi as reported by the driver. It does not mean “at least 64Gi”, and it does not carve 64Gi out of a larger GPU. A Pod references the template; its container references the resulting claim. Kubernetes can then compare that request with the device inventory before starting the workload. "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/docs/tasks/configure-pod-container/assign-resources/allocate-devices-dra/","target":null,"rel":null,"class":null,"title":null}}],"text":"The official task shows the full claim-to-Pod flow."}]},{"type":"heading","attrs":{"level":2,"id":"training-is-a-group-placement-problem-too"},"content":[{"type":"text","text":"Training is a group-placement problem too"}]},{"type":"paragraph","content":[{"type":"text","text":"If a training job needs eight workers before it can make progress, scheduling four and leaving four pending can tie up GPUs without starting useful work. Gang scheduling addresses that by placing a configured minimum number of Pods as a group. Set "},{"type":"text","marks":[{"type":"code"}],"text":"minCount"},{"type":"text","text":" to eight when all eight are required. This is an initial scheduling guarantee, not a promise that all workers become ready together or that the group can never shrink after a deletion or eviction."}]},{"type":"paragraph","content":[{"type":"text","text":"Kubernetes 1.37 also lets a Workload or PodGroup reference a DRA claim shared by its member Pods. That is useful when the group shares a resource; it is not shorthand for a separate GPU allocation for every worker. Model each worker''s accelerator needs explicitly, then use group scheduling for the all-or-nothing placement requirement."}]},{"type":"paragraph","content":[{"type":"text","text":"Both paths are Beta and disabled by default in Kubernetes 1.37. Gang scheduling uses the "},{"type":"text","marks":[{"type":"code"}],"text":"GenericWorkload"},{"type":"text","text":" feature gate; shared DRA workload claims use "},{"type":"text","marks":[{"type":"code"}],"text":"DRAWorkloadResourceClaims"},{"type":"text","text":". Topology-aware workload scheduling is still Alpha, so a claim does not by itself guarantee placement on a particular rack or fabric. "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/blog/2026/09/08/kubernetes-v1-37-advancing-workload-aware-scheduling/","target":null,"rel":null,"class":null,"title":null}}],"text":"The 1.37 scheduling update spells out the feature gates and current boundaries."}]},{"type":"heading","attrs":{"level":2,"id":"inference-needs-a-fallback-not-a-traffic-router"},"content":[{"type":"text","text":"Inference needs a fallback, not a traffic router"}]},{"type":"paragraph","content":[{"type":"text","text":"Serving fleets may have more than one acceptable accelerator class. DRA lets the platform define those classes and match device properties. Kubernetes 1.36 made prioritised device lists stable, so a request can prefer one device class and fall back to another. That can make otherwise-idle capacity usable, but it does not make the devices equivalent. Different replicas can receive different alternatives, so test the fallback against the model''s serving target. "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/blog/2026/05/07/kubernetes-v1-36-dra-136-updates/","target":null,"rel":null,"class":null,"title":null}}],"text":"The Kubernetes 1.36 DRA update describes prioritised selection."}]},{"type":"paragraph","content":[{"type":"text","text":"And this is still placement, not request routing. DRA does not choose which replica handles an HTTP request, autoscale a model server or enforce a latency objective. Those remain responsibilities of the serving and autoscaling layers."}]},{"type":"heading","attrs":{"level":2,"id":"existing-pod-requests-can-stay-put"},"content":[{"type":"text","text":"Existing Pod requests can stay put"}]},{"type":"paragraph","content":[{"type":"text","text":"Kubernetes 1.37 made it stable for DRA to satisfy traditional extended-resource requests. A Pod can keep asking for a resource through "},{"type":"text","marks":[{"type":"code"}],"text":"resources.requests"},{"type":"text","text":", while the scheduler allocates a matching DRA device behind that name. This gives platform teams a way to move allocation logic without first changing every workload manifest. "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/blog/2026/09/03/kubernetes-v1-37-dra-updates/","target":null,"rel":null,"class":null,"title":null}}],"text":"The Kubernetes 1.37 DRA update documents the compatibility path."}]},{"type":"paragraph","content":[{"type":"text","text":"That is manifest compatibility, not an automatic migration. For NVIDIA''s legacy "},{"type":"text","marks":[{"type":"code"}],"text":"nvidia.com/gpu"},{"type":"text","text":" name, the GPU Operator requires a separate "},{"type":"text","marks":[{"type":"code"}],"text":"DeviceClass"},{"type":"text","text":" with "},{"type":"text","marks":[{"type":"code"}],"text":"spec.extendedResourceName"},{"type":"text","text":" set to that name. Its 26.7 "},{"type":"text","marks":[{"type":"code"}],"text":"GPUCluster"},{"type":"text","text":" workflow also does not support in-place migration from "},{"type":"text","marks":[{"type":"code"}],"text":"ClusterPolicy"},{"type":"text","text":" or a standalone DRA driver installation. Check the driver and operator''s actual migration path before promising a no-disruption switch. "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://docs.nvidia.com/datacenter/cloud-native/gpu-operator/26.7/dra-intro-install.html","target":null,"rel":null,"class":null,"title":null}}],"text":"NVIDIA documents these prerequisites and limitations."}]},{"type":"heading","attrs":{"level":2,"id":"the-driver-still-decides-what-the-claim-means"},"content":[{"type":"text","text":"The driver still decides what the claim means"}]},{"type":"paragraph","content":[{"type":"text","text":"DRA is a Kubernetes API and scheduler integration, not a universal accelerator driver. The driver has to publish useful properties and do whatever preparation the hardware needs. The runtime and vendor stack still have to make the allocated device available inside the container. NVIDIA''s current GPU Operator DRA instructions, for example, require Kubernetes 1.34.2 or later, GPU driver 580 or later, and a CDI-capable runtime configured for CDI injection."}]},{"type":"paragraph","content":[{"type":"text","text":"Sharing also depends on the driver and device. DRA can coordinate supported sharing, but it does not make a sharing mode fair or isolated by itself. Core DRA is stable; several workload and fine-grained capacity features are still Beta or feature-gated. Check the state of the specific capability you plan to use, not just the headline API."}]},{"type":"heading","attrs":{"level":2,"id":"a-useful-first-test"},"content":[{"type":"text","text":"A useful first test"}]},{"type":"paragraph","content":[{"type":"text","text":"Pick one serving workload and one training job. Ask the driver which attributes it publishes, then make a claim that should match and one that should not. Check the allocated device and confirm the container can use it. For the training job, test the 1.37 PodGroup and DRA gates separately in a non-production cluster, and make the topology requirement explicit."}]},{"type":"paragraph","content":[{"type":"text","text":"If the scheduler cannot match the request to a real device, or the container cannot use the allocation it receives, DRA has not yet made that hardware contract useful. That is the test to pass before turning a new claim schema into a platform promise."}]},{"type":"heading","attrs":{"level":2,"id":"references"},"content":[{"type":"text","text":"References"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/docs/concepts/resource-management/dynamic-resource-allocation/","target":null,"rel":null,"class":null,"title":null}}],"text":"Dynamic Resource Allocation concepts"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/docs/tasks/configure-pod-container/assign-resources/allocate-devices-dra/","target":null,"rel":null,"class":null,"title":null}}],"text":"Allocate devices to workloads with DRA"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/blog/2026/05/07/kubernetes-v1-36-dra-136-updates/","target":null,"rel":null,"class":null,"title":null}}],"text":"Kubernetes 1.36 DRA updates"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/blog/2026/09/03/kubernetes-v1-37-dra-updates/","target":null,"rel":null,"class":null,"title":null}}],"text":"Kubernetes 1.37 DRA updates"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/blog/2026/09/08/kubernetes-v1-37-advancing-workload-aware-scheduling/","target":null,"rel":null,"class":null,"title":null}}],"text":"Kubernetes 1.37 workload-aware scheduling"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://docs.nvidia.com/datacenter/cloud-native/gpu-operator/26.7/dra-intro-install.html","target":null,"rel":null,"class":null,"title":null}}],"text":"NVIDIA GPU Operator DRA prerequisites"}]}]}]}]}', 'tutorial', 0, 0, NULL, '[]', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1790294400000, NULL, 1790346175000);
