INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES ('zed-show-and-tell', 'Zed: Show & Tell', NULL, 'Explore Zed, a fast and modern code editor written in Rust with collaborative features', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A common habit of developers is searching for new tools on a regular basis. Visual Studio Code is such a tool which helped me over the years write some awesome code. But I always wanted to try something new. So I stumbled upon Zed."}]},{"type":"heading","attrs":{"level":2,"id":"so-what-is-zed"},"content":[{"type":"text","text":"So what is Zed?"}]},{"type":"paragraph","content":[{"type":"text","text":"Zed is a fairly new code editor written in Rust by the awesome folks which created tools like "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/atom/atom","target":null,"rel":null,"class":null,"title":null}}],"text":"Atom"},{"type":"text","text":". It got open sourced in the beginning of 2024. Zed aims to be a fast, collaborative and hackable editor. But have a look for yourself "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/zed-industries/zed","target":null,"rel":null,"class":null,"title":null}}],"text":"here"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"I personally really like that it comes with a lot of "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/zed-industries/zed/tree/main/extensions","target":null,"rel":null,"class":null,"title":null}}],"text":"extensions"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://zed.dev/docs/vim","target":null,"rel":null,"class":null,"title":null}}],"text":"\"vim mode\""},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2,"id":"installation"},"content":[{"type":"text","text":"Installation"}]},{"type":"paragraph","content":[{"type":"text","text":"You could build Zed either from source or download a pre-compiled binary (only macOS is currently supported)."}]},{"type":"paragraph","content":[{"type":"text","text":"I personally used "},{"type":"text","marks":[{"type":"code"}],"text":"brew"},{"type":"text","text":" to install Zed: "},{"type":"text","marks":[{"type":"code"}],"text":"brew install zed"}]},{"type":"heading","attrs":{"level":2,"id":"lets-open-a-project"},"content":[{"type":"text","text":"Let''s open a project"}]},{"type":"paragraph","content":[{"type":"text","text":"The first thing you see is an empty window. I typically use "},{"type":"text","marks":[{"type":"code"}],"text":"⌘ + P"},{"type":"text","text":" to open the file finder and navigate to my file of choice."}]},{"type":"image","attrs":{"src":"https://content.rawkode.academy/articles/zed-show-and-tell/zed-show-and-tell-01.png","alt":"Zed - empty window","title":null,"width":2672,"height":1420,"darkSrc":null,"zoomable":true}},{"type":"paragraph","content":[{"type":"text","text":"Here you see the file finder in action."}]},{"type":"image","attrs":{"src":"https://content.rawkode.academy/articles/zed-show-and-tell/zed-show-and-tell-02.png","alt":"Zed - file finder","title":null,"width":2672,"height":1420,"darkSrc":null,"zoomable":true}},{"type":"heading","attrs":{"level":2,"id":"working-with-rust"},"content":[{"type":"text","text":"Working with Rust"}]},{"type":"paragraph","content":[{"type":"text","text":"Zed is \"language aware\" and detected that I opened a Rust file and applies the correct syntax highlighting. The "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://zed.dev/docs/languages/rust","target":null,"rel":null,"class":null,"title":null}}],"text":"Rust extension"},{"type":"text","text":" is shipped with Zed by default. The extension uses "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/rust-lang/rust-analyzer","target":null,"rel":null,"class":null,"title":null}}],"text":"rust-analyzer"},{"type":"text","text":" for things like code completion, running tests and "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/tree-sitter/tree-sitter-rust","target":null,"rel":null,"class":null,"title":null}}],"text":"tree-sitter-rust"},{"type":"text","text":" for syntax highlighting. It also added indicators for Rust tests, so that I can run them directly from the editor. Let''s try it out :)"}]},{"type":"image","attrs":{"src":"https://content.rawkode.academy/articles/zed-show-and-tell/zed-show-and-tell-03.png","alt":"Zed - rust file","title":null,"width":2672,"height":1420,"darkSrc":null,"zoomable":true}},{"type":"paragraph","content":[{"type":"text","text":"After clicking the \"Run\" button (the little \"play\" icon next to the test function), the test output is displayed in the built-in terminal at the bottom of the window."}]},{"type":"image","attrs":{"src":"https://content.rawkode.academy/articles/zed-show-and-tell/zed-show-and-tell-04.png","alt":"Zed - rust test","title":null,"width":2672,"height":1420,"darkSrc":null,"zoomable":true}},{"type":"paragraph","content":[{"type":"text","text":"Let''s do some refactoring. I open the "},{"type":"text","marks":[{"type":"code"}],"text":"editor: rename"},{"type":"text","text":" option (via Command Palette) by pressing "},{"type":"text","marks":[{"type":"code"}],"text":"⌘ + Shift + P"},{"type":"text","text":", change the name of the variable and see all changes in some kind of preview window."}]},{"type":"image","attrs":{"src":"https://content.rawkode.academy/articles/zed-show-and-tell/zed-show-and-tell-05.png","alt":"Zed - refactoring","title":null,"width":2672,"height":1420,"darkSrc":null,"zoomable":true}},{"type":"heading","attrs":{"level":2,"id":"conclusion"},"content":[{"type":"text","text":"Conclusion"}]},{"type":"paragraph","content":[{"type":"text","text":"Coming from Visual Studio Code, knowing its key bindings and what not, the transition to Zed was quite a smooth ride. I used it for 2 weeks to write some Rust and TypeScript and did not miss too much. I will definitely stick with Visual Studio Code for now, because some extensions e.g. "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/evrensen467/zed-sql","target":null,"rel":null,"class":null,"title":null}}],"text":"zed-sql"},{"type":"text","text":" is still behind what the Visual Studio Code ecosystem offers."}]},{"type":"paragraph","content":[{"type":"text","text":"Things I haven''t yet tried are the AI integration and the collaboration features, but I will definitely give them a try in the future."}]},{"type":"paragraph","content":[{"type":"text","text":"I''m very happy with the overall experience so far and I''m looking forward to a bright future for Zed."}]}]}', 'article', 0, 0, NULL, '[]', '[]', 'https://content.rawkode.academy/articles/zed-show-and-tell/zed-show-and-tell-cover.png', 'zed website', 1574, 769, 'A New Editor in Town', 'A modern code editor, written in Rust', '[]', '[]', 1720137600000, NULL, 1790346206000);
INSERT INTO `article_authors` (`article_id`, `person_id`, `position`) VALUES ('zed-show-and-tell', 'icepuma', 0);
INSERT INTO `article_technologies` (`article_id`, `technology_id`, `position`) VALUES ('zed-show-and-tell', 'rust', 0);
